-- Guide texts (zhCN) for the Polestar_Guides_Alliance pack.
-- Includes the official Polestar_zhCN texts (they win) and fills every gap,
-- so the addon stays complete whatever order the addons load in.

local _, E = ...
if not (GetLocale and GetLocale() == "zhCN") then return end
if not E.enabled then return end

local G = E.guides

-- Format:
--

G["forever/alliance/02-westfall"] = {
	["Back north past {area:918} to the mine: Kobold Diggers work inside."] = "向北经过{area:918}回到矿洞：狗头人掘地工在矿洞内干活。",
	["Back to {area:108}"] = "返回{area:108}",
	["Back to {area:1519}"] = "返回{area:1519}",
	["Bartleby"] = "巴特莱比",
	["Defias Highwayman"] = "迪菲亚路霸",
	["Defias Knuckleduster"] = "迪菲亚拳斗士",
	["Defias Looter"] = "迪菲亚抢劫者",
	["Defias Pathstalker"] = "迪菲亚巡路者",
	["Defias Pathstalkers and Knuckledusters walk {area:20}; Highwaymen (level 17) patrol the hills south and east of it in pairs: pull them apart. {area:1581} entrance in the smithy is a group dungeon.\nCareful: The camps in the hills hold mixed groups of Defias, so it is easy to pull more than one at a time if you are low level."] = "迪菲亚巡路者和拳斗士在{area:20}走动；路霸（17级）成对巡逻其南边和东边的丘陵：分开拉。铁匠铺里的{area:1581}入口是组队副本。\n小心：丘陵中的营地混编着各类迪菲亚，低等级时很容易一次拉来不止一只。",
	["Defias Pillager"] = "迪菲亚掠夺者",
	["Defias Pillagers and Looters hold the farms west of {area:108}, between the coast road and {area:20}.\nCareful: The {area:113} cave holds many Defias packed together, so it is easy to pull several at once there."] = "迪菲亚掠夺者和抢劫者占据{area:108}以西的农场，位于海岸道路和{area:20}之间。\n小心：{area:113}的洞穴里挤满了迪菲亚，在那里很容易一次拉来好几只。",
	["Defias Smuggler"] = "迪菲亚走私者",
	["Defias Trapper"] = "迪菲亚捕兽者",
	["Fill the vial at the farm's well"] = "在农场的井里装满药瓶",
	["Fill the vial at the well"] = "在井里装满药瓶",
	["Follow the hills south to the tower."] = "沿山丘向南走到塔。",
	["Follow the road from Elwynn into {area:40}: the Furlbrows sit by their burned farm, the first one on the road. Pick up oats from any {object:2724} you pass on the loop: the rest are gathered in the fields here on the way back."] = "沿路从艾尔文森林进入{area:40}：弗尔布罗一家坐在他们被烧毁的农场旁，就在路边第一家。环路上经过的每个{object:2724}都取走燕麦：其余的可在返程时从这片田地里收集。",
	["For {npc:11026} in {zone:1453}'s {object:28027}"] = "交给{zone:1453}{object:28027}的{npc:11026}",
	["For {npc:266} in {area:69}, Redridge"] = "交给赤脊山{area:69}的{npc:266}",
	["Gnoll Paws"] = "豺狼人的爪子",
	["Goretusk Snouts"] = "血牙野猪的头",
	["Harvest Watcher"] = "收割守望者",
	["Harvest Watchers"] = "看守傀儡",
	["Head to {zone:1453}. It has no shaman trainer: take the {area:2257} from the {object:28027} to {zone:1455}, train with {npc:258098}, then ride the tram back for the boat."] = "前往{zone:1453}。那里没有萨满祭司训练师：从{object:28027}乘{area:2257}前往{zone:1455}，在{npc:258098}处学习技能，然后乘地铁返回坐船。",
	["Inside"] = "室内",
	["It lies by the river north-west of the logging camp."] = "它躺在伐木场西北方的河边。",
	["Kobold Digger"] = "狗头人掘地工",
	["Kobold Diggers"] = "狗头人掘地工",
	["Level 12, 14 and 16 spells"] = "12、14和16级法术",
	["Longshore Murloc Gills"] = "长岸鱼人鳃",
	["North of Molsen Farm. Defias Trappers and Smugglers camp outside the mine. {object:290} stands by the ruined house east of the mine.\nWest of Saldean's. Harvest Watchers and Golems work the fields; they drop the isosprings, gyrostabilizers, {item:732} and sometimes a {item:255155}. {npc:573}, a level 20 rare, walks here: leave it alone. Keep killing Goretusks and Fleshrippers on every leg of this loop."] = "莫尔森农场以北。迪菲亚捕兽者和走私者扎营在矿洞外。{object:290}立在矿洞以东的破屋旁。\n萨尔丁农场以西。收割守望者和傀儡在田里干活；它们掉落等距弹簧、陀螺稳定器、{item:732}，偶尔还有{item:255155}。{npc:573}，一只20级稀有，在这里走动：别惹它。每一段环路都要继续杀血牙野猪和撕肉者。",
	["Only if you looted a {item:1972} in Elwynn: right-click it"] = "仅当你在艾尔文森林拾取了{item:1972}：右键点击它",
	["Red Linen Bandanas"] = "红色亚麻面罩",
	["Right-click the {item:6775} he gives you"] = "右键点击他给你的{item:6775}",
	["Riverpaw Gnolls and Scouts (level 11-13) roam the hills south of the coast, from above {area:111} east to the {area:916}. The gnolls further south and west are 13-19: stay in the north hills.\nMurloc Coastrunners and Raiders line the beach north of the mine. They flee at low health: pull one at a time.\nCareful: Gnolls that stand close together tend to join a fight as a group. Pulling one at a time is safer.\nCareful: Two Defias stand guard inside the house, one of them the level 15 named {npc:502}. They are linked, so attacking either one brings both."] = "河爪豺狼人和斥候（11-13级）在海岸以南的丘陵游荡，从{area:111}上方一直到东边的{area:916}。更南边和西边的豺狼人是13-19级：留在北边丘陵。\n鱼人海岸行者和鱼人袭击者分布在矿洞以北的海滩上。它们低血量时会逃跑：一只一只地拉。\n小心：站得很近的豺狼人容易成群加入战斗。一只一只地拉更安全。\n小心：屋内有两名迪菲亚守卫，其中一只是15级有名怪物{npc:502}。它们相互联动，攻击任意一只都会引来两只。",
	["Riverpaw Miner"] = "河爪矿工",
	["Riverpaw Miners"] = "河爪矿工",
	["Sacks of Oats in the fields around the farm"] = "农场周围田里的一袋燕麦",
	["Shaman training"] = "萨满祭司训练",
	["South along the road, past the fork. {npc:233} stands outside, {npc:235} in the house, {npc:253395} in the barn to the west. Young Goretusks and Fleshrippers roam the fields around the farm: start on livers and the stew's meat on the way."] = "沿路向南，过了岔路口。{npc:233}站在屋外，{npc:235}在屋里，{npc:253395}在西边的谷仓里。幼年血牙野猪和碎尸鸟在农场周围的田野游荡：顺路收集肝脏和炖肉用的肉。",
	["South-west to the coast, west of {area:918}. Riverpaw Miners work the quarry."] = "向西南前往海岸，在{area:918}以西。河爪矿工在采石场干活。",
	["Stormwind City"] = "暴风城",
	["The bridge"] = "桥",
	["The camp is north-east of the bridge. Bundles of Wood lie around the camp and in the woods north of it."] = "营地在桥的东北方。一捆木柴散落在营地周围和北边的树林里。",
	["The gnoll camps"] = "豺狼人营地",
	["The mine is south-west of the gnoll camps. {item:247816} lie near the entrance; Kobold Geomancers hold the tunnels."] = "矿洞在豺狼人营地西南方。{item:247816}在入口附近；狗头人地卜师占据着隧道。",
	["The {area:113}"] = "{area:113}",
	["Tram to {zone:1455}"] = "乘地铁前往{zone:1455}",
	["Walk to {zone:1453}, or fly if you know its flight path. Trainers: {object:2100} (Warriors, Rogues), the Cathedral (Paladins, Priests), the {object:2101} (Mages, Warlocks), the Park (Druids)."] = "步行前往{zone:1453}，如果你已有其飞行路线则飞过去。训练师：{object:2100}（战士、潜行者），大教堂（圣骑士、牧师），{object:2101}（法师、术士），公园（德鲁伊）。",
	["Walk to {zone:1453}. {npc:376} is in the Cathedral of Light."] = "步行前往{zone:1453}。{npc:376}在光明大教堂。",
	["Walk to {zone:1453}. {npc:5480} trains warriors in {object:2100}; {npc:6089} and {npc:6090} stand together by the {object:2152} there. {npc:6090} fights you for his mug."] = "步行前往{zone:1453}。{npc:5480}在{object:2100}训练战士；{npc:6089}和{npc:6090}一起站在那里的{object:2152}旁。{npc:6090}会为他的杯子和你打架。",
	["While you're here: learn Staves from {npc:11867} ({object:2096}, 10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "顺便：在{npc:11867}处学习法杖（{object:2096}，10银币）；猎人的近战武器主要看属性，而双手武器属性最多。",
	["While you're here: learn Staves from {npc:11867} ({object:2096}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "顺便：在{npc:11867}处学习法杖（{object:2096}，10银币）；升级期间，法杖的法术属性比单手武器更多。",
	["While you're here: learn Swords from {npc:11867} ({object:2096}, 10 silver); a sword in the main hand levels a Rogue steadily."] = "顺便：在{npc:11867}处学习剑（{object:2096}，10银币）；主手持剑能让潜行者稳定升级。",
	["While you're here: learn {spell:202} from {npc:11867} ({object:2096}, 10 silver); two-handers level a Paladin fastest."] = "趁在这里：向{npc:11867}学习{spell:202}（{object:2096}，10银）；双手武器让圣骑士升级最快。",
	["While you're here: learn {spell:202} from {npc:11867} ({object:2096}, 10 silver); two-handers level a Warrior fastest."] = "趁在这里：向{npc:11867}学习{spell:202}（{object:2096}，10银）；双手武器让战士升级最快。",
	["{area:109}: kill these as you meet them"] = "{area:109}：遇到就杀",
	["{area:20} and the Defias hills"] = "{area:20}和迪菲亚山丘",
	["{area:20}: kill these as you meet them"] = "{area:20}：遇到就杀",
	["{area:40}: kill these as you meet them"] = "{area:40}：遇到就杀",
	["{item:2449} for Gathering the Cure (6123) in {zone:1439}: {npc:1313}, Alchemy Supplies; herbalists pick it there instead"] = "为{zone:1439}的任务“收集解药”（6123）准备{item:2449}：在{npc:1313}的炼金用品店购买；草药师可在那里采集",
	["{item:254676}, from the crates around {area:20}"] = "{item:254676}，来自{area:20}周围的箱子",
	["{item:6529}, from {npc:5494}"] = "{item:6529}，来自{npc:5494}",
	["{item:729}: Fleshrippers"] = "{item:729}：碎尸鸟",
	["{item:731} on the way"] = "顺路拿{item:731}",
	["{npc:234} and {npc:821} stand at the top of the stone tower. {npc:491} is in the tower, {npc:878} on the south side of the hill, next to the inn and {npc:523} the gryphon master."] = "{npc:234}和{npc:821}站在石塔顶上。{npc:491}在塔内，{npc:878}在山丘南侧，旅店和狮鹫管理员{npc:523}旁边。",
	["{npc:235}, inside"] = "{npc:235}，在屋内",
	["{npc:237}; Humans took it from {npc:963} in Elwynn"] = "{npc:237}；人类角色已在艾尔文森林从{npc:963}处接取此任务",
	["{npc:253092}, beside {npc:878}"] = "{npc:253092}，在{npc:878}旁边",
	["{npc:278}, inside"] = "{npc:278}，在里面",
	["{npc:491}, inside"] = "{npc:491}，在屋内",
	["{npc:523}; skip the free flight it offers"] = "{npc:523}；不要乘坐它提供的免费飞行",
	["{npc:5494} sells fishing supplies along the canal just west of the {object:2096}; {npc:267118} fishes at the harbor, on the way to the boat."] = "{npc:5494}在{object:2096}西边的运河旁出售钓鱼用品；{npc:267118}在港口钓鱼，就在去坐船的路上。",
	["{npc:5497}, Wizard's Sanctum: {quest:1861}"] = "{npc:5497}，法师圣殿：{quest:1861}",
	["{npc:6171} and {npc:6173} are in the Cathedral of Light; {npc:6174} stands in the {object:2096} and asks for ten {item:2589} (humanoids drop it; the Auction House sells it)."] = "{npc:6171}和{npc:6173}在光明大教堂；{npc:6174}站在{object:2096}，要求十块{item:2589}（人型生物掉落；拍卖行有售）。",
	["{npc:6172}, by {area:86} in Elwynn, on the road to Redridge"] = "{npc:6172}，在艾尔文森林{area:86}旁，通往赤脊山的路上",
	["{object:290}; inside"] = "{object:290}；在屋内",
	["{quest:153}: every Defias drops them"] = "{quest:153}：每个迪菲亚都会掉落",
}

G["forever/alliance/03-darkshore"] = {
	["At the {area:2362}"] = "在{area:2362}",
	["Back north-east into the mountains to the crystal."] = "向东北回到山里的水晶处。",
	["Back south"] = "返回南方",
	["Back to {npc:11802}"] = "返回{npc:11802}处",
	["Back to {npc:11802} in {area:2361}, then {npc:11800} there flies Druids straight to {area:702}. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "回到{area:2361}的{npc:11802}处，再找那里的{npc:11800}，他能直接把德鲁伊送到{area:702}。{npc:11802}在他那栋楼的楼上：从里面上楼，箭头分不清楼层。",
	["Bears and the Blackwood camp"] = "熊和黑木营地",
	["Blackwood Pathfinder"] = "黑木探路者",
	["Blackwood Pathfinders and Windtalkers hold the camp south-east of {area:442}."] = "黑木探路者和黑木风语者占据着{area:442}东南方的营地。",
	["Blackwood Windtalker"] = "黑木语风者",
	["Blackwood furbolgs"] = "黑木熊怪",
	["By the bonfire closest to the river: summons Xabraxxis"] = "在离河流最近的篝火旁使用，召出萨巴克希斯",
	["Careful: If you attack one cub, the other cubs and often the mother join the fight, so expect to take on several at the same time."] = "注意：攻击一只幼崽时，其他幼崽甚至母兽常会一起加入战斗，做好同时面对多只的准备。",
	["Cast {spell:18960}"] = "施放{spell:18960}",
	["Cast {spell:18960}. {npc:11802} stands upstairs in his building in {area:2361}: go up inside, the arrow cannot tell the floors apart. Learn the flight path there if you do not have it."] = "施放{spell:18960}。{npc:11802}在{area:2361}他那栋楼的楼上：从里面上楼，箭头分不清楼层。还没学会飞行路线就在那里学。",
	["Cast {spell:18960}. {npc:11802} stands upstairs in his building in {area:2361}: go up inside, the arrow cannot tell the floors apart. Shrine Baubles lie in the containers on the floor of {area:656}, below {area:2361}: take one to the {area:2362} in the north-west, use it there and speak to {npc:11799}. Then fly back to {area:442} from {area:2361}."] = "施放{spell:18960}。{npc:11802}在{area:2361}他那栋楼的楼上：从里面上楼，箭头分不清楼层。神龛饰品放在{area:656}的地面容器里，位于{area:2361}下方：拿一个到西北的{area:2362}，在那里使用并和{npc:11799}交谈。然后从{area:2361}飞回{area:442}。",
	["Climb the eastern mountains east of {area:447}; the {object:175524} sits on a ledge."] = "爬上{area:447}东边的山脉；{object:175524}位于一处岩架上。",
	["Crawler Legs"] = "蟹腿",
	["Den Mother"] = "母熊",
	["Escort her out of the glaive; Therysil takes the turn-in in {zone:1440}"] = "护送她离开主宰之剑；在{zone:1440}交给瑟瑞希尔",
	["Fill the tube at the moonwell in the village"] = "在村里的月亮井装满试管",
	["Fine Moonstalker Pelts"] = "优质月夜猛虎毛皮",
	["Fly from {area:442} to {area:702} and take the portal up to {npc:4217} in the {area:1658}."] = "从{area:442}飞往{area:702}，乘传送门上去找{area:1658}的{npc:4217}。",
	["Follow the coast north-east to the {area:443}. {quest:951} lie among the ruins; Stormscale Myrmidons, Sorceresses and Warriors hold them, and Stormscale Beastmistresses walk the shore."] = "沿海岸向东北到{area:443}。{quest:951}散落在废墟中；雷鳞侍从、雷鳞巫师和雷鳞战士占据着那里，雷鳞兽王在岸边巡逻。",
	["Follow the coast south past {area:447}: one {quest:4728} lies on the shore west of the Grove, another further south near {area:450}. Three more remains lie further south-west among Greymist Oracles and Tidehunters (18-20): the guide leaves them for the last loop, when you are closer to their level."] = "沿海岸向南经过{area:447}：一只{quest:4728}躺在古树之林西边的岸上，另一只在更南边的{area:450}附近。更西南方的灰雾智者和灰雾潮行者（18-20级）之间还有三具遗骸：指南把它们留到最后一轮，那时你的等级更接近它们。",
	["Follow the hills north to the {area:456} and up to the falls. Two more beached remains lie on the north shore: near the {area:443} and north of {quest:954}."] = "沿山丘向北到{area:456}，再往上到瀑布。北岸还有两具搁浅的遗骸：在{area:443}附近和{quest:954}北边。",
	["Follow the road north."] = "沿道路向北。",
	["Grell Earrings"] = "劣魔耳环",
	["Grizzled Scalps"] = "灰色头皮",
	["Grizzled Thistle Bears roam the hills around the Grove; {quest:1003} stands west of it among them."] = "灰斑蓟熊在林地周围的山丘上游荡；{quest:1003}就在林地西边的熊群之中。",
	["Highborne Relics"] = "上层精灵的遗物",
	["Kill Rabid Thistle Bears in the hills east of {area:442}, then walk up to the furbolg camp south-east of them: nothing to kill yet."] = "在{area:442}东边的山丘上击杀狂暴蓟熊，然后走到它们东南方的熊怪营地：暂时不用击杀任何东西。",
	["Level 18.47"] = "18.47级",
	["Level 20"] = "20级",
	["Moonstalker Fangs"] = "月夜猛虎的牙齿",
	["Moonstalker Sires prowl the woods around the glaive. The {object:10076} and the {object:12666} sit at the bottom of the crater; {npc:3584} stands on its north side."] = "月夜雄虎在主宰之剑周围的树林里潜行。{object:10076}和{object:12666}在陨坑底部；{npc:3584}站在陨坑北侧。",
	["Moonstalkers prowl the hills between {quest:954} and the tower. {quest:1002} stands on the hill west of the tower."] = "月夜猛虎在{quest:954}和塔之间的山丘上潜行。{quest:1002}立在塔西边的山丘上。",
	["Murkdeep"] = "深泥",
	["Night Elves fly from {area:442} to {area:702}; Skyborne take the boat from the {area:442} dock and learn the Rut'theran flight path there. Take the portal up to {npc:4217} in the {area:1658}."] = "暗夜精灵从{area:442}飞往{area:702}；天裔乘{area:442}码头的船前往，并在那里学习鲁瑟兰村的飞行路线。乘传送门上去找{area:1658}的{npc:4217}。",
	["North along the hills. {npc:3650} waits in the ruins of {quest:954}; Wild Grells and Vile Sprites fill them, Deth'ryll Satyrs the eastern edge. {quest:1001} stands by the road west of the ruins; a {quest:4723} lies on the shore on the way to him."] = "沿山丘向北。{npc:3650}在{quest:954}的废墟中等候；废墟里满是野生劣魔和恶灵劣魔，东缘是戴瑟雷萨特。{quest:1001}立在废墟西边的路旁；去找它的路上，岸边躺着一只{quest:4723}。",
	["On the way"] = "顺路",
	["Only if a Disciple or Thug dropped {item:5352}: right-click it"] = "仅当暮光信徒或暮光暴徒掉落了{item:5352}：右键点击它",
	["Plagued bears"] = "染病的熊",
	["Rabid Thistle Bear"] = "狂暴蓟熊",
	["Rabid Thistle Bears roam the hills just east of {area:442}. Use {quest:2139} on one and lead it back to him."] = "狂暴蓟熊在{area:442}东边的山丘上游荡。对一只使用{quest:2139}，然后把它引回他身边。",
	["Read the {object:17188}"] = "阅读{object:17188}",
	["Read the {object:17189}"] = "阅读{object:17189}",
	["Scaber Stalks; below ground"] = "痂壳潜伏者；地下",
	["She gives you the {item:15826}"] = "她会给你{item:15826}",
	["Sickly Deer"] = "病弱鹿",
	["Stormscale Myrmidon"] = "雷鳞迈尔米顿",
	["Stormscale Sorceress"] = "雷鳞女巫",
	["Stormscale Warrior"] = "雷鳞战士",
	["Take the portal up to {npc:4217}, then fly back to {area:442} for the boat to {zone:1453}."] = "乘传送门上去找{npc:4217}，然后飞回{area:442}乘船前往{zone:1453}。",
	["The Lunar Fungal Blooms grow in the moonkin caves in the hills just east of {area:442}; the moonkin there are irritable. {item:2449} needs {skill:182}: herbalists pick it all over {zone:1439}, anyone else brings it from {zone:1453} ({npc:1313}) or the Auction House."] = "{object:177750}生长在{area:442}东边山丘上的枭兽洞穴里；那里的枭兽很暴躁。{item:2449}需要{skill:182}：草药师在{zone:1439}各处都能采到，其他人从{zone:1453}（{npc:1313}）或拍卖行带来。",
	["The WANTED poster"] = "通缉布告",
	["The WANTED poster outside the inn"] = "旅店外的通缉布告",
	["The bay wrecks"] = "海湾沉船",
	["The beach"] = "海滩",
	["The boat docks west of the village. The flight master stands on the hill south of the inn; the quest givers are spread along the main street. {npc:3666} stands upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart."] = "船停靠在村子西边。飞行管理员站在旅店南边的山丘上；任务发布者分散在主街上。{npc:3666}站在旅店楼上：从里面上楼梯，箭头分不清楼层。",
	["The cave and the {npc:6788}"] = "洞穴和{npc:6788}",
	["The cave lies south of the falls: Scaber Stalks grow all through it, the {item:5270} at the very back. The {npc:6788} lairs in the hills south of the falls."] = "洞穴在瀑布南边：整个洞里都长着粗柄蘑菇，{item:5270}在最深处。{npc:6788}的巢穴在瀑布南边的山丘上。",
	["The flame burns in the south of {area:447}."] = "火焰在{area:447}南部燃烧。",
	["The furbolg camp south of the {area:456} keeps its Nut, Fruit and Grain Stores by the bonfires. With a sample of each and the {item:12347} in your bags (the {item:12346} is filled at the {object:174795}), use the bowl by the bonfire closest to the river: it summons Xabraxxis, the satyr corruptor, and the {item:12355} lies in his Demon Bag."] = "{area:456}南边的熊怪营地里，坚果、水果和谷物储存在篝火旁。各取一份样本，并备好{item:12347}（在{object:174795}装满{item:12346}），然后在离河流最近的篝火旁使用净化碗，召出腐化熊怪的萨特萨巴克希斯。{item:12355}在他的恶魔之包里。",
	["The half pendants lie in {zone:1439} and {zone:1436}: later on the route"] = "两块吊坠碎片在{zone:1439}和{zone:1436}：在路线后面",
	["The naga"] = "纳迦",
	["The northern Blackwood camp"] = "北边的黑木营地",
	["The red crystal"] = "红色水晶",
	["The relics of the Barrow Dens"] = "兽穴里的遗物",
	["The skeletal turtle"] = "骷髅海龟",
	["The southern beaches"] = "南部海滩",
	["The {area:443}"] = "{area:443}",
	["The {object:10076}"] = "{object:10076}",
	["The {object:12666}"] = "{object:12666}",
	["The {object:16393}"] = "{object:16393}",
	["The {quest:952}"] = "{quest:952}",
	["Thresher Eyes; underwater"] = "长尾鲨之眼；水下",
	["Tide Crawlers scuttle along the shore below the village; {quest:983} stands on the beach just south of the docks. Darkshore Threshers swim in the shallows. The {object:175207} lies on the shore just south of the village."] = "潮行蟹在村子下方的岸边爬行；{quest:983}立在码头南边的海滩上。黑海岸蛇颈龙在浅水中游动。{object:175207}躺在村子南边的岸上。",
	["Top up here to level 18.47 before the hand-ins at {quest:952}: they take you to level 19."] = "在交{quest:952}之前在这里补到18.47级：这些任务会把你带到19级。",
	["Top up here to level 20 before the hand-ins at {zone:1453}: they take you to level 21."] = "在交{zone:1453}的任务之前在这里补到20级：它们会把你带到21级。",
	["Two wrecks lie on the sea floor in the bay north of {area:442}; each holds a lockbox. Reef Crawlers and Encrusted Tide Crawlers line this shore.\nCareful: The murlocs inside the wrecks are close together and fast. They often swim through the hull walls and holes, so you will usually pull extra murlocs."] = "两艘沉船躺在{area:442}北边海湾的海底；每艘都有一个保险箱。礁石爬行者与镶壳潮汐爬行者沿这片海岸分布。\n注意：沉船里的鱼人密集且移动很快，常常穿过船体墙壁和破洞游动，所以通常会额外引到鱼人。",
	["Underwater"] = "水下",
	["grind on {npc:2187}"] = "刷{npc:2187}",
	["grind on {npc:2237}"] = "刷{npc:2237}",
	["grind on {npc:2339}"] = "刷{npc:2339}",
	["the Rabid Thistle Bears nearest {npc:3701}"] = "距{npc:3701}最近的狂暴蓟熊",
	["{area:442} flight master"] = "{area:442}飞行管理员",
	["{area:450} lies on the coast south of {npc:10323}'s beach. Protect the prospector while he searches for the fossil.\nCareful: Ambushers appear as he passes certain spots: a scout comes out from under the board ramp, and more scouts come out when he checks the tent."] = "{area:450}位于{npc:10323}海滩以南的海岸上。在勘探者寻找化石时保护他。\n注意：他经过某些地点时会出现伏击者：经过木板坡道下方时会钻出一名斥候，他检查帐篷时还会钻出更多斥候。",
	["{area:452}: kill these as you meet them"] = "{area:452}：遇到就杀",
	["{item:12191}; underwater"] = "{item:12191}；水下",
	["{item:12192}; underwater"] = "{item:12192}；水下",
	["{item:12237} from {npc:2233} and {npc:2235}, by this stop"] = "{item:12237}：掉落自此处附近的{npc:2233}和{npc:2235}",
	["{item:12238}: fish from the pier"] = "{item:12238}：在码头钓鱼",
	["{item:12289}, on the beach west of the docks; underwater"] = "{item:12289}，在码头西边的海滩；水下",
	["{item:12347}: fill the {item:12346} at the {object:174795}"] = "{item:12347}：在{object:174795}装满{item:12346}",
	["{item:12349}, at the waterfall"] = "{item:12349}，在瀑布处",
	["{item:12355}, in {object:177624}"] = "{item:12355}，在{object:177624}里",
	["{item:15845}: at the mouth of the cave by the falls"] = "{item:15845}：在瀑布旁的洞口",
	["{item:15851} and {item:2449}"] = "{item:15851}和{item:2449}",
	["{item:15877}, from a {object:177785} in the lake"] = "{item:15877}，来自湖中的{object:177785}",
	["{item:15883}: the {object:177792} under the water off the north coast, west of the ruins"] = "{item:15883}：在废墟西边、北部海岸外水下的{object:177792}",
	["{item:279279}: Twilight Disciples and Thugs"] = "{item:279279}：暮光信徒和暮光暴徒",
	["{item:5270}; below ground"] = "{item:5270}；地下",
	["{item:5338}: Deth'ryll Satyrs"] = "{item:5338}：戴瑟雷萨特",
	["{item:5348}: Dark Strand Fanatics"] = "{item:5348}：暗滩狂热者",
	["{npc:10216}, on the pier"] = "{npc:10216}，在码头上",
	["{npc:10216}, on the pier: only with {skill:356}"] = "{npc:10216}，在码头上：需要{skill:356}",
	["{npc:10323} camps on the beach west of the glaive: kill the murlocs at the camp fire; he comes in the third wave with his hound. Three beached remains lie on the beaches west and south-west of {area:450}."] = "{npc:10323}在主宰之剑西边的海滩上扎营：击杀营火旁的鱼人；他会在第三波带着猎犬出现。{area:450}西边和西南边的海滩上还有三具搁浅的遗骸。",
	["{npc:10323}'s beach"] = "{npc:10323}的海滩",
	["{npc:11802} stands upstairs in his building in {area:2361}: go up inside, the arrow cannot tell the floors apart."] = "{npc:11802}站在{area:2361}他那栋楼的楼上：从里面上楼，箭头分不清楼层。",
	["{npc:11802}: the welcome from Sheldras"] = "{npc:11802}：沙德拉斯·月树的问候",
	["{npc:12298}: use the {item:15826} on them; they roam all of {zone:1439}"] = "{npc:12298}：对它们使用{item:15826}；它们在整个{zone:1439}游荡",
	["{npc:2164} on the way"] = "{npc:2164}，顺路",
	["{npc:3616}, at the Grove"] = "{npc:3616}，在古树之林",
	["{npc:3639} stands at the north edge of the ruins. Cursed, Writhing and {npc:2178} haunt them; {npc:3667}'s ghost walks among them, {npc:270196} the owl circles east of them. The two tablets lie in the ruins; a {quest:4722} lies on the shore west of them."] = "{npc:3639}站在废墟北缘。被诅咒的贵族、挣扎的贵族和{npc:2178}在那里出没；{npc:3667}的鬼魂在它们中间游荡，猫头鹰{npc:270196}在它们东边盘旋。两块石板在废墟中；一只{quest:4722}躺在废墟西边的岸上。",
	["{npc:3644}, on the pier"] = "{npc:3644}，在码头上",
	["{npc:3649}, north end of the village"] = "{npc:3649}，在村子北端",
	["{npc:3649}: for {npc:1646} in {zone:1453}"] = "{npc:3649}：交给{zone:1453}的{npc:1646}",
	["{npc:3661} hides at the foot of the tower among the Dark Strand Fanatics. Keep his letter for Delgren in {zone:1440}."] = "{npc:3661}躲在塔脚下的{npc:2336}中间。保留他的信，交给{zone:1440}的净化者德尔格伦。",
	["{npc:3666}, upstairs in the inn"] = "{npc:3666}，在旅店楼上",
	["{npc:3692} hides in the hills east of the {area:449}. Help him back to the road; he fights on his way out."] = "{npc:3692}躲在{area:449}东边的山丘上。帮他回到道路上；他会一路战斗出去。",
	["{npc:3692}, inside {area:455}"] = "{npc:3692}，{area:455}内",
	["{npc:3694}: for {npc:3691} in {area:415}, on the later {zone:1440} leg"] = "{npc:3694}：交给{area:415}的{npc:3691}，在之后的{zone:1440}阶段",
	["{npc:6667} hides on the little island off the ruins. The key pieces drop from Giant Foreststriders (top), Greymist murlocs (middle) and Raging Reef Crawlers (bottom)."] = "{npc:6667}躲在废墟外的小岛上。钥匙碎片掉落自凶猛的森林陆行鸟（上段）、灰雾鱼人（中段）和狂暴暗礁蟹（下段）。",
	["{npc:6788}, below ground"] = "{npc:6788}，地下",
	["{quest:6122}: fill the sampler at {area:445}"] = "{quest:6122}：在{area:445}装满取样器",
	["{quest:87760}: {npc:10219} offers it once all nine beached remains are handed in"] = "{quest:87760}：交齐全部九具搁浅的遗骸后，{npc:10219}会提供这个任务",
	["{quest:948} is the ancient at the Grove; {npc:270269} and {npc:11218} sleep beside him."] = "{quest:948}是树林中的上古者；{npc:270269}和{npc:11218}睡在他身旁。",
	["{quest:98394} (Night Elves) and the {npc:272054} (Skyborne) wait in southern {area:493}. The three relics lie in the {area:2363}, east of them. Reports from the first weeks say a relic gives no loot while another player is looting it: wait a moment and try again."] = "{quest:98394}（暗夜精灵）和{npc:272054}（天裔）在{area:493}南部等候。三件遗物在它们东边的{area:2363}里。最初几周的报告称：其他玩家正在拾取某件遗物时，你拾取不到东西：稍等片刻再试。",
	["{zone:1439}: kill these as you meet them"] = "{zone:1439}：遇到就杀",
}

