G["forever/alliance/04-redridge-mountains"] = {
	["Back to {area:12}"] = "返回{area:12}",
	["Back to {area:69}"] = "回到{area:69}",
	["Blackrock Champion"] = "黑石勇士",
	["Blackrock camps"] = "黑石营地",
	["Boat to {area:17203}"] = "乘船前往{area:17203}",
	["Cross the long bridge north into town. {npc:341} and {npc:382} stand at the north end of the bridge, {npc:900} in the town hall, {npc:381} and {npc:266} on the docks, {npc:343} at the inn, {npc:342} in her garden at the west end."] = "向北过长桥进入镇子。{npc:341}和{npc:382}站在桥的北端，{npc:900}在市政厅，{npc:381}和{npc:266}在码头，{npc:343}在旅店，{npc:342}在镇子西端她的菜园里。",
	["Fly to {area:108}"] = "飞往{area:108}",
	["Fly to {area:108} and head north-west to the coast: the {object:177790} lies on the sea floor off the shore. Then head east along the road through Elwynn to Redridge."] = "飞往{area:108}，向西北前往海岸：{object:177790}躺在近海的海底。然后沿路向东穿过艾尔文森林前往赤脊山。",
	["Follow the road along the south shore of {area:68} to the gryphon master. {npc:1070} and {npc:903} stand by the road next to her."] = "沿{area:68}南岸的道路走到狮鹫管理员处。{npc:1070}和{npc:903}站在她旁边的路边。",
	["Follow the road north-west past the cemetery to {npc:311}'s camp on the far west edge of the forest. {npc:893} stands beside {npc:311}."] = "沿道路向西北经过墓地，前往森林最西缘的{npc:311}营地。{npc:893}站在{npc:311}旁边。",
	["For {npc:302}, on the hill south-east of town"] = "交给{npc:302}，在镇子东南方的山上",
	["Greater Tarantula"] = "巨型狼蛛",
	["Greater Tarantulas crawl on the slopes around the mill north-east of the lake."] = "巨型狼蛛在湖东北边伐木场周围的山坡上爬行。",
	["Head north out of {area:69} up the {area:95} to {area:997}. Blackrock Champions camp in the valley."] = "从{area:69}向北出发，沿{area:95}上行到{area:997}。黑石勇士在山谷中扎营。",
	["Inside"] = "室内",
	["Keeshan hides at the very north end of the valley, by the {zone:1428} border. Escort him down to {area:69}; Blackrock orcs ambush you on the way."] = "基沙恩下士躲在山谷最北端，靠近{zone:1428}边界。护送他下山回到{area:69}；途中会遭到黑石兽人伏击。",
	["Level 18 and 20 spells"] = "18级和20级法术",
	["Murloc Flesheaters and Tidecallers line the south shore east of the bridge. Any of them can carry a {item:1467} or a fin.\nGreater Tarantulas crawl on the slopes around the mill north-east of the lake."] = "鱼人食肉者和唤潮者沿桥东的南岸分布。它们任何一个都可能带着{item:1467}或鱼鳍。\n巨型狼蛛在湖东北磨坊周围的山坡上爬行。",
	["On the road east, past the {area:91}, head north from the bridge to {area:86}. {npc:6172} lies south of the lake: use the {item:6866} on him. The Defias Rogue Wizards around him carry the {item:6846}."] = "沿路向东，经过{area:91}后从桥边向北到{area:86}。{npc:6172}躺在湖的南边：对他使用{item:6866}。他周围的迪菲亚流氓巫师带着{item:6846}。",
	["Only once {quest:97914} is handed in: for {npc:3649}, back in {area:442} (06-ashenvale)"] = "只有在交完{quest:97914}之后：交给回到{area:442}的{npc:3649}（06-灰谷）",
	["Redridge Mongrel"] = "赤脊杂种",
	["Redridge Mongrels and other gnolls hold the hills east of {area:1002}, north of the road; Redridge Thrashers prowl among them, Poachers camp south of the road. Redridge Brutes, for the Iron Pikes and Rivets, hold the hills further north; Dire Condors and Great Goretusks roam the hills east of them."] = "赤脊杂种和其他豺狼人占据着{area:1002}以东、路北的丘陵；赤脊鞭笞者在其间游荡，偷猎者扎营在路南。赤脊蛮兵（为铁矛和铆钉任务而来）占据更北的丘陵；凶暴秃鹫和巨型刺喉猪在它们东边的丘陵上游荡。",
	["Redridge Poacher"] = "赤脊偷猎者",
	["Shaman training"] = "萨满祭司训练",
	["South-east from the mill, west of {area:1000}'s gnolls, to the Blackrock camps east of {area:2099}. Renegades, Grunts and Outrunners fill them; keep east of the keep, whose orcs are elite."] = "从磨坊向东南，到{area:1000}豺狼人以西，再到{area:2099}以东的黑石营地。营地里满是叛徒、步兵和先锋；待在要塞以东，那里面的兽人是精英。",
	["Swim east from the bridge into {area:68}; the chest lies on the lake bed."] = "从桥边向东游进{area:68}；箱子在湖底。",
	["The Wanted poster by the inn"] = "旅店旁的通缉布告",
	["The cemetery lies north of the village. Skeletal Horrors and Skeletal Fiends walk its southern half. {npc:522}, an elite, wanders the graves: keep away from him."] = "墓地位于村子北边。恐怖骸骨和骸骨魔在墓地南半部游荡。精英{npc:522}在墓地间徘徊：离他远点。",
	["The mound of loose dirt lies south of the farmhouse, by the old stump."] = "松土堆在农舍南边的老树桩旁。",
	["The road from Elwynn enters Redridge at {area:1002}. {npc:464} stands where the roads to Redridge and {zone:1431} meet."] = "来自艾尔文森林的道路在{area:1002}进入赤脊山。{npc:464}站在通往赤脊山和{zone:1431}的道路交汇处。",
	["The {area:442} boat docks at {area:17203}. Walk up into the city for training and {npc:1646}, then leave by the main gate and follow the road east through {area:12}."] = "{area:442}的船停靠在{area:17203}。走进城里学技能并找{npc:1646}，然后从正门出城，沿路向东穿过{area:12}。",
	["Tram to {zone:1455}"] = "乘地铁前往{zone:1455}",
	["Use the {item:6866} on {npc:6172}"] = "对{npc:6172}使用{item:6866}",
	["While you're here: learn Polearms from {npc:11867} ({object:2096}, 1 gold); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "趁在这里：向{npc:11867}学习长柄武器（{object:2096}，1金）；猎人的近战武器主要提供属性，双手武器的属性最多。",
	["While you're here: learn Polearms from {npc:11867} ({object:2096}, 1 gold); two-handers level a Warrior fastest."] = "趁在这里：向{npc:11867}学习长柄武器（{object:2096}，1金）；双手武器让战士练级最快。",
	["{area:1001}: kill these as you meet them"] = "{area:1001}：遇到就杀",
	["{area:68}: kill these as you meet them"] = "{area:68}：遇到就杀",
	["{item:1075}: any Shadowhide gnoll"] = "{item:1075}：任何暗皮豺狼人",
	["{item:1130}: Pygmy Venom Web Spiders, Venom Web Spiders and Green Recluses"] = "{item:1130}：小型结网毒蜘蛛、结网毒蜘蛛和绿色隐士蛛",
	["{item:1309}; underwater"] = "{item:1309}；水下",
	["{item:1467} on the way"] = "{item:1467}，顺路",
	["{item:15882}: the {object:177790}"] = "{item:15882}：{object:177790}",
	["{item:280911}: Redridge Thrashers"] = "{item:280911}：赤脊山鞭笞者",
	["{item:281046}, from the {object:673515}"] = "{item:281046}，来自{object:673515}",
	["{item:4371}, from {npc:3133}, if you have none"] = "如果没有{item:4371}，向{npc:3133}购买",
	["{item:6846}: Defias Rogue Wizards"] = "{item:6846}：迪菲亚流浪巫师",
	["{npc:1646}: Thundris' letter from {area:442}"] = "{npc:1646}：来自{area:442}的桑迪斯的信",
	["{npc:2409}, at the north end of town"] = "{npc:2409}，在镇子北端",
	["{npc:264}, in the town hall"] = "{npc:264}，在市政厅",
	["{npc:266}, by the docks; upstairs"] = "{npc:266}，码头旁；楼上",
	["{npc:267}, in the town hall"] = "{npc:267}，在市政厅",
	["{npc:268}, in the house behind the town hall"] = "{npc:268}，在市政厅后面的房子里",
	["{npc:332} is at SI:7 in {object:2100}, {npc:6122} in the {object:2164}'s cellar in the {object:2101}, {npc:376} in the Cathedral of Light."] = "{npc:332}在{object:2100}的军情七处，{npc:6122}在{object:2101}{object:2164}的地下室，{npc:376}在光明大教堂。",
	["{npc:332}: {npc:7024} in {zone:1436} takes it, at the end of {zone:1431}"] = "{npc:332}：交给{zone:1436}的{npc:7024}，在{zone:1431}结束时",
	["{npc:341}: after {quest:89}"] = "{npc:341}：在{quest:89}之后",
	["{npc:343}, inside"] = "{npc:343}，室内",
	["{npc:344}, in the town hall"] = "{npc:344}，在市政厅",
	["{npc:349}, below ground"] = "{npc:349}，地下",
	["{npc:376}: {npc:11401} in {zone:1457} takes it, later"] = "{npc:376}：之后交给{zone:1457}的{npc:11401}",
	["{npc:376}: {npc:11406} in {zone:1455} takes it, later"] = "{npc:376}：之后交给{zone:1455}的{npc:11406}",
	["{npc:376}: {npc:258785} in {zone:1455} takes it, later"] = "{npc:376}：之后交给{zone:1455}的{npc:258785}",
	["{npc:435}, below ground"] = "{npc:435}，地下",
	["{npc:464} walks around {area:1002}: look inside the circle on the map"] = "{npc:464}在{area:1002}一带走动：看地图上圆圈里的位置",
	["{npc:6122}: {npc:6244} in the {zone:1413} takes it, later"] = "{npc:6122}：之后交给{zone:1413}的{npc:6244}",
	["{npc:663}, by the town hall"] = "{npc:663}，在市政厅旁",
	["{npc:6790}, Scarlet Raven Tavern"] = "{npc:6790}，Scarlet Raven Tavern",
	["{npc:903}, by the gryphons south of the bridge"] = "{npc:903}，在桥南的狮鹫旁",
	["{zone:1431} is next: follow the road west to {area:1002}, then south to {area:42}."] = "下一站是{zone:1431}：沿道路向西到{area:1002}，再向南到{area:42}。",
	["{zone:1453} class quests"] = "{zone:1453}职业任务",
	["{zone:1453} flight master"] = "{zone:1453}飞行管理员",
	["{zone:1453} has no shaman trainer: take the {area:2257} from the {object:28027} to {zone:1455}, train with {npc:258098}, then ride the tram back."] = "{zone:1453}没有萨满祭司训练师：从{object:28027}乘{area:2257}前往{zone:1455}，在{npc:258098}处学习，然后乘地铁返回。",
}

G["forever/alliance/05-duskwood"] = {
	["/lay down beside {npc:7207}"] = "在{npc:7207}旁边 /lay down",
	["Back to {area:42}"] = "回到{area:42}",
	["Cathedral of Light"] = "光明大教堂",
	["Class trainer"] = "职业训练师",
	["Continue west to {area:94}. The {object:673515} glows by the ruined house south of the road."] = "继续向西到{area:94}。{object:673515}在道路南边的废弃房屋旁发光。",
	["Every ghoul of the {area:492}'s northern half can drop a rib: Flesh Eaters, Bone Chewers, Plague Spreaders and Brain Eaters.\nCareful: A {npc:948} casts {spell:3428} as it dies, which brings extra adds."] = "{area:492}北半部的每个食尸鬼都可能掉落肋骨：食肉者、嚼骨者、瘟疫传播者和食脑者。\n小心：一个{npc:948}死亡时会施放{spell:3428}，会带来额外的怪。",
	["Fly to {zone:1453}"] = "飞往{zone:1453}",
	["Follow the road north-west past the cemetery to {npc:311}'s camp on the far west edge of the forest. {npc:893} stands beside {npc:311}."] = "沿道路向西北经过墓地，前往森林最西缘的{npc:311}营地。{npc:893}站在{npc:311}旁边。",
	["Follow the road south from {area:1002} into {area:10}; {area:42} lies on the east side of the forest."] = "从{area:1002}沿路向南进入{area:10}；{area:42}在森林东侧。",
	["Ghoul Ribs"] = "食尸鬼的肋骨",
	["Head back east along the road to the {area:245}."] = "沿路向东回到{area:245}。",
	["Head back east to {area:42}."] = "向东回到{area:42}。",
	["Head north through Elwynn to {zone:1453}; Mathias Shaw is at SI:7 in {object:2100}."] = "穿过艾尔文森林向北到{zone:1453}；马迪亚斯·肖尔在{object:2100}的军情七处。",
	["Head west along the road once more."] = "再次沿路向西。",
	["Head west along the road out of {area:94} into {area:40}. {npc:7024} watches {npc:7053}'s tower from the hills just inside the border. The {npc:7051} (level 23) guarding the tower carries its key; Klaven's journal is in the chest at the top."] = "沿路向西离开{area:94}进入{area:40}。{npc:7024}在边界内侧的山丘上监视{npc:7053}的塔楼。守卫塔楼的{npc:7051}（23级）身上带着钥匙；克拉文的手记在塔顶的箱子里。",
	["Head west to the hermit once more."] = "再次向西去找隐士。",
	["Her house stands on the hill south-east of {area:42}, above the {area:121}."] = "她的房子在{area:42}东南方的山上，{area:121}上方。",
	["Inside"] = "在里面",
	["Level 22 and 24 spells"] = "22级和24级法术",
	["Next: {zone:1453} for training, then the boat from {area:17203} to {area:442} for {zone:1440}."] = "下一步：去{zone:1453}训练，然后从{area:17203}乘船前往{area:442}，再去{zone:1440}。",
	["Nightbane Shadow Weaver"] = "夜行魔织影者",
	["No {item:4371} for {quest:174}? {npc:3133} sells it in the house beside {npc:276}, in limited stock; {npc:1448} in {area:150} sells it too.\n{npc:276}'s house stands at the east end of town. {npc:3133} sells engineering goods in the house beside it."] = "没有{item:4371}做{quest:174}？{npc:3133}在{npc:276}旁的房子里出售，存货有限；{area:150}的{npc:1448}也卖。\n{npc:276}的房子在小镇东端。{npc:3133}在它旁边的房子里卖工程学商品。",
	["Pygmy Venom Web Spider"] = "小毒网蜘蛛",
	["Rabid Dire Wolf"] = "狂躁凶狼",
	["Rabid Dire Wolves roam the woods around the cemetery and {npc:289}, Starving Dire Wolves the hills north-east of him. Pygmy Venom Web Spiders crawl east of the cemetery and drop the venom. Every ghoul of the cemetery's northern half can drop a fang.\nCareful: Wolves and other spider types share the area along the {area:40} border, so you can easily pull several mobs at once."] = "狂躁凶狼在墓地和{npc:289}周围的森林游荡，饥饿凶狼在他东北的山丘。小毒网蜘蛛在墓地东边爬行，掉落毒液。墓地北半部的每个食尸鬼都可能掉落獠牙。\n小心：狼和其他种类的蜘蛛共处{area:40}边界一带，很容易一次拉好几只怪。",
	["Rogue training"] = "潜行者训练",
	["Rot Blossoms"] = "腐败之花",
	["Shaman training"] = "萨满祭司训练",
	["Skeletal Fiend"] = "骷髅恶鬼",
	["Skeletal Horror"] = "骷髅恐魔",
	["Skeletal Horrors walk the hillside between {area:42} and the {area:121}, south-east of town; they drop the Rot Blossoms."] = "恐怖骸骨在{area:42}与{area:121}之间、镇子东南方的山坡上游荡；它们掉落腐败之花。",
	["Skeletal Mage"] = "骷髅法师",
	["Skeletal Warrior"] = "骷髅战士",
	["Skeletal Warriors and Skeletal Mages walk among the graves south-east of {area:42}, below {npc:302}'s house on the hill. Every skeleton in {area:10} can drop a {item:2378}.\nCareful: Because the skeletons stand near each other, running straight in tends to pull several at once."] = "骷髅战士和骷髅法师在{area:42}东南的坟墓间走动，位于山上{npc:302}的房子下方。{area:10}里的每个骷髅都可能掉落{item:2378}。\n小心：骷髅彼此站得很近，直接冲进去往往会一次拉好几只。",
	["Starving Dire Wolf"] = "饥饿凶狼",
	["The cemetery lies north of the village. Skeletal Horrors and Skeletal Fiends walk its southern half. {npc:522}, an elite, wanders the graves: keep away from him."] = "墓地位于村子北边。恐怖骸骨和骸骨魔在墓地南半部游荡。精英{npc:522}在墓地间徘徊：离他远点。",
	["The hermit's shack stands in the woods north-east of the {area:492}."] = "隐士的小屋在{area:492}东北方的树林里。",
	["The mound of loose dirt lies south of the farmhouse, by the old stump."] = "松土堆在农舍南边的老树桩旁。",
	["Train here, in {zone:1453}, before you go on."] = "继续之前，先在{zone:1453}这里训练。",
	["Tram to {zone:1455}"] = "乘地铁前往{zone:1455}",
	["{area:108} flight master"] = "{area:108}飞行管理员",
	["{area:1097}: kill these as you meet them"] = "{area:1097}：遇到就杀",
	["{area:121}: kill these as you meet them"] = "{area:121}：遇到就杀",
	["{area:492}: kill these as you meet them"] = "{area:492}：遇到就杀",
	["{item:281046}, from the {object:673515}"] = "{item:281046}，来自{object:673515}",
	["{item:3372}: {npc:1313}, Alchemy Supplies"] = "{item:3372}：{npc:1313}，炼金用品",
	["{item:4371}, from {npc:3133}, if you have none"] = "若没有{item:4371}，找{npc:3133}买",
	["{item:4371}, from {npc:3133}: limited stock. Sold out? {npc:1448} in {area:150} sells it too."] = "{item:4371}，向{npc:3133}购买：存货有限。卖完了？{area:150}的{npc:1448}也有售。",
	["{item:7908}, in the chest"] = "{item:7908}，在箱子里",
	["{npc:202} on the way"] = "路上找{npc:202}",
	["{npc:2409}, at the north end of town"] = "{npc:2409}，在镇子北端",
	["{npc:264}, in the town hall"] = "{npc:264}，在市政厅",
	["{npc:265}, in her house by the tavern; inside"] = "{npc:265}，在旅店旁她的房子里；室内",
	["{npc:265}, inside"] = "{npc:265}，室内",
	["{npc:267}, in the town hall"] = "{npc:267}，在市政厅",
	["{npc:268}, in the house behind the town hall"] = "{npc:268}，在市政厅后面的房子里",
	["{npc:268}, inside"] = "{npc:268}，室内",
	["{npc:273}, in the tavern"] = "{npc:273}，在酒馆里",
	["{npc:276}, inside"] = "{npc:276}，室内",
	["{npc:288} hides in the house at the west end of {area:94}."] = "{npc:288}躲在{area:94}西端的房子里。",
	["{npc:332}: Poisons, and {item:18160}"] = "{npc:332}：毒药，以及{item:18160}",
	["{npc:531} on the way"] = "路上找{npc:531}",
	["{npc:533} on the way"] = "路上找{npc:533}",
	["{npc:6171}: Redemption"] = "{npc:6171}：救赎",
	["{npc:6173} and {npc:6171} are in the Cathedral of Light."] = "{npc:6173}和{npc:6171}在光明大教堂。",
	["{npc:633}, at the south end of town; inside"] = "{npc:633}，在小镇南端；室内",
	["{npc:663}, by the town hall"] = "{npc:663}，在市政厅旁",
	["{npc:6790}, Scarlet Raven Tavern"] = "{npc:6790}，Scarlet Raven Tavern",
	["{npc:888} stands south of the road, at the {area:245}."] = "{npc:888}站在道路南边的{area:245}。",
	["{quest:2607}: {npc:7207}, in the cellar of the Barracks"] = "{quest:2607}：{npc:7207}，在兵营地下室",
	["{quest:337}: a rare drop from {area:10}'s mobs"] = "{quest:337}：{area:10}怪物的稀有掉落",
