G["forever/alliance/06-ashenvale"] = {
	["A new {item:279996}, for the four titan watchers around the {zone:1437}; below ground"] = "新增的{item:279996}，用于{zone:1437}周围的四个泰坦守望者；地下",
	["Below ground"] = "地下",
	["Black, Crimson and Monstrous Oozes fill {area:309}, just west of the road to {area:205} and north of Einar's camp. Any ooze there may hold {npc:2111}'s bag.\nMosshide Fenrunners and Mistweavers roam the riverbanks just west and south of {npc:1244}; almost every one drops flint."] = "黑泥怪、赤红泥怪和畸形泥怪遍布{area:309}，就在通往{area:205}的路西、埃纳尔营地以北。那里的任何泥怪都可能带着{npc:2111}的袋子。\n苔皮沼泽奔行者与迷雾编织者在{npc:1244}以西和以南的河岸游荡；几乎每只都掉燧石。",
	["Bluegill Murloc"] = "蓝鳃鱼人",
	["Boat to {area:150}"] = "乘船前往{area:150}",
	["Cast {spell:18960}"] = "施放{spell:18960}",
	["Cathedral of Light"] = "光明大教堂",
	["Cave Stalkers and Leech Stalkers fill {area:1021}, the cave south-east of the excavation site."] = "{area:1021}是挖掘场东南方的洞穴，里面满是洞穴捕猎者和吸血捕猎者。",
	["Escort {npc:11218} to {area:413} in {area:331}."] = "护送{npc:11218}到{area:331}中的{area:413}。",
	["Fen Creeper"] = "沼泽爬行者",
	["Fly to {area:442}"] = "飞往{area:442}",
	["Fly to {area:702}"] = "飞往{area:702}",
	["Follow the coast north out of Menethil. Bluegill Murlocs fill the marsh; {npc:1259} walks with a pack in the middle of it."] = "沿海岸向北离开米奈希尔港。沼泽里满是蓝腮鱼人；{npc:1259}带着一群鱼人在沼泽中间游荡。",
	["Follow the coast north to the {area:414}. {npc:3846} camps on the beach; Wrathtail nagas fill the shore."] = "沿海岸向北到{area:414}。{npc:3846}在海滩上扎营；岸边满是怒尾纳迦。",
	["Follow the road east to the {area:419}; {npc:3916} stands by the moonwell.\nThe moonwell lies in the hills north-east of {area:415}."] = "沿路向东到{area:419}；{npc:3916}站在月亮井旁。\n月亮井位于{area:415}东北的丘陵中。",
	["Follow the road east. Young Wetlands Crocolisks lurk in the pools north of the excavation site."] = "沿道路向东。{npc:1417}潜伏在挖掘场北边的水塘里。",
	["For Bolvar Fordragon in {object:2117}: keep it"] = "交给{object:2117}的伯瓦尔·弗塔根公爵：先留着",
	["For the giant crocolisks of the north coast, on your next visit"] = "留给北部海岸的巨型湿地鳄鱼，下次来时完成",
	["For {npc:2228} in {area:271}: keep it"] = "交给{area:271}的{npc:2228}：先留着",
	["For {npc:2916} in {zone:1455}, at the end of this guide"] = "交给{zone:1455}的{npc:2916}，在本指南末尾",
	["Foulweald Den Watcher"] = "邪林巢穴看守",
	["Foulweald Totemic"] = "邪林图腾师",
	["Foulweald Ursa"] = "邪林巨熊",
	["Foulweald Warrior"] = "邪林战士",
	["From {area:17203} take the boat to {area:442}; {npc:3649} stands at the north end of the village. Then head south along the road through {zone:1439}."] = "从{area:17203}乘船到{area:442}；{npc:3649}站在村子北端。然后沿路向南穿过{zone:1439}。",
	["Head east along the {zone:1437} road, south through {area:836} into {zone:1432} and west through the tunnel into {zone:1426} to {area:1537}."] = "沿{zone:1437}的路向东，向南穿过{area:836}进入{zone:1432}，再向西穿过隧道进入{zone:1426}到{area:1537}。",
	["Head south past {area:421} into the {area:1276} tunnel; it comes out in Stonetalon's {area:461}. {npc:4080} and {npc:4077} camp on the {area:1076} south-west of the crag."] = "向南经过{area:421}进入{area:1276}隧道；出口在石爪山的{area:461}。{npc:4080}和{npc:4077}在峭壁西南的{area:1076}扎营。",
	["Head west to the shore of {area:441}. Teronis lies among the Saltspittle murlocs; any murloc can drop the {item:5463}."] = "向西到{area:441}的岸边。特罗尼斯躺在盐沫鱼人中间；任何鱼人都可能掉落{item:5463}。",
	["Inside"] = "在里面",
	["Into {zone:1426}"] = "进入{zone:1426}",
	["Into {zone:1432}"] = "进入{zone:1432}",
	["Into {zone:1455}"] = "进入{zone:1455}",
	["Into {zone:1457}"] = "进入{zone:1457}",
	["Kill the elementals for 5 Intact Elemental Bracers, then use the {item:5456}"] = "击杀元素获得5个完整的元素护腕，然后使用{item:5456}",
	["Melyria and {npc:3901}"] = "梅莉里亚和{npc:3901}",
	["Menethil"] = "米奈希尔",
	["Mosshide Gnoll"] = "苔皮豺狼人",
	["Mosshide Gnolls and Mongrels hold the hills south-east of the {area:1025}."] = "藓皮豺狼人和混血藓皮豺狼人占据着{area:1025}东南方的山丘。",
	["Mosshide Mongrel"] = "苔皮杂种",
	["Mottled Raptor"] = "斑纹迅猛龙",
	["Mottled Raptors and Screechers roam the hills west of the excavation site.\nCareful: Once a {npc:1021} drops to 30% health, it calls for help from creatures within 20 yd. Mottled Screechers frequently come in packs of three, and raptors summoned by their calls for help may also join the fight."] = "斑纹迅猛龙和尖啸者在挖掘场以西的丘陵游荡。\n注意：{npc:1021}一旦血量降到30%，就会呼叫20码内的生物来帮忙。斑纹尖啸者常常三只一群，被呼救引来的迅猛龙也可能加入战斗。",
	["Mottled Razormaw"] = "斑纹镰颚龙",
	["Mottled Screecher"] = "斑纹尖啸者",
	["Mottled Scytheclaw"] = "斑纹镰爪龙",
	["Next: fly to {area:42}."] = "下一步：飞往{area:42}。",
	["North of Maestra's Post, plant bundles lie around the ruins of {area:411}. Dark Strand cultists hold the ruins just south of them: any of them can drop the {item:5366}."] = "在迈斯特拉岗哨以北，{area:411}的废墟周围散落着植物束。暗滩教徒占据着其南边的废墟：任何一个都可能掉落{item:5366}。",
	["Only if you looted {quest:337} in {zone:1431}"] = "仅当你在{zone:1431}拾取了{quest:337}",
	["Only with {item:5352} from {zone:1439}: {npc:2786}, the {object:32383}"] = "仅当有来自{zone:1439}的{item:5352}：{npc:2786}，{object:32383}",
	["Raptor valley"] = "迅猛龙山谷",
	["Red whelps fill the hills west of the gates, Maddened Rotclaws the {area:1025}, Razormaws the northern slopes; Neru stands in the north-east (use the {item:279996}).\n{quest:98283} is elite: grouping up is advised.\nFen Creepers hide in the marsh pools north-west of the {area:1025}.\nCareful: When out of combat, Fen Creepers cast Sneak from time to time, so they are stealthed and hard to see."] = "红色幼龙遍布大门以西的丘陵，发狂的腐爪龙占据{area:1025}，镰颚龙在北坡；内鲁站在东北（使用{item:279996}）。\n{quest:98283}是精英任务：建议组队。\n沼泽爬行者藏在{area:1025}西北的沼泽水塘里。\n注意：脱离战斗时，沼泽爬行者会不时施放潜行，所以它们处于潜行状态，很难发现。",
	["Take the boat from {area:17203} to {area:442}. Join the two half pendants into the {item:15885} and cast {spell:18960}: {npc:11802} is in {area:2361}. Then {npc:11800} in {area:2361} flies Druids straight to {area:702}. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "从{area:17203}乘船到{area:442}。把两半吊坠合成{item:15885}并施放{spell:18960}：{npc:11802}在{area:2361}。然后{area:2361}的{npc:11800}会把德鲁伊直接飞到{area:702}。{npc:11802}站在他所在建筑的楼上：从里面上去，箭头分不清楼层。",
	["Take the portal up to the {area:1658}, then fly back to {area:442}."] = "乘传送门上到{area:1658}，然后飞回{area:442}。",
	["Take the {area:2257} from {object:171524} to {zone:1453}'s {object:28027}, then walk to the {object:2098}."] = "从{object:171524}乘{area:2257}前往{zone:1453}的{object:28027}，然后步行到{object:2098}。",
	["The Bluegill hovels"] = "蓝腮鱼人小屋",
	["The Foulweald"] = "污林",
	["The Foulweald furbolgs live in the woods south of the road, south-east of {area:415}. The Den Watcher and the Ursas guard the den."] = "污林熊怪住在道路南边、{area:415}东南方的树林里。污林卫兵和污林巨熊怪守卫着洞穴。",
	["The Mosshide gnolls"] = "藓皮豺狼人",
	["The Venture Co. clear the forest of {area:461}. Loggers and Deforesters work all over it; the Operators run the shredders and one carries the blueprints."] = "风险投资公司正在砍伐{area:461}的森林。风险投资公司樵夫和风险投资公司砍树工遍布各处；风险投资公司操作员驾驶伐木机，其中一个带着蓝图。",
	["The bigger raptors hunt in the valley just west of the dig."] = "更大的迅猛龙在挖掘场西边的山谷里捕猎。",
	["The excavation site sits on the hill south of the road."] = "挖掘场位于道路南边的山丘上。",
	["The raptor hills"] = "迅猛龙山丘",
	["The tears glow on the small isle east of {area:415}."] = "泪滴在{area:415}东边的小岛上发光。",
	["The two stand together at the western end of the road.\nSouth of the murlocs, {npc:3585} waits at the {area:416}."] = "两人并肩站在路的西端。\n在鱼人以南，{npc:3585}在{area:416}等着。",
	["Three containers in the murloc hovels, south to north: the {object:261}, then the {object:142151}, then the {object:259} at the north end."] = "鱼人小屋里的三个容器，从南到北：{object:261}，然后是{object:142151}，最后是北端的{object:259}。",
	["Timber and iron piles lie around the keep and along the harbor's walls."] = "木材堆和铁堆散落在城堡周围和港口城墙沿线。",
	["To {area:150}"] = "前往{area:150}",
	["Tram to {zone:1453}"] = "乘地铁前往{zone:1453}",
	["Underwater"] = "水下",
	["Venture Co. Deforester"] = "风险投资公司毁林者",
	["Venture Co. Logger"] = "风险投资公司伐木工",
	["West of Mystral Lake, the stardust bushes grow among the ruins."] = "在密斯特拉湖以西，星尘覆盖的草丛生长在废墟中。",
	["While you're here: learn {spell:197} from {npc:11865} ({object:32359}, 10 silver); two-handers level a Paladin fastest."] = "趁在这里：向{npc:11865}学习{spell:197}（{object:32359}，10银）；双手武器让圣骑士升级最快。",
	["While you're here: learn {spell:197} from {npc:11865} ({object:32359}, 10 silver); two-handers level a Warrior fastest."] = "趁在这里：向{npc:11865}学习{spell:197}（{object:32359}，10银）；双手武器让战士升级最快。",
	["While you're here: learn {spell:199} from {npc:11865} ({object:32359}, 10 silver); two-handers level a Warrior fastest."] = "趁在这里：向{npc:11865}学习{spell:199}（{object:32359}，10银）；双手武器让战士升级最快。",
	["Young crocolisks"] = "幼年鳄鱼",
	["{area:1025}: kill these as you meet them"] = "{area:1025}：遇到就杀",
	["{area:411}: kill these as you meet them"] = "{area:411}：遇到就杀",
	["{area:415} flight master"] = "{area:415}飞行管理员",
	["{area:442} flight master"] = "{area:442}飞行管理员",
	["{area:461}: kill these as you meet them"] = "{area:461}：遇到就杀",
	["{item:15885}: join the two halves"] = "{item:15885}：合并两块碎片",
	["{item:5424}, in the ruins on the shore"] = "{item:5424}，在岸边的废墟里",
	["{npc:1076}, below ground"] = "{npc:1076}，地下",
	["{npc:11218} sleeps at the {area:448} in southern {zone:1439}. Use the {item:13536} to wake him and lead him south along the road into {area:331} to {npc:11219} at {area:413}; blow the horn again whenever he falls asleep.\nCareful: Scripted ambushes of three mobs each attack along the road: furbolgs on the {zone:1439} stretch and undead nearer {area:413}."] = "{npc:11218}睡在{zone:1439}南部的{area:448}。用{item:13536}唤醒他，沿路向南把他带进{area:331}，到{area:413}的{npc:11219}那里；他每次睡着时就再吹一次号角。\n注意：路上会有三只怪一组的脚本伏击：{zone:1439}那段是熊怪，靠近{area:413}时是亡灵。",
	["{npc:11406} and {npc:258785} are in the {object:32386}, in the {object:32362}."] = "{npc:11406}和{npc:258785}在{object:32362}的{object:32386}。",
	["{npc:1217}, upstairs in the inn"] = "{npc:1217}，旅店楼上",
	["{npc:1239}, in the inn"] = "{npc:1239}，在旅店里",
	["{npc:1242}, on the pier north of the inn"] = "{npc:1242}，在旅店北边的码头上",
	["{npc:1242}: for {npc:2104} in the keep"] = "{npc:1242}：交给城堡里的{npc:2104}",
	["{npc:1244}: {quest:98283}, an elite raptor"] = "{npc:1244}：{quest:98283}，一只精英迅猛龙",
	["{npc:1440}, in the Royal Library"] = "{npc:1440}，在皇家图书馆",
	["{npc:1444}, in the {object:2098}"] = "{npc:1444}，在{object:2098}",
	["{npc:1480}, inside"] = "{npc:1480}，室内",
	["{npc:1573}, in the {object:32372}"] = "{npc:1573}，在{object:32372}",
	["{npc:2086}, by the keep; inside"] = "{npc:2086}，要塞旁；室内",
	["{npc:2092}'s quest in {zone:1455} needs level 28. If you are short of it after these hand-ins, grind the Dragonmaw orcs at the camps along the road east to {area:836} before you go on."] = "{npc:2092}在{zone:1455}的任务需要28级。如果这些任务交完还差一点，先沿东去{area:836}的路在营地里刷龙喉兽人，再继续。",
	["{npc:2093} camps by the road; {npc:1244} stands farther east, by the river."] = "{npc:2093}在路边扎营；{npc:1244}站在更东边的河旁。",
	["{npc:2094} stands by the north gate."] = "{npc:2094}站在北门旁。",
	["{npc:2094}, by the north gate"] = "{npc:2094}，在北门旁",
	["{npc:2096}, by the north gate"] = "{npc:2096}，在北门旁",
	["{npc:2096}: he won't offer 305 while you carry it"] = "{npc:2096}：你带着305时，他不会给你任务",
	["{npc:2097}, by the north gate"] = "{npc:2097}，在北门旁",
	["{npc:2104}, by the keep"] = "{npc:2104}，要塞旁",
	["{npc:2104}, on the top floor"] = "{npc:2104}，在顶层",
	["{npc:210995} may not offer these to every class; if he doesn't, carry on.; walks around {area:1276}: the map marks where to look"] = "{npc:210995}可能不会对每个职业提供这些任务，若没有就继续。；他在{area:1276}一带走动：地图上标出了查看位置",
	["{npc:3649}: Alexston's reply, if you took it in {zone:1453}"] = "{npc:3649}：亚历克斯顿的回信，如果你在{zone:1453}接了它",
	["{npc:3664} and his voidwalkers hold the {area:412} south of the shrine. Pull his guards first."] = "{npc:3664}和他的虚空行者占据着神殿南边的{area:412}。先拉他的卫兵。",
	["{npc:3691}, in the inn"] = "{npc:3691}，在旅店里",
	["{npc:376}: {npc:11401} in {zone:1457} takes it, later"] = "{npc:376}：之后交给{zone:1457}的{npc:11401}",
	["{npc:376}: {npc:11406} in {zone:1455} takes it, later"] = "{npc:376}：之后交给{zone:1455}的{npc:11406}",
	["{npc:376}: {npc:258785} in {zone:1455} takes it, later"] = "{npc:376}：之后交给{zone:1455}的{npc:258785}",
	["{npc:3885} stands at the {area:420} on the east shore of {area:421}; {npc:210995} camps on its west shore. Befouled Water Elementals wade in the lake between them."] = "{npc:3885}站在{area:421}东岸的{area:420}；{npc:210995}在湖的西岸扎营。污浊的水元素在两者之间的湖里涉水。",
	["{npc:3894}, inside"] = "{npc:3894}，室内",
	["{npc:3970}: for {npc:1480} in Menethil, at the end of this guide; inside"] = "{npc:3970}：交给米奈希尔的{npc:1480}，在本指南末尾；室内",
	["{npc:3987} (25) leads the Thistlefur furbolgs at the camp north of {area:415}. Clear his guards first, one at a time.\nCareful: The furbolgs near him usually join in when he is pulled. Killing the ones along his path first lets you fight him alone."] = "{npc:3987}（25级）率领{area:415}以北营地的蓟皮熊怪。先清掉他的守卫，一只一只来。\n注意：拉他时，附近的熊怪通常会加入。先杀掉他路径上的那些，就能单独与他交战。",
	["{npc:4201}, in the hut north of them; inside"] = "{npc:4201}，在他们北边的小屋里；室内",
	["{npc:4201}, inside"] = "{npc:4201}，在里面",
	["{npc:4276} mines in the {area:2160} at the east end of the crag. Talk to him and fend off the Venture Co. raiders while he mines.\nCareful: The kobolds arrive in waves. The first wave is melee fighters, and the second adds casters to the mix. Regular mobs in the mine respawn quickly and can join the fight while the waves are coming. A group is recommended."] = "{npc:4276}在峭壁东端的{area:2160}挖矿。与他交谈，并在挖矿时击退风险投资公司的袭击者。\n注意：狗头人成波出现。第一波是近战，第二波会增加施法者。矿洞里的普通怪刷新很快，波次来临时可能加入战斗。建议组队。",
	["{npc:482}, the cheese shop in the {object:2096}"] = "{npc:482}，在{object:2096}的奶酪店",
	["{npc:4959} and {npc:482}"] = "{npc:4959}和{npc:482}",
	["{npc:4982}, in the Cathedral of Light"] = "{npc:4982}，在光明大教堂",
	["{npc:5082}, Mikhail and Tapoke Jahn are all at Menethil's inn; Tapoke fights you when you talk to Mikhail, but gives up once beaten. {npc:1480} stands a short walk north-east of the inn.\n{npc:2104} stands in {area:2103}, a short walk from {npc:1242}.\n{npc:2104} stands in {area:2103}."] = "{npc:5082}、米哈伊尔和塔波克·扬都在米奈希尔的旅店里；与米哈伊尔交谈时塔波克会攻击你，但被打败后就会停手。{npc:1480}站在旅店东北不远的地方。\n{npc:2104}站在{area:2103}，离{npc:1242}不远。\n{npc:2104}站在{area:2103}。",
	["{npc:6122}: {npc:6244} in the {zone:1413} takes it, later"] = "{npc:6122}：之后交给{zone:1413}的{npc:6244}",
	["{object:176634}, beside him"] = "{object:176634}，在他身旁",
	["{object:2164} is in the {object:2101}."] = "{object:2164}在{object:2101}。",
	["{quest:1009} walks the northern tip of the {area:414} with Wrathtail guards."] = "{quest:1009}带着怒尾卫兵在{area:414}北端巡逻。",
	["{quest:1010}, from the plant bundles"] = "{quest:1010}，来自植物束",
	["{zone:1437}: kill these as you meet them"] = "{zone:1437}：遇到就杀",
	["{zone:1455} priests"] = "{zone:1455}的牧师",
}

G["forever/alliance/06-wetlands"] = {
	["Back to the Cathedral of Light: {npc:928} stands inside."] = "回到光明大教堂：{npc:928}站在里面。",
	["Cathedral of Light"] = "光明大教堂",
	["Dartol's Rod"] = "达图尔的变形魔棒",
	["For Bolvar Fordragon in {object:2117}: keep it"] = "交给{object:2117}的伯瓦尔·弗塔根公爵：先留着",
	["Insane druids"] = "发狂的德鲁伊",
	["Inside"] = "在里面",
	["Melyria and {npc:3901}"] = "哨兵梅丽瑞亚·霜影和{npc:3901}",
	["Only if you looted {quest:337} in {zone:1431}"] = "仅当你在{zone:1431}拾取了{quest:337}",
	["Raptor valley"] = "迅猛龙山谷",
	["The Bluegill hovels"] = "蓝腮鱼人小屋",
	["The Crazed and Withered Ancients north of the moonwell carry the {item:5475}; the worn chest it opens stands among them."] = "月亮井北边的疯狂的古树和干枯的古树带着{item:5475}；它能打开的旧箱子就在它们中间。",
	["The captain walks the deck of the wrecked ship; his strongbox sits in the hold."] = "船长在沉船甲板上走动；他的保险箱在货舱里。",
	["The relics lie in the dig itself. {npc:1353}, a big Razormaw, prowls the raptor valley just west of it."] = "圣物就在挖掘场里。{npc:1353}是一只大型刺喉龙，在挖掘场西边不远的迅猛龙山谷中徘徊。",
	["The shrine sits on the hill just south-east of the moonwell; follow the winding path up."] = "隐蔽的神龛在月亮井东南方不远处的山丘上；沿蜿蜒的小路上去。",
	["{item:15885}: join the two halves"] = "{item:15885}：合并两块碎片",
