	["{area:301}: kill these as you meet them"] = "{area:301}：遇到就杀",
	["{area:33}: kill these as you meet them"] = "{area:33}：遇到就杀",
	["{area:35} flight master"] = "{area:35}飞行管理员",
	["{item:2006}: {object:58}; underwater"] = "{item:2006}：{object:58}；水下",
	["{item:2634}, from a {object:263} crate"] = "{item:2634}，来自{object:263}箱子",
	["{npc:2495}, by the bank; inside"] = "{npc:2495}，在银行旁；室内",
	["{npc:2495}, inside"] = "{npc:2495}，室内",
	["{npc:2496}, upstairs in the tavern"] = "{npc:2496}，在旅店楼上",
	["{npc:2498}, inside"] = "{npc:2498}，室内",
	["{npc:2832}, in the {object:56910}; upstairs"] = "{npc:2832}，在{object:56910}内；楼上",
	["{npc:469}, in the hut"] = "{npc:469}，在小屋里",
	["{npc:6807}, {object:56910}; upstairs"] = "{npc:6807}，{object:56910}；楼上",
	["{npc:687} on the way"] = "路上有{npc:687}",
	["{npc:715}, from {zone:1441}"] = "{npc:715}，来自{zone:1441}",
	["{npc:716} collects the {item:2755}: the pages drop from almost every humanoid in the jungle. Turn the pages into chapters as you go."] = "{npc:716}收集{item:2755}：丛林中几乎所有人型怪都会掉落书页。边走边把书页合成章节。",
	["{npc:729} and the Lashtail raptors"] = "{npc:729}和鞭尾迅猛龙",
	["{npc:729}, the great tiger, lairs on the hilltop south-west of the camp; Lashtail Raptors run south of it, along the way to {area:35}."] = "大老虎{npc:729}的巢穴在营地西南方的山顶；鞭尾迅猛龙在其南边、通往{area:35}的路上奔跑。",
	["{npc:737}, in the tavern"] = "{npc:737}，在旅店里",
	["{npc:737}, upstairs"] = "{npc:737}，楼上",
	["{npc:770}: for {npc:773} in {area:35}"] = "{npc:770}：交给{area:35}的{npc:773}",
	["{npc:773}, in the tavern; upstairs"] = "{npc:773}，在旅店内；楼上",
	["{npc:773}, upstairs"] = "{npc:773}，楼上",
	["{npc:941}, below ground"] = "{npc:941}，地下",
	["{object:287}, upstairs"] = "{object:287}，楼上",
	["{object:288}, below ground"] = "{object:288}，地下",
	["{object:56910} is the tall building over the harbour; most of the quest givers are on its floors or the docks below."] = "{object:56910}是港口上方的高楼；大多数任务发布者都在楼内各层或下方码头。",
	["{quest:201}: just look around the hunters' camp"] = "{quest:201}：在猎人营地四处看看即可",
	["{zone:1455} has no druid trainer: take the {area:2257} from {object:171524} to {zone:1453} and train with {npc:5504}."] = "{zone:1455}没有德鲁伊训练师：从{object:171524}乘{area:2257}到{zone:1453}，找{npc:5504}学习。",
}

G["forever/alliance/30-40/04b-stranglethorn-vale"] = {
	["For Archmage Ansirem in {zone:1416}"] = "交给{zone:1416}的大法师安斯雷姆",
	["Skullsplitter trolls"] = "劈颅巨魔",
	["Snapjaw Crocolisks"] = "钳嘴鳄鱼",
	["The Skullsplitter trolls hold the ruins east of the road between Nesingwary and {object:3202}."] = "劈颅巨魔占据奈辛瓦里和{object:3202}之间道路东边的废墟。",
	["The jungle ruins"] = "丛林废墟",
	["{npc:2496}, upstairs in the tavern"] = "{npc:2496}，在旅店楼上",
}

G["forever/alliance/30-40/05-arathi-highlands"] = {
	["A {npc:2434} lurks unseen on the edge of {area:271}; kill him and read the contract he carries."] = "一名{npc:2434}隐身潜伏在{area:271}边缘；杀死他并阅读他携带的合同。",
	["Argus Shadow Mage"] = "阿古斯暗影法师",
	["Back west through {zone:1430} to {area:42}."] = "向西穿过{zone:1430}回到{area:42}。",
	["Below ground"] = "地下",
	["Careful: Syndicate Spies and Assassins can be stealthed. Assassins also poison you.\nCareful: About three stealthed Syndicate mobs are inside {npc:2320}'s house. {npc:2320} does not join when they are pulled, and a ranged attack through the doorway brings him out by himself."] = "注意：辛迪加间谍和刺客可能处于潜行。刺客还会对你下毒。\n注意：{npc:2320}的屋里有大约三个潜行的辛迪加怪物。拉它们时{npc:2320}不会加入战斗，隔着门口用远程攻击可以把他单独引出来。",
	["Crushridge ogres"] = "破碎岭食人魔",
	["Daggerspine Raider"] = "刺脊袭击者",
	["Daggerspine Sorceress"] = "刺脊女巫",
	["Each key lies at one of the Highlands' standing-stone circles: east of the shards, near {area:320} and in the west. The {object:2702} stands west of {area:320}.\nCareful: Each center stone is guarded by around three elementals near level 39 that attack together if you click the stone without clearing them: Burning Exiles at West, Thundering Exiles at Outer, Cresting Exiles at East."] = "每把钥匙都在高地的一处立石阵：碎片东边、{area:320}附近和西边。{object:2702}立在{area:320}西侧。\n注意：每根中央石柱旁都有大约三个39级左右的元素守卫，不先清掉就点石柱会被它们一起攻击：西边是燃烧的流放者，外圈是雷霆流放者，东边是涌潮流放者。",
	["East along the road to the {area:76}. {npc:256028} mobs drop the crystals; Noboru walks the ruins and drops his cudgel."] = "沿道路向东前往{area:76}。{npc:256028}怪物掉落水晶；木棒诺博鲁在废墟中游走，会掉落他的木棒。",
	["Ebenezer Rustlocke"] = "埃比尼泽·锈锁",
	["Escort the professor to the beach north of the cove and guard him while he works; naga attack in waves.\nCareful: The ambush is two level 40 water elementals, and they are immune to frost. If the fight happens inside the cave, the professor joins in instead of working and further elementals keep appearing; holding the elementals at the cave entrance, away from him, lets him finish with only the first two to deal with."] = "护送教授到海湾以北的沙滩，并在他工作时守护他；纳迦会一波波来袭。\n注意：伏击是两个40级的水元素，且免疫冰霜。如果战斗发生在洞内，教授会参战而不工作，还会不断出现更多水元素；把水元素挡在洞口、远离他，他就能只对付最初那两个并完成工作。",
	["Fly to {area:271}"] = "飞往{area:271}",
	["Fly to {area:42}"] = "飞往{area:42}",
	["Fly to {zone:1453}"] = "飞往{zone:1453}",
	["Follow the road east out of {area:287} over {area:1057} to {area:320}."] = "沿道路向东离开{area:287}，越过{area:1057}前往{area:320}。",
	["Follow the road north out of {area:271} into the mountains. Mountain lions roam the slopes; the Syndicate in {area:280} wear the signet rings, and {npc:2306} walks the manor grounds on the north side of town."] = "沿路向北离开{area:271}进入山区。山地狮在坡上游荡；{area:280}的辛迪加成员戴着印章戒指，{npc:2306}在小镇北侧的庄园里走动。",
	["Follow the road north to the draenei of the {area:657}."] = "沿道路向北前往{area:657}的德莱尼人处。",
	["For {npc:1440} in {zone:1453}: keep it"] = "交给{zone:1453}的{npc:1440}：保留它",
	["For {npc:2487} in {area:35}: keep it"] = "交给{area:35}的{npc:2487}：保留它",
	["For {npc:2542} in {area:35}: keep it"] = "交给{area:35}的{npc:2542}：保留它",
	["For {npc:2711} in {area:271}"] = "交给{area:271}的{npc:2711}",
	["From {zone:1455} take the tunnel east through {zone:1426} into {area:38} and follow the road to {area:144}."] = "从{zone:1455}经隧道向东穿过{zone:1426}进入{area:38}，再沿路前往{area:144}。",
	["Hay Weevil"] = "干草象鼻虫",
	["Head back north-east past {area:320}; {npc:2712} and {npc:2713} camp in the hills north of {area:314}."] = "向东北返回，经过{area:320}；{npc:2712}和{npc:2713}在{area:314}以北的丘陵扎营。",
	["Head north past {area:314}; the shards glitter on the hill by the {area:333}."] = "向北经过{area:314}；碎片在{area:333}旁的山丘上闪闪发光。",
	["Hulking Mountain Lion"] = "壮硕山地狮",
	["Inside"] = "在里面",
	["Mountain Lion"] = "山地狮",
	["Only if Gluggle gave you the pendant in Stranglethorn"] = "仅当格鲁高在荆棘谷给了你坠饰时",
	["Phizzlethorpe"] = "菲兹索普教授",
	["Shadowy Assassin"] = "暗影刺客",
	["Sorrow Spinner"] = "悲伤纺丝蛛",
	["South-east along the loch to the dig site."] = "沿湖向东南前往挖掘场（铁环挖掘场）。",
	["South-west to the Kirin Tor camp on the lake shore west of {area:279}, just over the border into {area:130}: the {npc:269127} stands there. Archmage Ansirem stands south-east of it, by the dome."] = "向西南前往{area:279}以西湖岸的肯瑞托营地，刚过边界进入{area:130}：{npc:269127}就立在那里。大法师安斯雷姆站在它东南侧、圆顶旁。",
	["Stay with {npc:2713} while she sneaks into {area:314} and back; Horde orcs jump you on the way.\nCareful: Orcs that drop to low health run away. {npc:2713} follows them and can pull more mobs, so kill or slow runners fast."] = "跟着{npc:2713}，她潜行进入{area:314}再返回；部落兽人会在途中伏击你。\n注意：残血的兽人会逃跑。{npc:2713}会追上去，可能多拉怪，所以要迅速杀死或减速逃跑者。",
	["Subdue the succubus"] = "制服魅魔",
	["Summoned Incubus"] = "被召唤的男魅魔",
	["Swamp Jaguar"] = "沼泽美洲豹",
	["Syndicate Highwayman"] = "辛迪加路霸",
	["Syndicate Mercenary"] = "辛迪加雇佣兵",
	["The Crushridge ogres hold the hills north of {area:280}. Farther north, a worn wooden chest holds the {item:3706}; {npc:2320} of the {quest:537} stands right by it."] = "破碎岭食人魔占据着{area:280}以北的山丘。再往北，一个破旧的木箱里装着{item:3706}；{quest:537}的{npc:2320}就站在旁边。",
	["The Drywhisker kobolds dig in the gorge east of {area:321} (Horde); skirt the town to the north. They drop both the motes and Krazek's ore.\nCareful: Every kobold type runs off for help when low on health (Kobolds at 30%, Surveyors and Diggers at 15%), which can pull more of them."] = "枯须狗头人在{area:321}以东的峡谷里挖掘（部落区域）；从北边绕过小镇。它们既掉密斯莱尔之尘，也掉克拉兹克的矿石。\n注意：所有狗头人残血时都会跑去求援（狗头人30%，勘测员和掘地工15%），可能引来更多同类。",
	["The Syndicate hold the farm north-west of {area:320}. A {npc:217589} crawls about the farm: catch one with {npc:217412}'s Entomology Starter Kit, then tick it off.\nCareful: Syndicate Highwaymen are level 30-31 and can cast Sneak while out of combat, so they are often stealthed and hard to spot."] = "辛迪加占据着{area:320}西北的农场。一只{npc:217589}在农场里爬动：用{npc:217412}的昆虫学入门工具包抓住一只，然后勾掉任务。\n注意：辛迪加路霸是30-31级，能在脱战时施放潜行，因此常常处于潜行状态，很难发现。",
	["The Witherbark trolls live in the hills south of {area:314}; Witch Doctors stand in the village, Shadow Hunters guard the far end of the valley."] = "枯木巨魔住在{area:314}以南的山丘；枯木巫医在村子里，枯木暗影猎手守在山谷尽头。",
	["The courier walks the road west of {area:314} with two guards; pull them off the road."] = "被遗忘者信使带着两名卫兵在{area:314}以西的路上行走；把他们引离道路。",
	["The shards lie at the far end of {area:318}."] = "碎片在{area:318}的尽头。",
	["The tomes lie in the ruined keep west of {area:280}; Argus Shadow Mages hold the ruins.\nCareful: Crushridge Warmongers call nearby allies within 15 yd once they fall below half health."] = "典籍在{area:280}以西的废弃堡垒里；阿古斯暗影法师占据着废墟。\n注意：碎山好战者血量降到一半以下后，会呼叫15码内的附近盟友。",
	["The two wrecks lie in the bay west of the cove. The charts and logs are inside them; the gems lie on the sea floor around them. Daggerspine naga swim the whole bay."] = "两艘沉船在海湾以西的海湾里。海图和航海日志在船里；宝石在周围的海底。整个海湾都有刺脊纳迦游动。",
	["The western swamp"] = "西部沼泽",
	["The wrecked caravan lies off the road near Biggs.\nCareful: The camp is full of Lost Ones around level 38. They stand in linked groups of 2-3, many are casters, and they respawn quickly."] = "损毁的车队在比格斯附近的道路旁。\n注意：营地到处是38级左右的失落者。它们以2-3只连组行动，其中许多是施法者，且刷新很快。",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:2417} is a level 40 elite: most classes solo it at level 42, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "这些是精英怪：建议组队，找人来一起做。{npc:2417}是40级精英：大多数职业42级可以单挑，但可能需要帮忙。如果只有你一个人就跳过：路线会安排你刷怪补经验。",
	["Tram to {zone:1455}"] = "乘地铁前往{zone:1455}",
	["Walk back onto the span: Ebenezer lies under its Arathi end."] = "走回桥面：埃比尼泽躺在桥的阿拉希一端下方。",
	["West along the coast to the goblins' cove; Lolo keeps watch on the rocks above it."] = "沿海岸向西前往地精的海湾（法迪尔海湾）；哨兵鲁鲁在上方的岩石上放哨。",
	["Young Sawtooth Crocolisk"] = "年幼的锯齿鳄",
	["Young crocolisks, Sorrow Spinners and Swamp Jaguars all roam the swamp around the road."] = "道路周围的沼泽里游荡着小鳄鱼、沼泽纺丝蛛和沼泽虎。",
	["{area:280}: kill these as you meet them"] = "{area:280}：遇到就杀",
	["{area:281}: kill these as you meet them"] = "{area:281}：遇到就杀",
	["{area:318}: kill these as you meet them"] = "{area:318}：遇到就杀",
	["{area:320} flight master"] = "{area:320}飞行管理员",
	["{area:328}: kill these as you meet them"] = "{area:328}：遇到就杀",
	["{area:35} flight master"] = "{area:35}飞行管理员",
	["{item:2321} for {npc:2438}'s cloak, from {npc:2381}, if you have none"] = "{npc:2438}的披风需要{item:2321}，如果没有就从{npc:2381}处购买",
	["{item:3658}: Crushridge ogres"] = "{item:3658}：破碎岭食人魔",
	["{item:3659}: the {object:1760}; inside"] = "{item:3659}：{object:1760}；室内",
	["{item:4435} from {npc:2572}, {npc:2573} and {npc:2574}, by this stop"] = "从这一站附近的{npc:2572}、{npc:2573}和{npc:2574}身上获取{item:4435}",
	["{item:4492}; underwater"] = "{item:4492}；水下",
	["{item:4525}; below ground"] = "{item:4525}；地下",
	["{item:5040}; below ground"] = "{item:5040}；地下",
	["{npc:1141}, {area:17203} road"] = "{npc:1141}，{area:17203}的路上",
	["{npc:12336}, Cathedral of Light"] = "{npc:12336}，光明大教堂",
	["{npc:1440}, the Royal Library in the keep"] = "{npc:1440}，城堡里的皇家图书馆",
	["{npc:1470}, below ground"] = "{npc:1470}，地下",
	["{npc:185335}, at the same circle"] = "{npc:185335}，在同一个法阵",
	["{npc:217412}: three critters to catch in Arathi, {zone:1443} and Stranglethorn"] = "{npc:217412}：在阿拉希、{zone:1443}和荆棘谷各捕捉一只小动物",
	["{npc:217589}: catch it, for {quest:93176}"] = "{npc:217589}：捕捉它，用于{quest:93176}",
	["{npc:2276}, inside"] = "{npc:2276}，室内",
	["{npc:2595}, underwater"] = "{npc:2595}，水下",
	["{npc:2596}, underwater"] = "{npc:2596}，水下",
	["{npc:2712} and {npc:2713}"] = "{npc:2712}和{npc:2713}",
	["{npc:2713}'s errand"] = "{npc:2713}的差事",
	["{npc:2793}, an ogre mage, holds the cave at the southern end of the Witherbark valley."] = "食人魔法师{npc:2793}占据着枯木巨魔山谷南端的洞穴。",
	["{npc:5391} is caged at the north end of the sanctuary. Free him and keep him alive on the walk out; his strongbox waits by the road afterwards."] = "{npc:5391}被关在避难所北端的笼子里。救出他，并在护送他出去时保护他存活；之后他的保险箱就在路边。",
	["{npc:5476} guards the road junction in the west of the swamp. {npc:217412} stands a short way north of him."] = "{npc:5476}守卫着沼泽西部的路口。{npc:217412}在他北边不远处。",
	["{npc:6122} binds the incubus to you"] = "{npc:6122}会将梦魇与你绑定",
	["{npc:6122} waits in the {object:2164}'s cellar, in the {object:2101}. Use the {item:6913} at the summoning circle there and defeat the succubus it calls. If you took {quest:65602}, hand him the {item:190309} too, place it at the same circle and defeat the incubus."] = "{npc:6122}在{object:2101}{object:2164}的地下室等候。在那里的召唤法阵使用{item:6913}，击败召来的魅魔。如果你接了{quest:65602}，也把{item:190309}交给他，放在同一个法阵上，然后击败梦魇。",
	["{object:2652}, inside"] = "{object:2652}，室内",
	["{object:2707}; underwater"] = "{object:2707}；水下",
	["{object:2708}; underwater"] = "{object:2708}；水下",
	["{object:2709}; underwater"] = "{object:2709}；水下",
	["{object:2710}; underwater"] = "{object:2710}；水下",
	["{quest:65602}, if you took it"] = "{quest:65602}，如果你接了",
	["{zone:1455} flight master"] = "{zone:1455}飞行管理员",
}

G["forever/alliance/30-40/06-badlands"] = {
	["Flesh Picker"] = "食腐者",
	["Fly to Theramore"] = "飞往塞拉摩岛",
	["Fly to {area:150}"] = "飞往{area:150}",
	["Follow the road north to {area:608}."] = "沿道路向北到{area:608}。",
	["Follow the road south to {area:2407}."] = "沿道路向南到{area:2407}。",
	["Follow the road west across the north of {zone:1443} to the ruins of {area:2405}. {npc:11863}'s tower stands on the hill there, on the way to the wreck."] = "沿道路向西穿过{zone:1443}北部，到{area:2405}的废墟。{npc:11863}的塔就在那里的山丘上，在去残骸的路上。",
	["Head back west to the road and follow it south out of {zone:1432} through the pass into the {area:3}. {npc:2910} and {npc:2860} camp side by side at the dig."] = "回到西边的路上，沿路向南离开{zone:1432}，穿过山口进入{area:3}。{npc:2910}和{npc:2860}并排在挖掘场扎营。",
	["Head north-east to the abandoned dig; the supply crate lies there among the Dustbelcher ogres."] = "向东北前往废弃的挖掘场；补给箱就在那里的沙腮食人魔中间。",
	["Head north-east to the dwarven ruins in the north of the {area:3}; the chest sits among the Shadowforge dwarves. {npc:2745} nearby is elite: give him room."] = "向东北前往{area:3}北部的矮人废墟；箱子在暗炉矮人中间。附近的{npc:2745}是精英：离他远点。",
	["Head south to {area:345}."] = "向南前往{area:345}。",
	["Head west into the {area:1878}; {npc:2921} works by his machines in the middle of it."] = "向西进入{area:1878}；{npc:2921}在中间他的机器旁工作。",
	["Into {area:3}"] = "进入{area:3}",
	["Lesser Rock Elementals"] = "小型岩石元素",
	["Maraudine centaurs"] = "玛洛迪半人马",
	["Rock Elementals"] = "石元素",
	["Ryedol's next errand goes into {area:1517}: skip it."] = "勘察员雷杜尔的下一个差事要进入{area:1517}：跳过。",
	["Stonevault Bonesnapper"] = "石窟断骨者",
	["The Dustbelcher ogres camp just south of the valley; any of them drops scrap. Buzzards circle the plain to the east.\nThe battered skeleton lies at the edge of the Stonevault trogg camp; {quest:739}, Agmond's killer, walks among the Bonesnappers.\nThe Lesser Rock Elementals wander the {area:1878} west of {npc:2921}.\nCareful: Dustbelcher Lords are level 44-45. They use {spell:5242} and {spell:1160}, and below 50% health they call for help from allies within 15 yd. Seven of them stand about 750 yd south of {area:340}."] = "沙腮食人魔就在山谷南边扎营；他们中任何一个都会掉落废料。秃鹫在东边的平原盘旋。\n破烂的骷髅躺在石窟穴居人营地边缘；杀死阿格蒙德的凶手{quest:739}在断骨者中间走动。\n次级岩石元素在{npc:2921}西边的{area:1878}游荡。\n小心：沙腮领主是44-45级。他们会用{spell:5242}和{spell:1160}，生命值低于50%时会呼叫15码内的盟友支援。其中七个站在{area:340}以南约750码处。",
	["The Maraudine centaurs hold the {area:607} west of the graveyard; every kind drops the totems."] = "玛洛迪半人马占据着墓地西边的{area:607}；每种都会掉落图腾。",
	["The Rock Elementals roam south-east of {npc:2921}; Giant Buzzards and Elder Crag Coyotes share the plain to their west."] = "石元素在{npc:2921}东南方游荡；巨型秃鹫和老峭壁山狗分布在它们西边的平原上。",
	["The Shadowforge dwarves camp just north of the digsite; the crumpled map lies among their tents. Tunnelers and Darkweavers carry Ryedol's pick. Crag Coyotes roam the slopes around it."] = "暗炉矮人在挖掘场北边不远处扎营；弄皱的地图在他们的帐篷之间。暗炉隧道工和暗炉巫师带着勘察员雷杜尔的镐。峭壁山狗在周围的山坡上游荡。",
	["The battered skeleton lies just east of the ogres, at the edge of the Stonevault trogg camp; the Bonesnappers and Shamans around it drop the flakes. Theldurin sits by the ruined camp further south."] = "破损的骷髅就在食人魔东边、石窟穴居人营地边缘；周围的石窟断骨者和石窟萨满祭司掉落碎片。迷失者塞尔杜林坐在更南边的废弃营地旁。",
	["The clams lie on Stranglethorn's north-west coast, in the next guide: keep it"] = "蚌壳在荆棘谷西北海岸，在下一份指南里：先留着",
	["The demons gather at the {area:602} in southern {zone:1443}: felhounds (Mana Eaters, Mage and Ley Hunters), Nether Maidens and Sisters, and Doomwarder Captains around the pit.\nCareful: Most of the mobs here walk patrol routes, so you can easily pull extra mobs."] = "恶魔聚集在{zone:1443}南部的{area:602}：地狱犬（法力吞噬者、法师猎手和魔网猎手）、虚空女妖和虚空姐妹，以及坑周围的末日守望者队长。\n小心：这里大多数怪物走巡逻路线，很容易多拉怪。",
	["The excavation crate"] = "挖掘补给箱",
	["The flight master stands by the gate of {area:514}; {npc:5083} and {npc:4964} are inside the citadel."] = "飞行管理员站在{area:514}的门口；{npc:5083}和{npc:4964}在城堡内。",
	["The next guide starts in Theramore."] = "下一份指南从塞拉摩岛开始。",
	["The skeleton's next task, {quest:739}, waits until the later {area:3} guide at 43."] = "骷髅的下一个任务{quest:739}要等到后面43级的{area:3}指南。",
	["The wrecked ship's chest lies on the shore just west of {npc:11863}'s tower."] = "失事船只的箱子在{npc:11863}的塔西边不远的岸上。",
	["The {area:2657}"] = "{area:2657}",
	["The {object:126260}"] = "{object:126260}",
	["Theramore"] = "塞拉摩岛",
	["To {area:2101}"] = "前往{area:2101}",
	["Undead Ravager"] = "亡灵劫掠者",
	["Undead Ravagers roam the bone fields south of the Magram village, east of the Coven; at the far south-east, use the {item:15848} to draw the Magrami Spectres."] = "亡灵劫掠者在玛格拉姆村南边、集会所东边的骨原上游荡；在最东南端使用{item:15848}引出玛格拉姆鬼魂。",
	["Underwater"] = "水下",
	["escort {npc:12277} back toward the graveyard"] = "护送{npc:12277}回到墓地",
	["for the Dustwallow loop in the next guide"] = "留给下一份指南的尘泥沼泽环线",
	["for {npc:2786} in {zone:1455}: keep it"] = "交给{zone:1455}的{npc:2786}：先留着",
	["for {npc:3980} in {area:271}: keep it"] = "交给{area:271}的{npc:3980}：先留着",
	["for {npc:5637} in {zone:1455}: keep it"] = "交给{zone:1455}的{npc:5637}：先留着",
	["only if you carry {item:2868} (a blacksmith's craft)"] = "仅当你带着{item:2868}（铁匠制品）",
	["{area:144} flight master"] = "{area:144}飞行管理员",
	["{area:345}: kill these as you meet them"] = "{area:345}：遇到就杀",
	["{area:346}: kill these as you meet them"] = "{area:346}：遇到就杀",
	["{area:598}: kill these as you meet them"] = "{area:598}：遇到就杀",
	["{item:4631}; below ground"] = "{item:4631}；地下",
	["{item:5797} on the way"] = "路上拿{item:5797}",
	["{npc:12277} is held in the centaur camp west of the graveyard. Free her and keep her alive on the walk out; she stops by the graveyard.\nCareful: The scripted groups are linked and only appear during the escort, so you cannot clear them in advance or pull them one at a time. Clearing the normal centaurs on the path before you start does help."] = "{npc:12277}被关在墓地西边的半人马营地。救出她，并在带她出来的途中保住她；她会在墓地旁停下。\n小心：剧情队伍是联动的，只在护送时出现，所以无法提前清掉，也不能一只一只地拉。出发前先清掉路上的普通半人马确实有帮助。",
	["{npc:12369}, a centaur chieftain, camps on the north-west coast, north of {npc:11863}'s tower."] = "{npc:12369}是一个半人马首领，在{npc:11863}的塔北边的西北海岸扎营。",
	["{npc:1470}, in the inn; below ground"] = "{npc:1470}，在旅店里；地下",
	["{npc:217590}: catch it, for My Little Friends"] = "{npc:217590}：抓住它，用于My Little Friends",
	["{npc:2893}, 130 yd north"] = "{npc:2893}，以北130码",
	["{npc:2920}, beside {npc:2921}"] = "{npc:2920}，在{npc:2921}旁边",
	["{npc:2921}'s next test needs crafted gear: skip it."] = "{npc:2921}的下一个测试需要制作的装备：跳过。",
	["{npc:4618} and {npc:2817} camp together in the {area:1877}, in the middle of the {area:3}."] = "{npc:4618}和{npc:2817}一起在{area:3}中部的{area:1877}扎营。",
	["{npc:4964}, on the top floor"] = "{npc:4964}，顶层",
	["{npc:5083}, on the top floor"] = "{npc:5083}，顶层",
	["{npc:6019} stands at the edge of the {area:596}, south-west of {area:2407}; {object:176751} lie among the skeletons. A {npc:217590} crawls about the graveyard: catch one with the Entomology Starter Kit, then tick it off."] = "{npc:6019}站在{area:2407}西南方的{area:596}边缘；{object:176751}散落在骨架之间。一只{npc:217590}在墓地里爬行：用Entomology Starter Kit抓住一只，然后勾选完成。",
}

G["forever/alliance/40-50/01-stranglethorn-vale"] = {
	["\"Sea Wolf\" MacKinley, on the top floor"] = "“海狼”麦金利，在顶层",
	["\"Stinky\" Ignatz"] = "伊格纳兹",
	["Arbor Tarantula"] = "树栖狼蛛",
	["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. Skyborne learn it from {npc:265756}, the stablemaster and riding trainer at the {area:17684} in {area:16638} on Zephras Isle, who also sells the Galestriders: the skyboat to the isle leaves the north side of {area:279} about every five minutes. Collectibles, Mounts · Level 40 lists the Galestriders."] = "40级时花100金就能学骑术，学会后可获得一匹坐骑。天裔在泽弗拉斯岛{area:16638}的{area:17684}向驯兽师兼骑术训练师{npc:265756}学习，他还出售风行者：前往该岛的天艇大约每五分钟从{area:279}北侧出发。收藏·坐骑·40级列出了风行者。",
	["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4732} teaches Humans at {area:88} in eastern {area:12}, beside {npc:384}'s horses. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "40级时花100金就能学骑术，学会后可获得一匹坐骑。{npc:4732}在{area:12}东部的{area:88}教人类，就在{npc:384}的马匹旁。Forever可能允许任何种族向任何骑术训练师学习（未经证实）。收藏·坐骑·40级列出了所有颜色。",
	["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4753} teaches Night Elves in {zone:1457}, beside {npc:4730}'s sabers: the boat from {area:17203} to {area:442}, then the flight to {area:702}. Forever may let any race learn from any riding trainer (unconfirmed), such as {npc:4732} at {area:88} in {area:12}. Collectibles, Mounts · Level 40 lists every colour."] = "40级时花100金就能学骑术，学会后可获得一匹坐骑。{npc:4753}在{zone:1457}教暗夜精灵，就在{npc:4730}的刃豹旁：从{area:17203}坐船到{area:442}，再飞往{area:702}。Forever可能允许任何种族向任何骑术训练师学习（未经证实），例如{area:12}中{area:88}的{npc:4732}。收藏·坐骑·40级列出了所有颜色。",
	["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4772} teaches Dwarves at {area:803}, east of {area:131} on the road to {zone:1432}, beside {npc:1261}'s rams. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "40级且有100金时可以学习骑术，学会后会获得一匹坐骑。{npc:4772}在{area:803}教授矮人，位于{area:131}东边通往{zone:1432}的路上，旁边是{npc:1261}的山羊。Forever 可能允许任何种族向任何骑术训练师学习（未确认）。收藏指南“坐骑 · 40级”列出了所有颜色。",
	["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:7954} teaches Gnomes at {area:189}, just east of {area:131}, beside {npc:7955}'s mechanostriders. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "40级且有100金时可以学习骑术，学会后会获得一匹坐骑。{npc:7954}在{area:131}东边不远的{area:189}教授侏儒，旁边是{npc:7955}的机械陆行鸟。Forever 可能允许任何种族向任何骑术训练师学习（未确认）。收藏指南“坐骑 · 40级”列出了所有颜色。",
	["Back in Theramore: Tervosh waits with Lady Jaina in the tower of {area:514}."] = "回到塞拉摩：特沃什和吉安娜女士在{area:514}的塔里等你。",
	["Bloodsail Swashbuckler"] = "血帆剑客",
	["Bloodsail camp"] = "血帆营地",
	["Boat to {area:150}"] = "乘船前往{area:150}",
	["Boat to {area:17203}"] = "乘船前往{area:17203}",
	["Boat to {area:35}"] = "乘船前往{area:35}",
	["Cold Eye Basilisks"] = "冷眼蜥蜴",
	["Defeat the challengers and {npc:6238}"] = "击败挑战者和{npc:6238}",
	["Every Bloodsail drops Snuff and one of them carries {npc:2493}'s eye; the Swashbucklers walk the shore just north of town. The charts and orders lie in the pirate camp on the {area:43}, south of {area:35}."] = "每个血帆海盗都掉落鼻烟，其中一个携带{npc:2493}的眼睛；血帆流氓在镇子北边的岸上游荡。海图和命令在{area:35}南边{area:43}的海盗营地里。",
	["Every Zanzil follower can drop the mixture; {npc:2537} walks the south of the camp."] = "每个赞吉尔的追随者都可能掉落药剂；{npc:2537}在营地南部走动。",
	["Fly to {area:144}"] = "飞往{area:144}",
	["Fly to {area:1537}"] = "飞往{area:1537}",
	["Fly to {area:35}"] = "飞往{area:35}",
	["Fly to {area:42}"] = "飞往{area:42}",
	["Fly to {area:442}"] = "飞往{area:442}",
	["Fly to {area:702}"] = "飞往{area:702}",
	["Fly to {zone:1453}"] = "飞往{zone:1453}",
	["Follow the road east back to Theramore. Tervosh, Lady Jaina and the officers are in the tower and {area:514}."] = "沿道路向东返回塞拉摩。特沃什、吉安娜女士和军官们在塔楼和{area:514}里。",
	["Follow the road north-west out of Theramore to the watchtower at {area:503}. Mudrock Burrowers roam the marsh around it."] = "沿路向西北离开塞拉摩，前往{area:503}的瞭望塔。泥岩掘地者在塔周围的沼泽里游荡。",
	["Gorilla hills"] = "猩猩山丘",
	["Hand in the fangs and stay: three waves of gorillas come, {npc:1514} last. Fight at full health."] = "交还牙齿后留下：会来三波猩猩，最后是{npc:1514}。满血再战。",
	["If you skipped {quest:193}, grind here to level 42.23 to stay on the route's plan."] = "如果你跳过了{quest:193}，就在这里刷到42.23级，以跟上本路线的进度规划。",
	["If you skipped {quest:196}, grind here to level 42.27 to stay on the route's plan."] = "如果你跳过了{quest:196}，就在这里刷到42.27级，以跟上本路线的进度规划。",
	["If you skipped {quest:208}, grind here to level 42.33 to stay on the route's plan."] = "如果你跳过了{quest:208}，就在这里刷到42.33级，以跟上本路线的进度规划。",
	["If you skipped {quest:543}, grind here to level 42.46 to stay on the route's plan."] = "如果你跳过了{quest:543}，就在这里刷到42.46级，以跟上本路线的进度规划。",
	["Inside"] = "在里面",
	["Into {area:10}"] = "进入{area:10}",
	["Into {area:12}"] = "进入{area:12}",
	["Into {area:8}"] = "进入{area:8}",
	["Into {zone:1430}"] = "进入{zone:1430}",
	["Into {zone:1453}"] = "进入{zone:1453}",
	["Jungle Stalker"] = "丛林潜伏者",
	["Leave town by the tunnel and follow the coast north; the letter lies in the Bloodsail camp on the beach, where \"Pretty Boy\" Duncan walks."] = "从隧道出城，沿海岸向北；信在沙滩上的血帆营地里，帅小伙子邓肯在那里走动。",
	["Level 42.23"] = "42.23级",
	["Level 42.27"] = "42.27级",
	["Level 42.33"] = "42.33级",
	["Level 42.46"] = "42.46级",
	["MacKinley's next task sends you after elite ogres: skip it."] = "马克基雷的下一个任务要你对付精英食人魔：跳过。",
	["Mirefin murlocs"] = "黑鳍鱼人",
	["Naga Explorers"] = "纳迦探险者",
	["On the ride north to {area:392}, {area:720} lies off the {area:391} south of the town: wade over the sand bar shallows. {npc:6236} sends four challengers and then {npc:6238} (level 33) at you, one at a time."] = "向北骑往{area:392}的路上，{area:720}位于镇子南边的{area:391}近海：涉水穿过沙洲浅滩。{npc:6236}会让四名挑战者和{npc:6238}（33级）依次与你交战。",
	["On the top floor"] = "在顶层",
	["Paladin: {quest:1661}"] = "圣骑士：{quest:1661}",
	["Ride back down to town; Shaky stands at the tunnel mouth."] = "骑回镇上；“病鬼”菲利普站在隧道口。",
	["Ride east; the Tangled Horrors along the way also drop the essays. Search the edge of the {area:74}, where the temple's ruins break the water."] = "向东骑行；沿途的纠缠恐兽也会掉落研究笔记。在{area:74}边缘搜寻，神庙的废墟在那里露出水面。",
	["Ride inland to the Mistvale gorilla hills. Elder Mistvale Gorillas drop the giblets; {npc:1449} sits among them."] = "向内陆骑行到迷雾谷猩猩所在的山丘。老迈的迷雾谷猩猩掉落内脏；{npc:1449}坐在它们中间。",
	["Ride north to the hills west of the road. {npc:2535} and {npc:2536} stand together just north of Zanzil's village."] = "向北骑行到道路西边的山丘。{npc:2535}和{npc:2536}一起站在赞吉尔村子北边不远处。",
	["Ride north-east past Nesingwary's camp and follow the road north to the camp at the top of the vale. On the way, an {npc:217588} crawls in the jungle south-east of Nesingwary's camp: catch one with the Entomology Starter Kit, then tick it off."] = "向东北经过奈辛瓦里营地，沿道路向北前往山谷顶端的营地。途中，奈辛瓦里营地东南方的丛林里有一只{npc:217588}：用昆虫学入门工具包捕捉一只，然后勾选。",
	["Ride north-west from the mine to the bay on the north-west coast. The Giant Clams lie on its floor and hold the pearls; {npc:2624} swims among them and drops the {item:4034}."] = "从矿井向西北骑行到西北海岸的海湾。巨型蚌壳在海底，里面有珍珠；{npc:2624}在它们中间游动，掉落{item:4034}。",
	["Ride south out of {zone:1432} through the pass into the {area:3}; {npc:2860} camps at the dig."] = "骑马向南离开{zone:1432}，穿过山口进入{area:3}；{npc:2860}在挖掘场扎营。",
	["Ride south to the giant's hut in the middle of the marsh."] = "向南骑行到沼泽中央巨人的小屋。",
	["Riding and Galestriders: {npc:265756}, at the {area:17684} in {area:16638} on Zephras Isle."] = "骑术与风行者：{npc:265756}，在泽弗拉斯岛{area:16638}的{area:17684}。",
	["Riding at 40"] = "40级骑术",
	["Seahorn's next errand goes back to Arathi: skip it."] = "海角的下一个差事要回阿拉希：跳过。",
	["Skyboat to Zephras Isle: the north side of {area:279}, about every five minutes."] = "前往泽弗拉斯岛的天艇：{area:279}北侧，大约每五分钟一班。",
	["Stinky waits west of the manor, in the marsh below {area:504}. Lead him to his Bogbean leaves and keep the swamp creatures off him."] = "伊格纳兹在庄园西边、{area:504}下方的沼泽中等候。带他去找Bogbean叶子，别让沼泽生物靠近他。",
	["Stormwind City"] = "暴风城",
	["Take the road north to the ruined manor; Jarl lives in the shack beside it and the loose dirt is at the corner of the house."] = "沿道路向北前往废弃的庄园；加尔住在旁边的棚屋里，松土就在房子的拐角处。",
	["Take the {area:2257} from the {object:28027}. {npc:5637} is in the Reclaimers' hall by the {object:32356}, {npc:1356} in the hall itself, {npc:2786} in the {object:32383}. The next guide flies on to {area:144}."] = "从{object:28027}乘{area:2257}。{npc:5637}在{object:32356}旁的寻物公司大厅，{npc:1356}在大厅内，{npc:2786}在{object:32383}。下一份指南飞往{area:144}。",
	["The Bloodsail captains"] = "血帆船长",
	["The Cold Eye Basilisks lie on the rocks west of the mine."] = "冷眼蜥蜴趴在矿井西边的岩石上。",
	["The Darkmist spiders nest around the cavern in the north-west of the marsh; every spider drops eyes.\nCareful: Darkmist Lurkers move about stealthed and use poison once in combat. The spiders stand close together, so adds are common; pulling single targets from the outer edge cuts down on them."] = "暗雾蜘蛛在沼泽西北的洞穴周围结巢；每种蜘蛛都掉眼睛。\n注意：暗雾潜伏者潜行移动，进入战斗后会使用毒。蜘蛛站得很近，很容易多拉怪；从外围一次拉一只可以减少额外怪。",
	["The Mirefin murlocs crowd the north coast past {area:497}; finish the tongues on the tortoises beside them."] = "黑鳍鱼人聚集在{area:497}以外的北部海岸；在旁边的海龟身上收集完舌头。",
	["The Skullsplitter trolls hold the ruins just east of the mine; any of them can drop tusks, their panthers always do.\nFollow the road north-east to the Venture Co. camp at the {area:310}; the miners, surveyors and foremen drop the crystals.\nCareful: Stealthed Shadowmaw Panthers and Stranglethorn Tigresses roam the area around the camp."] = "劈颅者巨魔占据着矿场以东的废墟；其中任何一个都可能掉獠牙，他们的黑豹必掉。\n沿路向东北前往{area:310}的风险投资公司营地；矿工、勘测员和工头掉落水晶。\n注意：潜行的影颚黑豹和荆棘谷母虎在营地周围活动。",
	["The burned inn stands on the road west, toward the {area:17}; the guard's badge lies in the ashes and the hoofprints are in the mud beside the inn."] = "烧毁的旅店在向西通往{area:17}的路上；卫兵的徽章在灰烬里，蹄印在旅店旁的泥地里。",
	["The captains stand on the ships anchored off the {area:43}, each with a crew of 42-45 pirates: Stillwater (45) and Keelhaul (46) on the nearer decks, {npc:2546} (48) on the flagship. At 42 this is a fight for a group or for the end of the guide; clear each deck first if you go. Cortello's scroll lies on the wreck by the shore."] = "船长们站在停泊于{area:43}外的船上，每艘有42-45级的海盗船员：斯蒂沃特（45）和尼哈鲁（46）在较近的甲板上，{npc:2546}（48）在旗舰上。42级时这需要组队，或留到指南最后；如果要去，先清理每层甲板。科泰罗的卷轴在岸边的沉船上。",
	["The deserters camp south of the road, west of {npc:4503}'s hut."] = "逃兵在道路南边、{npc:4503}小屋西边扎营。",
	["The driftwood washes up along the eastern shore."] = "浮木冲上东岸。",
	["The naga comb the beaches north of the Bloodsail camp; they drop the reeds."] = "纳迦在血帆营地北边的海滩上搜寻；它们掉落芦苇。",
	["The north-west coast"] = "西北海岸",
	["The riddle's next scroll lies in western Dustwallow: skip it."] = "谜题的下一张卷轴在尘泥沼泽西部：跳过。",
	["The scroll lies in the marsh north of Biggs. The Swampwalkers north of it can drop Khadgar's essays."] = "卷轴在比格斯北边的沼泽里。其北边的沼泽漫步者可能掉落卡德加的空间收敛研究笔记。",
	["The sunken temple"] = "沉没的神庙",
	["Theramore"] = "塞拉摩",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:728} is a level 40 elite: most classes solo it at level 42, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "这些是精英怪：建议组队，找人来一起做。{npc:728}是40级精英：大多数职业42级可以单挑，但可能需要帮忙。如果只有你一个人就跳过：路线会安排你刷怪补经验。",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:730} is a level 43 elite: most classes solo it at level 45, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "这些是精英怪：建议组队，找人来一起做。{npc:730}是43级精英：大多数职业45级可以单挑，但可能需要帮忙。如果只有你一个人就跳过：路线会安排你刷怪补经验。",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:731} is a level 43 elite: most classes solo it at level 45, but you may need help. Skip it if you are alone: the route has you grind the XP back.\nCareful: Tigers and stealthed shadowmaw panthers roam close to him. Clear them before you pull him. When he is pulled, {npc:731} calls for help from creatures within 20 yd."] = "这些是精英怪：建议组队，找人来一起做。{npc:731}是43级精英：大多数职业45级可以单挑，但可能需要帮忙。如果只有你一个人就跳过：路线会安排你刷怪补经验。\n注意：老虎和潜行的影颚黑豹在他附近游荡。拉他之前先清掉。开打后，{npc:731}会向20码内的生物呼救。",
	["Tram to {zone:1455}"] = "乘地铁前往{zone:1455}",
	["Unbagwa's ritual"] = "安巴格瓦的仪式",
	["Upstairs"] = "楼上",
	["Warlock: {quest:3631}"] = "术士：{quest:3631}",
	["Zanzil's village"] = "赞吉尔的村子",
	["for Stoley in {zone:1446}: keep it; on the top floor"] = "给{zone:1446}的斯托雷：留着；在顶层",
	["for the {area:8} later"] = "留给以后的{area:8}",
	["for {area:1438}: keep it"] = "交给{area:1438}：留着",
	["for {npc:2616} in Theramore: keep it"] = "交给塞拉摩的{npc:2616}：留着",
	["for {npc:5635} at {area:348}: keep it"] = "交给{area:348}的{npc:5635}：留着",
	["for {npc:770} at the {area:99}, on the northern loop"] = "交给{area:99}的{npc:770}，在北部环线上",
	["grind on {npc:690}"] = "刷{npc:690}",
	["grind on {npc:766}"] = "刷{npc:766}",
	["only if you carry a {item:3853} (a blacksmith's craft)"] = "仅当你携带{item:3853}（铁匠制造品）时",
	["with the spices from Theramore"] = "带上从塞拉摩买的香料",
	["{area:103}: kill these as you meet them"] = "{area:103}：遇到就杀",
	["{area:108} flight master"] = "{area:108}飞行管理员",
	["{area:144} flight master"] = "{area:144}飞行管理员",
	["{area:150} flight master"] = "{area:150}飞行管理员",
	["{area:35} flight master"] = "{area:35}飞行管理员",
	["{area:42} flight master"] = "{area:42}飞行管理员",
	["{area:43}: kill these as you meet them"] = "{area:43}：遇到就杀",
	["{area:442} flight master"] = "{area:442}飞行管理员",
	["{area:702} flight master"] = "{area:702}飞行管理员",
	["{item:3713}, for \"Swamp Eye\" Jarl"] = "{item:3713}，交给“沼泽之眼”加尔",
	["{item:3919} on the way"] = "顺路拿{item:3919}",
	["{item:4611}; underwater"] = "{item:4611}；水下",
	["{npc:1141} cooks in the {object:2169}; {npc:5384} is in the {object:28027}."] = "{npc:1141}在{object:2169}做饭；{npc:5384}在{object:28027}。",
	["{npc:1261}: other colours, 20g"] = "{npc:1261}：其他颜色，20金",
	["{npc:1440}, the Royal Library in {object:2117}"] = "{npc:1440}，在{object:2117}的皇家图书馆",
	["{npc:1449}, inside {area:1742}"] = "{npc:1449}，在{area:1742}内",
	["{npc:217412}: {quest:93176}, from 30-40/05-arathi-highlands"] = "{npc:217412}：{quest:93176}，来自 30-40/05-arathi-highlands",
	["{npc:217588}: catch it, for {quest:93176}"] = "{npc:217588}：捕捉它，用于{quest:93176}",
	["{npc:2487}, top floor"] = "{npc:2487}，顶楼",
	["{npc:2488}, on the top floor"] = "{npc:2488}，在顶层",
	["{npc:2498}'s next Zanzil errand starts in {zone:1441}: skip it."] = "{npc:2498}的下一个赞吉尔差事从{zone:1441}开始：跳过。",
	["{npc:2535} and {npc:2536}"] = "{npc:2535}和{npc:2536}",
	["{npc:2542}, upstairs"] = "{npc:2542}，楼上",
	["{npc:2624} swims off the north-west coast, on the northern loop"] = "{npc:2624}在西北海岸外游动，在北部环线上",
	["{npc:2888} camps by himself in {area:1898}, south-east of the digsite."] = "{npc:2888}独自在挖掘场东南的{area:1898}扎营。",
	["{npc:384}: other colours, 20g"] = "{npc:384}：其他颜色，20金",
	["{npc:461}, in the {object:2164}: {npc:6251} in {area:392} takes it at the end of the next guide"] = "{npc:461}，在{object:2164}：{area:392}的{npc:6251}在下一份指南结尾接收",
	["{npc:4730}: other colours, 20g"] = "{npc:4730}：其他颜色，20金",
	["{npc:4794}, inside"] = "{npc:4794}，室内",
	["{npc:4948}, on the top floor"] = "{npc:4948}，在顶层",
	["{npc:4966} holds the tower with a few deserters. He turns on you: beat him until he yields.\nCareful: Hendel has two guards who join the fight when he turns hostile. The guards flee once he surrenders."] = "{npc:4966}和几个逃兵占据着塔楼。他会对你翻脸：打倒他直到他投降。\n注意：亨德尔有两名卫兵，他转为敌对时他们会加入战斗。他一投降，卫兵就会逃跑。",
	["{npc:4967}, upstairs"] = "{npc:4967}，楼上",
	["{npc:4968}, on the top floor"] = "{npc:4968}，在顶层",
	["{npc:5464}, by the flight master"] = "{npc:5464}，在飞行管理员旁边",
	["{npc:5476} stands by the road junction in the west of the swamp."] = "{npc:5476}站在沼泽西部的路口旁。",
	["{npc:5694}: for {area:1438}, keep it"] = "{npc:5694}：交给{area:1438}，留着",
	["{npc:6171}, in the Cathedral of Light"] = "{npc:6171}，在光明大教堂",
	["{npc:6236} offers The Windwatcher next (1791): the Whirlwind weapon chain, with an elite at the end, is in the Warrior class guide Whirlwind Weapon."] = "{npc:6236}接下来提供“捕风者”（1791）：旋风武器任务线最后有一个精英，见战士职业指南“旋风武器”。",
	["{npc:737}, upstairs"] = "{npc:737}，楼上",
	["{npc:773}, upstairs"] = "{npc:773}，楼上",
	["{npc:773}: for {quest:2864} in {zone:1446}, keep it"] = "{npc:773}：交给{zone:1446}的{quest:2864}，留着",
	["{npc:7955}: other colours, 20g"] = "{npc:7955}：其他颜色，20金",
	["{quest:1218}, for \"Swamp Eye\" Jarl"] = "{quest:1218}，给“沼泽之眼”加尔",
	["{quest:1260} stands near the inn; {npc:4897}, a trade supplier a few steps south, sells the spices Jarl wants."] = "{quest:1260}站在旅店附近；往南几步的商人{npc:4897}出售加尔要的香料。",
	["{quest:1260}, inside"] = "{quest:1260}，室内",
	["{zone:1453} flight master"] = "{zone:1453}飞行管理员",
	["{zone:1453} has no shaman trainer"] = "{zone:1453}没有萨满祭司训练师",
	["{zone:1455} flight master"] = "{zone:1455}飞行管理员",
}

G["forever/alliance/40-50/02-badlands"] = {
	["Blue Pearls from Stranglethorn"] = "来自荆棘谷的{item:4611}",
	["Fly to {area:144}"] = "飞往{area:144}",
	["Fly to {area:150}"] = "飞往{area:150}",
	["Fly to {area:271}"] = "飞往{area:271}",
	["From Theramore, ride north into the {zone:1413} to {area:392}, or fly if you know its flight path. {npc:6251} teaches in the house by the bank."] = "从塞拉摩向北骑进{zone:1413}，前往{area:392}；如果知道飞行路线也可以直接飞。{npc:6251}在银行旁的房子里教学。",
	["Inside {area:498}"] = "在{area:498}内部",
	["Murdaloc"] = "穆达洛克",
	["Raleigh's next errand is in the {area:796}: skip it."] = "虔诚的莱雷恩的下一个差事在{area:796}：跳过。",
	["Ride back east to {area:1898}."] = "向东骑回{area:1898}。",
	["Ride north to {area:144} and fly to {area:271}. {npc:3980} preaches by the inn."] = "向北骑到{area:144}，飞往{area:271}。{npc:3980}在旅店旁布道。",
	["Ride north-east out of {area:271} on the road into the {area:47}; {area:348} sits just past the border. {npc:5635} holds court at the top, {quest:1450} tends the aviary and {npc:7884} stands by the inn."] = "从{area:271}沿路向东北骑进{area:47}；{area:348}就在边界那边。{npc:5635}在顶层坐镇，{quest:1450}照看鸟舍，{npc:7884}站在旅店旁。",
	["Ride west across the {area:3} to the Dustbelcher camp at {area:342}. {npc:2944} stands in its middle with Wyrmhunters and Maulers around him."] = "向西骑过{area:3}，前往{area:342}的尘嚼营地。{npc:2944}站在营地中央，周围是猎龙者和重击者。",
	["Stonevault Bonesnapper"] = "石窟断骨者",
	["Talonaxe's next task waits for a later {area:47} guide."] = "塔隆艾克斯的下一个任务要等后面的{area:47}攻略。",
	["The Scalding Whelps nest in the ravine east of {npc:2888}; leave the Scorched Guardians (elite) alone. The {item:4612} drops rarely: take it if it comes while you grind."] = "滚烫的雏龙在{npc:2888}东边的峡谷里筑巢；别惹烈焰守护者（精英）。{item:4612}很少掉落：刷怪时掉了就拿上。",
	["The first two cages stand together in the Witherbark village south of {npc:5634}; the third is in the next village to the east. Every Witherbark troll can drop a necklace."] = "前两个笼子一起在{npc:5634}南边的枯木村庄里；第三个在东边的下一个村庄里。每个枯木巨魔都可能掉落项链。",
	["Theramore"] = "塞拉摩岛",
	["Theramore flight master"] = "塞拉摩飞行管理员",
	["Warlock: {quest:3631}"] = "术士：{quest:3631}",
	["Witherbark villages"] = "枯木村庄",
	["for {npc:4454} in the {area:439}: the {zone:1446} guide crosses them at 45, keep it"] = "给{area:439}的{npc:4454}：{zone:1446}的攻略会在45级经过那里，留着。",
	["{area:144} flight master"] = "{area:144}飞行管理员",
	["{area:348} flight master"] = "{area:348}飞行管理员",
	["{npc:2616} stands on the docks where the boat lands."] = "{npc:2616}站在船停靠的码头上。",
	["{npc:2817}'s next quest pays no experience: skip it."] = "{npc:2817}的下一个任务不给经验：跳过。",
	["{npc:2888}'s next task is an elite hunt: skip it."] = "{npc:2888}的下一个任务是精英狩猎：跳过。",
	["{npc:3980}, upstairs"] = "{npc:3980}，楼上",
	["{npc:4944}, on the top floor"] = "{npc:4944}，顶楼",
	["{npc:4968}, on the top floor"] = "{npc:4968}，顶楼",
	["{npc:5634} camps on the road east of {area:348}."] = "{npc:5634}在{area:348}东边的路上扎营。",
	["{npc:5636}, beside the flight master at the top; inside"] = "{npc:5636}，在顶层的飞行管理员旁；室内",
	["{npc:7744}: the last guide binds here, so this usually ticks at once; below ground"] = "{npc:7744}：上一份攻略在这里绑定炉石，所以这一步通常立刻完成；地下",
	["{npc:7884} keeps paying for necklaces: hand in any extras"] = "{npc:7884}会继续收购项链：交上多余的",
	["{npc:7884}, inside"] = "{npc:7884}，室内",
	["{quest:1450}, inside"] = "{quest:1450}，室内",
	["{zone:1455} flight master"] = "{zone:1455}飞行管理员",
}

G["forever/alliance/40-50/03-feralas"] = {
	["Back to the {area:1117}. Every Hatecrest naga there can drop scales."] = "回到{area:1117}。那里的每个憎世纳迦都可能掉落鳞片。",
	["Boat to the {area:1108} and ride east across {area:357} to the Grimtotem camp north of the road. {npc:7956} waits outside it; free the Sprite Darters from the pen in the middle and keep {npc:7956} and at least six of them alive."] = "坐船到{area:1108}，向东骑过{area:357}到路北的恐怖图腾营地。{npc:7956}在营地外等着；把精灵龙从中间的围栏里放出来，并保住{npc:7956}和至少六只精灵龙。",
	["Boat to the {area:1108} and ride east into {area:1105}. {npc:14637}'s quests on the coast need level 45."] = "乘船前往{area:1108}，向东骑进{area:1105}。{npc:14637}在海岸的任务需要45级。",
	["Boat to {area:1108}"] = "坐船到{area:1108}",
	["Boat to {area:1116}"] = "坐船到{area:1116}",
	["Feathermoon flight master"] = "羽月飞行管理员",
	["Fly to {area:489}"] = "飞往{area:489}",
	["Gordunni Brute"] = "戈杜尼蛮兵",
	["Gordunni Shaman"] = "戈杜尼萨满祭司",
	["Gordunni Warlock"] = "戈杜尼术士",
	["Gordunni ogres"] = "戈杜尼食人魔",
	["Grimtotem Naturalist"] = "恐怖图腾自然学家",
	["Grimtotem Raider"] = "恐怖图腾劫掠者",
	["Grimtotem Shaman"] = "恐怖图腾萨满祭司",
	["Grimtotem camp"] = "恐怖图腾营地",
	["Grimtotem tauren"] = "恐怖图腾牛头人",
	["Grind to 45"] = "刷到45级",
	["Hatecrest naga"] = "憎世纳迦",
	["Into {area:17}"] = "进入{area:17}",
	["Ride back to the {area:1108}; the goblin stands by the dock."] = "骑回{area:1108}；那个地精站在码头旁。",
	["Ride back west along the road, then north into the Rage Scar hills. Every yeti here can drop a hide; one may drop a {quest:7735}, which {npc:7852} pays for too."] = "沿道路向西骑回，然后向北进入怒痕山丘。这里的每个雪人都可能掉落毛皮；可能会掉落{quest:7735}，{npc:7852}也会收购。",
	["Ride east to the Gordunni camp in the hills south-east of the yeti valley: Warlocks and Shaman hold the camp, Brutes wander the slopes around it and further north."] = "向东骑到雪人山谷东南方山丘上的戈杜尼营地：戈杜尼术士和戈杜尼萨满祭司占据着营地，戈杜尼蛮兵在周围和更北边的山坡上游荡。",
	["Ride north into the yeti valley. Every Feral Scar yeti can drop a thick hide; {npc:5346} (level 48) prowls the middle."] = "向北骑进雪人山谷。每个深痕雪人都可能掉落厚毛皮；{npc:5346}（48级）在中间潜行。",
	["Ride north-east to the night elf outpost on the {zone:1441} border."] = "向东北骑到{zone:1441}边境上的暗夜精灵前哨。",
	["Ride south-east to the Woodpaw gnolls; the courier's backpacks lie in their southern camp, and a parcel inside them starts a delivery to {area:489}. The Zukk'ash hive is just south: fight down to the pod that holds Raschal, free him and keep him alive on the way out."] = "向东南骑到木爪豺狼人那里；信使的背包在它们南边的营地里，其中的一个包裹会开始一个送往{area:489}的任务。祖卡什虫巢就在南边：一路打到关着拉斯卡尔的茧，救出他并在出去的路上保护他。",
	["Shore Striders, Deep Striders and Wave Striders (elite giants) wade along the coast north of the dock: zap one with {item:18904} and kill the shrunken giant. Sea Elementals and Sea Sprays drift in the same surf."] = "海岸巨人、深海巨人和波涛巨人（精英巨人）在码头北边的海岸涉水：用{item:18904}电一只，然后杀掉缩小的巨人。海元素和巨型海元素在同一片浪花中飘荡。",
	["Take the boat to the {area:1108} and follow the shore south to the wrecked row boat on the beach."] = "乘船前往{area:1108}，沿海岸向南走到海滩上失事的小船。",
	["The courier's boat"] = "信使的船",
	["The {area:1121} is the island just south of {area:1120}: swim over. Hatecrest Serpent Guards and Sorceresses hold it; {npc:8136} (level 47) waits in the cave at its south end. Pull his guards first."] = "{area:1121}是{area:1120}正南的岛屿：游过去。憎恨之鳞毒蛇守卫和女巫占据着它；{npc:8136}（47级）在岛南端的洞里等着。先拉他的卫兵。",
	["Walk south along the island to the naga ruins; the gazebo stands among them."] = "沿岛向南走到纳迦废墟；索兰萨尔瞭望台在废墟中。",
	["You end at the {area:1108} dock: the {zone:1446} guide starts with the trip east from here."] = "你在{area:1108}的码头结束：{zone:1446}指南从这里向东出发开始。",
	["for Tyrande in {zone:1457}: the route takes you there at 47"] = "交给{zone:1457}的泰兰德·语风：路线会在47级带你去那里",
	["grind on {npc:5292} at {area:1105}, {area:357}"] = "在{area:1105}、{area:357}刷{npc:5292}",
	["{area:1108}: kill these as you meet them"] = "{area:1108}：遇到就杀",
	["{area:1116} stands on {area:1120}, off the {area:1108}: the boat from the coast's dock crosses to it. {npc:7880} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "{area:1116}位于{area:1108}外的{area:1120}上：海岸码头的船会开过去。{npc:7880}站在他屋子的楼上：从里面上楼，箭头分不清楼层。",
	["{area:1136}: kill these as you meet them"] = "{area:1136}：遇到就杀",
	["{area:489} flight master"] = "{area:489}飞行管理员",
	["{item:11463}, from the backpacks"] = "{item:11463}，来自背包",
	["{item:9248}; below ground"] = "{item:9248}；地下",
	["{npc:14637}'s refills are level 55: skip them."] = "{npc:14637}的补充任务是55级：跳过。",
	["{npc:3936} then asks you to carry news to {zone:1457}: skip it, {area:976} sends you there instead."] = "{npc:3936}接着会让你把消息带到{zone:1457}：跳过，{area:976}会让你去那里。",
	["{npc:3936}, beside him"] = "{npc:3936}，在他旁边",
	["{npc:4048} walks around {area:489}: look inside the circle on the map"] = "{npc:4048}在{area:489}附近走动：看地图上的圆圈内",
	["{npc:7764}: his answer waits in {area:702}, later"] = "{npc:7764}：他的回复之后在{area:702}等你",
	["{npc:7877}, at the top of the stronghold"] = "{npc:7877}，在要塞顶层",
	["{npc:7879}, upstairs"] = "{npc:7879}，楼上",
	["{npc:7880} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "{npc:7880}站在他屋子的楼上：从里面上楼，箭头分不清楼层。",
	["{npc:8136} waits for the end of the mainland loop."] = "{npc:8136}留到大陆环线结束时。",
	["{object:164954}, inside"] = "{object:164954}，室内",
}

G["forever/alliance/40-50/04-tanaris"] = {
	["Boat to {area:150}"] = "乘船前往{area:150}",
	["Careful: Thieves cast Disarm. Rogues stay hidden with Sneak. Assassins use Execute when your health is at 20% or lower."] = "注意：窃贼会施放缴械。盗贼用潜行保持隐蔽。刺客在你血量20%或更低时使用斩杀。",
	["Dunemaul Brute"] = "砂槌蛮兵",
	["Dunemaul Enforcer"] = "砂槌打手",
	["Fly to Theramore"] = "飞往塞拉摩岛",
	["Fly to {area:348}"] = "飞往{area:348}",
	["Follow the coast south to the pirate cove. Southsea pirates crowd the beach and the boats: work along the edge and pull one at a time. {npc:7883} stands on the far side; {npc:7881}'s stolen cargo lies in the camp.\nCareful: Two or three pirates stand with {npc:7883}, and many more pirates from the town join the fight once it starts."] = "沿海岸向南前往海盗湾。南海海盗挤满沙滩和船只：沿边缘行动，一次拉一只。{npc:7883}在对面；{npc:7881}被偷的货物在营地里。\n注意：有两三个海盗和{npc:7883}站在一起，战斗一开始还会有更多镇上的海盗加入。",
	["Gives the {item:8585}"] = "获得{item:8585}",
	["Gnarled Thistleshrub"] = "多节的蓟灌木",
	["Gor'marok the Ravager"] = "蹂躏者戈玛洛克",
	["He runs off to keep Rizzle busy"] = "他会跑去拖住Rizzle",
	["Pool by {area:979}"] = "{area:979}旁的水池",
	["Ride back west to {area:976}."] = "向西骑回{area:976}。",
	["Ride back west toward {area:976}. The Wastewander bandits and thieves hold the dunes on the way; any of them can carry a water pouch.\nCareful: Wastewander Rogues (level 43-44) move stealthed, so they can approach unseen."] = "骑马向西返回{area:976}。废土强盗和窃贼占据着路上的沙丘；其中任何一个都可能带着水袋。\n注意：废土盗贼（43-44级）潜行移动，可能悄悄靠近。",
	["Ride east across the dunes to the goblin harbour on the north-east coast."] = "向东骑过沙丘到东北海岸的地精港口热砂港。",
	["Ride north-west to the Centipaar hive in the dunes. Any Centipaar can drop insect parts.\nCareful: Centipaar Swarmers cast {npc:4196} both in and out of combat, which brings small adds that interrupt you."] = "骑马向西北前往沙丘中的森提帕虫巢。任何森提帕虫都可能掉落昆虫部件。\n注意：森提帕群居者不论战斗内外都会施放{npc:4196}，召来打断你的小增援。",
	["Ride north-west to the Sandfury troll camp at {area:979}. Use the {item:8584} at the edge of its pool; the trolls stand close, so pull the nearest first."] = "向西北骑到{area:979}的沙怒巨魔营地。在水池边缘使用{item:8584}；巨魔站得很近，先拉最近的。",
	["Ride south into {quest:3362}. The Dew Collectors drop the glands; only some are full, so keep the Laden one. Gnarled Thistleshrubs and Rootshapers share the valley. The Thistleshrubs are 48-50, above you: pull one at a time.\nCareful: The other thistleshrub mobs in the area are level 49-50 and wander a lot, so you can easily pull extra mobs."] = "骑马向南进入{quest:3362}。露水收集者掉落露腺；只有部分是饱满的，因此只留饱满的那一个。多节的蓟灌木和塑根者共处山谷。蓟灌木是48-50级，高于你：一次拉一只。\n注意：该区域其他蓟灌木怪是49-50级，且活动范围广，很容易多拉怪。",
	["Ride south past the {area:1938} to the {area:981}, the Hazzali tunnels; Scrimshank's gear lies deep inside.\nCareful: One bug guards the gear. Many bugs patrol the tunnels, some of them level 50, so fights often pull extra adds."] = "骑马向南经过{area:1938}前往{area:981}，即哈扎利隧道；斯克林克的装备在深处。\n注意：一只虫子守着装备。许多虫子在隧道里巡逻，其中一些是50级，所以战斗常会多拉怪。",
	["Ride south to the dig camp at the {area:1938}. {npc:7771} hands you a detector helm: wear it to see the {quest:3161} mounds, which lie thick in the sand around the camp and south-west toward the ogres."] = "向南骑到{area:1938}的挖掘营地。{npc:7771}会给你一顶探测头盔：戴上它才能看到{quest:3161}土堆，营地周围和向西南通往食人魔的沙地里到处都是。",
	["Ride south-east off the {area:439} into {area:440}. {area:976} is just inside the border."] = "骑马向东南离开{area:439}进入{area:440}。{area:976}就在边界内侧。",
	["Ride south-east to {area:985}. {npc:7847} stands in the middle of the southern Wastewander camp: clear around him first.\nCareful: Two stealthed Wastewander Rogues travel with him wherever he goes. At his spawn camp, two shadowmages and their minions are close enough to join a fight with him. Out by the towers you can fight him without them."] = "骑马向东南前往{area:985}。{npc:7847}站在废土营地南部的中央：先清掉他周围。\n注意：两名潜行的废土盗贼跟着他移动。在他的刷新营地，两名暗法师及其仆从距离很近，能加入与他的战斗。在塔楼外则可以不受他们干扰地打他。",
	["Ride south-west to the ogre compound. Brutes and Enforcers (46-48) fill it; {npc:12046} (49) stands in the middle with guards around him: clear them first."] = "向西南骑到砂槌营地。里面满是砂槌蛮兵和砂槌执行者（46-48级）；{npc:12046}（49级）站在中间，周围有卫兵：先清理卫兵。",
	["Southsea Dock Worker"] = "南海码头工人",
	["Southsea Freebooter"] = "南海劫掠者",
	["Southsea Pirate"] = "南海海盗",
	["Southsea Swashbuckler"] = "南海剑客",
	["The Wanted poster beside him"] = "他旁边的通缉布告",
	["The little turtle {npc:5955} hides at the north end of the valley. Lead him home to his wife {npc:6015}, by the water just east of {area:977}: he walks slowly and the desert's beasts go for him, so keep him alive."] = "小乌龟{npc:5955}躲在山谷北端。带他回家去找他妻子{npc:6015}，她在{area:977}东边不远处的水边：他走得慢，沙漠里的野兽会攻击他，保护好他。",
	["The pool by {area:979}"] = "{area:979}旁的水池",
	["The same poster: {npc:7847} comes much later, after {area:976}"] = "同一张告示：{npc:7847}要很久以后才会出现，在{area:976}之后",
	["The tougher Wastewander rogues, shadow mages and assassins camp south-east of {area:976}, south of the bandits. Leave {npc:7847} in the middle of the southern camp for later.\nCareful: Wastewander Rogues keep Sneak up while out of combat, so hidden rogues can join a fight you start at a camp."] = "更强的废土盗贼、暗法师和刺客在{area:976}东南、强盗南边扎营。把南营地中央的{npc:7847}留到后面。\n注意：废土盗贼在脱战时保持潜行，因此藏着的盗贼可能加入你在营地挑起的战斗。",
	["The {area:1938}"] = "{area:1938}",
	["The {area:2240} lies on the {area:439} in south-east {area:400}. {npc:4454} and {npc:4630} are in the camps beside the track.\n{npc:4709} stands by the goblin camp.\nWhile {npc:4709} keeps Rizzle talking, his plans lie unguarded in the gnome camp across the track."] = "{area:2240}位于{area:400}东南的{area:439}上。{npc:4454}和{npc:4630}在赛道旁的营地。\n{npc:4709}站在地精营地旁。\n趁{npc:4709}缠住里兹尔说话时，他的计划就无人看守地放在赛道对面的侏儒营地里。",
	["Thistleshrub Rootshaper"] = "蓟灌木塑根者",
	["Underwater"] = "水下",
	["Wastewander Assassin"] = "废土刺客",
	["Wastewander Bandit"] = "废土强盗",
	["Wastewander Rogue"] = "废土盗贼",
	["Wastewander Shadow Mage"] = "废土暗法师",
	["Wastewander Thief"] = "废土窃贼",
	["for {zone:1457}: the route takes you there at 47"] = "交给{zone:1457}：路线会在47级带你去那里",
	["grind on {npc:5474}"] = "刷{npc:5474}",
	["{area:1336}: kill these as you meet them"] = "{area:1336}：遇到就杀",
	["{area:150} flight master"] = "{area:150}飞行管理员",
	["{area:1937}: kill these as you meet them"] = "{area:1937}：遇到就杀",
	["{area:976} flight master"] = "{area:976}飞行管理员",
	["{item:8593}; below ground"] = "{item:8593}；地下",
	["{npc:11758}, on the east side of town"] = "{npc:11758}，在镇子东侧",
	["{npc:12046}, below ground"] = "{npc:12046}，地下",
	["{npc:5594}, inside"] = "{npc:5594}，室内",
	["{npc:5955}'s escort"] = "{npc:5955}的护送",
	["{npc:7407}, by the water tower"] = "{npc:7407}，在水塔旁",
	["{npc:7408}, next to him"] = "{npc:7408}，在他旁边",
	["{npc:7583}'s next ingredient grows in the {area:47}, and the route never brings it back: skip it."] = "{npc:7583}下一种材料生长在{area:47}，而路线不会再回到那里：跳过它。",
	["{npc:7763}: his crate goes to {area:702}, later"] = "{npc:7763}：他的箱子之后送到{area:702}",
	["{npc:7881}'s next delivery goes back to {area:35}: skip it."] = "{npc:7881}的下一趟送货要回{area:35}：跳过。",
	["{npc:7881}, in the port's tavern; inside"] = "{npc:7881}，在港口酒馆里；室内",
	["{npc:7881}, inside"] = "{npc:7881}，室内",
	["{npc:7882}, inside"] = "{npc:7882}，室内",
	["{object:20805}, inside"] = "{object:20805}，室内",
	["{quest:2864}, north side of town"] = "{quest:2864}，镇子北侧",
	["{quest:2873}; upstairs"] = "{quest:2873}；楼上",
	["{quest:3362}: kill these as you meet them"] = "{quest:3362}：遇到就杀",
}

G["forever/alliance/40-50/05-the-hinterlands"] = {
	["Boat to {area:17203}"] = "坐船到{area:17203}",
	["Class trainer"] = "职业训练师",
	["Fly to {area:144}"] = "飞往{area:144}",
	["Fly to {area:150}"] = "飞往{area:150}",
	["Fly to {area:1537}"] = "飞往{area:1537}",
	["Fly to {area:35}"] = "飞往{area:35}",
	["Fly to {area:442}"] = "飞往{area:442}",
	["Fly to {area:69}"] = "飞往{area:69}",
	["Green Sludge"] = "绿色淤泥怪",
	["Inside"] = "在里面",
	["Into {area:38}"] = "进入{area:38}",
	["Into {area:3}"] = "进入{area:3}",
	["Jade Ooze"] = "碧玉软泥怪",
	["Portal to {area:141}"] = "传送门到{area:141}",
	["Ride back north to Ironband's camp."] = "向北骑回铁环挖掘场的营地。",
	["Ride east along the south shore of the loch to Ironband's camp."] = "沿湖南岸向东骑到铁环挖掘场的营地。",
	["Ride north to {area:351} in the middle of the {zone:1425}. Green Sludges and Jade Oozes crawl all around it.\nCareful: Panthers move around the area in stealth."] = "向北骑到{zone:1425}中部的{area:351}。绿色淤泥怪和碧玉软泥怪在四周爬行。\n注意：豹子会潜行在区域里游荡。",
	["Ride on east along the road to the keep first: the {item:6091} expires an hour after {area:42}, and the bloodmages' beasts take longer than that."] = "先沿道路继续向东到城堡：{item:6091}在离开{area:42}一小时后失效，而血法师要的野兽需要更长时间。",
	["Ride south through the pass into the {area:3}' northern edge: the Stonevault troggs dig outside {area:1517} there. The carved urns and the magenta mushroom clusters sit in their caves and tunnels, outside the dungeon itself."] = "向南穿过山口进入{area:3}的北缘：石穹穴居人在那里的{area:1517}外挖掘。雕花瓮和紫红色蘑菇簇就在他们的洞穴和隧道里，位于副本之外。",
	["Ride south-east to the {area:355}, the stepped Vilebranch temple in the south of the {zone:1425}, and climb to the top. Qiaga and {npc:8636} (elite, 50) stand up there: touch the top and come straight back down.\nCareful: Elite trolls guard the top platform, including {npc:7996} and {npc:8636}, along with several Vilebranch Soothsayers. The soothsayers cast spells and are linked to the rest of the group."] = "向东南骑到{area:355}，即{zone:1425}南部层层叠叠的邪枝神庙，一路爬顶层。琪亚加和{npc:8636}（精英，50级）驻守在那里：摸到顶部就立刻折返。\n注意：精英巨魔守卫顶层平台，包括{npc:7996}和{npc:8636}，还有几名邪枝预言者。预言者会施法，并与同组其他成员联动。",
	["Ride west: Starving Snickerfangs roam the dry hills just south of the bloodmages' camp; Scorpok Stingers (level 50) scuttle across the middle of the north. {npc:5982} vultures circle over all of it. Pull one at a time.\nAshmane Boars and Redstone Basilisks share the slopes south-west of the keep. Keep clear of the Helboars further south: they are level 52.\nCareful: Scorpok Stingers use {spell:5416}; {npc:8301} adds Knockdown."] = "向西骑：饥饿的窃齿兽在血法师营地南边的干旱丘陵游荡；斯科普克刺蝎（50级）在北侧中部爬行。{npc:5982}秃鹫在整片区域上空盘旋。一次只拉一只。\n灰鬃野猪和红石蜥蜴分布在堡垒西南的斜坡上。远离更南边的地狱野猪：它们是52级。\n注意：斯科普克刺蝎会使用{spell:5416}；{npc:8301}会附带击倒。",
	["Step through the portal into {zone:1457}. The Temple of the Moon is in the south of the city."] = "穿过传送门进入{zone:1457}。月神殿在城市南部。",
	["Temple of the Moon"] = "月神殿",
	["The bloodmages"] = "血法师",
	["The bloodmages' camp is the first stop beside the road into the {area:4}, north-west of {area:1438}."] = "血法师营地是通往{area:4}的路旁第一个落脚点，位于{area:1438}西北。",
	["The bloodmages' second tier pays for the same parts with a buff item and no experience: skip it."] = "血法师的第二阶段用增益物品而不是经验来交换同样的材料：跳过。",
	["The {area:1517} dig"] = "{area:1517}挖掘场",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:1494} (level 52 elite) needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "这些是精英怪：建议组队，找人一起做。{npc:1494}（52级精英）需要2人组队。独自一人时跳过：路线里安排了刷怪补回经验。",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {quest:8552} needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "这些是精英怪：建议组队，找人一起做。{quest:8552}需要2人组队。独自一人时跳过：路线里安排了刷怪补回经验。",
	["Tram to {zone:1453}"] = "乘地铁到{zone:1453}",
	["for {quest:2990} at {area:1438}, later"] = "之后交给{area:1438}的{quest:2990}",
	["the book on her table"] = "她桌上的书",
	["the soil comes from {zone:1449}, later"] = "土壤之后从{zone:1449}获得",
	["{area:1438} flight master"] = "{area:1438}飞行管理员",
	["{area:144} flight master"] = "{area:144}飞行管理员",
	["{area:2418} flight master"] = "{area:2418}飞行管理员",
	["{area:348} flight master"] = "{area:348}飞行管理员",
	["{area:42} flight master"] = "{area:42}飞行管理员",
	["{area:4}: kill these as you meet them"] = "{area:4}：遇到就杀",
	["{area:702} flight master"] = "{area:702}飞行管理员",
	["{item:8047}; below ground"] = "{item:8047}；地下",
