G["forever/alliance/40-50/06-searing-gorge"] = {
	["Below ground"] = "地下",
	["Class trainer"] = "职业训练师",
	["Dark Iron Geologist"] = "黑铁地质学家",
	["Dark Iron Slaver"] = "黑铁奴隶贩子",
	["Dark Iron Taskmaster"] = "黑铁监工",
	["Fly to {area:1537}"] = "飞往{area:1537}",
	["For {npc:8256} in {area:1537}, later"] = "给{area:1537}的{npc:8256}，稍后",
	["From {area:144} ride south into the {zone:1418}, then west past the Horde town of {area:340} (give it room) and up the trail into {area:51}. {area:1446} is the scaffolded camp on the north-west rim."] = "从{area:144}向南骑进{zone:1418}，然后向西经过部落城镇{area:340}（绕开它），再沿小路向上进入{area:51}。{area:1446}是西北边缘搭着脚手架的营地。",
	["Greater Lava Spider"] = "巨型熔岩蜘蛛",
	["Greater Lava Spiders"] = "灼热熔岩蜘蛛",
	["Heavy War Golem"] = "重型战争傀儡",
	["If you skipped The {item:3985} or Facing Negolash, grind here to level 48.27 to stay on the route's plan."] = "如果你跳过了{item:3985}或“直面内戈拉什”任务，就在这里刷到48.27级，以保持攻略的节奏。",
	["If you skipped {quest:3452}, grind here to level 48.98 to stay on the route's plan."] = "如果你跳过了{quest:3452}，就在这里刷到48.98级，以保持攻略的节奏。",
	["If you skipped {quest:7701}, grind here to level 48.66 to stay on the route's plan."] = "如果你跳过了{quest:7701}，就在这里刷到48.66级，以保持攻略的节奏。",
	["Incendosaur"] = "炎蜥",
	["Into {area:51}"] = "进入{area:51}",
	["Kalaran Windblade"] = "卡拉兰·风刃",
	["Kalaran stands on the rim of the Cauldron, south of {area:1446}. Listen to his story."] = "卡拉然·温布雷站在{area:1446}南边的大熔炉边缘。听他讲述他的故事。",
	["Level 48.27"] = "48.27级",
	["Level 48.66"] = "48.66级",
	["Level 48.98"] = "48.98级",
	["On the way"] = "途中",
	["Ride east across the Cauldron to the {area:247} in the south-east. The prisoner in the wooden outhouse wants 15 {item:4306} and eight dead Dark Iron Geologists from the dig site around it. The outhouse also opens with the key, if you found one.\nThe dwarf stands by the road at the dig site. When it is over, read the {object:175704} he leaves on the road in {area:1959}."] = "向东骑过火山口，前往东南的{area:247}。木制茅房里的囚犯要15个{item:4306}，以及其周围挖掘场里的八名黑铁地质学家。如果你找到了钥匙，茅房也可以用钥匙打开。\n那名矮人站在挖掘场路边。结束后，阅读他留在{area:1959}路上的{object:175704}。",
	["The Grimesilt outhouse"] = "格里塞特厕所",
	["The night elf stands alone west of {area:1446}. Hear his story."] = "那个暗夜精灵独自站在{area:1446}西边。听他讲述他的故事。",
	["The prisoner's next task, Ledger from {zone:1446}, sends you to the {zone:1435} and {zone:1445}: skip it."] = "囚犯的下一个任务“{zone:1446}的账本”会让你去{zone:1435}和{zone:1445}：跳过。",
	["The spiders roam the plateaus and lava pools in the south-west of the gorge.\nHeavy War Golems patrol the floor of the Cauldron below Kalaran; Magma Elementals drift among them. Golems and elementals drop the oil, elementals the hearts.\nTaskmasters and Slavers drive the slaves all over the Cauldron, and any of them can carry a {item:10551}. The Steamsmiths work at the furnaces in the middle (the {item:18959}), the Lookouts stand on the southern ridges (the Spyglass). Any {object:147516} may drop the {item:11818}: keep it.\nCareful: Dark Iron Slavers (level 45-46) call for help from allies within 15 yd when pulled, cast Net from up to 15 yd, and use Rend in melee."] = "蜘蛛在峡谷西南的高地和熔岩池出没。\n重型战争傀儡在卡拉兰下方的火山口地面上巡逻；岩浆元素在它们之间游荡。傀儡和元素掉落油，元素掉落心脏。\n监工和奴隶贩子驱赶着奴隶遍布火山口，他们中的任何一个都可能携带{item:10551}。蒸汽铁匠在中央的熔炉干活（{item:18959}），瞭望员站在南边的山脊上（望远镜）。任何{object:147516}都可能掉落{item:11818}：留着。\n注意：黑铁奴隶贩子（45-46级）被拉时向15码内的盟友求援，还会从最多15码外撒网，并在近战中使用撕裂。",
	["The {object:179827} board"] = "{object:179827}布告板",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:14621} is a level 50 elite: most classes solo it at level 52, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "这些是精英怪：建议组队，找人来一起做。{npc:14621}是50级精英：大多数职业52级可以单挑，但你可能需要帮忙。如果只有你一个人就跳过：路线会安排你刷怪补经验。",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:5860} (level 50 elite) needs a group of 3. Skip it if you are alone: the route has you grind the XP back."] = "这些是精英怪：建议组队，找人来一起做。{npc:5860}（50级精英）需要3人小队。如果只有你一个人就跳过：路线会安排你刷怪补经验。",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {quest:3181} needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "这些是精英怪：建议组队，找人来一起做。{quest:3181}需要2人小队。如果只有你一个人就跳过：路线会安排你刷怪补经验。",
	["To {area:2101}"] = "前往{area:2101}",
	["Zamael Lunthistle"] = "扎玛尔·伦西斯尔",
	["grind on {npc:5839}"] = "刷{npc:5839}",
	["grind on {npc:5844}"] = "刷{npc:5844}",
	["grind on {npc:9318}"] = "刷{npc:9318}",
	["{area:1442}: kill these as you meet them"] = "{area:1442}：遇到就杀",
	["{area:1443} opens in the north of the Cauldron. The Secret Plans lie on its upper ledge; Incendosaurs swim in the lava pools further in, so pull them to the edge. Stay clear of {npc:14621} and his elite guards deep inside."] = "{area:1443}的入口在大熔炉北部。秘密设计图在上层岩架上；熏火龙在更深处的熔岩池里游动，把它们拉到池边。远离深处的{npc:14621}和他的精英卫兵。",
	["{area:1446} flight master"] = "{area:1446}飞行管理员",
	["{area:51}: kill these as you meet them"] = "{area:51}：遇到就杀",
	["{item:10551} on the way"] = "{item:10551}，途中",
	["{item:18922}; below ground"] = "{item:18922}；地下",
	["{npc:5844} along the way to {area:1446}"] = "前往{area:1446}途中的{npc:5844}",
	["{npc:5846} along the way to {area:1446}"] = "前往{area:1446}途中的{npc:5846}",
	["{npc:5858} on the way"] = "{npc:5858}，途中",
	["{npc:9318} along the way to {area:1446}"] = "前往{area:1446}途中的{npc:9318}",
	["{npc:9318} on the way"] = "{npc:9318}，途中",
	["{object:147516} dwarves"] = "{object:147516}矮人",
}

G["forever/alliance/40-50/07-un-goro-crater"] = {
	["Archesonus stands beside King Magni in the {object:171709}."] = "阿克瑟努斯站在{object:171709}中麦格尼国王旁边。",
	["Below ground"] = "地下",
	["Bind and train"] = "设置炉石并训练",
	["Bones and equipment"] = "骨头和设备",
	["Class trainer"] = "职业训练师",
	["Dinosaur Bones lie on the ground in the south-west, among the stegodons: those are elite, pick the bones up around them and take the rest from Diemetradons. The expedition's {item:11112} lies in the south-west jungle."] = "恐龙骨头散落在西南部的地面上，在剑龙之间：剑龙是精英，在它们周围捡骨头，其余的从双帆龙身上获取。探险队的{item:11112}在西南部丛林中。",
	["Eastern Pylon"] = "东部水晶塔",
	["Ends with {npc:9298} in {zone:1452}: keep it"] = "在{zone:1452}的{npc:9298}处结束：留着",
	["Fly to {area:150}"] = "飞往{area:150}",
	["Fly to {area:1537}"] = "飞往{area:1537}",
	["Fly to {area:415}"] = "飞往{area:415}",
	["Fly to {area:976}"] = "飞往{area:976}",
	["For {npc:7775} in {zone:1444}: keep it"] = "交给{zone:1444}的{npc:7775}：留着",
	["Four rune rubbings in {zone:1447}: keep it"] = "{zone:1447}的四个符文拓片：留着",
	["Lar'korwi Mates and the raft"] = "拉克维的配偶和木筏",
	["Level 49.51"] = "49.51级",
	["Level 50.4"] = "50.4级",
	["Northern Pylon"] = "北部水晶塔",
	["Pterrordax"] = "翼手龙",
	["Ride north along the western jungle back to the refuge."] = "沿西部丛林向北骑回避难所。",
	["Ride north to {area:1943}, where the robot stands among the gorillas. Stay out of the deep cave there."] = "向北骑行到{area:1943}，机器人站在猩猩中间。别进那里的深洞。",
	["Ride south down the east side. Young Diemetradons graze the eastern jungle and {npc:9165} fly near the eastern cliffs; both drop {npc:9998}'s scales."] = "沿东侧向南骑行。幼双帆龙在东部丛林吃草，{npc:9165}在东部悬崖附近飞行；两者都掉落{npc:9998}要的鳞片。",
	["Ride south to {area:537} in the middle of the crater, then east into the eastern jungle. Crystal clusters stand all over the crater, many of them around {area:537}: take a few extra of each colour. Bloodpetal Lashers and Threshers drop the petals; the expedition's {item:11113} sits at an abandoned camp in the eastern jungle."] = "向南骑到陨石坑中央的{area:537}，然后向东进入东部丛林。水晶簇遍布陨石坑，许多在{area:537}周围：每种颜色多拿几个。血瓣花鞭笞者和血瓣花猛击者掉落花瓣；远征队的{item:11113}在东部丛林的一处废弃营地里。",
	["Ride west back to the refuge.\nGive the elite devilsaurs and stegodons a wide berth. Pick up every Power Crystal and {object:157936} you pass from here on."] = "向西骑回营地。\n远远绕开精英魔暴龙和剑龙。从这里开始，路上遇到的每个能量水晶和{object:157936}都捡起来。",
	["Ride west from {npc:9619}: the silithid hive fills the south of the crater. Use the Scraping Vial on a hatchery, a chamber with hanging larvae. Gorishi wasps and workers drop {quest:3764}; Pterrordax nest on the southern cliffs if you still need kills.\nCareful: Gorishi silithids are level 51-54 and cast {spell:8137} or {spell:14120} in melee; Gorishi Workers have a 50% chance to call for help within 25 yd once they fall below 45% health."] = "从{npc:9619}向西骑：异种虫巢穴布满火山口南部。在一处孵化室（挂着幼虫的房间）使用刮取小瓶。格里什黄蜂和工虫掉落{quest:3764}；如果还需要击杀数，翼手龙在南边的悬崖筑巢。\n小心：格里什异种虫为51-54级，近战时施放{spell:8137}或{spell:14120}；格里什工虫血量降到45%以下时，有50%几率在25码内呼救。",
	["Ride west out of {area:976} to the long ramp down into {area:490}. {npc:9619} camps at the foot of the ramp, in the south-east corner of the crater."] = "从{area:976}向西骑，沿长坡下到{area:490}。{npc:9619}在坡底扎营，位于火山口的东南角。",
	["The Gorishi hive"] = "格里什虫巢",
	["The Lar'korwi Mates prowl the jungle west of {npc:9619}. The wrecked raft lies on the shore of the lake there; the small pack sits in the water beside it. Keep the compass, map and key for {npc:8737}. Any beast in the crater may drop {item:11116}: right-click it."] = "拉克维的配偶在{npc:9619}西边的丛林中徘徊。失事的木筏在那里的湖岸上；小背包在它旁边的水里。指南针、地图和钥匙留给{npc:8737}。环形山中任何野兽都可能掉落{item:11116}：右键点击它。",
	["The dead Threshadon lies by the water north of {npc:9619}."] = "死去的蛇颈龙躺在{npc:9619}北边的水边。",
	["The flight from Theramore lands in {area:976}."] = "从塞拉摩起飞的航班降落在{area:976}。",
	["The pylon stands on the eastern cliffs."] = "水晶塔立在东部悬崖上。",
	["The pylon stands on the slope east of the refuge. Pterrordax circle the slopes around it: they count for Spraggle and drop {npc:9998}'s scales."] = "能量塔立在营地东边的斜坡上。翼手龙在它周围的斜坡盘旋：它们算作斯普拉格的进度，并掉落{npc:9998}的鳞片。",
	["The pylon stands on the western cliffs. {npc:9167} fly over the whole west side."] = "水晶塔立在西部悬崖上。{npc:9167}在整个西侧上空飞行。",
	["The relics are in the {zone:1428}: keep it"] = "圣物在{zone:1428}：留着",
	["Theramore flight master"] = "塞拉摩飞行管理员",
	["To {area:2101}"] = "前往{area:2101}",
	["Top up here to level 49.51 before the hand-ins at {area:541}: they take you to level 50."] = "在{area:541}交任务前，先在这里刷到49.51级：交完后能到50级。",
	["Top up here to level 50.4 before the hand-ins at {area:3137}: they take you to level 51."] = "在{area:3137}交任务前，先在这里刷到50.4级：交完后能到51级。",
	["Western Pylon"] = "西部水晶塔",
	["Xiggs waits in the {object:32359}."] = "西格斯在{object:32359}等候。",
	["grind on Pterrordax"] = "刷翼手龙",
	["grind on {npc:6116}"] = "刷{npc:6116}",
	["grind on {npc:9164}"] = "刷{npc:9164}",
	["grind on {npc:9167}"] = "刷{npc:9167}",
	["{area:144} flight master"] = "{area:144}飞行管理员",
	["{area:442} flight master"] = "{area:442}飞行管理员",
	["{area:490}: kill these as you meet them"] = "{area:490}：遇到就杀",
	["{area:537} and the eastern jungle"] = "{area:537}和东部丛林",
	["{item:11834} from {npc:6518} and {npc:6519}, 60 yd south"] = "{item:11834}来自{npc:6518}和{npc:6519}，在南边60码",
	["{npc:11406}: for Ogtinc in {zone:1447}, keep it"] = "{npc:11406}：交给{zone:1447}的奥汀克，留着",
	["{npc:9117}, at the back of the cave; below ground"] = "{npc:9117}，在洞穴深处；地下",
	["{npc:9117}, below ground"] = "{npc:9117}，地下",
	["{npc:9616}: the oozes are in {zone:1448}, keep it"] = "{npc:9616}：软泥怪在{zone:1448}，留着",
	["{npc:9618} stands just outside the refuge."] = "{npc:9618}站在避难所外面。",
	["{npc:9998}, at the refuge entrance"] = "{npc:9998}，在避难所入口",
	["{npc:9998}, at the refuge's entrance"] = "{npc:9998}，在避难所入口",
	["{object:161504}, underwater"] = "{object:161504}，水下",
	["{zone:1455} flight master"] = "{zone:1455}飞行管理员",
}

G["forever/alliance/50-60/01-burning-steppes"] = {
	["Archesonus stands beside King Magni in the {object:171709}."] = "阿克瑟努斯站在{object:171709}中麦格尼国王旁边。",
	["Back to {area:141}"] = "返回{area:141}",
	["Below ground"] = "地下",
	["Climb to the top of {area:249} and plant the head in the soft dirt mound."] = "爬到{area:249}顶端，把头颅插在松软的土堆上。",
	["Druid training"] = "德鲁伊训练",
	["Ends with {quest:4808} in {area:2255}, {zone:1452}: keep it"] = "在{zone:1452}{area:2255}的{quest:4808}处结束：留着",
	["Firegut Brute"] = "火腹蛮兵",
	["Firegut Ogre"] = "火腹食人魔",
	["Firegut Ogre Mage"] = "火腹食人魔法师",
	["Fly to {area:1438}"] = "飞往{area:1438}",
	["Fly to {area:1537}"] = "飞往{area:1537}",
	["Fly to {area:2418}"] = "飞往{area:2418}",
	["Fly to {area:271}"] = "飞往{area:271}",
	["Fly to {area:348}"] = "飞往{area:348}",
	["Fly to {area:702}"] = "飞往{area:702}",
	["Follow the road west, then climb north to the goblin camp on {area:251}."] = "沿道路向西，然后向北爬到{area:251}上的地精营地。",
	["For {zone:1453}: keep it"] = "交给{zone:1453}：先留着",
	["Haldarr Felsworn"] = "哈达尔邪誓者",
	["Haldarr Satyr"] = "哈达尔萨特",
	["Haldarr Trickster"] = "哈达尔欺诈者",
	["Highborne Apparition"] = "上层精灵幻影",
	["Highborne Lichling"] = "上层精灵小巫妖",
	["If you skipped {quest:4022}, grind here to level 52.08 to stay on the route's plan."] = "如果你跳过了{quest:4022}，就在这里刷到52.08级，以符合路线规划。",
	["Kum'isha waits at the {area:2517}, the hill south-west of the keep. The {zone:1419} mobs on the way drop the Imperfect Draenethyst Fragments; bring her what you have.\nCareful: Felcular, {npc:7664} and Ilifar are all level 60 elites. Razelikh casts {spell:2691}, {spell:8255} and Decimate, and as its health drops it adds {object:141891}, {spell:10854} and then Enrage at 15%."] = "库米沙在{area:2517}等候，那是城堡西南的山丘。路上的{zone:1419}怪物会掉落不完美的德莱尼水晶碎片；把已有的都带给她。\n小心：费尔库拉、{npc:7664}和伊里法尔都是60级精英。拉兹利克会施放{spell:2691}、{spell:8255}和屠灭，随着生命值下降，它还会加上{object:141891}、{spell:10854}，然后在15%时进入狂暴。",
	["Level 50.89"] = "50.89级",
	["Level 51.39"] = "51.39级",
	["Level 52"] = "52级",
	["Level 52.08"] = "52.08级",
	["Mosshoof Coursers"] = "苔蹄快步者",
	["Optional: {npc:8395} wants two Undamaged Hippogryph Feathers from the hippogryphs around his camp. The data lists no experience for it."] = "可选：{npc:8395}要两根完好无损的角鹰兽羽毛，从他营地周围的角鹰兽身上获取。数据显示这个任务没有经验。",
	["Ride back east along the road to the Vigil."] = "沿道路向东骑回守望堡。",
	["Ride back south to the camp."] = "向南骑回营地。",
	["Ride north-east from the shrine: {npc:8405} camps at the {area:1224}, in the hills above the road."] = "从神殿向东北骑行：{npc:8405}在道路上方山丘中的{area:1224}扎营。",
	["Swim to the small island off the southern tip of {area:16}: {npc:8392} waits by the monument."] = "游到{area:16}南端外的小岛：{npc:8392}在纪念碑旁等候。",
	["The Firegut ogres hold the great rock north of the Vigil, with the Brutes on its east side."] = "火腹食人魔占据守望堡北边的巨石，火腹蛮兵在巨石东侧。",
	["The Highborne ghosts haunt the ruins around the shrine; the Haldarr satyrs hold the camp just north of it."] = "上层精灵的鬼魂在神殿周围的废墟中游荡；哈达尔萨特占据神殿北边不远的营地。",
	["The Spitelash naga of the {area:1221} carry {item:13815}. {npc:8507}'s four runes stand among the ruins: use his {item:10445} on each."] = "{area:1221}的恶鞭纳迦携带{item:13815}。{npc:8507}的四个符文立在废墟中：对每个使用他的{item:10445}。",
	["The Wildkin Feathers lie on the ground across the {area:47}, south and east of {area:348}, where the owlbeasts roam; the mobs here are well below you now."] = "枭兽羽毛散落在{area:47}的地面上，位于{area:348}的南边和东边，枭兽在那里游荡；这里的怪物等级已经远低于你。",
	["The nearest Mosshoof Coursers graze the hills north-east of the {area:1224}, toward the {area:1219}; a larger herd roams the open ground to the south."] = "最近的苔蹄快步者在{area:1224}东北方的山丘上吃草，朝{area:1219}方向；更大的一群在南边的开阔地游荡。",
	["The relics are in the {zone:1428}: keep it"] = "圣物在{zone:1428}：留着",
	["The relics are the carved stones scattered through the {area:250} around {area:251}: click them until the information is recovered.\nRead the tablet in the {object:147516} camp among the ruins, south-west of {area:251}, to copy the transcript.\nUse the {item:12284} on a {npc:7047} on the slopes east of {area:251} just before it dies, then loot the essence it leaves."] = "遗物是散落在{area:251}周围{area:250}里的雕纹石：点击它们，直到信息被记录下来。\n阅读{area:251}西南废墟间{object:147516}营地里的石板，以抄录文字。\n在{area:251}东边山坡上，趁{npc:7047}临死前对它使用{item:12284}，然后拾取它留下的精华。",
	["The shrine lies in the south-west corner of {area:16}, south of {area:3137}."] = "神龛位于{area:16}的西南角，{area:3137}以南。",
	["The wildkin are in {zone:1452}: keep it"] = "枭兽在{zone:1452}：留着",
	["The {area:1221}"] = "{area:1221}",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:7977} (level 48 elite) needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "这些是精英怪：建议组队，找人一起做。{npc:7977}（48级精英）需要2人组队。如果你独自一人就跳过：路线会让你把经验刷回来。",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:9461} is a level 54 elite: most classes solo it at level 56, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "这些是精英怪：建议组队，找人一起做。{npc:9461}是54级精英：大多数职业在56级可以单挑，但你可能需要帮助。如果你独自一人就跳过：路线会让你把经验刷回来。",
	["To {area:2101}"] = "前往{area:2101}",
	["Top up here to level 50.89 before the hand-ins at {zone:1426}: they take you to level 51."] = "在交{zone:1426}的任务之前在这里补到50.89级：这些任务会把你带到51级。",
	["Top up here to level 51.39 before the hand-ins at {area:251}: they take you to level 52."] = "在交{area:251}的任务之前在这里补到51.39级：这些任务会把你带到52级。",
	["Top up here to level 52 before the hand-ins at {area:251}: they take you to level 53."] = "在交{area:251}的任务之前在这里补到52级：这些任务会把你带到53级。",
	["Wildkin feathers"] = "枭兽羽毛",
	["grind on {npc:6196}"] = "刷{npc:6196}",
	["grind on {npc:6375}"] = "刷{npc:6375}",
	["grind on {npc:7034}"] = "刷{npc:7034}",
	["grind on {npc:9690}"] = "刷{npc:9690}",
	["{area:144} flight master"] = "{area:144}飞行管理员",
	["{area:16}: kill these as you meet them"] = "{area:16}：遇到就杀",
	["{area:2418} flight master"] = "{area:2418}飞行管理员",
	["{area:2418} sits in the south-east of the Steppes, at the top of the pass up from Redridge."] = "{area:2418}位于燃烧平原东南部，在从赤脊山上来那条山道的顶端。",
	["{area:250}: kill these as you meet them"] = "{area:250}：遇到就杀",
	["{area:348} flight master"] = "{area:348}飞行管理员",
	["{area:442} flight master"] = "{area:442}飞行管理员",
	["{item:11467} on the way"] = "顺路的{item:11467}",
	["{item:11467}; inside"] = "{item:11467}；室内",
	["{item:7972}: the {npc:7864}, about 10%"] = "{item:7972}：{npc:7864}，约10%",
	["{npc:7034}, below ground"] = "{npc:7034}，地下",
	["{npc:7363} walks around here: look inside the circle on the map"] = "{npc:7363}在这附近走动：看地图上的圆圈内",
	["{npc:7907} stands upstairs, above {npc:7916}: go up inside, the arrow cannot tell the floors apart."] = "{npc:7907}在楼上，就在{npc:7916}上方：从室内上楼，箭头无法区分楼层。",
	["{npc:8420} camps at the {area:1219} in the north; his equipment lies all over the {area:1220} just south-east of him."] = "{npc:8420}在北部的{area:1219}扎营；他的设备散落在他东南边不远的{area:1220}各处。",
	["{npc:9176} and the Blackrock orcs hold the camps and the stronghold at the foot of {area:254}, west of {area:251}. Pull them one at a time; every orc and worg may drop a medallion, so kill them until you have fifty.\nCareful: {npc:9176} has a guard linked to him that joins the fight, and a second soldier patrols close by; clear the patrol before pulling."] = "{npc:9176}和黑石兽人占据着{area:251}以西、{area:254}脚下的营地与要塞。一只一只地拉；每个兽人和座狼都可能掉落勋章，杀到你有五十个为止。\n小心：{npc:9176}身边有一名卫兵与他联动，会加入战斗，另有第二名士兵在附近巡逻；拉怪前先清掉巡逻兵。",
	["{npc:9177}: the Blackrock orcs drop the medallions, keep it open all through the Steppes"] = "{npc:9177}：黑石兽人掉落奖章，在整个燃烧平原期间保持此任务",
	["{object:153556} on the way"] = "顺路的{object:153556}",
	["{zone:1455} flight master"] = "{zone:1455}飞行管理员",
	["{zone:1455} has no druid trainer: take the portal up to {zone:1457} and train in the {area:1658}, then come back down to {area:702}."] = "{zone:1455}没有德鲁伊训练师：乘传送门上到{zone:1457}，在{area:1658}训练，然后回到{area:702}。",
}

G["forever/alliance/50-60/02-felwood"] = {
	["Below ground"] = "在地下",
	["Deadwood Avenger"] = "枯木复仇者",
	["Deadwood Den Watcher"] = "枯木巢穴守卫",
	["Deadwood Gardener"] = "枯木园丁",
	["Deadwood Pathfinder"] = "枯木寻路者",
	["Deadwood Shaman"] = "枯木萨满",
	["Deadwood Warrior"] = "枯木战士",
	["Ends in the {zone:1413}: keep it"] = "在{zone:1413}结束：留着",
	["Entropic Beast"] = "熵能野兽",
	["Entropic Horror"] = "熵能恐魔",
	["First crater"] = "第一个弹坑",
	["Five feathers buy a little Timbermaw reputation"] = "五根羽毛换少量木喉熊怪声望",
	["Fly to {area:415}"] = "飞往{area:415}",
	["Follow the road north to the cave mouth of {area:1769}; {npc:15395} guards it."] = "沿道路向北到{area:1769}的洞口；{npc:15395}守在那里。",
	["Follow the road north to the cratered vale and walk to each crater, killing the Entropic Beasts and Horrors between them."] = "沿道路向北前往布满弹坑的山谷，走到每个弹坑处，杀死途中的热能野兽和Horror。",
	["If you skipped The Horn of the Beast or The {item:9328}, grind here to level 52.58 to stay on the route's plan."] = "如果跳过了“野兽的号角”或“{item:9328}”，就在这里刷到52.58级，以保持在路线计划内。",
	["Jadefire Betrayer"] = "碧火背叛者",
	["Jadefire Felsworn"] = "碧火邪誓者",
	["Jadefire Hellcaller"] = "碧火唤狱者",
	["Jadefire Rogue"] = "碧火潜行者",
	["Jadefire Shadowstalker"] = "碧火暗影潜伏者",
	["Jadefire Trickster"] = "碧火欺诈者",
	["Jaedenar Adept"] = "加德纳尔侍僧",
	["Jaedenar Cultist"] = "加德纳尔邪教徒",
	["Jaedenar Guardian"] = "加德纳尔守卫",
	["Jaedenar Hound"] = "加德纳尔猎犬",
	["Keep her alive until she is out of the cave"] = "保护她直到离开洞穴",
	["Level 52.58"] = "52.58级",
	["Level 52.69"] = "52.69级",
	["Level 52.9"] = "52.9级",
	["Oozes"] = "软泥怪",
	["Rakaiah"] = "拉凯亚",
	["Ride north out of {area:415} into {area:361}. {npc:11554} the furbolg stands by the road just south of the {area:2479}."] = "从{area:415}向北骑出，进入{area:361}。熊怪{npc:11554}站在路边，就在{area:2479}以南。",
	["Ride south-east from {area:1763} to the {area:2479}, the druids' camp by the road in southern {area:361}."] = "从{area:1763}向东南骑到{area:2479}，那是{area:361}南部路旁的德鲁伊营地。",
	["Salfa stands at the {zone:1452} end of the tunnel: keep it"] = "萨尔法站在隧道的{zone:1452}一端：留着",
	["Second crater"] = "第二个弹坑",
	["Step into the cave: {npc:11558} and {npc:11557} stand just inside."] = "走进洞穴：{npc:11558}和{npc:11557}就站在入口内。",
	["The Cursed and Tainted Oozes slide about the streams and fel pools around {area:1763} and {area:1765}: kill them and use Laris's Empty Ooze Jars on their remains."] = "被诅咒的软泥怪和被污染的软泥怪在{area:1763}和{area:1765}周围的溪流和邪能池中滑行：杀死它们，对残骸使用拉里斯给的空采样瓶。",
	["The Deadwood furbolgs live in the village just south-west of {npc:11554}; keep the Deadwood Headdress Feathers they drop."] = "死木熊怪住在{npc:11554}西南方不远的村子里；保留它们掉落的死木头饰羽毛。",
	["The Deadwood furbolgs of {area:1762} fill the hills west of the cave. The Avengers can drop a {quest:8470}.\nCareful: Den Watchers are level 53-54; they call nearby allies within 25 yd once below 50% health and run off for help below 15%."] = "{area:1762}的枯木熊怪遍布洞穴以西的丘陵。复仇者可能掉落{quest:8470}。\n小心：巢穴守卫是53-54级；血量低于50%后，它们会呼叫25码内的盟友，低于15%时会跑去求援。",
	["The Jadefire satyrs hold the glen west of the road, with {npc:9454} at its back.\nCareful: Jadefire Shadowstalkers (level 51-52) use Sneak and {spell:7992} and are stealthed, so they often join fights uninvited."] = "碧火萨特占据道路以西的山谷，{npc:9454}在最深处。\n小心：碧火暗影潜伏者（51-52级）会潜行并使用{spell:7992}，常常不请自来地加入战斗。",
	["The Warpwood treants of {area:1767}, east of {area:2618}, carry the {item:11503}."] = "{area:2618}东边{area:1767}的扭木树人携带{item:11503}。",
	["The vial is filled in {zone:1457}: keep it; inside"] = "药瓶在{zone:1457}装满：留着；在里面",
	["The {area:2479}"] = "{area:2479}",
	["Third crater"] = "第三个弹坑",
	["Top up here to level 52.69 before the hand-ins at {area:1763}: they take you to level 53."] = "先在这里补到52.69级，再去{area:1763}交任务：这些任务会把你带到53级。",
	["Top up here to level 52.9 before the hand-ins at {area:2479}: they take you to level 53."] = "先在这里补到52.9级，再去{area:2479}交任务：这些任务会把你带到53级。",
	["Trey Lightforge's remains lie beside her."] = "特雷·光铸的遗骸就在她身旁。",
	["Use the {item:12922} at the corrupted moonwell in the middle of {area:1763}. If you freed {npc:11018}, go back into {area:1770} for the succubus {npc:9518}."] = "在{area:1763}中央被腐蚀的月亮井旁使用{item:12922}。如果你已解救{npc:11018}，就回到{area:1770}找魅魔{npc:9518}。",
	["Xavaric"] = "沙瓦里克",
	["Xavathras"] = "沙瓦瑟拉斯",
	["grind on {npc:7109}"] = "刷{npc:7109}",
	["grind on {npc:7125}"] = "刷{npc:7125}",
	["grind on {npc:7153}"] = "刷{npc:7153}",
	["grind on {npc:7155}"] = "刷{npc:7155}",
	["{area:1763} again"] = "再次前往{area:1763}",
	["{area:1763} is the ruined temple north of the glen. Some of its cultists drop a {item:13140}, about one kill in thirty: it opens {npc:11018}'s cell in {area:1770}, the cave at the back. If it drops, clear the way out before you free her; if not, skip her quests."] = "{area:1763}是山谷北边的废弃神殿。其中一些信徒会掉落{item:13140}，约三十次击杀一次：它能打开后方洞穴{area:1770}中{npc:11018}的牢房。掉落了就先清出退路再放她出来；没掉就跳过她的任务。",
	["{area:2618} is the satyr valley in the north-west, with {npc:10648} at its far end. He drops the {quest:939}; every Jadefire satyr can drop {item:11674}."] = "{area:2618}是西北部的萨特山谷，{npc:10648}在最深处。他掉落{quest:939}；每个碧火萨特都可能掉落{item:11674}。",
	["{area:2618}: kill these as you meet them"] = "{area:2618}：遇到就杀",
	["{area:702} flight master"] = "{area:702}飞行管理员",
	["{item:13140}, a rare drop"] = "{item:13140}，稀有掉落",
	["{npc:11016}, in {area:1770}; below ground"] = "{npc:11016}，在{area:1770}；地下",
	["{npc:11020}, below ground"] = "{npc:11020}，地下",
	["{npc:11557}: thirty {quest:6031}, handed in when you pass through again at 57; below ground"] = "{npc:11557}：30个{quest:6031}，57级再次经过时交付；地下",
	["{npc:11558}: the Timbermaw speak to you only from Neutral; walks around here: look inside the circle on the map"] = "{npc:11558}：木喉只有在你达到中立后才会与你交谈；他在这一带走动：看地图圆圈内",
	["{npc:15395} waits at the north end of {area:361}"] = "{npc:15395}在{area:361}北端等候",
	["{npc:9116}, inside"] = "{npc:9116}，在里面",
	["{npc:9518}, below ground"] = "{npc:9518}，地下",
	["{npc:9528}, in the ruins just east of {npc:11554}"] = "{npc:9528}，在{npc:11554}东边不远的废墟中",
	["{quest:8470}, a rare drop"] = "{quest:8470}，稀有掉落",
}

G["forever/alliance/50-60/03-winterspring"] = {
	["Back to the hills: only the Ice Thistle Matriarchs and Patriarchs carry the horns. Keep killing yetis until level 54: Harlo's wildkin quests are red before that."] = "回到丘陵：只有冰蓟母熊和公熊带着角。继续杀雪人直到54级：在此之前，哈洛的枭兽任务都是红色的。",
	["Boat to {area:150}"] = "乘船前往{area:150}",
	["Careful: {npc:10411} goes invisible when out of combat and calls Rockwing Gargoyles once a fight starts. Only 3 exist and they respawn every 15 min."] = "小心：{npc:10411}脱离战斗后会隐身，战斗一开始就会召唤石翼石像鬼。它们只有3只，每15分钟刷新。",
	["Darrowshire Spirit"] = "达隆郡幽灵",
	["Fly to Theramore"] = "飞往塞拉摩岛",
	["Fly to {area:271}"] = "飞往{area:271}",
	["Follow the road east across the zone to the chapel."] = "沿道路向东穿过该地区前往圣光之愿礼拜堂。",
	["Follow the road west to {npc:9298}'s camp beside the hot springs."] = "沿道路向西前往温泉旁{npc:9298}的营地。",
	["Follow the southern road east into the {area:139}; the ruins of {area:2262} lie south of it. {npc:10926}'s ghost plays by the ruined house at the south end."] = "沿南边的路向东进入{area:139}；{area:2262}的废墟在它南边。{npc:10926}的幽灵在南端破屋旁玩耍。",
	["For Kernda in {area:1769}: keep it"] = "交给{area:1769}的克尔达：保留它",
	["Free Darrowshire Spirits: talk to them"] = "解放达隆郡居民的灵魂：与它们交谈",
	["From {area:271}, ride north up the road through Alterac to {area:3197}."] = "从{area:271}沿路向北骑，穿过奥特兰克前往{area:3197}。",
	["Ice Thistle yetis live in the hills south of {area:2244}, Chillwind Chimaeras in the valley toward {area:2255}."] = "冰蓟雪人住在{area:2244}以南的山丘，冰风奇美拉在通往{area:2255}的山谷中。",
	["Inside"] = "在里面",
	["Into {area:139}"] = "进入{area:139}",
	["Into {area:618}"] = "进入{area:618}",
	["Keep it: Gregan in {zone:1444} brews the elixir later"] = "保留它：之后{zone:1444}的格雷甘·山酒会调制药剂",
	["Legacki"] = "莱加基",
	["Level 55.05"] = "55.05级",
	["On the way"] = "顺路",
	["On {npc:10978}, by the inn"] = "在旅店旁的{npc:10978}处",
	["Optional: {area:1417}"] = "可选：{area:1417}",
	["Pick up the supplies around the wagon and take {npc:10301}'s amulet back from the owlbeasts nearby."] = "拾取马车周围的补给，并从附近的枭兽身上夺回{npc:10301}的护符。",
	["Pristine Yeti Horns"] = "完美的雪人角",
	["Ride north-west back to the village."] = "向西北骑回村子。",
	["Ride south-east down the valley to {npc:10301}'s damaged crate in the snow at {area:2245}, with his wrecked wagon just east of it."] = "向东南沿山谷而下，到{area:2245}雪地里{npc:10301}的破损箱子处，他被毁的马车就在东边。",
	["Short of level 54 after the yetis? Running the {area:1417} (50-54) instead of grinding gets you there faster in a group. Come back to {area:2255} afterwards."] = "打完雪人还不到54级？组队刷{area:1417}（50-54）比练级更快。之后回到{area:2255}。",
	["The Deadwood cauldron in {zone:1448}: keep it"] = "{zone:1448}的死木熊怪大锅：保留它",
	["The Scourge around {area:2264}, west of the chapel, drop both kinds of Scourgestone; Darrowshire Spirits rise from them: talk to each one to free it."] = "{area:2264}周围、礼拜堂西边的天灾军团会掉落两种天灾石；达隆郡居民的灵魂会从它们身上升起：和每一个交谈以解放它。",
	["The Winterfall furbolg village lies east of {area:2255}: Shaman (56-57), Den Watchers (55-56) and Ursa (57-58), all above you. Kill the Shaman first, they heal, and pull from the edge. {npc:10738} in the cave at the back is elite: stay out."] = "冬泉熊怪的村子位于{area:2255}以东：冬泉萨满祭司（56-57）、冬泉巢穴守卫（55-56）和冬泉巨熊怪（57-58），都比你等级高。先杀萨满祭司，它们会治疗，从边缘开始引怪。后方洞穴里的{npc:10738}是精英：别进去。",
	["The next guide starts here and flies to {area:3197}."] = "下一份指南从这里开始，飞往{area:3197}。",
	["The ruins lie around the frozen lake south of {area:2253}. Pick up the four relic fragments lying in the ruins and the Moontouched Feathers on the ground where the wildkin roam."] = "废墟位于{area:2253}以南的冰湖周围。拾取废墟中的四块遗物碎片，以及枭兽游荡处地上的月光羽毛。",
	["The three pieces of the doll lie in the ruined houses of {area:2262}; picking one up can call out ghosts. Combine them into the doll."] = "娃娃的三个部件在{area:2262}的废屋里；拾取时可能引出鬼魂。把它们合成娃娃。",
	["The western Winterfall camp sits in the hills between {npc:11556} and {npc:9298}. Any furbolg here can drop an {item:12771} (about one in ten) and, rarely, a {quest:8471}: right-click whichever drops. Keep the {quest:6031} the furbolgs drop for Meilosh."] = "西边的冬泉熊怪营地位于{npc:11556}和{npc:9298}之间的山丘。这里任何熊怪都可能掉落{item:12771}（约十分之一），少数会掉落{quest:8471}：掉落哪个就右键点击哪个。保留熊怪掉落的{quest:6031}，交给梅罗什。",
	["Top up here to level 55.05 before the hand-ins at {area:2255}: they take you to level 56."] = "在{area:2255}交任务前，先在这里刷到55.05级：交完后能到56级。",
	["Winterfall Den Watcher"] = "冬泉巢穴守望者",
	["Winterfall Pathfinder"] = "冬泉探路者",
	["Winterfall Shaman"] = "冬泉萨满祭司",
	["Winterfall Totemic"] = "冬泉图腾师",
	["Winterfall Ursa"] = "冬泉巨熊",
	["Zaeldarr is elite: grouping up is advised. He waits at the bottom of the {area:2261}, the crypt in the south-west of the zone."] = "扎尔达是精英：建议组队。他在{area:2261}深处等候，那是该区域西南的墓穴。",
	["grind on {npc:11552}"] = "刷{npc:11552}",
	["{area:150} flight master"] = "{area:150}飞行管理员",
	["{area:2246}: kill these as you meet them"] = "{area:2246}：遇到就杀",
	["{area:2247}: kill these as you meet them"] = "{area:2247}：遇到就杀",
	["{area:2255} flight master"] = "{area:2255}飞行管理员",
	["{area:2269}: kill these as you meet them"] = "{area:2269}：遇到就杀",
	["{item:12383}, 110 yd north"] = "{item:12383}，往北110码",
	["{item:12771}, a rare drop"] = "{item:12771}，稀有掉落",
	["{item:12886}; inside"] = "{item:12886}；室内",
	["{item:12888}; inside"] = "{item:12888}；室内",
	["{item:15785}; below ground"] = "{item:15785}；地下",
	["{npc:10301}'s camp"] = "{npc:10301}的营地",
	["{npc:10301}'s supplies"] = "{npc:10301}的补给",
	["{npc:10431}: keep both for the Plaguelands; inside"] = "{npc:10431}：两个都留着给瘟疫之地；室内",
	["{npc:10926}'s doll"] = "{npc:10926}的娃娃",
	["{npc:10978}: {npc:7583} and {npc:10977} come later"] = "{npc:10978}：{npc:7583}和{npc:10977}之后再去",
	["{npc:11038}, by the graves south of the chapel"] = "{npc:11038}，在教堂南边的坟墓旁",
	["{npc:11038}: Zaeldarr is a level 54 elite"] = "{npc:11038}：扎尔达是54级精英",
	["{npc:11118}: the last guide binds here, so this usually ticks at once"] = "{npc:11118}：上一份指南在这里绑定炉石，所以这一步通常会立即完成",
	["{npc:11556} guards the mouth of {area:1769}, north-west of {npc:9298}."] = "{npc:11556}守在{npc:9298}西北的{area:1769}入口处。",
	["{npc:11616}: the termites come later, in {area:2627}"] = "{npc:11616}：白蚁任务后面才有，在{area:2627}",
	["{npc:11629}: keep it for {area:2262}; inside"] = "{npc:11629}：留着给{area:2262}；室内",
	["{npc:11754} walks around {area:2255}: look inside the circle on the map"] = "{npc:11754}在{area:2255}附近走动：看地图上的圆圈内",
	["{npc:7440} along the way to {npc:9298}"] = "顺路去{npc:9298}的路上{npc:7440}",
	["{npc:7441} along the way to {npc:9298}"] = "顺路去{npc:9298}的路上{npc:7441}",
	["{npc:7442} along the way to {npc:9298}"] = "顺路去{npc:9298}的路上{npc:7442}",
	["{quest:5152}, in the {area:28}: keep it"] = "{quest:5152}，在{area:28}：留着它",
	["{quest:6031}, for Meilosh later"] = "{quest:6031}，之后交给梅罗什",
	["{quest:8471}, a rare drop"] = "{quest:8471}，稀有掉落",
}

G["forever/alliance/50-60/04-western-plaguelands"] = {
	["Andorhal"] = "安多哈尔",
	["Andorhal Tower Four"] = "安多哈尔四号塔",
	["Andorhal Tower One"] = "安多哈尔一号塔",
	["Andorhal Tower Three"] = "安多哈尔三号塔",
	["Andorhal Tower Two"] = "安多哈尔二号塔",
	["Below ground"] = "地下",
	["Boat to {area:1108}"] = "坐船到{area:1108}",
	["Cavalier Durgen"] = "骑士杜根",
	["Climb the hill west of {area:190} to look down on the town.\nCareful: Sentinels posted at the gate can detect stealthed players. Additional sentinels are found within the town, and an elite walks a patrol route nearby."] = "登上{area:190}西边的山丘，俯瞰小镇。\n注意：驻守大门的哨兵能发现潜行的玩家。镇内还有更多哨兵，附近有一名精英沿巡逻路线行走。",
	["Collie is up the hill behind it."] = "科利在它后面的山上。",
	["Cross the river east to the {area:2261}, the crypt in the south-west of the zone. The {object:177667} lies inside: its key is on {npc:12248} in the far north-east, done in the next guide."] = "向东过河到{area:2261}，即区域西南的墓穴。{object:177667}就在里面：钥匙在遥远东北方的{npc:12248}身上，下一份攻略会处理。",
	["Cross the river west to {npc:1855}'s hut."] = "向西过河到{npc:1855}的小屋。",
	["Cross the south of the crater to {npc:9619} by the ramp."] = "穿过环形山南部，到坡道旁找{npc:9619}。",
	["Diseased Grizzlies"] = "生病的灰熊",
	["Diseased Grizzly"] = "患病灰熊",
	["Diseased Wolf"] = "患病狼",
	["Dredge Crusher"] = "挖掘粉碎者",
	["Dredge Crushers dig further west; Stonelash Pincers, Flayers and Rock Stalkers hunt the same sands."] = "掘泥摧毁者在更西边挖掘；石鞭巨钳蝎、石鞭掠夺者和石行蜘蛛在同一片沙地狩猎。",
	["Dredge Striker"] = "挖掘打击者",
	["Dredge Strikers dig in the dunes north-west of the hold; Stonelash Scorpids and Sand Skitterers roam all around."] = "掘泥打击者在要塞西北方的沙丘中挖掘；石鞭蝎和掠沙蜘蛛在四周游荡。",
	["Ends with {npc:9298} in {area:618}: keep it"] = "以{area:618}的{npc:9298}收尾：保留",
	["Escort {npc:9999}"] = "护送{npc:9999}",
	["Fly from {area:976} to {area:541}. {npc:8737}'s hut stands at the {area:538}, west of the refuge; J.D.\n{npc:9997}'s friend {npc:9999} has gone missing."] = "从{area:976}飞往{area:541}。{npc:8737}的小屋位于庇护所西边的{area:538}；J.D.\n{npc:9997}的朋友{npc:9999}失踪了。",
	["Fly to Theramore"] = "飞往塞拉摩岛",
	["Fly to {area:2255}"] = "飞往{area:2255}",
	["Fly to {area:2268}"] = "飞往{area:2268}",
	["Fly to {area:271}"] = "飞往{area:271}",
	["Fly to {area:541}"] = "飞往{area:541}",
	["Fly to {area:702}"] = "飞往{area:702}",
	["Fly to {area:976}"] = "飞往{area:976}",
	["Follow the road south-west out of the pass to {area:3425}. {npc:15189} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "沿路向西南出山口到{area:3425}。{npc:15189}站在他建筑的楼上：从里面上楼，箭头无法分辨楼层。",
	["For the druids of {zone:1457}: keep it"] = "交给{zone:1457}的德鲁伊：先留着",
	["For {area:1377}: keep it"] = "留着给{area:1377}",
	["For {area:3197}: keep it"] = "留着给{area:3197}",
	["For {zone:1448}: keep it"] = "交给{zone:1448}：先留着",
	["For {zone:1453}: keep it"] = "交给{zone:1453}：先留着",
	["Frenzied Plaguehound"] = "狂乱瘟疫犬",
	["Frenzied Pterrordax"] = "狂乱翼手龙",
	["From Theramore, ride west into the {area:17} and north up the coast to {area:392}."] = "从塞拉摩向西骑进入{area:17}，再沿海岸北上到{area:392}。",
	["From {area:702}, fly to {area:1116}."] = "从{area:702}飞往{area:1116}。",
	["Horgus' skull lies at {area:2624} and Marduk's sword in the {area:2623}, each where ghosts fight; grown Plaguehounds hunt the plains between."] = "掠夺者霍古斯的头骨在{area:2624}，Marduk的剑在{area:2623}，各在鬼魂交战的地方；成年的瘟疫犬在两地之间的平原上捕猎。",
	["Huntsman Radley"] = "猎人拉德利",
	["If you skipped The {item:9328}, grind here to level 56.89 to stay on the route's plan."] = "如果你跳过了{item:9328}，就在这里刷到56.89级，以保持路线的计划。",
	["Inside"] = "在里面",
	["Lead {npc:9999} north to {area:541}. When he faints, use {item:11804} on him to wake him."] = "把{npc:9999}向北带到{area:541}。他昏倒时，对他使用{item:11804}唤醒他。",
	["Level 56.89"] = "56.89级",
	["Listen to his story"] = "听他讲述他的故事",
	["Mark {npc:10902} with the {item:12815}"] = "用{item:12815}标记{npc:10902}",
	["Mark {npc:10903} with the {item:12815}"] = "用{item:12815}标记{npc:10903}",
	["Mark {npc:10904} with the {item:12815}"] = "用{item:12815}标记{npc:10904}",
	["Mark {npc:10905} with the {item:12815}"] = "用{item:12815}标记{npc:10905}",
	["More watches"] = "更多怀表",
	["Northern Pylon"] = "北部水晶塔",
	["On {npc:7583}"] = "交给{npc:7583}",
	["Plaguebat"] = "瘟疫蝙蝠",
	["Plaguehound"] = "瘟疫犬",
	["Plaguehound Runt"] = "瘟疫犬幼崽",
	["Portal to {zone:1438}"] = "传送门到{zone:1438}",
	["Pterrordax"] = "翼手龙",
	["Radley and Durgen"] = "猎人莱德雷和骑士杜尔根",
	["Ranshalla in {area:618}: keep it"] = "{area:618}的兰莎拉：保留",
	["Ride back south to the camp."] = "向南骑回营地。",
	["Ride down the ramp into the crater: {npc:9619} camps at its foot."] = "沿坡道下到环形山：{npc:9619}在坡道脚下扎营。",
	["Ride east to the border river: {npc:1855} lives in a small hut on the bank."] = "向东骑到边界河：{npc:1855}住在河岸边的小屋里。",
	["Ride east to the {area:2742} tower in {area:2738}; climb it and kill the ambushers that rise for the encrusted object."] = "向东骑到{area:2738}内的{area:2742}塔；爬上塔，击杀为那块布满硬壳的物件而出现的伏击者。",
	["Ride east to {area:537}, climb it and use {npc:10541} at the lava vents near the top."] = "向东骑到{area:537}，爬上去，在顶部附近的熔岩喷口使用{npc:10541}。",
	["Ride east to {npc:13220}."] = "向东骑行到{npc:13220}处。",
	["Ride north along the east side to the gorilla plateau. {npc:9622}, a level 55 gorilla, sits in its deepest cave: clear the gorillas at the cave mouth first."] = "沿东侧向北骑行到猩猩高地。55级的猩猩{npc:9622}坐在最深的洞里：先清理洞口的猩猩。",
	["Ride north to {area:2627}. {npc:12384} lives in the ruined hut, and his receipt book lies in the ruined inn nearby.\n{npc:11140} stands by {npc:12384}' hut in {area:2627}."] = "向北骑到{area:2627}。{npc:12384}住在破旧的小屋里，他的收据簿在附近的废弃旅店里。\n{npc:11140}站在{area:2627}中{npc:12384}的小屋旁。",
	["Ride north up the road to the Northridge lumber mill; {npc:11610} hides at the camp's edge."] = "沿道路向北骑到北山伐木场；{npc:11610}躲在营地边缘。",
	["Ride north-west to the Dalson farm. The diary lies in the barn; a wandering skeleton carries the outhouse key, and {npc:10836} waits in the outhouse with the cabinet key."] = "向西北骑到达尔松农场。日记在谷仓里；一个游荡的骷髅带着厕所钥匙，{npc:10836}在厕所里等候，身上有柜子钥匙。",
	["Ride north-west to {area:2276}, at the edge of the {area:2277}."] = "向西北骑到{area:2277}边缘的{area:2276}。",
	["Ride out of the crater's north-western pass into {area:1377} and on to {area:3425}. {npc:15189} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "从环形山西北山口骑出，进入{area:1377}，再前往{area:3425}。{npc:15189}站在他建筑的楼上：从里面上楼，箭头无法分辨楼层。",
	["Ride south to {area:201}, where {npc:11078} guards the cauldron."] = "向南骑到{area:201}，{npc:11078}守卫着那里的大锅。",
	["Ride south-west to the camp."] = "向西南骑回营地。",
	["Ride south-west to {npc:7771}'s camp at the {area:1938}."] = "向西南骑到{area:1938}旁{npc:7771}的营地。",
	["Ride west along the road to the hot springs."] = "沿道路向西骑到温泉。",
	["Ride west past {area:541} and south down the western side to {area:543}: {npc:10302} the goblin sits by the water."] = "向西骑过{area:541}，沿西侧南下到{area:543}：地精{npc:10302}坐在水边。",
	["Ride west to {area:2627}. Plaguehound Runts, Plaguebats and Carrion Grubs roam its woods; fill the {item:15042} at the big termite mounds and kill the Frenzied Plaguehounds further north."] = "向西骑到{area:2627}。瘟疫幼犬、瘟疫蝙蝠和腐肉虫在树林里游荡；在大白蚁丘装满{item:15042}，然后击杀更北边的狂怒的瘟疫犬。",
	["Scarlet Hunter"] = "血色猎人",
	["Scarlet Knight"] = "血色骑士",
	["Scarlet Mage"] = "血色法师",
	["Scarlet Medic"] = "血色医师",
	["Skeletal Flayer"] = "骷髅撕掠者",
	["Skeletal Flayers and Slavering Ghouls roam the fields north of the camp; all the Scourge here drop Scourgestones.\nCareful: These undead notice you from far away, and other undead nearby join the fight when one is pulled.\nCareful: The {npc:10411} (3 spawns, 15 min respawn) turns invisible when out of combat and calls in Rockwing Gargoyles once a fight starts."] = "骷髅撕掠者和流涎食尸鬼在营地北面的田野游荡；这里的天灾怪都会掉落天灾石。\n注意：这些亡灵从很远就能发现你，拉怪时附近的亡灵会加入战斗。\n注意：{npc:10411}（3个刷新点，15分钟刷新）脱离战斗后会隐形，战斗一开始就会呼叫石翼石像鬼。",
	["Slavering Ghoul"] = "流涎食尸鬼",
	["Sprinkle"] = "斯普林克",
	["Take the boat to the mainland and ride north-east to {npc:14637}'s camp by the {area:1119}."] = "乘船到大陆，向东北骑到{area:1119}旁{npc:14637}的营地。",
	["Tar Beasts wallow in the {area:538}; the fire elementals of {area:537} in the middle carry the ash; the Gorishi wasps of the {area:540} in the south carry the gland. Every creature in the crater can drop {item:11018}.\nCareful: Gorishi Workers that drop below 45% health have a 50% chance to call for help from allies within 25 yd."] = "焦油兽在{area:538}里打滚；中部{area:537}的火元素携带着灰烬；南部{area:540}的格里什黄蜂携带着腺体。环形山里的每种生物都可能掉落{item:11018}。\n注意：生命值降到45%以下的格里什工蜂有50%几率呼叫25码内的同伴支援。",
	["Temporal Parasite"] = "时间寄生虫",
	["Ten {item:11040} from the {item:11020}"] = "从{item:11020}获得十个{item:11040}",
	["The Andorhal watchtowers"] = "安多哈尔瞭望塔",
	["The Scarlet Crusade"] = "血色十字军",
	["The Scarlet Medics, Hunters, Knights and Mages patrol the lumber camp and the road toward {area:190}."] = "血色医护员、血色猎人、血色骑士和血色法师在伐木场和通往{area:190}的道路上巡逻。",
	["The cauldron sits at the {area:202}, by {npc:10739}' farm."] = "大锅在{area:202}，{npc:10739}的农场旁。",
	["The cauldron sits at {area:200}, north-east of Felstone; its Cauldron Lord stands beside it."] = "大锅在费尔斯通农场东北方的{area:200}；护锅者拉扎奇站在旁边。",
	["The crater"] = "环形山",
	["The gorillas live on {area:1943}, east of {area:541}. Keep their pelts for {npc:9619}. Stay out of the deepest cave: {npc:9622} is level 55.\nCareful: Un'Goro Gorillas (level 50-51) call for help from allies within 20 yd once they drop to 25% health. There is a cave full of apes in the area, and fighting there brings many adds."] = "大猩猩生活在{area:541}东边的{area:1943}。把它们的毛皮留给{npc:9619}。别进最深的洞穴：{npc:9622}是55级。\n注意：安戈洛大猩猩（50-51级）生命值降到25%后会呼叫20码内的同伴支援。该区域有一个满是猩猩的洞穴，在那里战斗会引来大量增援。",
	["The pelts come after loop 2, on the gorilla plateau"] = "毛皮在第二圈之后，在猩猩高地上",
	["The portal in {area:702} leads up to {zone:1457}."] = "{area:702}的传送门通向{zone:1457}。",
	["The shrunken giants roam the {area:1119}; the sea elementals wade along the coast to the west."] = "缩小的巨人在{area:1119}游荡；海元素在西边的海岸涉水。",
	["The tortured druids and sentinels haunt the ruined village south-west of {npc:13220}."] = "被折磨的德鲁伊和被折磨的哨兵在{npc:13220}西南方的废弃村庄中游荡。",
	["The wooden sign beside {npc:9997}"] = "{npc:9997}旁边的木牌",
	["The {area:2742} tower"] = "{area:2742}塔",
	["Tirion Fordring"] = "提里奥·弗丁",
	["Tortured Druid"] = "受折磨的德鲁伊",
	["Tortured Sentinel"] = "受折磨的哨兵",
	["Umber in {area:493}: keep it"] = "{area:493}的安伯：保留",
	["Upstairs"] = "楼上",
	["Use the {item:12627} by the grain silos to draw out Temporal Parasites. {quest:5154} is one of the musty tomes in the town hall. Every skeleton in town drops {quest:5537}."] = "在粮仓旁使用{item:12627}引出时光寄生虫。{quest:5154}是市政厅里的发霉的书籍之一。镇上的每个骷髅都会掉落{quest:5537}。",
	["Use the {item:12815} at the foot of each of the four watchtowers around the edge of Andorhal, north of the camp."] = "在营地北边、安多哈尔外围的四座瞭望塔脚下各使用一次{item:12815}。",
	["Walk into {area:1769} and take the {area:493} branch of the tunnel to {area:2361}."] = "走进{area:1769}，沿隧道的{area:493}分支前往{area:2361}。",
	["grind on {npc:11740}"] = "刷{npc:11740}",
