	["{item:11478}; below ground"] = "{item:11478}；地下",
	["{item:11479}; below ground"] = "{item:11479}；地下",
	["{item:11480}; below ground"] = "{item:11480}；地下",
	["{item:11834} on the way"] = "路上有{item:11834}",
	["{item:12894}, at the monument"] = "{item:12894}，在纪念碑旁",
	["{item:12954} lies in the town hall of {area:190}, west of {npc:1855}: the Scarlet guards stand close together."] = "{item:12954}在{npc:1855}西边{area:190}的市政厅里：血色卫兵站得很近。",
	["{item:12954}; inside"] = "{item:12954}；室内",
	["{item:12955} lies east of the barn at {area:201}."] = "{item:12955}在{area:201}谷仓东边。",
	["{item:12956}; underwater"] = "{item:12956}；水下",
	["{item:13853} on the way"] = "路上有{item:13853}",
	["{npc:10667} waits in the ruined inn on the west side of Andorhal."] = "{npc:10667}在安多哈尔西侧的废弃旅店里等候。",
	["{npc:10739} stands by the farm at the {area:202}, north-east of the fields."] = "{npc:10739}站在田野东北方{area:202}的农场旁。",
	["{npc:10778}'s ghost wanders by the farmhouse of {area:199}, west of {area:200}; her parcel lies inside."] = "{npc:10778}的鬼魂在{area:200}西边、{area:199}的农舍旁游荡；她的包裹在屋里。",
	["{npc:10878} and {npc:7740} stand by the Temple of the Moon; fill {item:11682} at the moonwell inside."] = "{npc:10878}和{npc:7740}站在月神殿旁；在殿内的月亮井装满{item:11682}。",
	["{npc:10927}'s farmhouse stands on the hill east of the camp; {npc:10936}'s monument is just north of it."] = "{npc:10927}的农舍在营地东边的山丘上；{npc:10936}的纪念碑就在它北边。",
	["{npc:11075} guards the cauldron in {area:199}, west of Andorhal."] = "{npc:11075}守卫着安多哈尔西边{area:199}的大锅。",
	["{npc:11613} walks the Northridge camp east of {npc:11610}; {npc:11611} guards the tower at {area:190}'s southern approach.\nCareful: Guards stand at the tower's base and one more circles it on patrol. Clear them before you engage Durgen so they don't join the fight."] = "{npc:11613}在{npc:11610}东边的北岭营地巡逻；{npc:11611}守卫着{area:190}南侧入口的哨塔。\n注意：塔基处有卫兵，另有一名绕着塔巡逻。攻击杜根前先清掉他们，以免他们加入战斗。",
	["{npc:11741} walks around here: look inside the circle on the map"] = "{npc:11741}在这附近巡逻：看地图上圆圈内部",
	["{npc:11886} is elite: grouping up is advised"] = "{npc:11886}是精英：建议组队",
	["{npc:17082}, at the Alliance tents"] = "{npc:17082}，在联盟帐篷处",
	["{npc:1833} along the way to {npc:11610}"] = "前往{npc:11610}途中的{npc:1833}",
	["{npc:1833} on the way"] = "路上有{npc:1833}",
	["{npc:1852} is a level 61 elite"] = "{npc:1852}是61级精英",
	["{npc:1852} is elite: grouping up is advised. He guards his phylactery in the middle of Andorhal.\nSmall lockboxes lie in the rubble all over Andorhal; each holds a watch.\nCareful: Ghouls and skeletons usually stand next to the boxes and attack when you come close. Searing ghouls also hurt anyone nearby and will break stealth."] = "{npc:1852}是精英：建议组队。他在安多哈尔中部守护着自己的命匣。\n安多哈尔各处的瓦砾中散落着小锁箱；每个里面都有一只怀表。\n注意：食尸鬼和骷髅通常站在箱子旁，你一靠近就会攻击。灼热食尸鬼还会伤害附近的人，并会打破潜行。",
	["{npc:5411} in {area:976}: keep it"] = "{area:976}的{npc:5411}：先留着",
	["{npc:5594}, inside"] = "{npc:5594}，室内",
	["{npc:5901}, on the coast north of town"] = "{npc:5901}，在镇子北边的海岸",
	["{npc:7740}: keep it for {area:976}"] = "{npc:7740}：留到{area:976}",
	["{npc:7775}'s camp lies north of the {area:1119}. He sells the {item:11243} once he has his bait."] = "{npc:7775}的营地在{area:1119}北边。拿到诱饵后，他会出售{item:11243}。",
	["{npc:7900}: keep it for {area:440}"] = "{npc:7900}：留着给{area:440}",
	["{npc:8496}: keep it for Un'Goro; inside"] = "{npc:8496}：留着给安戈洛；室内",
	["{npc:8598}, 170 yd north-east"] = "{npc:8598}，东北方170码",
	["{npc:9047}, in the {area:1658}"] = "{npc:9047}，在{area:1658}",
	["{npc:9117}, below ground"] = "{npc:9117}，地下",
	["{npc:9299} in {area:976}: keep it"] = "{area:976}的{npc:9299}：保留",
	["{npc:9299} waits at the graveyard just east of town; the gravestone stands nearby."] = "{npc:9299}在镇子东边不远的墓地等候；墓碑就在附近。",
	["{npc:9684}'s lair lies in the jungle north of {npc:9619}, below the eastern cliffs: use {item:11568} there. {npc:9684} is level 56: start at full health."] = "{npc:9684}的巢穴在{npc:9619}北边的丛林中，东部悬崖下方：在那里使用{item:11568}。{npc:9684}是56级：满血开打。",
	["{npc:9999} sits on the south-east slope of {area:537}, in the middle of the crater."] = "{npc:9999}坐在{area:537}东南坡上，位于环形山中部。",
	["{object:175894}, inside"] = "{object:175894}，室内",
	["{object:175924}, in the farmhouse; inside"] = "{object:175924}，在农舍内；室内",
	["{object:177667}, below ground"] = "{object:177667}，地下",
	["{quest:3444} is in {area:392}"] = "{quest:3444}在{area:392}",
	["{quest:5058}, inside"] = "{quest:5058}，室内",
	["{quest:5210}, at {area:2268}: keep it"] = "{quest:5210}，在{area:2268}：先留着",
	["{quest:6762} in {area:493}: keep it"] = "{area:493}的{quest:6762}：保留",
	["{zone:1455}, where the next guide trains, has no druid trainer"] = "下一份指南学习技能的{zone:1455}没有德鲁伊训练师",
}

G["forever/alliance/50-60/05-silithus"] = {
	["Boat to {area:35}"] = "乘船去{area:35}",
	["Chromie in Andorhal: keep it"] = "安多哈尔的克罗米：留着",
	["Fly from {area:541} to {area:392}."] = "从{area:541}飞到{area:392}。",
	["Fly to {area:2268}"] = "飞往{area:2268}",
	["Fly to {zone:1453}"] = "飞往{zone:1453}",
	["For {npc:10778}: keep it"] = "交给{npc:10778}：留着",
	["Its jars are filled on the next Un'Goro visit"] = "采样瓶在下次去安戈洛时装满",
	["Ride north to the {area:2277}'s north-eastern edge.\nCareful: The trolls along the path to {area:2273} are level 57-59. They run away at low health and call for help, so they often bring adds with them."] = "向北骑到{area:2277}的东北边缘。\n注意：通往{area:2273}路径上的巨魔为57-59级。他们会在血量低时逃跑并呼救，所以常会带来援兵。",
	["Ride on north to {area:3197} and fly to {area:2268}."] = "继续向北骑到{area:3197}，再飞往{area:2268}。",
	["Ride south-west to the {area:2261}. The mound of dirt lies inside. {npc:11886} is elite: grouping up is advised.\nCareful: About four non-elite adds come with Mercutio. They walk to the grave instead of appearing on the spot."] = "向西南骑到{area:2261}。土堆就在里面。{npc:11886}是精英：建议组队。\n注意：默库提奥身边约有四名非精英随从。他们要走到墓地，不会原地出现。",
	["Scourge Champion"] = "天灾勇士",
	["Scourge Champions"] = "天灾勇士",
	["Scourge Champions (59) roam the {area:2270}, north of {area:2268}. Pass {npc:11063}'s {item:13156} over each one you kill: the skulls that resonate are the ones he wants. Pull them one at a time."] = "天灾勇士（59级）在{area:2268}以北的{area:2270}游荡。每杀掉一个就用{npc:11063}的{item:13156}对其使用：产生共鸣的头骨才是他要的。一次拉一个。",
	["Take the boat from {area:392} to {area:35} and fly to {zone:1453}."] = "从{area:392}乘船到{area:35}，再飞往{zone:1453}。",
	["Take the {area:2257} to {zone:1455}."] = "乘坐{area:2257}前往{zone:1455}。",
	["Tram to {zone:1455}"] = "乘地铁前往{zone:1455}",
	["{area:35} flight master"] = "{area:35}飞行管理员",
	["{item:13155}, from the Scourge Champions"] = "{item:13155}，来自天灾勇士",
	["{item:14613}, from {npc:11886}"] = "{item:14613}，来自{npc:11886}",
	["{npc:14724}, by the tram"] = "{npc:14724}，在地铁旁",
	["{npc:332}, in SI:7"] = "{npc:332}，在军情七处",
	["{npc:3520}, who walks the canals"] = "{npc:3520}，在运河边走动",
	["{npc:8496}, inside"] = "{npc:8496}，室内",
	["{quest:6184} at {area:3197}: keep it"] = "{area:3197}的{quest:6184}：留着",
	["{zone:1455} flight master"] = "{zone:1455}飞行管理员",
}

G["forever/alliance/50-60/06-silithus"] = {
	["Andorhal"] = "安多哈尔",
	["Angerclaw bears and Felpaw wolves"] = "怒爪熊和魔爪狼",
	["Araj is elite: grouping up is advised."] = "阿拉基是精英：建议组队。",
	["Back into {area:1770}: {npc:9861} and {npc:9860} guard {npc:9517} in its deepest chamber.\nCareful: The three bosses fight as a group. Kill the nearby mobs first so you don't pull extra enemies."] = "回到{area:1770}：{npc:9861}和{npc:9860}在最深处的房间里守着{npc:9517}。\n小心：三个首领一起作战。先清掉附近的怪，以免多拉敌人。",
	["Below ground"] = "地下",
	["Boat to {area:150}"] = "乘船前往{area:150}",
	["Bronzebeard's Encampment"] = "Bronzebeard's Encampment",
	["Climb {area:537} in the middle of the crater and use the {item:14644} by the lava lake at the top, with two Thorium Bars in your bags. Fill {npc:9616}'s Empty Pure Sample Jars on the Primal Oozes in the pools around the ridge."] = "爬上火山口中央的{area:537}，在顶部熔岩湖旁使用{item:14644}，背包里要带两块瑟银锭。用{npc:9616}的空纯净取样瓶，在山脊周围水池里的原始软泥怪身上取样。",
	["Cross the river east of {npc:1855} into {area:2627}. The Terrordale Spirits haunt the woods there."] = "过{npc:1855}东边的河进入恐惧谷。{area:2627}的灵魂在那里的树林中游荡。",
	["Fly to {area:1537}"] = "飞往{area:1537}",
	["Fly to {area:2255}"] = "飞往{area:2255}",
	["Fly to {area:271}"] = "飞往{area:271}",
	["Fly to {area:3137}"] = "飞往{area:3137}",
	["Fly to {area:3137} in {area:16} and ride west along the road to {area:2358}, just over the {zone:1440} border."] = "飞往{area:16}的{area:3137}，沿路向西骑到{area:2358}，刚过{zone:1440}边界。",
	["Fly to {area:3425}"] = "飞往{area:3425}",
	["Fly to {area:442}"] = "飞往{area:442}",
	["Fly to {area:702}"] = "飞往{area:702}",
	["Fly to {area:976}"] = "飞往{area:976}",
	["Fly to {area:976}."] = "飞往{area:976}。",
	["Fly to {area:976}. Buy two Thorium Bars at the Auction House here for {quest:5801}."] = "飞往{area:976}。在这里的拍卖行买两块瑟银锭，用于{quest:5801}。",
	["Fly to {zone:1453}"] = "飞往{zone:1453}",
	["Follow the road north to {area:1767}. The Irontree Stompers carry the heart; finish the claws on the Angerclaw Grizzlies and Felpaw Ravagers of the north."] = "沿道路向北到{area:1767}。铁木践踏者携带心脏；在北部的怒爪灰熊和魔爪掠夺者身上收集完爪子。",
	["Follow {npc:9298}'s directions to the mouth of {area:2256}, past the Frostmaul giants: pass them one at a time."] = "按{npc:9298}的指引前往{area:2256}入口，途经霜槌巨人：一只一只地绕过他们。",
	["Frankal Stonebridge"] = "弗兰克尔·石桥",
	["Grind to 60"] = "刷到60级",
	["Hand him the ten texts you kept"] = "把你留下的十份文本交给他",
	["Havunth's camp sits just west of {area:3425}."] = "哈弗斯的营地就在{area:3425}西边。",
	["Inside"] = "在里面",
	["Irontree Stompers"] = "铁木践踏者",
	["Jabbering Ghoul"] = "呓语食尸鬼",
	["Keep the {item:11169}, the claws and the heart he hands back"] = "保留他还给你的{item:11169}、爪子和心脏",
	["Keep west on the road to {npc:9298}'s camp beside the hot springs."] = "沿道路继续向西，到温泉旁{npc:9298}的营地。",
	["Learn the flight path in {area:2361}."] = "在{area:2361}学会飞行路线。",
	["Moora"] = "穆拉",
	["Pick up the supplies around the wagon and take {npc:10301}'s amulet back from the owlbeasts nearby."] = "拾取马车周围的补给，并从附近的枭兽身上夺回{npc:10301}的护符。",
	["Portal to {zone:1438}"] = "传送门到{zone:1438}",
	["Quixxil"] = "奎克希尔",
	["Ride back south along the road to the Sanctuary."] = "沿道路向南骑回避难所。",
	["Ride back south-east to the hermit."] = "向东南骑回隐士处。",
	["Ride back south-west to {area:3197}."] = "向西南骑回{area:3197}。",
	["Ride back to {area:3137} and fly to {area:2255}."] = "骑回{area:3137}，飞往{area:2255}。",
	["Ride east into the hills. Use the {item:11169} to summon {quest:4005}, then defeat him for the totem."] = "向东骑进山丘。使用{item:11169}召唤{quest:4005}，然后击败他获得图腾。",
	["Ride east to the ruins of {area:2738}. The {object:179565} lies among the ruined buildings, watched by Tortured Sentinels."] = "向东骑行到{area:2738}的废墟。{object:179565}在废弃的建筑之间，被折磨的哨兵看守着。",
	["Ride north along the west side to Mayna's small camp."] = "沿西侧向北骑行到玛恩纳的小营地。",
	["Ride north out of {area:415} into {area:361} to the druids' camp on the road just past the border."] = "从{area:415}向北骑进{area:361}，到刚过边界路上德鲁伊的营地。",
	["Ride north to the Deadwood furbolgs' village by the {area:1769} cave mouth."] = "向北骑行到{area:1769}洞口旁的死木熊怪村庄。",
	["Ride north to {area:541}. Use {npc:10980} beside {npc:10977}."] = "向北骑行到{area:541}。在{npc:10977}旁边使用{npc:10980}。",
	["Ride north up the road to the lumber mill and set the termite barrel down in the middle of it."] = "沿道路向北骑到伐木场，把白蚁桶放在中央。",
	["Ride south-west to the dwarves' camp near the southern mountains and question {npc:15171} and {npc:15170}. {npc:15190}'s satchel lies in the sand just south-east of the camp."] = "向西南骑行到南部山脉附近的矮人营地，询问{npc:15171}和{npc:15170}。{npc:15190}的背包在营地东南方不远的沙子里。",
	["Ride south-west to {npc:7771}'s camp at the {area:1938}."] = "向西南骑行到{area:1938}的{npc:7771}营地。",
	["Running {area:2057} ({area:2298}, south-east {area:28}) or {area:2279} instead of grinding gets you there faster in a group. Skip this step to grind solo."] = "组队时跑{area:2057}（{area:2298}，{area:28}东南）或{area:2279}比刷怪更快到达。单人刷怪就跳过这一步。",
	["Running {area:2577} in {zone:1444} instead of grinding gets you there faster in a group. Skip this step to grind solo."] = "组队打{zone:1444}的{area:2577}代替刷怪会更快。单人刷怪就跳过此步骤。",
	["Rutgar Glyphshaper"] = "鲁特加·雕文者",
	["Salia"] = "萨莉亚",
	["Sixty {item:2592}, if you carry them"] = "六十个{item:2592}（如果你带着的话）",
	["Stormwind City"] = "暴风城",
	["Take the portal up to {zone:1457}."] = "乘传送门上到{zone:1457}。",
	["Take the road west down into the crater and ride to the {area:540}, the silithid cave in the south. The {npc:10041} waits in its deepest chamber."] = "沿道路向西下到环形山，骑行到南部的异种虫洞穴{area:540}。{npc:10041}在最深处的房间等候。",
	["Take the {area:1769} tunnel from its {area:618} mouth, west of {npc:9298}, and follow the {area:493} branch to {area:2361}. {npc:11939} studies by the lake shore."] = "从{npc:9298}西边的{area:618}入口进入{area:1769}隧道，沿{area:493}分支走到{area:2361}。{npc:11939}在湖边读书。",
	["Take the {area:2257} to {zone:1455}. {npc:14724} and {npc:14723} each take sixty Wool, sixty Silk and sixty Mageweave, then sixty {item:14047}: hand in what you carry (or buy at the Auction House), skip the rest.\nCareful: Jadefire Shadowstalkers are level 51-52 and move stealthed. They use {spell:7992} and are found about 550 yd south of {area:1997}.\nCareful: Jadefire Shadowstalkers sneak around and use {spell:7992}."] = "乘{area:2257}前往{zone:1455}。{npc:14724}和{npc:14723}各收六十个毛料、六十个丝绸和六十个魔纹布，然后是六十个{item:14047}：交掉身上带的（或在拍卖行买），其余跳过。\n小心：碧火潜行者是51-52级，会潜行移动。他们使用{spell:7992}，位于{area:1997}以南约550码处。\n小心：碧火潜行者会潜行游走并使用{spell:7992}。",
	["Ten more for {quest:8323}"] = "再交十个用于{quest:8323}",
	["The Twilight's Hammer dig fills the north-west corner: tablet fragments lie on the ground and the Dust Stormers and Desert Rumblers carry them too. Every cultist can drop an {item:20404}: keep twenty, ten for {npc:15306} and ten for {npc:15194} later."] = "暮光之锤的挖掘场占据西北角：石板碎片散落在地上，灰尘风暴和沙漠奔行者也携带碎片。每个信徒都可能掉落{item:20404}：留二十个，十个给{npc:15306}，十个稍后给{npc:15194}。",
	["The flight lands in {area:702}. {npc:7916} stands a short walk north-west of the flight master."] = "航班降落在{area:702}。{npc:7916}站在飞行管理员西北不远处。",
	["The hermit hides among the rocks south-east of {area:2738}."] = "隐士躲在{area:2738}东南方的岩石间。",
	["The western Winterfall furbolgs drop the beads.\nCareful: Turning in spawns three or four level 56-57 Winterfall ambushers that attack you; you can escape them while mounted, in stealth or with {spell:5384}, and they then gather by the lake so you can take the next quest."] = "西边的冬泉熊怪掉落念珠。\n小心：交任务会刷出三到四个56-57级的冬泉伏击者攻击你；可以骑马、潜行或用{spell:5384}逃脱，之后它们会聚集在湖边，方便你接下个任务。",
	["The {area:2479}"] = "{area:2479}",
	["The {area:3098}"] = "{area:3098}",
	["To {area:392}"] = "前往{area:392}",
	["Tram to {zone:1455}"] = "乘地铁前往{zone:1455}",
	["Twilight Tablet Fragments"] = "暮光石板碎片",
	["Twilight's Hammer cultists"] = "暮光之锤信徒",
	["Underwater"] = "水下",
	["Upstairs"] = "楼上",
	["Use the jars on slain oozes"] = "对被杀的软泥怪使用样本瓶",
	["Wait a moment for {npc:9116}"] = "稍等{npc:9116}片刻",
	["grind on {npc:14564} at {area:2627}, {area:139}"] = "在{area:2627}、{area:139}刷{npc:14564}",
	["{area:150} flight master"] = "{area:150}飞行管理员",
	["{area:1770} braziers"] = "{area:1770}的火盆",
	["{area:1770} is the cave at the back of {area:1763}, west of the road. Use the {item:12906} on the four braziers inside. Kill the Angerclaw bears and Felpaw wolves you pass for the {item:11172}.\nCareful: Shadow Council mobs of level 53-55 fill the cave and often come in large linked groups, many with stuns. A group of 2-3 players is recommended."] = "{area:1770}是{area:1763}后方、路西的洞穴。对里面的四个火盆使用{item:12906}。顺路杀掉怒气爪熊和邪爪狼，拿{item:11172}。\n小心：洞里到处是53-55级的暗影议会怪物，常常成群联动，很多会眩晕。建议2-3人组队。",
	["{area:2057} (optional)"] = "{area:2057}（可选）",
	["{area:2057} fits levels 58 to 60; {quest:5505} is handed in at {area:3197} below."] = "{area:2057}适合58-60级；{quest:5505}在下面的{area:3197}交还。",
	["{area:2577} (optional)"] = "{area:2577}（可选）",
	["{area:2577} fits levels 55 to 60; the {npc:7446} grind below gets you to 59 alone."] = "{area:2577}适合55-60级；下面刷{npc:7446}可以单人练到59级。",
	["{area:2742}: kill these as you meet them"] = "{area:2742}：遇到就杀",
	["{area:3137} flight master"] = "{area:3137}飞行管理员",
	["{area:392} flight master"] = "{area:392}飞行管理员",
	["{area:541} flight master"] = "{area:541}飞行管理员",
	["{area:618}: kill these as you meet them"] = "{area:618}：遇到就杀",
	["{area:702} flight master"] = "{area:702}飞行管理员",
	["{item:14047}, from your bags"] = "{item:14047}，从背包里拿",
	["{item:2592}, from your bags"] = "{item:2592}，从背包里拿",
	["{item:4306}, from your bags"] = "{item:4306}，从背包里拿",
	["{item:4338}, from your bags"] = "{item:4338}，从背包里拿",
	["{npc:10300} waits at {area:2250}, south of {area:2255}.\nProtect {npc:10300} while she lights the torches on the way to the {object:177404}."] = "{npc:10300}在{area:2255}以南的{area:2250}等着。\n保护{npc:10300}，直到她在前往{object:177404}的路上点亮火把。",
	["{npc:10300}: her escort comes later on the route"] = "{npc:10300}：她的护送任务在这条路线的后面",
	["{npc:10301}'s camp"] = "{npc:10301}的营地",
	["{npc:10301}'s supplies"] = "{npc:10301}的补给",
	["{npc:10667} waits in the ruined inn on the west side of Andorhal, the ruined city north of the camp. {npc:1852} guards his phylactery in the middle of the town."] = "{npc:10667}在安多哈尔西侧的废弃旅店等候，安多哈尔是营地北边的废墟城市。{npc:1852}在城镇中央守护他的护符匣。",
	["{npc:10667}, upstairs"] = "{npc:10667}，楼上",
	["{npc:10778}'s ghost wanders by the farmhouse of {area:199}, west of Andorhal. The Jabbering Ghouls in the field carry the other half of the charm: combine the two halves."] = "{npc:10778}的鬼魂在安多哈尔西边{area:199}的农舍旁游荡。田里的喋喋不休的食尸鬼携带护符的另一半：把两半合在一起。",
	["{npc:11557}, if you have thirty {quest:6031}; below ground"] = "{npc:11557}，如果你有三十个{quest:6031}；地下",
	["{npc:11558}, just inside the cave: only from Neutral with the Timbermaw; walks around here: look inside the circle on the map"] = "{npc:11558}，就在洞口内：仅在木喉熊怪声望中立时可交易；在这一带走动：看地图上的圆圈内",
	["{npc:11801}'s house stands in {area:2361}, east of {npc:11939}."] = "{npc:11801}的房子在{area:2361}，{npc:11939}东边。",
	["{npc:11803} holds the cultists' camp in the far south-west."] = "{npc:11803}占据最西南端的信徒营地。",
	["{npc:11939} walks around {area:2361}: look inside the circle on the map"] = "{npc:11939}在{area:2361}附近走动：看地图上的圆圈里",
	["{npc:14722} takes sixty Silk, sixty Mageweave and sixty {quest:6031}: hand in what you carry (or buy at the Auction House), skip the rest."] = "{npc:14722}收六十个丝绸、六十个魔纹布和六十个{quest:6031}：交掉身上带的（或在拍卖行买），其余跳过。",
	["{npc:14722}, in the {object:2096}"] = "{npc:14722}，在{object:2096}",
	["{npc:15189} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "{npc:15189}站在他所在建筑的楼上：从室内上楼，箭头无法区分楼层。",
	["{npc:15190} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "{npc:15190}站在他所在建筑的楼上：从室内上楼，箭头无法区分楼层。",
	["{npc:15190}, upstairs beside {npc:15189}"] = "{npc:15190}，在楼上{npc:15189}旁边",
	["{npc:17080} camps outside {area:2743}, the western hive. Pick up a Silithyst at one of the red geysers nearby and carry it to the Alliance extractor at his camp.\nCareful: You lose the Silithyst if you mount, stealth, use {spell:642}, {spell:5384} or Vanish. Blink and {spell:17} do not drop it."] = "{npc:17080}在西部虫巢{area:2743}外扎营。在附近某个红色喷泉拿一块希利苏斯晶体，送到他营地里的联盟萃取器。\n小心：骑马、潜行、使用{spell:642}、{spell:5384}或消失都会丢失晶体。闪现和{spell:17}不会丢。",
	["{npc:1852} is a level 61 elite"] = "{npc:1852}是61级精英",
	["{npc:1855} (optional)"] = "{npc:1855}（可选）",
	["{npc:1855} lives in a small hut on the border river, north-east of the lumber camp. Hand in {quest:5781} if you finished it."] = "{npc:1855}住在伐木场东北方边境河边的小屋里。如果完成了{quest:5781}就交还。",
	["{npc:3516}, atop the {area:1658}"] = "{npc:3516}，在{area:1658}顶上",
	["{npc:4155}, in the bank"] = "{npc:4155}，在银行",
	["{npc:5594}, inside"] = "{npc:5594}，室内",
	["{npc:7740} in {zone:1457}: keep it"] = "{zone:1457}的{npc:7740}：留着",
	["{npc:7740}, in the Temple of the Moon"] = "{npc:7740}，在月神殿",
	["{npc:8737}, at the back of the refuge"] = "{npc:8737}，在避难所深处",
	["{npc:9116}, inside"] = "{npc:9116}，在里面",
	["{npc:9117}, below ground"] = "{npc:9117}，地下",
	["{npc:9517}; below ground"] = "{npc:9517}；地下",
	["{npc:9598} waits in {area:1767}. Escort her out of the woods and keep her alive.\nCareful: Three {quest:5086} ambush you soon after the escort starts."] = "{npc:9598}在{area:1767}等着。护送她走出森林，并保住她的性命。\n小心：护送开始后不久，三个{quest:5086}会伏击你。",
	["{npc:9860}, below ground"] = "{npc:9860}，地下",
	["{npc:9861}, below ground"] = "{npc:9861}，地下",
	["{object:176091}, if you found the Firewater flask in {area:618}"] = "{object:176091}，如果你在{area:618}找到了火水壶",
	["{object:176158}, below ground"] = "{object:176158}，地下",
	["{object:176159}, below ground"] = "{object:176159}，地下",
	["{object:176160}, below ground"] = "{object:176160}，地下",
	["{object:176161}, below ground"] = "{object:176161}，地下",
	["{object:179565}; inside"] = "{object:179565}；室内",
	["{quest:5085}: {npc:9298} in {area:618}, keep it"] = "{quest:5085}：{npc:9298}在{area:618}，留着",
	["{zone:1451}, {area:361}, {area:618} & the Plaguelands"] = "{zone:1451}、{area:361}、{area:618}和瘟疫之地",
	["{zone:1453} flight master"] = "{zone:1453}飞行管理员",
	["{zone:1453} has no shaman trainer"] = "{zone:1453}没有萨满祭司训练师",
	["{zone:1455} flight master"] = "{zone:1455}飞行管理员",
}

G["forever/alliance/dwarf/01-dun-morogh"] = {
	["Back east through {area:131}: the class quests here wait for level 10."] = "向东返回，穿过{area:131}：这里的职业任务要等到10级。",
	["Back through the tunnel to {npc:257597}' cave above the farm."] = "穿过隧道回到农场上方{npc:257597}的洞穴。",
	["Back to {area:77}"] = "返回{area:77}",
	["Back to {npc:257446} in {area:77}. He gives you the {item:6635}: take the rubble-marked path that climbs west from the south of the valley to the Spirit Stone on the ridge, drink the Sapta beside it and speak to the {npc:5891}, then bring its {item:6656} back to Teo."] = "回到{area:77}找{npc:257446}。他会给你{item:6635}：沿着山谷南部向西攀升、标有碎石的小路走到山脊上的灵魂石，在旁边喝下圣水并与{npc:5891}交谈，然后把它的{item:6656}带回给Teo。",
	["Back to {npc:257597}"] = "返回{npc:257597}处",
	["Back to {npc:6122}. Use the {item:6928} at the summoning circle in the {object:2164}'s cellar and defeat the voidwalker it calls. {area:40} is next, west of {area:87}."] = "回到{npc:6122}。在{object:2164}地窖里的召唤法阵上使用{item:6928}，击败它召唤出的虚空行者。接下来去{area:40}，在{area:87}西边。",
	["Bartleby"] = "巴特莱比",
	["Below ground"] = "地下",
	["Burly Rockjaw Trogg"] = "强壮的石颚穴居人",
	["Class trainer"] = "职业训练师",
	["Crag Boars and Young Black Bears roam the fields around {area:131} and the depot."] = "{npc:1125}和{npc:1128}在{area:131}和补给站周围的田野里游荡。",
	["Dark Iron Spy"] = "黑铁间谍",
	["Druid trainer"] = "德鲁伊训练师",
	["Each of Grif Wildheart's quests hands you a {item:15908}: use it on the beast he names, then bring the rod back to him at the {area:131} smithy. Large Crag Boars, Snow Leopards and Ice Claw Bears all roam the fields just south and east of {area:131}."] = "格瑞夫的每个任务都会给你一根{item:15908}：对他指定的野兽使用，然后把驯兽棒带回{area:131}铁匠铺交给他。大峭壁野猪、雪豹和冰爪熊都在{area:131}南边和东边的田野里游荡。",
	["Elder Crag Boar"] = "老峭壁野猪",
	["Farsen camps on the ridge overlooking the {area:134} from the west. Talk to him for his farsight."] = "Farsen在{area:134}西边可俯瞰采掘场的山脊上扎营。与他交谈获得远视。",
	["Feather Charms, from the Frostmane Novices"] = "羽毛咒符，来自霜鬃巨魔新兵",
	["Firewood"] = "木柴",
	["Flintfire's shipments lie on the cave floor, and {npc:278166} is missing somewhere inside.\nCareful: Wendigos stand close together inside the cave, so fights easily pull several at once; drawing them out one at a time with ranged attacks from outside avoids this."] = "弗林特菲尔的货物散落在洞穴地面上，{npc:278166}在洞里某处失踪了。\n小心：洞里的雪人彼此站得很近，战斗时很容易一次引来好几只；在洞外用远程攻击一只一只地引出来就能避免。",
	["Flintfire's shipments lie on the cave floor, and {object:460004} is missing somewhere inside.\nCareful: Wendigos stand close together inside the cave, so fights easily pull several at once; drawing them out one at a time with ranged attacks from outside avoids this."] = "燧火的货物散落在洞穴地面，{object:460004}则在洞穴某处遗失。\n小心：洞穴里的雪怪站得很近，战斗很容易同时引到好几只；在洞外用远程攻击一只一只引出来就能避免。",
	["Follow the road all the way east to the {area:806} at the {area:38} tunnel."] = "沿路一直向东，到{area:38}隧道处的{area:806}。",
	["Follow the road east past the depot to {area:138}."] = "沿道路向东经过补给站到{area:138}。",
	["Follow the road north-east from {area:131} to the depot below the {zone:1455} road."] = "沿道路从{area:131}向东北到{zone:1455}道路下方的钢架补给站。",
	["Follow the road north-east from {area:131} to the depot: the whole east of {area:1} is one sweep from here."] = "从{area:131}沿路向东北前往补给站：{area:1}整个东边都可以从这里一次清完。",
	["Follow the road through the tunnel and north-east to {area:131}. Start outside: {npc:1252} and Eric's campfire are in front of the {area:2102}."] = "沿路穿过隧道，向东北到{area:131}。从外面开始：{npc:1252}和埃里克的营火在{area:2102}前面。",
	["Follow the road up to {zone:1455} and take the {object:32362}: {npc:5149}, {npc:6179} and {npc:6178} are in the {object:32386}, {npc:6179} and {npc:6178} on its upper floor: the stairs up start just north-east of {npc:5149}. {npc:6175}, a beggar, wanders the city. He asks for ten {item:2589}: the troggs and trolls of {area:1} drop it, and the Auction House sells it."] = "沿路走到{zone:1455}，乘坐{object:32362}：{npc:5149}、{npc:6179}和{npc:6178}在{object:32386}里，{npc:6179}和{npc:6178}在它的上层：上楼的楼梯就在{npc:5149}东北。乞丐{npc:6175}在城中游荡。他要十块{item:2589}：{area:1}的穴居人和巨魔会掉落，拍卖行也有卖。",
	["Follow the road up to {zone:1455} and train with your class trainer. The {area:2257} leaves from {object:171524}, in the east of the city. Ride it to {zone:1453}."] = "沿道路上到{zone:1455}，找你的职业训练师学习。{area:2257}从城市东部的{object:171524}出发。乘它前往{zone:1453}。",
	["From the {quest:2997} she gives you"] = "从她给你的{quest:2997}获得",
	["Frostmane Headhunter"] = "霜鬃猎头者",
	["Frostmane Troll Whelp"] = "霜鬃巨魔幼崽",
	["Frostmane Troll Whelps fill the slopes south and east of {npc:786}'s camp."] = "霜鬃巨魔幼崽遍布{npc:786}营地南边和东边的山坡。",
	["Go through the tunnel into {area:38}. Just past it, a path marked by stones climbs the hills on the right of the road north to {npc:257808}'s camp."] = "穿过隧道进入{area:38}。刚过隧道，一条用石头标记的小路沿着通往{npc:257808}营地的北路右侧爬上山。",
	["Gretchen camps just outside the {area:136}, the wendigo cave south-west of {area:131}."] = "这位巡山人在{area:136}外扎营；那是{area:131}西南边的雪怪洞穴。",
	["Head back out of {zone:1455} and east along the road to {area:212}. {npc:6177} lies dead by its shore: use the {item:6866} on him. The Dark Iron Spies sneaking around the lake carry the script."] = "离开{zone:1455}往回走，沿路向东到{area:212}。{npc:6177}死在岸边：对他使用{item:6866}。在湖边潜行的黑铁间谍身上带着那份名册。",
	["Ice Claw Bear"] = "冰爪熊",
	["Iceclaw Bear Pendants, from the Frostmane Troll Whelps on the slopes above the camp"] = "冰爪熊坠饰，来自营地上方山坡上的霜鬃巨魔幼崽",
	["If you skipped {quest:314}, grind here to level 11.6 to stay on the route's plan."] = "如果你跳过了{quest:314}，就在这里刷到11.6级，以符合路线规划。",
	["Inn and flight master"] = "旅店与飞行管理员",
	["Inside {area:77}"] = "在{area:77}里面",
	["Instead of walking back up to {area:1537}, go east through the South Gate tunnel into {area:38} and follow the road north to {area:144}. {npc:1681} stands on the east side of town, past the {area:2101}; his errand pays for a flight back to {area:1537}."] = "不必走回{area:1537}，改为向东穿过南门隧道进入{area:38}，沿路向北到{area:144}。{npc:1681}在小镇东侧、{area:2101}再往前；他的差事报酬足够坐飞机回{area:1537}。",
	["Kill the Crag Boars on the way: their ribs drop before you have {npc:1267}'s quest and count toward it. Back in the distillery: {npc:1699} teaches {skill:185}, then the ribs go to {npc:1267}."] = "路上杀峭壁野猪：它们的肋排在接到{npc:1267}的任务前就会掉落，并且算作任务进度。回到酿酒厂：{npc:1699}传授{skill:185}，然后把肋排交给{npc:1267}。",
	["Large Crag Boar"] = "大型峭壁野猪",
	["Last: some classes' trainers stand outside"] = "最后处理屋外的职业训练师：部分职业的训练师站在外面",
	["Leave {zone:1453} by the main gate, go south to {area:87} and east along the road to the {area:62}. {npc:881} (level 9) stands by its farmhouse."] = "从正门离开{zone:1453}，向南到{area:87}，再沿道路向东到{area:62}。{npc:881}（9级）站在农舍旁。",
	["Leper Gnomes around Brewnall and the {area:133} road carry the cogs and gears. Ice Claw Bears, Elder Crag Boars and Snow Leopards roam the hills around the lake."] = "烈酒村和{area:133}道路周围的麻疯侏儒带着齿轮。冰爪熊、老峭壁野猪和雪豹在湖周围的山丘上游荡。",
	["Level 11.6"] = "11.6级",
	["Level 4 spells, before Gozwin's camp"] = "4级法术，在去戈兹温营地之前",
	["Minor Ice Elemental"] = "小型冰元素",
	["On the road back west to {zone:1455}."] = "在回西边{zone:1455}的路上。",
	["On the way"] = "顺路",
	["Ragged Young Wolves roam the snow just south of {area:77}."] = "蓬毛幼狼在{area:77}南边的雪地里游荡。",
	["Rockjaw Ambushers by {area:212}, north of the quarry, and Rockjaw Backbreakers further east drop the {quest:95214}. Rockjaw Bonesnappers prowl the quarry and the lake; Dark Iron Spies sneak around the lake shore. One spy drops the {item:274268}."] = "{area:212}旁、采石场以北的石颚伏击者，以及更东边的石颚碎背者掉落{quest:95214}。石颚碎骨者在采石场和湖边徘徊；黑铁间谍在湖岸潜行。其中一个间谍掉落{item:274268}。",
	["Rockjaw Bonesnapper"] = "石颚碎骨者",
	["Rockjaw Skullthumper"] = "石颚碎颅者",
	["Rockjaw Skullthumpers fill the quarry; Rockjaw Ambushers by {area:212} drop the {item:268548}."] = "{npc:1115}遍布采掘场；{area:212}旁的{npc:1116}掉落{item:268548}。",
	["Rockjaw Skullthumpers, Bonesnappers and Ambushers share the quarry and the slopes north of it; the Ambushers drop the {item:268548}."] = "石腭击颅者、石腭碎骨者和石腭伏击者分布在采掘场及其北边的山坡上；伏击者掉落{item:268548}。",
	["Rockjaw Trogg"] = "石颚穴居人",
	["Rockjaw Troggs and Burly Rockjaw Troggs dig all over the valley floor south of {area:77}."] = "石腭穴居人和壮实的石腭怪在{area:77}南边的谷底到处挖掘。",
	["Sit by Eric's campfire (type /sit) and wait for the buff."] = "坐在艾瑞克的营火旁（输入 /sit），等待获得增益效果。",
	["Small Crag Boar"] = "小型峭壁野猪",
	["Small Crag Boars graze around {npc:714}'s camp and along the west side of the valley."] = "小型峭壁野猪在{npc:714}的营地周围和山谷西侧吃草。",
	["Snow Leopard"] = "雪豹",
	["Snow Leopard Prowler"] = "雪豹潜行者",
	["Snow Leopards and boars roam the snow between the ranch and the quarry. Blacksmiths: Copper Bars come from smelting {item:2770} or the trade vendors."] = "雪豹和野猪在农场与采掘场之间的雪地里游荡。铁匠：铜锭可以通过熔炼{item:2770}获得，或从商人处购买。",
	["Stonesplinter Seers (level 13) stand among the troggs in the south of {area:923}, south of {npc:257808}; Tunnel Rat Geomancers (level 12) work the {area:149} at the north end of the loch. The troggs come in packs and some throw from range: pull one at a time."] = "碎石怪先知（13级）站在{npc:257808}南边、{area:923}南部的穴居人之间；坑道鼠地卜师（12级）在湖北端的{area:149}工作。穴居人成群出现，有些会远程投掷：一次拉一个。",
	["Subdue the voidwalker"] = "制服虚空行者",
	["The Fire Spirit Stone"] = "火之灵魂石",
	["The Scalding Mornbrew lasts five minutes: go straight north to {npc:836} inside {area:77}."] = "德南的热酒只持续五分钟：直接向北到{area:77}里面找{npc:836}。",
	["The boars"] = "野猪",
	["The firewood lies in the snow around the frozen lake by the refuge."] = "木柴散落在避难所旁结冰湖泊周围的雪地里。",
	["The quarry lies just east of Farsen's ridge."] = "采石场就在法森山脊以东。",
	["The quarry troggs"] = "采掘场的穴居人",
	["The three rifles lie in the snow around the frozen lake by the refuge. Minor Ice Elementals drift around the lake and along the way: kill them as you go for {quest:99160}.\nFinish off the Minor Ice Elementals around the small lake just west of the refuge if you are still short."] = "三支步枪在营地旁冰湖周围的雪地里。小型冰元素在湖边和路上飘荡：为{quest:99160}一路杀过去。\n如果数量还不够，把营地西边小湖周围的小型冰元素也清掉。",
	["The tram arrives in the {object:28027}. {npc:5480} trains warriors in {object:2100}; {npc:6089} and {npc:6090} stand together by the {object:2152} there. {npc:6090} fights you for his mug."] = "地铁到达{object:28027}。{npc:5480}在{object:2100}训练战士；{npc:6089}和{npc:6090}一起站在那里的{object:2152}旁。{npc:6090}会为了他的杯子和你打一架。",
	["The troggs"] = "穴居人",
	["The troll cave"] = "巨魔洞穴",
	["The tunnel"] = "隧道",
	["The {area:2257}"] = "{area:2257}",
	["The {item:2676} grows in baskets up on {area:802}, the snowy slope north of the road between {area:131} and Brewnall: climb from the road west of {area:131}. The Frostmane Seers camped on the ridge drop it too."] = "{item:2676}长在{area:802}上的篮子里，那是{area:131}与布伦诺尔之间道路以北的雪坡：从{area:131}西边的路上山。山脊上扎营的霜鬃先知也会掉落。",
	["The {object:176785} sits next to {npc:271546}, south of the {area:136}."] = "{object:176785}在{npc:271546}旁边，{area:136}以南。",
	["The {object:269} in the basement"] = "地下室里的{object:269}",
	["The {object:270} in the distillery; below ground"] = "{object:270}在酿酒厂里；地下",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:1388} is a level 12 elite: most classes solo it at level 14, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "这些是精英怪：建议组队，找人一起做。{npc:1388}是12级精英：大多数职业在14级可以单挑，但你可能需要帮助。如果你独自一人就跳过：路线会让你把经验刷回来。",
	["Tram to {zone:1453}"] = "乘地铁前往{zone:1453}",
	["Upstairs"] = "楼上",
	["Use the {item:6866} on {npc:6177}"] = "对{npc:6177}使用{item:6866}",
	["While you're here: learn Staves from {npc:11867} ({object:2096}, 10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "顺便：在{npc:11867}处学习法杖（{object:2096}，10银币）；猎人的近战武器主要看属性，而双手武器属性最多。",
	["While you're here: learn Staves from {npc:11867} ({object:2096}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "顺便：在{npc:11867}处学习法杖（{object:2096}，10银币）；升级期间，法杖的法术属性比单手武器更多。",
	["While you're here: learn Swords from {npc:11867} ({object:2096}, 10 silver); a sword in the main hand levels a Rogue steadily."] = "顺便：在{npc:11867}处学习剑（{object:2096}，10银币）；主手持剑能让潜行者稳定升级。",
	["While you're here: learn {spell:197} from {npc:11865} ({object:32359}, 10 silver); two-handers level a Paladin fastest."] = "趁在这里：向{npc:11865}学习{spell:197}（{object:32359}，10银）；双手武器让圣骑士升级最快。",
	["While you're here: learn {spell:197} from {npc:11865} ({object:32359}, 10 silver); two-handers level a Warrior fastest."] = "趁在这里：向{npc:11865}学习{spell:197}（{object:32359}，10银）；双手武器让战士升级最快。",
	["While you're here: learn {spell:199} from {npc:11865} ({object:32359}, 10 silver); two-handers level a Warrior fastest."] = "趁在这里：向{npc:11865}学习{spell:199}（{object:32359}，10银）；双手武器让战士升级最快。",
	["While you're here: learn {spell:202} from {npc:11867} ({object:2096}, 10 silver); two-handers level a Paladin fastest."] = "趁在这里：向{npc:11867}学习{spell:202}（{object:2096}，10银）；双手武器让圣骑士升级最快。",
	["While you're here: learn {spell:202} from {npc:11867} ({object:2096}, 10 silver); two-handers level a Warrior fastest."] = "趁在这里：向{npc:11867}学习{spell:202}（{object:2096}，10银）；双手武器让战士升级最快。",
	["You start in front of {area:77}, the stone hall at the north end of the valley. {npc:658} waits outside the door."] = "你从{area:77}前方出发，那是山谷北端的石厅。{npc:658}在门外等候。",
	["Young wolves"] = "幼狼",
	["grind on {npc:260157}"] = "刷{npc:260157}",
	["{area:131} and the depot"] = "{area:131}和补给站",
	["{area:132}: kill these as you meet them"] = "{area:132}：遇到就杀",
	["{area:133}: kill these as you meet them"] = "{area:133}：遇到就杀",
	["{area:134}: kill these as you meet them"] = "{area:134}：遇到就杀",
	["{area:135} is the troll cave in the hills south-west of {area:137}. Ice Claw Bears, Elder Crag Boars and Snow Leopards you kill on the way count for {npc:1374}. Kill Headhunters at its mouth and walk through to its far end."] = "{area:135}是{area:137}西南边山丘里的巨魔洞穴。沿途击杀的冰爪熊、老峭壁野猪和雪豹都计入{npc:1374}的任务。先击杀洞口的猎头者，再穿过洞穴走到另一端。",
	["{area:137} sits on the lake west of {area:131}. {npc:8508}'s dock is the first stop; {npc:1374} and {npc:1375} are in the village beyond it."] = "{area:137}位于{area:131}西边的湖畔。先去{npc:8508}所在的码头，再到后面的村子找{npc:1374}和{npc:1375}。",
	["{area:138}: kill these as you meet them"] = "{area:138}：遇到就杀",
	["{area:1}: kill these as you meet them"] = "{area:1}：遇到就杀",
