	["{npc:1123}, below ground"] = "{npc:1123}，地下",
	["{npc:1126}: tame it with the {item:15908}"] = "{npc:1126}：用{item:15908}驯服它",
	["{npc:1127}, on the way"] = "{npc:1127}，沿途击杀",
	["{npc:1196}, on the way to the Hold"] = "{npc:1196}，前往据点的路上顺手击杀",
	["{npc:1196}: tame it with the {item:15908}"] = "{npc:1196}：用{item:15908}驯服它",
	["{npc:1201}, on the way"] = "{npc:1201}，沿途击杀",
	["{npc:1201}: tame it with the {item:15908}"] = "{npc:1201}：用{item:15908}驯服它",
	["{npc:1226}, upstairs"] = "{npc:1226}，楼上",
	["{npc:1226}: {npc:376} in {zone:1453} takes it"] = "{npc:1226}：交给{zone:1453}的{npc:376}",
	["{npc:1231}, at the smithy"] = "{npc:1231}，在铁匠铺",
	["{npc:1241}, below ground"] = "{npc:1241}，地下",
	["{npc:1243} camps south-west of it, by the road to Coldridge."] = "{npc:1243}在它西南扎营，靠近去冷岭的路。",
	["{npc:1252}: {npc:1274} in {zone:1455} takes it"] = "{npc:1252}：交给{zone:1455}的{npc:1274}",
	["{npc:1266} camps in {area:801}, south of the road back east from Brewnall to {area:131}. His meats are in the locker in {npc:1271}'s cave, east of his camp. {npc:1271} is an elite yeti: wait out of sight until he wanders off on his patrol, then take the meats and leave before he comes back. You don't need to fight him."] = "{npc:1266}在{area:801}扎营，位于从布伦诺尔向东返回{area:131}的道路以南。他的肉在{npc:1271}洞穴的冷藏柜里，在营地以东。{npc:1271}是精英雪人：躲起来等他巡逻走开，然后拿走肉，在他回来前离开。不需要和他战斗。",
	["{npc:1269}, below ground"] = "{npc:1269}，地下",
	["{npc:1269}, by the depot; below ground"] = "{npc:1269}，在补给站旁；地下",
	["{npc:1269}, on the way back; below ground"] = "{npc:1269}，在回程路上；在地下",
	["{npc:12738}, next to him"] = "{npc:12738}，在他旁边",
	["{npc:12738}: timed, five minutes to reach {npc:836} in {area:77}"] = "{npc:12738}：限时任务，五分钟内赶到{area:77}找{npc:836}",
	["{npc:1274}, in the {object:171709} with King Magni"] = "{npc:1274}，在{object:171709}里，和麦格尼国王在一起",
	["{npc:1373} guards the {item:2686} barrels in the distillery basement. Buy a {item:2686} from {npc:1247}, click the guarded barrel, then hand the ale to {npc:1373} from his quest window (there is no quest to accept); after that, the unguarded barrel takes the {spell:8553}."] = "{npc:1373}看守酿酒厂地下室的{item:2686}酒桶。先从{npc:1247}买一份{item:2686}，点击有守卫的酒桶，然后在{npc:1373}的任务窗口把酒交给他（没有任务可接）；之后，没有守卫的那个酒桶就能接受{spell:8553}了。",
	["{npc:1373}, beside the barrel; below ground"] = "{npc:1373}，在酒桶旁；地下",
	["{npc:1377}, at the depot"] = "{npc:1377}，在补给站",
	["{npc:1377}, beside him"] = "{npc:1377}，在他旁边",
	["{npc:1572}, the gryphon master"] = "{npc:1572}，狮鹫管理员",
	["{npc:1573}, the gryphon master where you landed"] = "{npc:1573}，落地处的狮鹫管理员",
	["{npc:1694}, beside him"] = "{npc:1694}，在他旁边",
	["{npc:1698}: blacksmiths only"] = "{npc:1698}：仅限铁匠",
	["{npc:1699}: Camping 101 asks you to learn it; below ground"] = "{npc:1699}：任务“露营入门”要求你学会它；地下",
	["{npc:1872} works the forge west of the distillery.\nThen go in: {npc:6806}, the innkeeper, {npc:1226} and {npc:1267}. {npc:1699}'s {skill:185} lesson waits for the return with the ribs, when the copper is there for it."] = "{npc:1872}在酿酒厂西边的铁匠铺干活。\n然后进去：旅店老板{npc:6806}、{npc:1226}和{npc:1267}。{npc:1699}的{skill:185}课程要等你带着肋排回来才教，那时铜币也够了。",
	["{npc:1960} waits at the {area:808}, north of the South Gate; the dwarven corpse lies up the pass to the west of him."] = "{npc:1960}在南门以北的{area:808}等候；矮人尸体就在他西边的山道上方。",
	["{npc:1965} guards the tunnel out of the valley, east of {area:77}; {npc:6782} stands beside him at its mouth."] = "{npc:1965}守卫着{area:77}东边离开山谷的隧道；{npc:6782}站在隧道口他的旁边。",
	["{npc:1977}, in the quarry"] = "{npc:1977}，在采掘场里",
	["{npc:257446}, inside {area:77}"] = "{npc:257446}，在{area:77}里面",
	["{npc:257446}: {npc:5873} and your {item:5175}"] = "{npc:257446}：{npc:5873}和你的{item:5175}",
	["{npc:257597} waits in a cave above the farm north-west of the {area:806}; the path up starts behind the farm."] = "{npc:257597}在{area:806}西北方农场上方的洞穴里等候；上去的小路从农场后面开始。",
	["{npc:257597}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:257597}：{npc:2523}、你的{item:5176}和{item:263412}",
	["{npc:257808} gives you the {item:6636}. Climb to the peak above his camp, drink the Sapta beside the Spirit Stone and defeat the {npc:5893}, then place its {item:6655} in the {object:61934}, atop the Shrine of Eternal Flame."] = "{npc:257808}会给你{item:6636}。爬到他营地上方的山顶，在灵魂石旁喝下圣水并击败{npc:5893}，然后把它的{item:6655}放进永恒之火神龛顶上的{object:61934}。",
	["{npc:258098}, the shaman trainer, north of the {object:32372}"] = "{npc:258098}，萨满祭司训练师，在{object:32372}北边",
	["{npc:258113}: {npc:257597} by the South Gate takes it"] = "{npc:258113}：交给南门旁的{npc:257597}",
	["{npc:2756} stands by {npc:8416} at the door of {area:77}. Gozwin's camp is in the hills just north-west; the {npc:269075} prowls around it."] = "{npc:2756}站在{area:77}门口的{npc:8416}旁边。戈兹温的营地在西北方不远处的山丘上；{npc:269075}在营地周围潜行。",
	["{npc:2756}, inside"] = "{npc:2756}，室内",
	["{npc:276003} along the way to {npc:1253}"] = "顺路去{npc:1253}的路上{npc:276003}",
	["{npc:276003} on the way"] = "顺路上的{npc:276003}",
	["{npc:276003}, around the small lake"] = "{npc:276003}，在小湖周围",
	["{npc:376} is in the Cathedral of Light."] = "{npc:376}在光明大教堂。",
	["{npc:4256}, in the {object:32372}"] = "{npc:4256}，在{object:32372}里",
	["{npc:460}, inside {area:77}"] = "{npc:460}，在{area:77}里面",
	["{npc:5505} in {zone:1453}; {area:1} has no druid trainer"] = "{npc:5505}在{zone:1453}；{area:1}没有德鲁伊训练师",
	["{npc:6120}: {npc:6122} in {zone:1453} takes it"] = "{npc:6120}：交给{zone:1453}的{npc:6122}",
	["{npc:6122} waits in the cellar of the {object:2164}, in the {object:2101}."] = "{npc:6122}在{object:2101}的{object:2164}地下室等候。",
	["{npc:6179}: Redemption"] = "{npc:6179}：救赎",
	["{npc:658}: a rune for {npc:895}"] = "{npc:658}：交给{npc:895}的符文",
	["{npc:658}: read the {quest:98581}"] = "{npc:658}：阅读{quest:98581}",
	["{npc:6806}, inside"] = "{npc:6806}，室内",
	["{npc:706} along the way to {npc:786}"] = "顺路去{npc:786}的路上{npc:706}",
	["{npc:706} on the way"] = "顺路上的{npc:706}",
	["{npc:713}, next to {npc:658}"] = "{npc:713}，在{npc:658}旁边",
	["{npc:714}'s camp is at the west end of the valley. {item:10438} lies in the snow south of it, his Chest by the troll cave and his Bucket of Bolts east of the cave: grab them as you pass."] = "{npc:714}的营地在山谷西端。{item:10438}在营地南边的雪地里，菲利克斯的箱子在巨魔洞穴旁，菲利克斯的螺钉桶在洞穴东边：路过时拿上。",
	["{npc:786} and {npc:12738} camp at the south-west edge of the valley, below the troll cave."] = "{npc:786}和{npc:12738}在山谷西南边缘、巨魔洞穴下方扎营。",
	["{npc:808} is inside the troll cave east of {npc:786}'s camp, not on the hill above it: go in at the mouth and follow the tunnel to the back."] = "{npc:808}在{npc:786}营地东边的巨魔洞穴里面，不在上方的山丘上：从洞口进去，沿隧道走到最深处。",
	["{npc:836}, inside {area:77}; below ground"] = "{npc:836}，在{area:77}内；地下",
	["{npc:837}, the priest trainer"] = "{npc:837}，牧师训练师",
	["{npc:8416}, at the door on the way out; inside"] = "{npc:8416}，在出门处的门口；室内",
	["{npc:8416}, by the door of {area:77}; inside"] = "{npc:8416}，在{area:77}门口；室内",
	["{npc:8508}, on the dock"] = "{npc:8508}，在码头上",
	["{npc:895}, the hunter trainer"] = "{npc:895}，猎人训练师",
	["{npc:912}, the warrior trainer; inside"] = "{npc:912}，战士训练师；室内",
	["{npc:916}, the rogue trainer"] = "{npc:916}，潜行者训练师",
	["{npc:926}, the paladin trainer"] = "{npc:926}，圣骑士训练师",
	["{object:660964}, by the mailbox in {object:171524}"] = "{object:660964}，在{object:171524}的邮箱旁",
	["{zone:1453} flight master"] = "{zone:1453}飞行管理员",
	["{zone:1455} class quests"] = "{zone:1455}职业任务",
}

G["forever/alliance/gnome/01-dun-morogh"] = {
	["Back east through {area:131}: the class quests here wait for level 10."] = "向东返回，穿过{area:131}：这里的职业任务要等到10级。",
	["Back through the tunnel to {npc:257597}' cave above the farm."] = "穿过隧道回到农场上方{npc:257597}的洞穴。",
	["Back to {area:77}"] = "返回{area:77}",
	["Back to {npc:257446} in {area:77}. He gives you the {item:6635}: take the rubble-marked path that climbs west from the south of the valley to the Spirit Stone on the ridge, drink the Sapta beside it and speak to the {npc:5891}, then bring its {item:6656} back to Teo."] = "回到{area:77}找{npc:257446}。他会给你{item:6635}：沿着山谷南部向西攀升、标有碎石的小路走到山脊上的灵魂石，在旁边喝下圣水并与{npc:5891}交谈，然后把它的{item:6656}带回给Teo。",
	["Back to {npc:257597}"] = "返回{npc:257597}处",
	["Back to {npc:6122}. Use the {item:6928} at the summoning circle in the {object:2164}'s cellar and defeat the voidwalker it calls. {area:40} is next, west of {area:87}."] = "回到{npc:6122}。在{object:2164}地窖里的召唤法阵上使用{item:6928}，击败它召唤出的虚空行者。接下来去{area:40}，在{area:87}西边。",
	["Bartleby"] = "巴特莱比",
	["Below ground"] = "地下",
	["Burly Rockjaw Trogg"] = "强壮的石颚穴居人",
	["Class trainer"] = "职业训练师",
	["Crag Boars and Young Black Bears roam the fields around {area:131} and the depot."] = "{npc:1125}和{npc:1128}在{area:131}和补给站周围的田野里游荡。",
	["Dark Iron Spy"] = "黑铁间谍",
	["Druid trainer"] = "德鲁伊训练师",
	["Elder Crag Boar"] = "老峭壁野猪",
	["Farsen camps on the ridge overlooking the {area:134} from the west. Talk to him for his farsight."] = "Farsen在{area:134}西边可俯瞰采掘场的山脊上扎营。与他交谈获得远视。",
	["Feather Charms, from the Frostmane Novices"] = "羽毛咒符，来自霜鬃巨魔新兵",
	["Firewood"] = "木柴",
	["Flintfire's shipments lie on the cave floor, and {npc:278166} is missing somewhere inside.\nCareful: Wendigos stand close together inside the cave, so fights easily pull several at once; drawing them out one at a time with ranged attacks from outside avoids this."] = "弗林特菲尔的货物散落在洞穴地面上，{npc:278166}在洞里某处失踪了。\n小心：洞里的雪人站得很密，战斗时很容易一次引来好几只；在洞外用远程攻击把它们一只一只引出来就能避免。",
	["Flintfire's shipments lie on the cave floor, and {object:460004} is missing somewhere inside.\nCareful: Wendigos stand close together inside the cave, so fights easily pull several at once; drawing them out one at a time with ranged attacks from outside avoids this."] = "燧火的货物散落在洞穴地面，{object:460004}则在洞穴某处遗失。\n小心：洞穴里的雪怪站得很近，战斗很容易同时引到好几只；在洞外用远程攻击一只一只引出来就能避免。",
	["Follow the road all the way east to the {area:806} at the {area:38} tunnel."] = "沿路一直向东，到{area:38}隧道处的{area:806}。",
	["Follow the road east past the depot to {area:138}."] = "沿道路向东经过补给站到{area:138}。",
	["Follow the road north-east from {area:131} to the depot below the {zone:1455} road."] = "沿道路从{area:131}向东北到{zone:1455}道路下方的钢架补给站。",
	["Follow the road north-east from {area:131} to the depot: the whole east of {area:1} is one sweep from here."] = "从{area:131}沿路向东北前往补给站：{area:1}整个东边都可以从这里一次清完。",
	["Follow the road through the tunnel and north-east to {area:131}. Start outside: {npc:1252} and Eric's campfire are in front of the {area:2102}.\n{npc:1872} works the forge west of the distillery.\nThen go in: {npc:6806}, the innkeeper, {npc:1226} and {npc:1267}. {npc:1699}'s {skill:185} lesson waits for the return with the ribs, when the copper is there for it."] = "沿路穿过隧道，向东北到{area:131}。从外面开始：{npc:1252}和埃里克的营火在{area:2102}前面。\n{npc:1872}在酿酒厂西边的铁匠铺干活。\n然后进去：旅店老板{npc:6806}、{npc:1226}和{npc:1267}。{npc:1699}的{skill:185}课程要等你带着肋排回来才教，那时铜币也够了。",
	["Follow the road up to {zone:1455} and take the {object:32362}: {npc:5149}, {npc:6179} and {npc:6178} are in the {object:32386}, Tiza and Muiredon on its upper floor: the stairs up start just north-east of {npc:5149}. {npc:6175}, a beggar, wanders the city. He asks for ten {item:2589}: the troggs and trolls of {area:1} drop it, and the Auction House sells it."] = "沿路走到{zone:1455}，乘坐{object:32362}：{npc:5149}、{npc:6179}和{npc:6178}在{object:32386}里，提扎和缪瑞顿在它的上层：上楼的楼梯就在{npc:5149}东北。乞丐{npc:6175}在城中游荡。他要十块{item:2589}：{area:1}的穴居人和巨魔会掉落，拍卖行也有卖。",
	["Follow the road up to {zone:1455} and train with your class trainer. The {area:2257} leaves from {object:171524}, in the east of the city. Ride it to {zone:1453}."] = "沿道路上到{zone:1455}，找你的职业训练师学习。{area:2257}从城市东部的{object:171524}出发。乘它前往{zone:1453}。",
	["Frostmane Headhunter"] = "霜鬃猎头者",
	["Frostmane Troll Whelp"] = "霜鬃巨魔幼崽",
	["Frostmane Troll Whelps fill the slopes south and east of {npc:786}'s camp."] = "霜鬃巨魔幼崽遍布{npc:786}营地南边和东边的山坡。",
	["Go through the tunnel into {area:38}. Just past it, a path marked by stones climbs the hills on the right of the road north to {npc:257808}'s camp."] = "穿过隧道进入{area:38}。刚过隧道，一条用石头标记的小路沿着通往{npc:257808}营地的北路右侧爬上山。",
	["Gretchen camps just outside the {area:136}, the wendigo cave south-west of {area:131}."] = "这位巡山人在{area:136}外扎营；那是{area:131}西南边的雪怪洞穴。",
	["Head back out of {zone:1455} and east along the road to {area:212}. {npc:6177} lies dead by its shore: use the {item:6866} on him. The Dark Iron Spies sneaking around the lake carry the script."] = "离开{zone:1455}往回走，沿路向东到{area:212}。{npc:6177}死在岸边：对他使用{item:6866}。在湖边潜行的黑铁间谍身上带着那份名册。",
	["Ice Claw Bear"] = "冰爪熊",
	["Iceclaw Bear Pendants, from the Frostmane Troll Whelps on the slopes above the camp"] = "冰爪熊坠饰，来自营地上方山坡上的霜鬃巨魔幼崽",
	["If you skipped {quest:314}, grind here to level 11.41 to stay on the route's plan."] = "如果你跳过了{quest:314}，就在这里刷到11.41级，以符合路线规划。",
	["Inn and flight master"] = "旅店与飞行管理员",
	["Inside {area:77}"] = "在{area:77}里面",
	["Instead of walking back up to {area:1537}, go east through the South Gate tunnel into {area:38} and follow the road north to {area:144}. {npc:1681} stands on the east side of town, past the {area:2101}; his errand pays for a flight back to {area:1537}."] = "不必走回{area:1537}，改为向东穿过南门隧道进入{area:38}，沿路向北到{area:144}。{npc:1681}在小镇东侧、{area:2101}再往前；他的差事报酬足够坐飞机回{area:1537}。",
	["Kill the Crag Boars on the way: their ribs drop before you have {npc:1267}'s quest and count toward it. Back in the distillery: {npc:1699} teaches {skill:185}, then the ribs go to {npc:1267}."] = "路上杀峭壁野猪：它们的肋排在接到{npc:1267}的任务前就会掉落，并且算作任务进度。回到酿酒厂：{npc:1699}传授{skill:185}，然后把肋排交给{npc:1267}。",
	["Last: some classes' trainers stand outside"] = "最后处理屋外的职业训练师：部分职业的训练师站在外面",
	["Leave {zone:1453} by the main gate, go south to {area:87} and east along the road to the {area:62}. {npc:881} (level 9) stands by its farmhouse."] = "从正门离开{zone:1453}，向南到{area:87}，再沿道路向东到{area:62}。{npc:881}（9级）站在农舍旁。",
	["Leave {zone:1453} by the main gate. The {quest:1861} waterfall is south-west of the gates, on the way west to {area:40}: fill {item:7207} at its base."] = "从正门离开{zone:1453}。{quest:1861}瀑布在城门外西南方，就在向西去{area:40}的路上：在瀑布底部装满{item:7207}。",
	["Leave {zone:1453} by the main gate. The {quest:1861} waterfall is south-west of the gates, on the way west to {zone:1436}: fill {item:7207} at its base."] = "从正门离开{zone:1453}。{quest:1861}瀑布在城门西南方，就在向西前往{zone:1436}的路上：在瀑布底部装满{item:7207}。",
	["Leper Gnomes around Brewnall and the {area:133} road carry the cogs and gears. Ice Claw Bears, Elder Crag Boars and Snow Leopards roam the hills around the lake."] = "烈酒村和{area:133}道路周围的麻疯侏儒带着齿轮。冰爪熊、老峭壁野猪和雪豹在湖周围的山丘上游荡。",
	["Level 11.41"] = "11.41级",
	["Level 4 spells, before Gozwin's camp"] = "4级法术，在去戈兹温营地之前",
	["Minor Ice Elemental"] = "小型冰元素",
	["On the road back west to {zone:1455}."] = "在回西边{zone:1455}的路上。",
	["On the way"] = "顺路",
	["Ragged Young Wolves roam the snow just south of {area:77}."] = "蓬毛幼狼在{area:77}南边的雪地里游荡。",
	["Rockjaw Ambushers by {area:212}, north of the quarry, and Rockjaw Backbreakers further east drop the {quest:95214}. Rockjaw Bonesnappers prowl the quarry and the lake; Dark Iron Spies sneak around the lake shore. One spy drops the {item:274268}."] = "{area:212}旁、采石场以北的石颚伏击者，以及更东边的石颚碎背者掉落{quest:95214}。石颚碎骨者在采石场和湖边徘徊；黑铁间谍在湖岸潜行。其中一个间谍掉落{item:274268}。",
	["Rockjaw Bonesnapper"] = "石颚碎骨者",
	["Rockjaw Skullthumper"] = "石颚碎颅者",
	["Rockjaw Skullthumpers fill the quarry; Rockjaw Ambushers by {area:212} drop the {item:268548}."] = "{npc:1115}遍布采掘场；{area:212}旁的{npc:1116}掉落{item:268548}。",
	["Rockjaw Skullthumpers, Bonesnappers and Ambushers share the quarry and the slopes north of it; the Ambushers drop the {item:268548}."] = "石腭击颅者、石腭碎骨者和石腭伏击者分布在采掘场及其北边的山坡上；伏击者掉落{item:268548}。",
	["Rockjaw Trogg"] = "石颚穴居人",
	["Rockjaw Troggs and Burly Rockjaw Troggs dig all over the valley floor south of {area:77}."] = "石腭穴居人和壮实的石腭怪在{area:77}南边的谷底到处挖掘。",
	["Sit by Eric's campfire (type /sit) and wait for the buff."] = "坐在艾瑞克的营火旁（输入 /sit），等待获得增益效果。",
	["Small Crag Boar"] = "小型峭壁野猪",
	["Small Crag Boars graze around {npc:714}'s camp and along the west side of the valley."] = "小型峭壁野猪在{npc:714}的营地周围和山谷西侧吃草。",
	["Snow Leopard"] = "雪豹",
	["Snow Leopard Prowler"] = "雪豹潜行者",
	["Snow Leopards and boars roam the snow between the ranch and the quarry. Blacksmiths: Copper Bars come from smelting {item:2770} or the trade vendors."] = "雪豹和野猪在农场与采掘场之间的雪地里游荡。铁匠：铜锭可以通过熔炼{item:2770}获得，或从商人处购买。",
	["Stonesplinter Seers (level 13) stand among the troggs in the south of {area:923}, south of {npc:257808}; Tunnel Rat Geomancers (level 12) work the {area:149} at the north end of the loch. The troggs come in packs and some throw from range: pull one at a time."] = "碎石怪先知（13级）站在{npc:257808}南边、{area:923}南部的穴居人之间；坑道鼠地卜师（12级）在湖北端的{area:149}工作。穴居人成群出现，有些会远程投掷：一次拉一个。",
	["Subdue the voidwalker"] = "制服虚空行者",
	["The Fire Spirit Stone"] = "火之灵魂石",
	["The Scalding Mornbrew lasts five minutes: go straight north to {npc:836} inside {area:77}."] = "德南的热酒只持续五分钟：直接向北到{area:77}里面找{npc:836}。",
	["The boars"] = "野猪",
	["The firewood lies in the snow around the frozen lake by the refuge."] = "木柴散落在避难所旁结冰湖泊周围的雪地里。",
	["The quarry lies just east of Farsen's ridge."] = "采石场就在法森山脊以东。",
	["The quarry troggs"] = "采掘场的穴居人",
	["The three rifles lie in the snow around the frozen lake by the refuge. Minor Ice Elementals drift around the lake and along the way: kill them as you go for {quest:99160}.\nFinish off the Minor Ice Elementals around the small lake just west of the refuge if you are still short."] = "三支步枪在营地旁冰湖周围的雪地里。小型冰元素在湖边和路上飘荡：为{quest:99160}一路杀过去。\n如果数量还不够，把营地西边小湖周围的小型冰元素也清掉。",
	["The tram arrives in the {object:28027}. {npc:5480} trains warriors in {object:2100}; {npc:6089} and {npc:6090} stand together by the {object:2152} there. {npc:6090} fights you for his mug."] = "地铁到达{object:28027}。{npc:5480}在{object:2100}训练战士；{npc:6089}和{npc:6090}一起站在那里的{object:2152}旁。{npc:6090}会为了他的杯子和你打一架。",
	["The troggs"] = "穴居人",
	["The troll cave"] = "巨魔洞穴",
	["The tunnel"] = "隧道",
	["The {area:2257}"] = "{area:2257}",
	["The {item:2676} grows in baskets up on {area:802}, the snowy slope north of the road between {area:131} and Brewnall: climb from the road west of {area:131}. The Frostmane Seers camped on the ridge drop it too."] = "{item:2676}长在{area:802}上的篮子里，那是{area:131}与布伦诺尔之间道路以北的雪坡：从{area:131}西边的路上山。山脊上扎营的霜鬃先知也会掉落。",
	["The {item:6775}"] = "{item:6775}",
	["The {object:176785} sits next to {npc:271546}, south of the {area:136}."] = "{object:176785}在{npc:271546}旁边，{area:136}以南。",
	["The {object:269} in the basement"] = "地下室里的{object:269}",
	["The {object:270} in the distillery; below ground"] = "{object:270}在酿酒厂里；地下",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:1388} is a level 12 elite: most classes solo it at level 14, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "这些是精英怪：建议组队，找人一起做。{npc:1388}是12级精英：大多数职业在14级可以单挑，但你可能需要帮助。如果你独自一人就跳过：路线会让你把经验刷回来。",
	["Tram to {zone:1453}"] = "乘地铁前往{zone:1453}",
	["Upstairs"] = "楼上",
	["While you're here: learn Staves from {npc:11867} ({object:2096}, 10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "顺便：在{npc:11867}处学习法杖（{object:2096}，10银币）；猎人的近战武器主要看属性，而双手武器属性最多。",
	["While you're here: learn Staves from {npc:11867} ({object:2096}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "顺便：在{npc:11867}处学习法杖（{object:2096}，10银币）；升级期间，法杖的法术属性比单手武器更多。",
	["While you're here: learn Swords from {npc:11867} ({object:2096}, 10 silver); a sword in the main hand levels a Rogue steadily."] = "顺便：在{npc:11867}处学习剑（{object:2096}，10银币）；主手持剑能让潜行者稳定升级。",
	["While you're here: learn {spell:197} from {npc:11865} ({object:32359}, 10 silver); two-handers level a Paladin fastest."] = "趁在这里：向{npc:11865}学习{spell:197}（{object:32359}，10银）；双手武器让圣骑士升级最快。",
	["While you're here: learn {spell:197} from {npc:11865} ({object:32359}, 10 silver); two-handers level a Warrior fastest."] = "趁在这里：向{npc:11865}学习{spell:197}（{object:32359}，10银）；双手武器让战士升级最快。",
	["While you're here: learn {spell:199} from {npc:11865} ({object:32359}, 10 silver); two-handers level a Warrior fastest."] = "趁在这里：向{npc:11865}学习{spell:199}（{object:32359}，10银）；双手武器让战士升级最快。",
	["While you're here: learn {spell:202} from {npc:11867} ({object:2096}, 10 silver); two-handers level a Paladin fastest."] = "趁在这里：向{npc:11867}学习{spell:202}（{object:2096}，10银）；双手武器让圣骑士升级最快。",
	["While you're here: learn {spell:202} from {npc:11867} ({object:2096}, 10 silver); two-handers level a Warrior fastest."] = "趁在这里：向{npc:11867}学习{spell:202}（{object:2096}，10银）；双手武器让战士升级最快。",
	["You start in front of {area:77}, the stone hall at the north end of the valley. {npc:658} waits outside the door."] = "你从{area:77}前方出发，那是山谷北端的石厅。{npc:658}在门外等候。",
	["Young wolves"] = "幼狼",
	["grind on {npc:260157}"] = "刷{npc:260157}",
	["{area:131} and the depot"] = "{area:131}和补给站",
	["{area:132}: kill these as you meet them"] = "{area:132}：遇到就杀",
	["{area:133}: kill these as you meet them"] = "{area:133}：遇到就杀",
	["{area:135} is the troll cave in the hills south-west of {area:137}. Ice Claw Bears, Elder Crag Boars and Snow Leopards you kill on the way count for {npc:1374}. Kill Headhunters at its mouth and walk through to its far end."] = "{area:135}是{area:137}西南边山丘里的巨魔洞穴。沿途击杀的冰爪熊、老峭壁野猪和雪豹都计入{npc:1374}的任务。先击杀洞口的猎头者，再穿过洞穴走到另一端。",
	["{area:137} sits on the lake west of {area:131}. {npc:8508}'s dock is the first stop; {npc:1374} and {npc:1375} are in the village beyond it."] = "{area:137}位于{area:131}西边的湖畔。先去{npc:8508}所在的码头，再到后面的村子找{npc:1374}和{npc:1375}。",
	["{area:138}: kill these as you meet them"] = "{area:138}：遇到就杀",
	["{area:1}: kill these as you meet them"] = "{area:1}：遇到就杀",
	["{item:13850}: the {object:176785}"] = "{item:13850}：{object:176785}",
	["{item:2004}; below ground"] = "{item:2004}；地下",
	["{item:2667}: the meat locker; below ground"] = "{item:2667}：肉类冷藏柜；地下",
	["{item:2686}, from {npc:1247} in the distillery; upstairs"] = "{item:2686}，来自酿酒厂的{npc:1247}；楼上",
	["{item:277976}, in the camp"] = "{item:277976}，在营地里",
	["{item:286325} is by the frozen lake, among the ice elementals."] = "{item:286325}在结冰的湖边，冰元素之间。",
	["{item:2894}, from {npc:1247}; upstairs"] = "{item:2894}，来自{npc:1247}；楼上",
	["{item:3083}: Leper Gnomes"] = "{item:3083}：麻疯侏儒",
	["{item:3084}: Leper Gnomes"] = "{item:3084}：麻疯侏儒",
	["{item:5026} and the {item:6652}"] = "{item:5026}和{item:6652}",
	["{item:5026}: Tunnel Rat Geomancers"] = "{item:5026}：坑道鼠地卜师",
	["{item:6635}, beside the Spirit Stone"] = "{item:6635}，在灵魂石旁",
	["{item:6636}, beside the Spirit Stone"] = "{item:6636}，在灵魂石旁",
	["{item:6652}: Stonesplinter Seers"] = "{item:6652}：碎石怪先知",
	["{npc:10090} is in the {object:32390}, {npc:258785} in the {object:32386}, {npc:6120} in the {object:32383}."] = "{npc:10090}在{object:32390}，{npc:258785}在{object:32386}，{npc:6120}在{object:32383}。",
	["{npc:1117} along the way to {area:134}"] = "顺路去{area:134}的路上{npc:1117}",
	["{npc:1117} on the way"] = "顺路上的{npc:1117}",
	["{npc:1123}, below ground"] = "{npc:1123}，地下",
	["{npc:1127}, on the way"] = "{npc:1127}，沿途击杀",
	["{npc:1196}, on the way to the Hold"] = "{npc:1196}，前往据点的路上顺手击杀",
	["{npc:1201}, on the way"] = "{npc:1201}，沿途击杀",
	["{npc:1226}, upstairs"] = "{npc:1226}，楼上",
	["{npc:1226}: {npc:258785} in {zone:1455} takes it"] = "{npc:1226}：交给{zone:1455}的{npc:258785}",
	["{npc:1241}, below ground"] = "{npc:1241}，地下",
	["{npc:1243} camps south-west of it, by the road to Coldridge."] = "{npc:1243}在它西南扎营，靠近去冷岭的路。",
	["{npc:1252}: {npc:1274} in {zone:1455} takes it"] = "{npc:1252}：交给{zone:1455}的{npc:1274}",
	["{npc:1266} camps in {area:801}, south of the road back east from Brewnall to {area:131}. His meats are in the locker in {npc:1271}'s cave, east of his camp. {npc:1271} is an elite yeti: wait out of sight until he wanders off on his patrol, then take the meats and leave before he comes back. You don't need to fight him."] = "{npc:1266}在{area:801}扎营，位于从布伦诺尔向东返回{area:131}的道路以南。他的肉在{npc:1271}洞穴的冷藏柜里，在营地以东。{npc:1271}是精英雪人：躲起来等他巡逻走开，然后拿走肉，在他回来前离开。不需要和他战斗。",
	["{npc:1269}, below ground"] = "{npc:1269}，地下",
	["{npc:1269}, by the depot; below ground"] = "{npc:1269}，在补给站旁；地下",
	["{npc:1269}, on the way back; below ground"] = "{npc:1269}，在回去的路上；在地下",
	["{npc:12738}, next to him"] = "{npc:12738}，在他旁边",
	["{npc:12738}: timed, five minutes to reach {npc:836} in {area:77}"] = "{npc:12738}：限时任务，五分钟内赶到{area:77}找{npc:836}",
	["{npc:1274}, in the {object:171709} with King Magni"] = "{npc:1274}，在{object:171709}里，和麦格尼国王在一起",
	["{npc:1373} guards the {item:2686} barrels in the distillery basement. Buy a {item:2686} from {npc:1247}, click the guarded barrel, then hand the ale to {npc:1373} from his quest window (there is no quest to accept); after that, the unguarded barrel takes the {spell:8553}."] = "{npc:1373}看守酿酒厂地下室的{item:2686}酒桶。先从{npc:1247}买一份{item:2686}，点击有守卫的酒桶，然后在{npc:1373}的任务窗口把酒交给他（没有任务可接）；之后，没有守卫的那个酒桶就能接受{spell:8553}了。",
	["{npc:1373}, beside the barrel; below ground"] = "{npc:1373}，在酒桶旁；地下",
	["{npc:1377}, at the depot"] = "{npc:1377}，在补给站",
	["{npc:1377}, beside him"] = "{npc:1377}，在他旁边",
	["{npc:1572}, the gryphon master"] = "{npc:1572}，狮鹫管理员",
	["{npc:1573}, the gryphon master where you landed"] = "{npc:1573}，落地处的狮鹫管理员",
	["{npc:1694}, beside him"] = "{npc:1694}，在他旁边",
	["{npc:1698}: blacksmiths only"] = "{npc:1698}：仅限铁匠",
	["{npc:1699}: Camping 101 asks you to learn it; below ground"] = "{npc:1699}：任务“露营入门”要求你学会它；地下",
	["{npc:1960} waits at the {area:808}, north of the South Gate; the dwarven corpse lies up the pass to the west of him."] = "{npc:1960}在南门以北的{area:808}等候；矮人尸体就在他西边的山道上方。",
	["{npc:1965} guards the tunnel out of the valley, east of {area:77}; {npc:6782} stands beside him at its mouth."] = "{npc:1965}守卫着{area:77}东边离开山谷的隧道；{npc:6782}站在隧道口他的旁边。",
	["{npc:1977}, in the quarry"] = "{npc:1977}，在采掘场里",
	["{npc:257446}, inside {area:77}"] = "{npc:257446}，在{area:77}里面",
	["{npc:257446}: {npc:5873} and your {item:5175}"] = "{npc:257446}：{npc:5873}和你的{item:5175}",
	["{npc:257597} waits in a cave above the farm north-west of the {area:806}; the path up starts behind the farm."] = "{npc:257597}在{area:806}西北方农场上方的洞穴里等候；上去的小路从农场后面开始。",
	["{npc:257597}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:257597}：{npc:2523}、你的{item:5176}和{item:263412}",
	["{npc:257808} gives you the {item:6636}. Climb to the peak above his camp, drink the Sapta beside the Spirit Stone and defeat the {npc:5893}, then place its {item:6655} in the {object:61934}, atop the Shrine of Eternal Flame."] = "{npc:257808}会给你{item:6636}。爬到他营地上方的山顶，在灵魂石旁喝下圣水并击败{npc:5893}，然后把它的{item:6655}放进永恒之火神龛顶上的{object:61934}。",
	["{npc:258098}, the shaman trainer, north of the {object:32372}"] = "{npc:258098}，萨满祭司训练师，在{object:32372}北边",
	["{npc:258113}: {npc:257597} by the South Gate takes it"] = "{npc:258113}：交给南门旁的{npc:257597}",
	["{npc:2756} stands by {npc:8416} at the door of {area:77}. Gozwin's camp is in the hills just north-west; the {npc:269075} prowls around it."] = "{npc:2756}站在{area:77}门口的{npc:8416}旁边。戈兹温的营地在西北方不远处的山丘上；{npc:269075}在营地周围潜行。",
	["{npc:2756}, inside"] = "{npc:2756}，室内",
	["{npc:276003} along the way to {npc:1253}"] = "顺路去{npc:1253}的路上{npc:276003}",
	["{npc:276003} on the way"] = "顺路上的{npc:276003}",
	["{npc:276003}, around the small lake"] = "{npc:276003}，在小湖周围",
	["{npc:4256}, in the {object:32372}"] = "{npc:4256}，在{object:32372}里",
	["{npc:460}, inside {area:77}"] = "{npc:460}，在{area:77}里面",
	["{npc:5497} stands in the Wizard's Sanctum, the tower of the {object:2101}; she gives you a flask for the {quest:1861} waterfall."] = "{npc:5497}站在{object:2101}的法师圣殿塔里；她会给你一个瓶子，用于{quest:1861}的瀑布。",
	["{npc:5505} in {zone:1453}; {area:1} has no druid trainer"] = "{npc:5505}在{zone:1453}；{area:1}没有德鲁伊训练师",
	["{npc:6120}: {npc:6122} in {zone:1453} takes it"] = "{npc:6120}：交给{zone:1453}的{npc:6122}",
	["{npc:6122} waits in the cellar of the {object:2164}, in the {object:2101}."] = "{npc:6122}在{object:2101}的{object:2164}地下室等候。",
	["{npc:6806}, inside"] = "{npc:6806}，室内",
	["{npc:706} along the way to {npc:786}"] = "顺路去{npc:786}的路上{npc:706}",
	["{npc:706} on the way"] = "顺路上的{npc:706}",
	["{npc:713}, next to {npc:658}"] = "{npc:713}，在{npc:658}旁边",
	["{npc:714}'s camp is at the west end of the valley. {item:10438} lies in the snow south of it, his Chest by the troll cave and his Bucket of Bolts east of the cave: grab them as you pass."] = "{npc:714}的营地在山谷西端。{item:10438}在营地南边的雪地里，菲利克斯的箱子在巨魔洞穴旁，菲利克斯的螺钉桶在洞穴东边：路过时拿上。",
	["{npc:786} and {npc:12738} camp at the south-west edge of the valley, below the troll cave."] = "{npc:786}和{npc:12738}在山谷西南边缘、巨魔洞穴下方扎营。",
	["{npc:808} is inside the troll cave east of {npc:786}'s camp, not on the hill above it: go in at the mouth and follow the tunnel to the back."] = "{npc:808}在{npc:786}营地东边的巨魔洞穴里面，不在上方的山丘上：从洞口进去，沿隧道走到最深处。",
	["{npc:836}, inside {area:77}; below ground"] = "{npc:836}，在{area:77}内；地下",
	["{npc:837}, the priest trainer"] = "{npc:837}，牧师训练师",
	["{npc:8416}, at the door on the way out; inside"] = "{npc:8416}，在出门处的门口；室内",
	["{npc:8416}, by the door of {area:77}; inside"] = "{npc:8416}，在{area:77}门口；室内",
	["{npc:8508}, on the dock"] = "{npc:8508}，在码头上",
	["{npc:912}, the warrior trainer"] = "{npc:912}，战士训练师",
	["{npc:916}, the rogue trainer"] = "{npc:916}，潜行者训练师",
	["{npc:944}, the mage trainer, inside {area:77}"] = "{npc:944}，法师训练师，在{area:77}里面",
	["{object:660964}, by the mailbox in {object:171524}"] = "{object:660964}，在{object:171524}的邮箱旁",
	["{zone:1453} flight master"] = "{zone:1453}飞行管理员",
	["{zone:1455} class quests"] = "{zone:1455}职业任务",
}

G["forever/alliance/human/01-elwynn-forest"] = {
	["\"Auntie\" Bernice Stonefield"] = "波尼斯·斯通菲尔德姑妈",
	["Back south to the {area:120}, by the road to {zone:1436}. {npc:963} stands outside the barracks, {npc:955} beside him."] = "向南返回通往{zone:1436}的路旁的{area:120}。{npc:963}站在兵营外，{npc:955}在他旁边。",
	["Back to {area:12}"] = "返回{area:12}",
	["Back to {npc:6122}. Use the {item:6928} at the summoning circle in the {object:2164}'s cellar and defeat the voidwalker it calls."] = "回去找{npc:6122}。在{object:2164}地下室的召唤法阵处使用{item:6928}，击败召唤出的虚空行者。",
	["Billy plays in the {area:64}, east of the mine."] = "比利·马科伦在矿洞东边的{area:64}玩耍。",
	["Chunks of Boar Meat"] = "大块野猪肉",
	["Class trainer"] = "职业训练师",
	["Crystal Kelp Fronds"] = "水晶藻叶",
	["Defias Rogue Wizard"] = "迪菲亚流氓法师",
	["Defias Rogue Wizards camp on the shores of {area:86}; they drop the Red Linen Bandanas too. {object:56} lies in the murloc village on the north-east shore."] = "迪菲亚流浪巫师在{area:86}岸边扎营；它们也掉落红色亚麻面罩。{object:56}在东北岸的鱼人村里。",
	["Defias Thugs camp in the clearing east of the Abbey and along the valley's east side."] = "迪菲亚暴徒在修道院东边的空地和山谷东侧扎营。",
	["Druid trainer"] = "德鲁伊训练师",
	["Follow the hills south to the tower, on the road west."] = "沿山丘向南走到塔，就在向西的路上。",
	["Follow the hills south to the tower."] = "沿山丘向南走到塔。",
	["Follow the path north to the mine. Kobold Workers swarm outside it; every kobold in the valley can drop the {object:83763}."] = "沿小路向北到矿洞。狗头人劳工聚集在矿洞外；山谷里的每个狗头人都可能掉落{object:83763}。",
	["Follow the road east past the {area:91} to the bridge. Finish the Prowlers and Young Forest Bears around the river south of it."] = "沿路向东经过{area:91}到桥上。在桥南河边把徘徊者和幼年森林熊清完。",
	["Follow the road north from {area:87} into {zone:1453}. {npc:5497} stands in the Wizard's Sanctum, the tower of the {object:2101}; she gives you a flask for the {quest:1861} waterfall."] = "沿道路从{area:87}向北进入{zone:1453}。{npc:5497}站在{object:2101}的法师圣殿塔里；她会给你一个瓶子，用于{quest:1861}的瀑布。",
	["Follow the road north from {area:87} into {zone:1453}. {npc:6122} waits in the cellar of the {object:2164}, in the {object:2101}."] = "沿道路从{area:87}向北进入{zone:1453}。{npc:6122}在{object:2101}的{object:2164}地下室等候。",
	["Follow the road south out of the valley to {area:87}. {npc:295} is in the Lion's Pride Inn; {npc:240} stands outside the smithy across the road, {npc:253} at the inn's front and {npc:241} by the road south of it."] = "沿道路向南离开山谷到{area:87}。{npc:295}在狮王之傲旅店里；{npc:240}站在路对面的铁匠铺外，{npc:253}在旅店前，{npc:241}在旅店南边的路旁。",
	["Follow the road south out of {area:87} to the {area:64}. {npc:251} waits by the house."] = "沿道路向南离开{area:87}到{area:64}。{npc:251}在房子旁等候。",
	["Follow the road west back to {area:87}. {npc:377} (priests), {npc:328} (mages) and {npc:917} (rogues) stand upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart."] = "沿路向西回到{area:87}。{npc:377}（牧师）、{npc:328}（法师）和{npc:917}（盗贼）站在旅店楼上：从里面上楼，箭头分不清楼层。",
	["Follow the road west back to {area:87}; {npc:6306} and Jason stand on the lake shore before town. {npc:377} (priests), {npc:328} (mages) and {npc:917} (rogues) stand upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart."] = "沿路向西回到{area:87}；{npc:6306}和杰森站在进城前的湖岸上。{npc:377}（牧师）、{npc:328}（法师）和{npc:917}（盗贼）站在旅店楼上：从里面上楼，箭头分不清楼层。",
	["Follow the road west to the {area:120}, on the way into {zone:1436}. {npc:963} stands outside the barracks."] = "沿路向西前往{area:120}，这里位于通往{zone:1436}的路上。{npc:963}站在兵营外。",
	["Fun with Elementals: {npc:248464}"] = "绘本：和元素一起玩：{npc:248464}",
	["Gray Forest Wolf"] = "灰森林狼",
	["He stands by the river west of the farm."] = "他站在农场西边的河旁。",
	["Head back out through {area:87} and east along the road to the {area:62}. {npc:881} (level 9) stands by its farmhouse."] = "穿过{area:87}返回，沿路向东到{area:62}。{npc:881}（9级）站在农舍旁。",
	["If you skipped {quest:91740}, grind here to level 8.85 to stay on the route's plan."] = "如果你跳过了{quest:91740}，在这里刷到8.85级以跟上路线计划。",
	["If you skipped {quest:91752}, grind here to level 5.48 to stay on the route's plan."] = "如果你跳过了{quest:91752}，在这里刷到5.48级以跟上路线计划。",
	["If you skipped {quest:91752}, grind here to level 5.77 to stay on the route's plan."] = "如果你跳过了{quest:91752}，在这里刷到5.77级以跟上路线计划。",
	["If you skipped {quest:91775}, grind here to level 8.39 to stay on the route's plan."] = "如果你跳过了{quest:91775}，在这里刷到8.39级以跟上路线计划。",
	["Inside"] = "在里面",
	["Inside {area:34}"] = "{area:34}里面",
	["It lies by the river north-west of the logging camp."] = "它躺在伐木场西北方的河边。",
	["Kobold Geomancer"] = "狗头人地卜师",
	["Kobold Laborer"] = "狗头人劳工",
	["Kobold Laborers work the tunnels inside the mine. {npc:248362} waits down the second turn on the right."] = "狗头人苦力在矿洞里的隧道中干活。{npc:248362}在右边第二个转弯处等候。",
	["Kobold Vermin"] = "狗头人害兽",
	["Kobold Worker"] = "狗头人工人",
	["Large Candles"] = "大蜡烛",
	["Leave {zone:1453} by the main gate. The {quest:1861} waterfall is south-west of the gates, on the way west to {zone:1436}: fill {item:7207} at its base."] = "从正门离开{zone:1453}。{quest:1861}瀑布在城门西南方，就在向西前往{zone:1436}的路上：在瀑布底部装满{item:7207}。",
	["Level 5.48"] = "等级5.48",
	["Level 5.77"] = "等级5.77",
	["Level 8.39"] = "等级 8.39",
	["Level 8.85"] = "等级 8.85",
	["Lost Books: Kobold Miners and Tunnelers"] = "遗失的书本：狗头人矿工和狗头人隧道工",
	["Mages: {npc:198}, the mage trainer, stands upstairs in the Abbey: take the stairs inside, the arrow cannot tell the floors apart."] = "法师：法师训练师{npc:198}在修道院楼上：从里面的楼梯上去，箭头无法区分楼层。",
	["Murloc"] = "鱼人",
	["Murloc Streamrunner"] = "鱼人溪流行者",
	["Murlocs and Murloc Streamrunners hold the east shore; the Junk Piles lie in their camp."] = "鱼人和溪流鱼人占据着东岸；垃圾堆就在它们的营地里。",
	["North-east of the logging camp. Defias Rogue Wizards camp on the shores of the lake."] = "在伐木场东北方。迪菲亚流浪巫师在湖岸边扎营。",
	["Painted Gnoll Armbands"] = "彩色豺狼人臂章",
	["Prowler"] = "徘徊者",
	["Red Burlap Bandanas"] = "红色粗麻面罩",
	["Red Linen Bandanas"] = "红色亚麻面罩",
	["Riverpaw Runts and Outrunners hold the hills south of the garrison, along the {zone:1436} border."] = "矮小的河爪豺狼人和河爪豺狼人前锋占据着要塞南边、{zone:1436}边境沿线的山丘。",
	["Riverpaw gnolls camp in the hills west of {area:86}; the {quest:91725} lie in their camps."] = "河爪豺狼人在{area:86}西边的山丘上扎营；{quest:91725}在它们的营地里。",
	["Rockhide Boar"] = "石皮野猪",
	["Shaman trainer"] = "萨满祭司训练师",
	["She stands by her cart at the vineyard east of the Abbey."] = "她站在修道院东边葡萄园的推车旁。",
	["She stands outside the mine entrance. {npc:248362}, inside, is elite: grouping up is advised."] = "她站在矿洞入口外。里面的{npc:248362}是精英：建议组队。",
	["Shiny Red Apples, from {npc:894}, for the {quest:91736}"] = "新鲜的红苹果，来自{npc:894}，用于{quest:91736}",
	["Sit (/sit) by his campfire until you have {spell:1229451}"] = "在他的营火旁坐下（/sit），直到获得{spell:1229451}",
	["South down the road to the {area:64}."] = "沿道路向南到{area:64}。",
	["Subdue the voidwalker"] = "制服虚空行者",
	["Tame {npc:1922}"] = "驯服{npc:1922}",
	["Tame {npc:524}"] = "驯服{npc:524}",
	["Tame {npc:822}"] = "驯服{npc:822}",
	["The Defias camp"] = "迪菲亚营地",
	["The Fishing Traps sit along the west shore of the lake."] = "Fishing Net分布在湖的西岸。",
	["The Stonefield farm is west of the mine. Ma and \"Auntie\" Bernice stand by the house.\nShe sits inside the farmhouse."] = "斯通菲尔德农场在矿洞西边。斯通菲尔德妈妈和波尼斯·斯通菲尔德姑妈站在房子旁。\n她坐在农舍里。",
	["The bridge"] = "桥",
	["The camp is north-east of the bridge. Bundles of Wood lie around the camp and in the woods north of it."] = "营地在桥的东北方。一捆木柴散落在营地周围和北边的树林里。",
	["The crates of grapes lie in the vineyards behind the Defias. {npc:103} waits by the cabin at the east end of the valley."] = "装葡萄的箱子在迪菲亚身后的葡萄园里。{npc:103}在山谷东端的小屋旁等候。",
	["The gnoll camps"] = "豺狼人营地",
	["The kobold camp"] = "狗头人营地",
	["The lake shore"] = "湖岸",
	["The mine is south-west of the gnoll camps. {item:247816} lie near the entrance; Kobold Geomancers hold the tunnels."] = "矿洞在豺狼人营地西南方。{item:247816}在入口附近；狗头人地卜师占据着隧道。",
	["The mine is west of the vineyards. Kobold Miners and Tunnelers fill both levels; {npc:248464}, a named kobold, holds the picture book in the lower tunnels. {npc:248464} is elite: grouping up is advised."] = "矿洞在葡萄园西边。狗头人矿工和狗头人隧道工遍布两层；名为{npc:248464}的狗头人在下层隧道里拿着绘本。{npc:248464}是精英：建议组队。",
	["The murlocs on the east shore drop the kelp. Skinners: Gray Forest Wolves roam the woods between the lake and the {area:91}; Prowlers further east give pelts too."] = "东岸的鱼人掉落海草。剥皮者：森林灰狼在湖和{area:91}之间的树林里游荡；更东边的觅食的灰狼也能剥出毛皮。",
	["The vineyards and {npc:103}"] = "葡萄园和{npc:103}",
	["The {area:88}"] = "{area:88}",
	["The {area:91}"] = "{area:91}",
	["The {item:247813}, Axe and Toolbox lie in the river south of the bridge. {npc:330}, a big boar, roots in the {area:62} west of the river with her {npc:390}: pull the piglets away first. Kill Prowlers and Young Forest Bears on the way. Careful: {npc:248278} is a level 11 elite on the murloc shore. Only go for his head with a group or once you're level 10; otherwise leave him: it's optional."] = "{item:247813}、斧子和工具箱在桥南的河里。{npc:330}，一只大野猪，带着她的{npc:390}在河以西的{area:62}拱食：先把小猪引开。路上杀徘徊者和幼年森林熊。小心：{npc:248278}是鱼人海岸上的11级精英。只在组队或达到10级后再去取他的头；否则别管他：这是可选内容。",
	["The {quest:91736}"] = "{quest:91736}",
	["The {quest:91736} stands north of the {area:120}. Click it with four Shiny Red Apples in your bags: it takes them and gives you a {item:247824} on the spot (the quest never shows in your quest log). Keep the Applejack for {npc:955}: don't drink it."] = "{quest:91736}立在{area:120}以北。带着四个闪光红苹果点击它：它会收下苹果，并当场交给你一个{item:247824}（该任务不会出现在任务日志中）。把苹果酒留给{npc:955}：不要喝掉。",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:248362} (level 3 elite) needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "这些是精英怪：建议组队，找人一起做。{npc:248362}（3级精英）需要2人小队。如果你独自一人就跳过：路线会让你把经验值刷回来。",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:248464} (level 6 elite) needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "这些是精英怪：建议组队，找人一起做。{npc:248464}（6级精英）需要2人小队。如果你独自一人就跳过：路线会让你把经验刷回来。",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {quest:91740} needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "这些是精英怪：建议组队，找人一起做。{quest:91740}需要2人小队。如果你独自一人就跳过：路线会让你把经验刷回来。",
	["Walk into the mine"] = "走进矿洞",
	["Walk through the mine"] = "走过矿洞",
	["While you're here: learn Staves from {npc:11867} ({object:2096}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "顺便：向{npc:11867}（{object:2096}，10银币）学习法杖；升级期间，法杖提供的法术属性比单手武器多。",
	["Wolves"] = "狼",
	["You start in front of the Abbey. {npc:823} stands at the foot of the steps, {npc:197} inside the hall, {npc:951} and {npc:247229} in the library to the right, {npc:196} outside the north-west corner."] = "你从修道院前方出发。{npc:823}站在台阶下，{npc:197}在大厅里，{npc:951}和{npc:247229}在右边的图书馆，{npc:196}在西北角外面。",
	["Young Forest Bear"] = "幼年森林熊",
	["Young Wolves and Timber Wolves roam the fields right around the Abbey."] = "幼狼和森林狼就在修道院周围的田野里游荡。",
	["grind on {npc:118}"] = "刷{npc:118}",
	["grind on {npc:40}"] = "刷{npc:40}",
	["grind on {npc:80}"] = "刷{npc:80}",
	["his kobold tracker shows the kobolds to click on the road to {area:87}"] = "他的狗头人追踪器会显示前往{area:87}路上可点击的狗头人",
	["{area:12}: kill these as you meet them"] = "{area:12}：遇到就杀",
	["{area:18}: kill these as you meet them"] = "{area:18}：遇到就杀",
	["{area:34}: kill these as you meet them"] = "{area:34}：遇到就杀",
	["{area:54}: kill these as you meet them"] = "{area:54}：遇到就杀",
	["{area:64}: kill these as you meet them"] = "{area:64}：遇到就杀",
	["{item:247824}, from the still"] = "{item:247824}，来自蒸馏器",
	["{item:286214} on the way"] = "顺路拿{item:286214}",
	["{item:286215}: Stonetusk Boars"] = "{item:286215}：石牙野猪",
	["{item:6785}: the {object:83763} in the Defias camp"] = "{item:6785}：迪菲亚营地里的{object:83763}",
	["{item:981}; below ground"] = "{item:981}；在地下",
	["{npc:118} on the way"] = "路上有{npc:118}",
	["{npc:1430} cooks in the inn's kitchen. {npc:377} (priests), {npc:328} (mages) and {npc:917} (rogues) stand upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart."] = "{npc:1430}在旅店厨房里做饭。{npc:377}（牧师）、{npc:328}（法师）和{npc:917}（潜行者）在旅店楼上：走室内楼梯上去，箭头无法区分楼层。",
	["{npc:1430}: Camping 101 asks you to learn it; below ground"] = "{npc:1430}：野营入门要求你学会它；在地下",
	["{npc:1922}: tame it with the {item:15908}"] = "{npc:1922}：用{item:15908}驯服它",
	["{npc:197}, inside"] = "{npc:197}，在里面",
	["{npc:198}, the mage trainer, inside the Abbey"] = "{npc:198}，法师训练师，在修道院里",
	["{npc:240}, while William brews"] = "{npc:240}，趁威廉酿酒时",
	["{npc:247229}, in the library; inside"] = "{npc:247229}，在图书馆里；在里面",
	["{npc:248242} and {npc:248248} stand at the foot of the tower."] = "{npc:248242}和{npc:248248}站在塔脚下。",
	["{npc:248415} stands behind the Abbey, by the stables. {npc:198}, the mage trainer, stands upstairs in the Abbey: take the stairs inside, the arrow cannot tell the floors apart."] = "{npc:248415}站在修道院后面的马厩旁。法师训练师{npc:198}在修道院楼上：从里面的楼梯上去，箭头无法区分楼层。",
	["{npc:248415}, by the Abbey"] = "{npc:248415}，在修道院旁",
	["{npc:251507} stands with the {area:87} trainers. Each of her quests hands you a {item:15908}: use it on the beast she names, then bring the rod back to her. Rockhide Boars and Young Forest Bears roam the hills south of the {area:64}, Gray Forest Wolves the woods east of {area:18}."] = "{npc:251507}和{area:87}的训练师站在一起。她的每个任务都会给你一根{item:15908}：对她指定的野兽使用，然后把驯兽棒带回给她。石皮野猪和森林熊幼崽在{area:64}南边的山丘上游荡，森林灰狼在{area:18}东边的树林里。",
	["{npc:253}, inside"] = "{npc:253}，在里面",
	["{npc:257446} in {zone:1426}; {area:87} has no shaman trainer"] = "{npc:257446}在{zone:1426}；{area:87}没有萨满祭司训练师",
	["{npc:258930}, beside her: {spell:5149}"] = "{npc:258930}，在她旁边：{spell:5149}",
	["{npc:261} guards the bridge on the road east; {npc:248265} stands just across it."] = "{npc:261}守卫着向东道路上的桥；{npc:248265}就站在桥对面。",
	["{npc:263399} camps north-east of the inn; {npc:6306}, {npc:383} and {npc:1651} stand on the shore of {area:18} east of town."] = "{npc:263399}在旅店东北方扎营；{npc:6306}、{npc:383}和{npc:1651}站在镇子东边的{area:18}岸边。",
	["{npc:278}, inside"] = "{npc:278}，在里面",
	["{npc:279} in {zone:1453} takes it (02-westfall)"] = "交给{zone:1453}的{npc:279}（02-westfall）",
	["{npc:295}, inside"] = "{npc:295}，在里面",
	["{npc:328}: {npc:5497} in {zone:1453} takes it"] = "{npc:328}：交给{zone:1453}的{npc:5497}",
	["{npc:375}, the priest trainer"] = "{npc:375}，牧师训练师",
	["{npc:377} (priests), {npc:328} (mages) and {npc:917} (rogues) stand upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart."] = "{npc:377}（牧师）、{npc:328}（法师）和{npc:917}（潜行者）在旅店楼上：走室内楼梯上去，箭头无法区分楼层。",
	["{npc:377}: {npc:376} in {zone:1453} takes it"] = "{npc:377}：交给{zone:1453}的{npc:376}",
	["{npc:459}, outside the Abbey"] = "{npc:459}，在修道院外",
	["{npc:476} walks around {area:54}: look inside the circle on the map"] = "{npc:476}在{area:54}一带走动：看地图上的圆圈内部",
	["{npc:524}: tame it with the {item:15908}"] = "{npc:524}：用{item:15908}驯服它",
	["{npc:5504} in {zone:1453}; {area:87} has no druid trainer"] = "{npc:5504}在{zone:1453}；{area:87}没有德鲁伊训练师",
	["{npc:6121}: {npc:6122} in {zone:1453} takes it"] = "{npc:6121}：交给{zone:1453}的{npc:6122}",
	["{npc:6306}, inside"] = "{npc:6306}，在里面",
	["{npc:6306}: skinners only, the pelts are skinned; inside"] = "{npc:6306}：仅限剥皮者，毛皮需剥皮获得；在里面",
	["{npc:6774}, by the stables south of the Abbey"] = "{npc:6774}，在修道院南边的马厩旁",
	["{npc:6} dig in the vineyards north-east of the Abbey. Now and then one drops a {quest:91741}: right-click it."] = "{npc:6}在修道院东北方的葡萄园里挖掘。偶尔会有一只掉落{quest:91741}：右键点击它。",
	["{npc:80} walks around {area:34}: look inside the circle on the map"] = "{npc:80}在{area:34}一带走动：看地图上的圆圈内部",
	["{npc:822}: tame it with the {item:15908}"] = "{npc:822}：用{item:15908}驯服它",
	["{npc:823}, at the Abbey steps"] = "{npc:823}，在修道院台阶处",
	["{npc:823}, back at the Abbey steps"] = "{npc:823}，回到修道院台阶处",
	["{npc:894} sells the Shiny Red Apples for the {quest:91736}. Apples looted from kobolds and crates count too: the purchase ticks itself once you have four."] = "{npc:894}出售{quest:91736}所需的闪光的红苹果。从狗头人和箱子拾取的苹果也算：凑够四个后，购买目标会自动完成。",
	["{npc:911}, the warrior trainer; inside"] = "{npc:911}，战士训练师；在里面",
	["{npc:915}, the rogue trainer"] = "{npc:915}，潜行者训练师",
	["{npc:925}, the paladin trainer"] = "{npc:925}，圣骑士训练师",
	["{npc:952}, upstairs"] = "{npc:952}，在楼上",
	["{npc:955} stands inside the barracks. He has {quest:91738} only while you carry the {item:247824}: talk to him and it goes straight to the hand-in."] = "{npc:955}站在兵营里面。只有你带着{item:247824}时他才会给{quest:91738}：和他交谈后就直接进入交付环节。",
	["{npc:955}: he wants your {item:247824}; inside"] = "{npc:955}：他要你的{item:247824}；在里面",
	["{npc:963}: for {npc:234} at {area:108}"] = "{npc:963}：给{area:108}的{npc:234}",
	["{object:694855} grows in the fields around the vineyards and the Stonefield farm; Stonetusk Boars around them give the blood.\nStonetusk Boars graze between the vineyards and the farm."] = "{object:694855}生长在葡萄园和斯通菲尔德农场周围的田野里；周围的石牙野猪提供血液。\n石牙野猪在葡萄园和农场之间吃草。",
	["{quest:76}'s entrance"] = "{quest:76}的入口",
	["{quest:87} is inside the {area:57}, not on the hill above it: go in at the mouth and keep left to the back of the mine floor; don't take the stairs up. Defias Bandits around the vineyards drop a {item:1972} now and then: right-click it."] = "{quest:87}在{area:57}里面，不在上方的山丘上：从入口进去，一直靠左走到矿洞底层的最深处；不要上楼梯。葡萄园周围的迪菲亚强盗偶尔会掉落{item:1972}：右键点击它。",
	["{quest:91733} and {npc:330}"] = "{quest:91733}和{npc:330}",
}

G["forever/alliance/nightelf/01-teldrassil"] = {
	["/sit by {npc:265811}'s campfire until you get {spell:1229451}"] = "在{npc:265811}的营火旁坐下（/sit），直到获得{spell:1229451}",
	["Back at {area:256}"] = "回到{area:256}",
	["Back out of the city gate and east along the road: {quest:1683} stands south of it, by {area:736}. Bring his horn back to {quest:1684}."] = "出城门后沿路向东：{quest:1683}站在路南、{area:736}旁。把他的号角带回去交给{quest:1684}。",
	["Back to the moonwell."] = "回到月亮井。",
	["Back to the top of {area:256}. The {object:654846} lies beside him."] = "回到{area:256}顶端。{object:654846}就在他旁边。",
	["Below ground"] = "地下",
	["Bloodfeather harpies"] = "血羽鹰身人",
	["Boat to {zone:1453}"] = "乘船前往{zone:1453}",
	["Cast {spell:18960}. {npc:11802} is in {area:2361}; the {quest:5929} sits in the woods to the north-west. Then {npc:11800} in {area:2361} flies Druids straight to {area:702}, no flight path needed. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "施放{spell:18960}。{npc:11802}在{area:2361}；{quest:5929}位于西北的树林里。然后{area:2361}的{npc:11800}会把德鲁伊直接送到{area:702}，无需飞行路线。{npc:11802}站在他那栋楼的楼上：从里面上楼，箭头分不清楼层。",
	["Each of Dazalar's quests hands you a {item:15908}: use it on the beast he names, then bring the rod back to him in {area:186}. Webwood Lurkers creep around the village, Nightsaber Stalkers and Strigid Screechers roam the woods south of it."] = "达扎拉的每个任务都会给你一根{item:15908}：对他指定的野兽使用，然后把驯兽棒带回{area:186}交给他。树林潜伏者在村子周围爬行，夜刃捕食者和巨翼恶枭在村子南边的树林里游荡。",
	["Escort {npc:275744} out of the barrow; {npc:2081} in {area:186} takes the report."] = "护送{npc:275744}离开兽穴；{area:186}的{npc:2081}接收报告。",
	["Fandral in {zone:1457} takes it"] = "交给{zone:1457}的范达尔",
	["Fel Cones lie under the trees all around {area:186} and {npc:2150}: pick them up on the road east and hand them to {npc:2150} on the way to {npc:7234}."] = "魔锥草散布在{area:186}和{npc:2150}周围的所有树下：向东的路上顺手采集，前往{npc:7234}时交给{npc:2150}。",
	["Fly back to {area:702} from {npc:3841}, hand {item:16263} to {npc:10118} on the dock, then fly back to {area:442} for the boat."] = "从{npc:3841}处飞回{area:702}，把{item:16263}交给码头上的{npc:10118}，然后飞回{area:442}乘船。",
	["Fly to {area:702} once more and take the portal up to {npc:4217}, then fly back to {area:442} for the boat."] = "再次飞往{area:702}，乘传送门上去找{npc:4217}，然后飞回{area:442}乘船。",
	["Follow the road south-west out of {area:188}. {npc:2150} sits beside it just east of {area:186}."] = "沿道路向西南离开{area:188}。{npc:2150}就坐在路旁，在{area:186}东边不远处。",
	["Follow the road west into {zone:1457}. {npc:4241} stands on the {area:1659} just inside the city. {npc:3516} is in the {area:1658} at the north end of the city, {quest:922} just south of it; {npc:4092} and {npc:7999} are in the Temple of the Moon at the south end. {npc:7316} is in the west of the city, on the way to the pink portal down to Rut'theran."] = "沿道路向西进入{zone:1457}。{npc:4241}站在一进城的{area:1659}上。{npc:3516}在城市北端的{area:1658}，{quest:922}就在其南边；{npc:4092}和{npc:7999}在南端的月神殿。{npc:7316}在城市西部，在通往鲁瑟兰村的粉色传送门的路上。",
	["From {area:17203}, head through the city gates into {zone:1429} and follow the road west to {zone:1436}."] = "从{area:17203}出发，穿过城门进入{zone:1429}，沿路向西到{zone:1436}。",
	["Gnarlpine Ambusher"] = "瘤背伏击者",
	["Gnarlpine Ambushers hide along the road west of {area:258}."] = "瘤背伏击者埋伏在{area:258}西边的道路沿途。",
	["Gnarlpine Mystic"] = "瘤背秘法师",
	["Gnarlpine Mystics and {npc:7234} camp north-east of {area:260}. {npc:7234} drops the {item:8049}: open it for the jewel.\nCareful: {npc:7234} waits near the camp fire with mystics around him, so pulling him without adds is hard."] = "瘤背秘法师和{npc:7234}在{area:260}东北扎营。{npc:7234}掉落{item:8049}：打开取宝石。\n注意：{npc:7234}在营火旁等候，身边围着秘法师，所以很难在不引到增援的情况下拉他。",
	["Gnarlpine Shamans"] = "瘤背萨满祭司",
	["Go back down to {area:702} and fly to {area:442}. The {object:177525} stands in the hills just east of the village: use the {item:15208} there, defeat Lunaclaw and speak to the {npc:12144}."] = "回到{area:702}，飞往{area:442}。{object:177525}立在村子东边的山丘上：在那里使用{item:15208}，击败月爪枭兽，然后与{npc:12144}交谈。",
	["Grells"] = "小劣魔",
	["Into {zone:1457}"] = "进入{zone:1457}",
	["Learn the flight path from {npc:3841} where you land. {npc:4200}'s fish stall is just north of her, by the docks.\nThe boat docks west of the village. The flight master stands on the hill south of the inn; the quest givers are spread along the main street."] = "降落后先找{npc:3841}学习飞行路线。{npc:4200}的鱼摊就在她北边、码头旁。\n船停在村子西边。飞行管理员站在旅店南边的山丘上；任务发布者分散在主街上。",
	["Leave {area:188} by the path south-east of {area:256}: {npc:6780} stands beside it, where it goes down towards the road to {area:186}."] = "从{area:256}东南方的小路离开{area:188}：{npc:6780}站在路旁，在小路下坡通往{area:186}道路的地方。",
	["Mangy Nightsaber"] = "癞皮夜刃豹",
	["Mangy Nightsabers and Thistle Boars roam north of {area:256}, on the way to the cave. {npc:1994} sits deep inside."] = "癞皮夜刃豹和蓟野猪在{area:256}以北游荡，就在去洞穴的路上。{npc:1994}坐在洞穴深处。",
	["Nightsaber Stalker"] = "夜刃豹潜行者",
	["Nightsabers"] = "夜刃豹",
	["Nightsabers, Strigid Owls and Webwood Lurkers roam all around {area:186} and along the road east; the lurkers also drop the recipe's spider legs. The moonwell is at the west edge of {area:260}."] = "夜刃豹、夜枭和蛛网潜伏者遍布{area:186}周围以及东边的路上；潜伏者还会掉落配方所需的蜘蛛腿。月亮井在{area:260}的西缘。",
	["North from the lake to {npc:2150}, on the road back to {area:186}."] = "从湖边向北到{npc:2150}，就在回{area:186}的路上。",
	["North to {area:257}"] = "向北前往{area:257}",
	["North-east from Ursal's den, back to {area:186}."] = "从乌萨尔的巢穴向东北返回{area:186}。",
	["Portal to {quest:940}"] = "通往{quest:940}的传送门",
	["Rageclaw"] = "怒爪",
	["Sentinel Arynia again"] = "再次找哨兵阿瑞尼亚",
	["South of the pools. The {object:6751} grows by the Hold."] = "在水池南边。{object:6751}长在脊骨堡旁。",
	["South-east of Dolanaar, to {npc:2080}. Lasher Sproutlings wander around him on the shore."] = "前往多兰纳尔东南方的{npc:2080}处。鞭笞幼芽在湖岸上围着他游荡。",
	["South-west of Starbreeze, south of {npc:2150}. {npc:2080} tends his saplings on the shore; Lasher Sproutlings and Timberlings wander around him, and the {quest:919} grow among them."] = "在星风村西南、{npc:2150}以南。{npc:2080}在岸边照料他的树苗；鞭笞幼芽和小树人围着他游荡，{quest:919}就长在它们中间。",
	["South-west of the barrow. The moonwell sits by the pools."] = "在兽穴西南方。月亮井就在水池旁。",
	["Speak with the {quest:5929}"] = "与{quest:5929}交谈",
	["Strigid Screecher"] = "夜枭尖啸者",
	["Take the boat to {zone:1453} from {area:442}'s docks."] = "从{area:442}码头乘船前往{zone:1453}。",
	["Take the portal down to {area:702}. {npc:10118} stands on the dock, {npc:3838} by the hippogryphs. Once you have {quest:6342}, talk to {npc:3838} again and choose the flight to {area:442}: it is free and lands beside {npc:4200}. If the flight map opens instead, close it and talk to him again holding Shift."] = "通过传送门下到{area:702}。{npc:10118}站在码头上，{npc:3838}在角鹰兽旁。接到{quest:6342}后，再次与{npc:3838}交谈，选择飞往{area:442}：这趟免费，落地就在{npc:4200}旁边。如果打开的是飞行地图，先关闭，再按住 Shift 与他交谈。",
	["Take the road north-west from {area:186} again; she still lies beside it, on the way to {zone:1457}."] = "再次从{area:186}沿道路向西北走；她仍躺在路旁，在去{zone:1457}的路上。",
	["The Bloodfeather harpies nest on the slopes west and north of the glade.\nCareful: The harpies stand packed together, so extra ones often join a fight. Casters are mixed in among them."] = "血羽鹰身人在林间空地以西和以北的山坡筑巢。\n注意：鹰身人站得很密集，所以常会有额外的加入战斗。施法者混在它们中间。",
	["The WANTED poster outside the inn"] = "旅店外的通缉布告",
	["The barrow is south of the road. {npc:275744} is held inside, {npc:7317} sleeps in its depths, and the four relic chests sit in the lower rooms."] = "兽穴在道路南边。{npc:275744}被关在里面，{npc:7317}在深处沉睡，四个圣物箱在下层房间里。",
	["The moonwell and {npc:8584}"] = "月亮井和{npc:8584}",
	["The moonwell is in the middle of the glade. The {object:6752} grows at its north end."] = "月亮井在林地中央。{object:6752}长在林地北端。",
	["The moonwell sits north of {area:256}."] = "月亮井位于{area:256}以北。",
	["The named harpies"] = "有名字的鹰身人",
	["The road to {zone:1457}"] = "通往{zone:1457}的路",
	["The trainers stand upstairs inside {area:256}, along the ramp that winds up the tree: {npc:3593} and {npc:3594} on the first level, {npc:3595} above them, {npc:3596} and {npc:3597} at the top. The arrow cannot tell the levels apart."] = "训练师们站在{area:256}内的楼上，沿绕着树干盘旋而上的坡道分布：{npc:3593}和{npc:3594}在第一层，{npc:3595}在他们上方，{npc:3596}和{npc:3597}在顶层。箭头分不清楼层。",
	["The {area:478}"] = "{area:478}",
	["The {object:177525}"] = "{object:177525}",
	["The {object:4406} lie at the back of {area:257}: take the central path, then left where it splits, up to the high ledge. Hyacinth Mushrooms drop from Grells, Moonpetal Lilies grow by the ponds north of {area:256}."] = "{object:4406}在{area:257}深处：走中间的路，分岔处向左，一直上到高处的岩架。紫蓝色蘑菇由小劣魔掉落，月牙百合花长在{area:256}北边的池塘旁。",
	["Thistle Boar"] = "蓟野猪",
	["Tide Crawlers scuttle along the shore below the village; {object:17182} stands on the beach just south of the docks. Darkshore Threshers swim in the shallows. The {object:175207} lies on the shore just south of the village."] = "潮汐爬行者沿着村子下方的海岸爬行；{object:17182}立在码头正南的海滩上。黑海岸长尾鲨在浅水中游动。{object:175207}躺在村子正南的海岸上。",
	["Upstairs"] = "楼上",
	["Ursal the Mauler"] = "重击者乌尔萨",
	["Use the {item:18152} at the moonwell"] = "在月亮井旁使用{item:18152}",
	["Use the {item:5185} at the moonwell"] = "在月亮井使用{item:5185}",
	["Use the {item:5619} at the moonwell"] = "在月亮井使用{item:5619}",
	["Use the {item:5621} at the moonwell"] = "在月亮井使用{item:5621}",
	["Walk Lynessa out and keep her alive"] = "带Lynessa走出去，保证她存活",
	["Walk south along the west side of the island. Ursal prowls the far south, below the {area:478}.\nCareful: Gnarlpine of roughly level 9-12 crowd the camp and sit close together, so it is easy to pull several at once. Take them on singly before you engage Ursal."] = "沿岛屿西侧向南走。乌尔萨在遥远的南方、{area:478}下方徘徊。\n注意：约9-12级的瘤背熊怪挤在营地里，站位很密，很容易一次拉到好几只。先一只只解决它们，再去对付乌尔萨。",
	["Webwood Lurker"] = "蛛网潜伏者",
	["Webwood Lurkers"] = "树林潜伏者",
	["Webwood Spiders; below ground"] = "蛛网蜘蛛；地下",
	["While you're here: learn Staves from {npc:11866} ({area:1660}, 10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "顺路：向{npc:11866}（{area:1660}，10银）学习法杖；猎人的近战武器主要看属性，双手武器提供的属性最多。",
	["While you're here: learn Staves from {npc:11866} ({area:1660}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "顺路：向{npc:11866}（{area:1660}，10银）学习法杖；升级期间法杖提供的法术属性比单手武器多。",
	["You start at the foot of {area:256}, the great tree of {area:188}."] = "你从{area:188}的巨树{area:256}脚下开始。",
	["Young Nightsaber"] = "年幼的夜刃豹",
	["Young Nightsabers and Young Thistle Boars roam around {area:256}. Grells carry {item:3297} in the woods west of the tree, where the Gnarlpine Totems stand."] = "夜刃豹幼崽和草刺野猪幼崽在{area:256}周围游荡。小劣魔在巨树西边的树林里携带{item:3297}，瘤背图腾就立在那里。",
	["Young Thistle Boar"] = "年幼的蓟野猪",
	["talk to {npc:3838} again: free with {quest:6342}"] = "再次与{npc:3838}交谈：持有{quest:6342}时免费",
	["the same {object:673378}: Fandral in {zone:1457} takes it"] = "同一个{object:673378}：{zone:1457}的范达尔会收下它",
	["{area:186} again"] = "再次回到{area:186}",
	["{area:188}: kill these as you meet them"] = "{area:188}：遇到就杀",
	["{area:258}'s mouth"] = "{area:258}的洞口",
	["{area:736}, outside the barrow"] = "{area:736}，在兽穴外",
	["{item:10639} along the way to {area:256}"] = "{item:10639}，在去{area:256}的路上",
	["{item:10639} on the way"] = "{item:10639}，途中",
	["{item:159} from {npc:6736}, for {npc:6094}"] = "从{npc:6736}处获得{item:159}，交给{npc:6094}",
	["{item:3371} from {npc:3614}, beside {npc:6094}"] = "从{npc:6094}旁边的{npc:3614}处获得{item:3371}",
	["{item:8049}, from {npc:7234}"] = "{item:8049}，来自{npc:7234}",
	["{npc:10118} stands on the Rut'theran dock where you land. Then take the portal up to {npc:4217} in the {area:1658}."] = "落地后，{npc:10118}就在鲁瑟兰村码头上。随后通过传送门上去，到{area:1658}找{npc:4217}。",
	["{npc:10216}, on the pier"] = "{npc:10216}，在码头上",
	["{npc:10216}, on the pier: only with {skill:356}"] = "{npc:10216}，在码头上：需要{skill:356}",
	["{npc:11401}, in the Temple of the Moon: Starshards"] = "{npc:11401}，在月神殿：星辰碎片",
	["{npc:1984} along the way to Back at {area:256}"] = "{npc:1984}，在回{area:256}的路上",
	["{npc:1984} on the way"] = "{npc:1984}，途中",
	["{npc:1992}, south of the tree"] = "{npc:1992}，在巨树南边",
	["{npc:1996}: tame it with the {item:15908}"] = "{npc:1996}：用{item:15908}驯服它",
	["{npc:1998}: tame it with the {item:15908}"] = "{npc:1998}：用{item:15908}驯服它",
	["{npc:2038} waits inside the cave, at the bottom or up on the ledge; keep to the right."] = "{npc:2038}在洞内等候，在底部或上方的岩架上；靠右走。",
	["{npc:2038}; below ground"] = "{npc:2038}；地下",
	["{npc:2043}: tame it with the {item:15908}"] = "{npc:2043}：用{item:15908}驯服它",
	["{npc:2077}, by the path"] = "{npc:2077}，在小路旁",
	["{npc:2079}: a sigil for {npc:3596}"] = "{npc:2079}：给{npc:3596}的印记",
	["{npc:2080}: {quest:922} in {zone:1457} takes it"] = "{npc:2080}：交给{zone:1457}的{quest:922}",
	["{npc:2082}, on the tree's ramp"] = "{npc:2082}，在巨树的坡道上",
	["{npc:2107} stands upstairs in a house in the village, east of the moonwell: go up inside, the arrow cannot tell the floors apart. {object:126158} is in the house on the hill at the east end of the village."] = "{npc:2107}在村里月亮井东边一座房子的楼上：从里面上楼，箭头无法区分楼层。{object:126158}在村子东端山丘上的房子里。",
	["{npc:2151} patrols the road west of the village: if she isn't at the arrow, follow the road until you meet her."] = "{npc:2151}在村子西边的道路上巡逻：如果她不在箭头处，沿着道路走直到遇见她。",
	["{npc:2151}, on the road west of the village"] = "{npc:2151}，在村子西边的路上",
	["{npc:265811}, by the campfire"] = "{npc:265811}，在篝火旁",
	["{npc:272034} and {npc:272044} fly just west of the moonwell, {npc:272046} further north."] = "{npc:272034}和{npc:272044}在月亮井西边不远处飞行，{npc:272046}在更北边。",
	["{npc:3514}, at the top of the tree"] = "{npc:3514}，在巨树顶端",
	["{npc:3515}, south of the inn"] = "{npc:3515}，在旅店南边",
	["{npc:3516}, in the {area:1658}"] = "{npc:3516}，在{area:1658}",
	["{npc:3519}, by the moonwell"] = "{npc:3519}，在月亮井旁",
	["{npc:3567}, back in {area:186}; upstairs"] = "{npc:3567}，回到{area:186}；楼上",
	["{npc:3567}, upstairs"] = "{npc:3567}，楼上",
	["{npc:3593}, the warrior trainer; inside"] = "{npc:3593}，战士训练师；室内",
	["{npc:3594}, the rogue trainer"] = "{npc:3594}，潜行者训练师",
	["{npc:3595}, the priest trainer: in at the tree's front entrance and up the ramp"] = "{npc:3595}是牧师训练师：从树的正面入口进去，沿斜坡上楼",
	["{npc:3595}: in at the tree's front entrance and up the ramp; upstairs"] = "{npc:3595}：从树的前门进入，沿坡道上行；楼上",
	["{npc:3596}, the hunter trainer"] = "{npc:3596}，猎人训练师",
	["{npc:3597}, the druid trainer at {area:256}"] = "{npc:3597}，{area:256}的德鲁伊训练师",
	["{npc:3598}, the warrior trainer: {quest:1684} in {zone:1457} takes it"] = "{npc:3598}，战士训练师：{zone:1457}的{quest:1684}会收下它",
	["{npc:3600}, inside"] = "{npc:3600}，室内",
	["{npc:3600}: {npc:11401} in {zone:1457} takes it"] = "{npc:3600}：交给{zone:1457}的{npc:11401}",
	["{npc:3602}: {npc:4217} in {zone:1457} takes it"] = "{npc:3602}：交给{zone:1457}的{npc:4217}",
	["{npc:3608}, upstairs"] = "{npc:3608}，楼上",
	["{npc:3649}, north end of the village"] = "{npc:3649}，在村子北端",
	["{npc:4088}, on the {area:1660}: {spell:71}"] = "{npc:4088}，在{area:1660}上：{spell:71}",
	["{npc:4092}, in the Temple of the Moon"] = "{npc:4092}，在月神殿",
	["{npc:4146} in {zone:1457} takes it"] = "交给{zone:1457}的{npc:4146}",
	["{npc:4146}, in the {area:1658}: {spell:5149}"] = "{npc:4146}，在{area:1658}内：{spell:5149}",
	["{npc:4217}, in the {area:1658}"] = "{npc:4217}，在{area:1658}",
	["{npc:6094} takes a {item:159} with the fronds and the vial: if you drank yours, buy another from {npc:6736} in this inn before you hand in."] = "{npc:6094}要一份{item:159}，连同叶子和药瓶一起：如果你已经喝掉了自己的，就在交任务前到这间旅店找{npc:6736}再买一份。",
	["{npc:6094}, inside"] = "{npc:6094}，室内",
	["{npc:6286}, south of the inn: Camping 101 asks you to learn it"] = "{npc:6286}，旅店以南：《露营入门》要求你学会它",
	["{npc:7317}, below ground"] = "{npc:7317}，地下",
	["{npc:7318}, in the den; walks around {area:736}: look inside the circle on the map"] = "{npc:7318}，在洞穴里；在{area:736}一带走动：看地图上的圆圈内",
	["{npc:7999}, above {npc:4092}"] = "{npc:7999}，在{npc:4092}上方",
	["{npc:8583}, east of the tree"] = "{npc:8583}，在巨树东边",
	["{npc:8584} is a little further north-west. {quest:3522} lasts five minutes: fill the phial and go straight on to him."] = "{npc:8584}再往西北一点。{quest:3522}持续五分钟：装满小瓶后直接去找他。",
	["{npc:8584} waits in the trees west of the cave mouth."] = "{npc:8584}在洞口以西的树林里等候。",
	["{object:126158}; inside"] = "{object:126158}；室内",
	["{object:654846}, upstairs"] = "{object:654846}，楼上",
	["{object:673378}, just west of the moonwell"] = "{object:673378}，在月亮井西边不远处",
	["{object:7510}, beside him"] = "{object:7510}，在他旁边",
	["{quest:1684} stands on the {area:1660}, just inside the city."] = "{quest:1684}站在{area:1660}上，就在城内。",
	["{quest:917} and the antidote"] = "{quest:917}和解药",
	["{quest:940}: kill these as you meet them"] = "{quest:940}：遇到就杀",
	["{quest:97236}; below ground"] = "{quest:97236}；地下",
	["{quest:97979}: cast {spell:1259799} and Shadowmeld, then hand it back to {npc:3595}"] = "{quest:97979}：施放{spell:1259799}并影遁，然后把它交还给{npc:3595}",
}

G["forever/alliance/nightelf/02-darkshore"] = {
	["Back north-east into the mountains to the crystal."] = "向东北回到山里的水晶处。",
	["Bears and the Blackwood camp"] = "熊和黑木营地",
	["Blackwood Pathfinder"] = "黑木探路者",
	["Blackwood Pathfinders and Windtalkers hold the camp south-east of {area:442}."] = "黑木探路者和黑木语风者占据着{area:442}东南的营地。",
	["Blackwood Windtalker"] = "黑木语风者",
	["Blackwood furbolgs"] = "黑木熊怪",
	["Boat to {area:17203}"] = "乘船前往{area:17203}",
	["Class trainer"] = "职业训练师",
	["Climb the eastern mountains east of {area:447}; the {object:175524} sits on a ledge."] = "爬上{area:447}以东的东部山脉；{object:175524}在岩架上。",
	["Druid trainer"] = "德鲁伊训练师",
	["Fill the tube at the moonwell in the village"] = "在村里的月亮井装满试管",
	["Follow the coast south past {area:447}: one {quest:4728} lies on the shore west of the Grove, another further south near {area:450}. Three more remains lie further south-west among Greymist Oracles and Tidehunters (18-20): the guide leaves them for the last loop, when you are closer to their level."] = "沿海岸向南经过{area:447}：一件{quest:4728}在树林西边的海岸上，另一件在更南边、{area:450}附近。还有三件遗骸在更西南的灰雾神谕者和潮汐猎人（18-20级）中间：指南把它们留到最后一轮，那时你更接近它们的等级。",
	["Grell Earrings"] = "劣魔耳环",
	["Highborne Relics"] = "上层精灵的遗物",
	["Into {area:12}"] = "进入{area:12}",
	["Kill Rabid Thistle Bears in the hills east of {area:442}, then walk up to the furbolg camp south-east of them: nothing to kill yet."] = "在{area:442}东边的丘陵里杀狂暴蓟熊，然后走到它们东南的熊怪营地：现在还没有要杀的东西。",
	["North along the hills. {npc:3650} waits in the ruins of {quest:954}; Wild Grells and Vile Sprites fill them, Deth'ryll Satyrs the eastern edge. {object:17183} stands by the road west of the ruins; a {quest:4723} lies on the shore on the way to him."] = "沿丘陵向北。{npc:3650}在{quest:954}的废墟里等候；野生格里尔和邪恶小精灵遍布其中，东边是德塞利尔萨特。{object:17183}在废墟以西的路旁；去他那边的海岸上有一件{quest:4723}。",
	["Plagued bears"] = "染疫的熊",
	["Rabid Thistle Bears roam the hills just east of {area:442}. Use {item:7586} on one and lead it back to him."] = "狂暴蓟熊在{area:442}东边的丘陵游荡。对其中一只使用{item:7586}，把它引回他那里。",
	["Read the {object:17188}"] = "阅读{object:17188}",
	["Read the {object:17189}"] = "阅读{object:17189}",
	["Shaman trainer"] = "萨满祭司训练师",
	["The WANTED poster outside the inn"] = "旅店外的通缉布告",
	["The beach"] = "海滩",
	["The boat docks west of the village. The flight master stands on the hill south of the inn; the quest givers are spread along the main street."] = "船停靠在村子西边。飞行管理员站在旅店南边的山丘上；任务发布者分布在主街上。",
	["The boat docks west of the village. The flight master stands on the hill south of the inn; the quest givers are spread along the main street. {npc:3666} stands upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart."] = "船停靠在村庄西边。飞行管理员站在旅店南边的山坡上；任务给予者分布在主街两旁。{npc:3666}在旅店楼上：从室内楼梯上去，箭头无法区分楼层。",
	["The flame burns in the south of {area:447}."] = "火焰在{area:447}的南部燃烧。",
	["The red crystal"] = "红色水晶",
	["The skeletal turtle"] = "骷髅海龟",
	["The southern beaches"] = "南部海滩",
	["Tide Crawlers scuttle along the shore below the village; {quest:983} stands on the beach just south of the docks. Darkshore Threshers swim in the shallows. The {object:175207} lies on the shore just south of the village."] = "潮行蟹在村子下方的岸边爬行；{quest:983}立在码头南边的海滩上。黑海岸蛇颈龙在浅水中游动。{object:175207}躺在村子南边的岸上。",
	["While you're here: learn Swords from {npc:11867} ({object:2096}, 10 silver); a sword in the main hand levels a Rogue steadily."] = "顺便：在{npc:11867}处学习剑（{object:2096}，10银币）；主手持剑能让潜行者稳定升级。",
	["While you're here: learn {spell:202} from {npc:11867} ({object:2096}, 10 silver); two-handers level a Warrior fastest."] = "趁在这里：向{npc:11867}学习{spell:202}（{object:2096}，10银）；双手武器让战士升级最快。",
	["the Rabid Thistle Bears nearest {npc:3701}"] = "距{npc:3701}最近的狂暴蓟熊",
	["{item:12289}, on the beach west of the docks; underwater"] = "{item:12289}，在码头西边的海滩；水下",
	["{item:5338}: Deth'ryll Satyrs"] = "{item:5338}：戴瑟雷萨特",
	["{npc:257446} in {zone:1426}; {area:87} has no shaman trainer"] = "{npc:257446}在{zone:1426}；{area:87}没有萨满祭司训练师",
	["{npc:3639} stands at the north edge of the ruins. Cursed, Writhing and {npc:2178} haunt them; {npc:3667}'s ghost walks among them, {npc:270196} the owl circles east of them. The two tablets lie in the ruins; a {quest:4722} lies on the shore west of them."] = "{npc:3639}站在废墟北缘。被诅咒的贵族、挣扎的贵族和{npc:2178}在那里出没；{npc:3667}的鬼魂在它们中间游荡，猫头鹰{npc:270196}在它们东边盘旋。两块石板在废墟中；一只{quest:4722}躺在废墟西边的岸上。",
	["{npc:3649}, north end of the village"] = "{npc:3649}，在村子北端",
	["{npc:3666}, upstairs in the inn"] = "{npc:3666}，在旅店楼上",
	["{npc:5504} in {zone:1453}; {area:87} has no druid trainer"] = "{npc:5504}在{zone:1453}；{area:87}没有德鲁伊训练师",
	["{zone:1453} flight master"] = "{zone:1453}飞行管理员",
}

G["forever/alliance/skyborne/01-zephras-isle"] = {
	["\"Badwind\" Bennic"] = "“恶风”本尼克",
	["\"Badwind\" Bennic, below ground"] = "“恶风”本尼克，地下",
	["/sit by {npc:263664}'s campfire until you get {spell:1229451}"] = "在{npc:263664}的篝火旁输入/sit坐下，直到获得{spell:1229451}",
	["Al'Aketh Assassin"] = "奥阿克刺客",
	["Al'Aketh Blademaster"] = "奥阿克剑圣",
	["Al'Aketh Brawler"] = "奥阿克斗殴者",
	["Al'Aketh Brute"] = "奥阿克蛮兵",
	["Al'Aketh Convert"] = "奥阿克皈依者",
	["Al'Aketh Guardian"] = "奥阿克守卫",
	["Al'Aketh Healer"] = "奥阿克治疗者",
	["Al'Aketh Neophyte"] = "奥阿克新信徒",
	["Al'Aketh Spiritcaller"] = "奥阿克唤灵者",
	["Al'Aketh Stormcaller"] = "奥阿克唤风者",
	["Al'Aketh Stormchasers and Footsoldiers camp just north of {npc:257944} and drop the heirloom; the Shrieklings west of her drop the feathers and talons; the {item:265105} grows along the stream west of her."] = "奥拉凯斯Stormchaser和Footsoldier在{npc:257944}北边不远处扎营，会掉落传家宝；她西边的尖啸幼兽掉落羽毛和利爪；{item:265105}生长在她西边的溪流旁。",
	["Back east out of the den to the grove."] = "从巢穴向东返回林地。",
	["Back in {quest:92529}: Stormcallers and {npc:251662} fill the village, the Stormcallers carry the stolen supplies, and {npc:251966} stands at its south end."] = "回到{quest:92529}：奥拉凯斯唤暴者和{npc:251662}遍布村中，唤暴者携带着失窃的补给品，{npc:251966}站在村子南端。",
	["Back to the Hermit"] = "回到隐士那里",
	["Back to {area:16622}"] = "回到{area:16622}",
	["Bandit Highwaymen"] = "强盗路霸",
	["Below ground"] = "在地下",
	["Bolvar Fordragon stands in the throne room of {object:2117}, at the north end of the city. Then leave by the main gate for {area:40}."] = "伯瓦尔·弗塔根站在{object:2117}的王座厅里，位于城市北端。然后从正门离开，前往{area:40}。",
	["Cast {spell:1259705} at the {object:460002}"] = "对着{object:460002}施放{spell:1259705}",
	["Cirrusfly Queen"] = "卷云蝇后",
	["Class trainer"] = "职业训练师",
	["Commander Belguilos"] = "指挥官贝尔吉洛斯",
	["Desperate times"] = "危急时刻",
	["Ferauu the Bludgeon"] = "重击者费劳",
	["Fight north to the {area:16629}. Guardians, Spiritcallers and Blademasters hold the approach; {npc:253576} waits at the shrine's door, {npc:253590} inside the inner sanctum."] = "向北一路杀到{area:16629}。奥拉凯斯守护者、唤灵者和剑圣把守着通道；{npc:253576}在圣坛门口等候，{npc:253590}在内殿里。",
	["Fillion's camp is north-west of it, and the Shriekling Matriarchs nest just west of the camp."] = "菲利昂的营地在它西北方，尖啸迅猛龙族长就在营地以西筑巢。",
	["Find {npc:258130}"] = "找到{npc:258130}",
	["Follow the road south to {area:16624}. {npc:263664} camps by the fire west of the village; {npc:251523} and {npc:251903} stand in its middle."] = "沿道路向南前往{area:16624}。{npc:263664}在村子西边的篝火旁扎营；{npc:251523}和{npc:251903}站在村子中央。",
	["For {npc:234} at {area:108}"] = "前往{area:108}找{npc:234}",
	["Head north into {area:16631}. {npc:257944} camps in its east."] = "向北进入{area:16631}。{npc:257944}在其东部扎营。",
	["Head north-west to the hippogryph nests on the western cliffs. {item:263493} lies around the nests; the Matriarch patrols among them.\nThe Novice Seers practise in the clearing west of Shen'dar, on the way back to the village."] = "向西北前往西部悬崖上的角鹰兽巢穴。{item:263493}散落在巢穴周围；角鹰兽主母在其间巡逻。\n见习先知在申达尔西边的空地上修炼，就在返回村子的路上。",
	["Head north-west to the hippogryph nests on the western cliffs. {item:263493} lies around the nests; the Matriarch patrols among them.\nThe Novice Seers practise in the clearing west of Shen'dar."] = "向西北前往西部悬崖上的角鹰兽巢穴。{item:263493}散落在巢穴周围；女族长在巢间巡逻。\n见习先知在杉达尔以西的空地上练习。",
	["Heal the injured druids in the Nightfang Den"] = "治疗夜牙巢穴内受伤的德鲁伊",
	["Highlands Bandit"] = "高地强盗",
	["Highlands Bandits"] = "高地强盗",
	["Hippogryph Matriarch"] = "角鹰兽女族长",
	["Hippogryph Protector"] = "角鹰兽保卫者",
	["Hippogryph Youth"] = "幼年角鹰兽",
	["Hungry Bandit"] = "饥饿的强盗",
	["Innkeeper {npc:255940}, by the west gate"] = "旅店老板{npc:255940}，在西门旁",
	["Inside"] = "在里面",
	["Jump off the top of the watchtower and use {spell:1259416} to float down to {npc:251361}, west of the tower."] = "从瞭望塔顶跳下，使用{spell:1259416}飘落到塔西的{npc:251361}处。",
	["Juvenile Vuldren"] = "幼年鹫龙",
	["Lariia in {zone:1438}; {area:16624} has no priest trainer"] = "拉瑞娅在{zone:1438}；{area:16624}没有牧师训练师",
	["Leave {zone:1453} by the main gate. The {quest:1861} waterfall is south-west of the gates, on the way west to {area:40}: fill {item:7207} at its base."] = "从正门离开{zone:1453}。{quest:1861}的瀑布在城门西南，位于向西前往{area:40}的路上：在瀑布底部装满{item:7207}。",
	["Leave {zone:2521} to {zone:1416}"] = "离开{zone:2521}前往{zone:1416}",
	["Level 4 spells"] = "4级法术",
	["Level 6 spells"] = "6级法术",
	["Listen to {npc:252448}'s story"] = "听{npc:252448}讲述他的故事",
	["Listen to {npc:257554}"] = "聆听{npc:257554}",
	["Living Lightning"] = "活体闪电",
	["Lorthuna waits up on the {area:16630}, east of the shrine: take the Portal to {area:16630} in the inner sanctum, beside Valennia, and cross the heights east to {npc:252475}. When she falls, the {object:617084} beside her takes you back to town."] = "洛尔图娜在神殿以东的{area:16630}上方等候：在内殿瓦伦妮娅身旁乘通往{area:16630}的传送门，再向东穿过高地到达{npc:252475}。她倒下后，她身旁的{object:617084}会把你送回城里。",
	["Malduko Cloudcrush"] = "马尔杜科·碎云",
	["Meet {npc:253844} at the gate"] = "在城门与{npc:253844}会合",
	["Naaleos Leafwhisper"] = "纳里奥斯·叶语",
	["North of the cones: the Wind Hollows drift around the refugees' camp, the {item:266433} lie between the tents, and {npc:259013} lies at its north end."] = "球果北边：Wind Hollow在难民营地周围飘荡，{item:266433}在帐篷之间，{npc:259013}躺在营地北端。",
	["North-west of Valanaar along the road, past {npc:273017}: the dead cultist lies just north of him."] = "沿道路前往瓦拉纳尔西北，经过{npc:273017}：死去的邪教徒就躺在他北边不远处。",
	["North-west of Valanaar along the road: {npc:273017} watches the {quest:98512}; the dead cultist lies just north of him."] = "沿道路前往瓦拉纳尔西北：{npc:273017}监视着{quest:98512}；死去的邪教徒就躺在他北边不远处。",
	["Ornery Galestrider"] = "暴躁的疾风行者",
	["Paladin trainer"] = "圣骑士训练师",
	["Pesky Cirrusfly"] = "讨厌的卷云蝇",
	["Portal to {area:16630}"] = "通往{area:16630}的传送门",
	["Prideclaws and Galestriders"] = "傲爪和疾风陆行鸟",
	["Prideclaws and Galestriders roam the grasslands south of the village. Galestriders drop both the eggs and the meat."] = "傲爪和疾风陆行鸟在村子南边的草原上游荡。疾风陆行鸟会掉落蛋和肉。",
	["Priest trainer"] = "牧师训练师",
	["Raw Windstones and the {npc:251404}"] = "原始风石和{npc:251404}",
	["Ripe Stormapples and Hungry Bandits are in the orchard by the farm, {quest:92683} in the fields north-east of it, Ornery Galestriders all around. The {npc:250929} stands in the field north-east of the farm."] = "成熟的风暴苹果和饥饿的强盗在农场旁的果园里，{quest:92683}在其东北边的田野里，暴躁的疾风陆行鸟到处都是。{npc:250929}站在农场东北边的田里。",
	["Roiling Winds"] = "翻腾之风",
	["Search the dead cultist"] = "搜查死去的邪教徒",
	["Search the wardrobe"] = "搜查衣柜",
	["Shaman trainer"] = "萨满祭司训练师",
	["Shen'dar turn-ins"] = "申达尔交还任务",
	["Skyhopper"] = "跳天者",
	["Skyhoppers"] = "天空跳跃者",
	["Skyhoppers swarm the fields west of {area:16638}."] = "天空跳跃者成群出没于{area:16638}西边的田野。",
	["Skypriest Aanders"] = "天空祭司安德斯",
	["Standing our ground"] = "坚守阵地",
	["Tame it with the {item:15908}"] = "用{item:15908}驯服它",
	["Tame {npc:250874}"] = "驯服{npc:250874}",
	["Tame {npc:251707}"] = "驯服{npc:251707}",
	["Tame {npc:254588}"] = "驯服{npc:254588}",
	["Tell {npc:252800} you're ready"] = "告诉{npc:252800}你准备好了",
	["The Bandit Highwaymen hold the hills north of the farm."] = "强盗路霸占据了农场北边的山丘。",
	["The Highlands Bandits camp north-east of the village. \"Badwind\" Bennic waits at the far north end of their camp."] = "高地强盗在村子东北边扎营。“恶风”本尼克在他们营地的最北端等着。",
	["The Raw Windstones glitter on the ground just south of the grove. {quest:92463} hovers over the meadow further east, on the way to {npc:249363}."] = "原始风石在林地南边的地面上闪闪发光。{quest:92463}在更东边的草地上空盘旋，就在前往{npc:249363}的路上。",
	["The Ursera Scavengers den west of the grove, with {npc:251115}, the matriarch, at the back of the den; {npc:250926} prowl the woods between the den and the grove."] = "厄塞拉食腐者在林地西边筑巢，主母{npc:251115}在巢穴深处；{npc:250926}在巢穴与林地之间的树林里游荡。",
	["The Windstone Formations"] = "Windstone Formation",
	["The Windstone Formations stand on the rise west of Fillion's camp."] = "Windstone Formation矗立在Fillion营地西边的高地上。",
	["The bounty board"] = "悬赏布告板",
	["The class trainers stand together in the grove"] = "职业训练师都聚在林地里",
	["The dead cultist"] = "死去的邪教徒",
	["The eastern watchtower"] = "东部瞭望塔",
	["The missing scholar"] = "失踪的学者",
	["The road to {area:16638}"] = "前往{area:16638}的路",
	["The {area:16629}"] = "{area:16629}",
	["The {item:254871}"] = "{item:254871}",
	["The {object:581822}"] = "{object:581822}",
	["The {object:581822} lies by the path west of {area:16638}."] = "{object:581822}在{area:16638}以西的小路旁。",
	["The {object:617084} sets you down beside {npc:252475} at the south end of the town. {npc:252476} is at the north end, {npc:259012} a few steps north-west of her."] = "{object:617084}会把你送到城镇南端的{npc:252475}身旁。{npc:252476}在北端，{npc:259012}在她西北边几步远。",
	["Underwater"] = "水下",
	["Upstairs"] = "楼上",
	["Ur'endra"] = "乌恩德拉",
	["Ursera Scavenger"] = "乌尔瑟拉食腐者",
	["Village quests"] = "村庄任务",
	["Vuldren Alpha"] = "鹫龙头领",
	["Warlock trainer"] = "术士训练师",
	["While you're here: learn Staves from {npc:11867} ({object:2096}, 10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "顺便：在{npc:11867}处学习法杖（{object:2096}，10银币）；猎人的近战武器主要看属性，而双手武器属性最多。",
	["While you're here: learn Swords from {npc:11867} ({object:2096}, 10 silver); a sword in the main hand levels a Rogue steadily."] = "顺便：在{npc:11867}处学习剑（{object:2096}，10银币）；主手持剑能让潜行者稳定升级。",
	["While you're here: learn {spell:202} from {npc:11867} ({object:2096}, 10 silver); two-handers level a Warrior fastest."] = "趁在这里：向{npc:11867}学习{spell:202}（{object:2096}，10银）；双手武器让战士练级最快。",
	["Wind Hollow"] = "风穴怪",
	["Windshaper Novice Seer"] = "塑风者见习先知",
	["Windsong Crawler"] = "风歌爬行者",
	["You wake in {area:16622}. {npc:251362} stands beside you; {npc:251361} is a few steps west, {npc:251368} by the south edge of the grove."] = "你在{area:16622}醒来。{npc:251362}站在你身旁；{npc:251361}在西边几步远，{npc:251368}在林地南缘。",
	["{area:16622} turn-ins"] = "{area:16622}交还任务",
	["{area:16622}: kill these as you meet them"] = "{area:16622}：遇到就杀",
	["{area:16623}: kill these as you meet them"] = "{area:16623}：遇到就杀",
	["{area:16624} again"] = "再次前往{area:16624}",
	["{area:16626}: kill these as you meet them"] = "{area:16626}：遇到就杀",
	["{area:16631}: kill these as you meet them"] = "{area:16631}：遇到就杀",
	["{area:16638} turn-ins"] = "{area:16638}交还任务",
	["{area:16638}, the fate of Zephras"] = "{area:16638}，泽风岛的命运",
	["{area:16638}, the turncoat"] = "{area:16638}，叛徒",
	["{area:16833}: kill these as you meet them"] = "{area:16833}：遇到就杀",
	["{item:2450} in {zone:1455}; {area:16624} has no warlock trainer"] = "{item:2450}在{zone:1455}；{area:16624}没有术士训练师",
	["{item:2450} in {zone:1455}; {area:16638} has no warlock trainer"] = "{item:2450}在{zone:1455}；{area:16638}没有术士训练师",
	["{item:252665}; below ground"] = "{item:252665}；在地下",
	["{item:257107}; below ground"] = "{item:257107}；在地下",
	["{item:262668}: by the formations"] = "{item:262668}：在石阵旁",
	["{item:263993}: {npc:257196} holds it, west of the shrine's approach; defeat him for it on the way in"] = "{item:263993}：由{npc:257196}持有，在神殿入口通道以西；进去的路上击败他即可获得",
	["{npc:249363} keeps watch east of the grove. The {npc:251143} and Al'Aketh Converts gather just north of her; the {object:460002} rises further north: cast your {spell:1259705} racial ability at it."] = "{npc:249363}在林地东边放哨。{npc:251143}和奥阿克皈依者聚集在她北边；{object:460002}在更北处耸立：对着它施放你的种族技能{spell:1259705}。",
	["{npc:250873} and Pesky Cirrusflies roam the meadow just south-east of the grove."] = "{npc:250873}和烦人的卷云蝇在林地东南方的草地上游荡。",
	["{npc:250926} prowl the woods just west of the grove; the Ursera Scavengers den further west, with {npc:251115}, the matriarch, at the back of the den."] = "{npc:250926}在林地西边不远的树林里游荡；乌萨拉食腐者的巢穴在更西边，族母{npc:251115}在巢穴深处。",
	["{npc:251361}: a note from your trainer"] = "{npc:251361}：训练师的便条",
	["{npc:251361}: read the {item:9547}"] = "{npc:251361}：阅读{item:9547}",
	["{npc:251361}: the {item:4100}"] = "{npc:251361}：{item:4100}",
	["{npc:251373}, the druid trainer, on the ground floor of the tree behind {npc:251361}"] = "{npc:251373}，德鲁伊训练师，在{npc:251361}身后那棵树的底层",
	["{npc:251379}, the mage trainer: read the {item:282416} first"] = "{npc:251379}，法师训练师：先阅读{item:282416}",
	["{npc:251389}, in the watchtower"] = "{npc:251389}，在瞭望塔里",
	["{npc:251905}: Camping 101 asks you to learn it"] = "{npc:251905}：“露营入门”要求你学会它",
	["{npc:251918} along the way to Shen'dar turn-ins"] = "前往杉达尔交任务途中的{npc:251918}",
	["{npc:251918} on the way"] = "{npc:251918}，途中",
	["{npc:251964}, in the watchtower"] = "{npc:251964}，在瞭望塔里",
	["{npc:252095} camps south of the Ursera den. The Al'Aketh thugs hold the camp south-west of her; {npc:256935} stands in its middle.\nCareful: {npc:256935} casts shocks; drag him clear of the other cultists before fighting so they don't join in."] = "{npc:252095}在乌尔瑟拉巢穴以南扎营。奥阿克暴徒占据她西南方的营地；{npc:256935}站在营地中央。\n注意：{npc:256935}会施放震击法术；开战前把他拉离其他信徒，以免它们加入战斗。",
	["{npc:252095} camps south-west of the grove, south of the Ursera den, on the way south to Shen'dar. The Al'Aketh thugs hold the camp south-west of her; {npc:256935} stands in its middle.\nCareful: {npc:256935} casts shocks; drag him clear of the other cultists before fighting so they don't join in."] = "{npc:252095}在林地西南边、厄塞拉巢穴南边扎营，就在南下前往申达尔的路上。奥拉凯斯暴徒占据了她西南边的营地；{npc:256935}站在营地中央。\n小心：{npc:256935}会施放电击；开战前把他引离其他邪教徒，以免他们加入战斗。",
	["{npc:252155} holds the western watch, south-west of Falaath. {npc:256966} and the fallen guards lie just south of her."] = "{npc:252155}驻守西部哨所，在法拉斯西南边。{npc:256966}和阵亡的卫兵躺在她南边不远处。",
	["{npc:252359}, between the west gate and Valennia's house: {quest:94006}"] = "{npc:252359}，在西门和瓦伦妮亚的房子之间：{quest:94006}",
	["{npc:252359}, the druid trainer, stands between the west gate and Valennia's house."] = "德鲁伊训练师{npc:252359}站在西门与瓦伦妮娅的房屋之间。",
	["{npc:252359}: {quest:94006} (level 10)"] = "{npc:252359}：{quest:94006}（10级）",
	["{npc:252373}, the mage trainer"] = "{npc:252373}，法师训练师",
	["{npc:252377}, beside {npc:257006}: {npc:257196} holds the Bulwark at the {area:16629}"] = "{npc:252377}，在{npc:257006}旁：{npc:257196}在{area:16629}持有壁垒",
	["{npc:252378} holds the watchtower north of {area:16638}. The Al'Aketh camp is just west of the tower, its healers around 65,68 and 65,65; {npc:252666} stands at its north end. The Al'Aketh there drop Windstone Charms."] = "{npc:252378}驻守{area:16638}北边的瞭望塔。奥拉凯斯营地就在塔的西边，其治疗者在65,68和65,65附近；{npc:252666}站在营地北端。那里的奥拉凯斯成员会掉落Windstone Charm。",
	["{npc:252383} and {npc:252476} stand at the north end of {area:16638}, {npc:252475} and {npc:253204} at the south end."] = "{npc:252383}和{npc:252476}站在{area:16638}北端，{npc:252475}和{npc:253204}在南端。",
	["{npc:252383}, upstairs"] = "{npc:252383}，在楼上",
	["{npc:252389} takes back the first {item:15908} and hands you two more, one at a time: Ornery Galestriders and Vuldren Alphas roam the fields just north of her. Tame each with its rod and bring the rod back to her. {npc:254411}, beside her, teaches {spell:5149}."] = "{npc:252389}收回第一根{item:15908}，再逐一交给你两根：暴躁的疾风行者和鹫龙头领就在她北边的田野上游荡。用对应的驯兽棒驯服每只，再把驯兽棒带回给她。她旁边的{npc:254411}教授{spell:5149}。",
	["{npc:252389}, beside {npc:257006}: the first {item:15908}"] = "{npc:252389}，在{npc:257006}旁：第一根{item:15908}",
	["{npc:252475} sends you on to {area:279}. Once you have trained, take the skycutter from the dock tower just south of {area:16638}: it lands by the Kirin Tor camp west of {area:279}, beside {npc:259084} and the Skyborne Portal."] = "{npc:252475}派你前往{area:279}。训练完成后，从{area:16638}正南的码头塔乘飞空艇：它会降落在{area:279}以西的肯瑞托营地旁，就在{npc:259084}和天裔传送门旁。",
	["{npc:252475}: {npc:259084} waits by the Skyborne portal"] = "{npc:252475}：{npc:259084}在天裔传送门旁等候",
	["{npc:252476}, upstairs"] = "{npc:252476}，在楼上",
	["{npc:252800} again"] = "再次找{npc:252800}",
	["{npc:252800} runs the farm in the south-west lowlands."] = "{npc:252800}经营着西南低地的农场。",
	["{npc:253590}, in the sanctum; upstairs"] = "{npc:253590}，在内殿；在楼上",
	["{npc:254151}, {npc:258130} and {npc:258134} are north-east of {npc:257944}; {npc:253622} stands east of them. Haalien also drops a {quest:94490}. For {quest:94489}, enter the Nightfang Den, heal 7 injured druids and find {npc:258130}."] = "{npc:254151}、{npc:258130}和{npc:258134}在{npc:257944}东北边；{npc:253622}站在他们东边。这名指挥官还会掉落{quest:94490}。完成{quest:94489}时，进入夜牙巢穴，治疗7名受伤的德鲁伊并找到{npc:258130}。",
	["{npc:254588}, among the crabs: tame one with {npc:252389}'s first {item:15908} while you are there"] = "{npc:254588}，在螃蟹群中：你在那里时用{npc:252389}的第一根{item:15908}驯服一只",
	["{npc:254589} lurks in the hills south-west of the village, on the way back. {npc:254589} is elite: grouping up is advised."] = "{npc:254589}潜伏在村子西南边的山丘中，就在回去的路上。{npc:254589}是精英：建议组队。",
	["{npc:255853} waits by the falls north-east of {area:16638}. {npc:258443} prowls the {area:16623} west of {area:16638}, by the road you take next."] = "{npc:255853}在{area:16638}东北边的瀑布旁等候。{npc:258443}在{area:16638}西边的{area:16623}游荡，就在你接下来要走的路旁。",
	["{npc:255853}, by the falls north-east of {area:16638}, on the way north: {spell:5487}"] = "{npc:255853}，在{area:16638}东北的瀑布旁，位于向北的路上：{spell:5487}",
	["{npc:257006} and {npc:252448} stand on {area:16638}'s west side, beside the inn; {npc:252377} and {npc:252389} train just west of {npc:257006}. Windsong Crawlers line the shore further west, around 51,70."] = "{npc:257006}和{npc:252448}站在{area:16638}西侧、旅店旁；{npc:252377}和{npc:252389}在{npc:257006}正西训练。再往西的海岸一线是风歌爬行者，坐标约51,70。",
	["{npc:257006}, inside"] = "{npc:257006}，室内",
	["{npc:257065} waits at the entrance to {quest:92529}, south of Shen'dar. The {spell:1254832} lets you walk in among the faithful."] = "{npc:257065}在杉达尔以南{quest:92529}的入口等候。{spell:1254832}能让你走进信徒中间。",
	["{npc:257532} on the way"] = "{npc:257532}，途中",
	["{npc:257554} and {npc:263113} stand at the top of the watchtower, a few steps north-east of {npc:251368}."] = "{npc:257554}和{npc:263113}站在瞭望塔顶层，就在{npc:251368}东北边几步远处。",
	["{npc:257944} again"] = "再次找{npc:257944}",
	["{npc:257944}, the missive"] = "{npc:257944}，密信",
	["{npc:258098} in {zone:1455}; {area:16624} has no shaman trainer"] = "{npc:258098}在{zone:1455}；{area:16624}没有萨满祭司训练师",
	["{npc:258098} in {zone:1455}; {area:16638} has no shaman trainer"] = "{npc:258098}在{zone:1455}；{area:16638}没有萨满祭司训练师",
	["{npc:258443}, in the highlands south-west of the cultist"] = "{npc:258443}，在邪教徒西南边的高地",
	["{npc:259084} stands beside the Skyborne Portal, where the skycutter lands by the Kirin Tor camp west of {area:279}. The portal takes you to {zone:1453}."] = "{npc:259084}站在天裔传送门旁，飞空艇就降落在{area:279}以西的肯瑞托营地边。传送门会把你送往{zone:1453}。",
	["{npc:259084}, inside"] = "{npc:259084}，在里面",
	["{npc:270459}, beside {npc:259084}: for {npc:5504} in {zone:1453}"] = "{npc:270459}，在{npc:259084}身旁：前往{zone:1453}找{npc:5504}",
	["{npc:5141} in {zone:1455}; {area:16638} has no priest trainer"] = "{npc:5141}在{zone:1455}；{area:16638}没有牧师训练师",
	["{npc:5148} in {zone:1455}; {area:16624} has no paladin trainer"] = "{npc:5148}在{zone:1455}；{area:16624}没有圣骑士训练师",
	["{npc:5148} in {zone:1455}; {area:16638} has no paladin trainer"] = "{npc:5148}在{zone:1455}；{area:16638}没有圣骑士训练师",
	["{npc:5497} stands in the Wizard's Sanctum, the tower of the {object:2101}; she gives you a flask for the {quest:1861} waterfall."] = "{npc:5497}站在{object:2101}的塔楼巫师圣殿里；她会给你一个瓶子，用于{quest:1861}的瀑布。",
	["{npc:5504}, {zone:1453}'s druid trainer, teaches you {spell:18960}. {npc:11802}'s welcome waits for your {spell:499} trip at the end of {zone:1439}."] = "{zone:1453}的德鲁伊训练师{npc:5504}教你{spell:18960}。{npc:11802}的欢迎在{zone:1439}尽头等着你的{spell:499}之旅。",
	["{object:631299}, inside"] = "{object:631299}，在里面",
	["{quest:93159} lives west of {npc:257944}. The Zephyrseed Cones lie in the woods between his hut and {npc:257944}."] = "{quest:93159}住在{npc:257944}西边。和风之种球果散落在他的小屋和{npc:257944}之间的树林里。",
	["{zone:1453} flight master"] = "{zone:1453}飞行管理员",
}

G["forever/class/hunter/taming-the-beast-alliance"] = {
	["At 10 go to {npc:1231}, the hunter trainer at the smithy in {area:131}. The Hunter's Path from {npc:5116} in {zone:1455}, {npc:11807} north-west of {area:131} or {npc:5515} in {zone:1453} also leads here, for a little experience; it is only a pointer. In Elwynn at 10 instead? {npc:251507}'s chain in {area:87} teaches the same."] = "10级时去找{npc:1231}，{area:131}铁匠铺的猎人训练师。来自{zone:1455}的{npc:5116}、{area:131}西北的{npc:11807}或{zone:1453}的{npc:5515}的“猎手之路”也会指引到这里，可得到少量经验；它只是指路任务。10级时改去艾尔文森林？{area:87}的{npc:251507}任务链教的内容一样。",
	["At 10 go to {npc:251507}, the hunter trainer who stands with the other trainers by the Lion's Pride Inn in {area:87}; {npc:258930}, the pet trainer, is beside her. Skyborne: this is for one who left {zone:2521} without taming; it teaches the same."] = "10级时去找{npc:251507}，她和其它训练师一起站在{area:87}的狮王之傲旅店旁；宠物训练师{npc:258930}就在她身边。天裔：这是给没在{zone:2521}完成驯服就离开的人准备的；教的内容一样。",
	["At 10 go to {npc:3601}, the hunter trainer in {area:186}. The Hunter's Path from {npc:3596} at {area:256}, {npc:4146} in {zone:1457}, {npc:5515} in {zone:1453}, {npc:5116} in {zone:1455} or {npc:1231} in {area:131} also leads here, for a little experience; it is only a pointer. In Elwynn at 10 instead? {npc:251507}'s chain in {area:87} teaches the same."] = "10级时去找{area:186}的猎人训练师{npc:3601}。来自{area:256}的{npc:3596}、{zone:1457}的{npc:4146}、{zone:1453}的{npc:5515}、{zone:1455}的{npc:5116}或{area:131}的{npc:1231}的“猎手之路”也会指引到这里，可得到少量经验；它只是指路任务。10级时改去艾尔文森林？{area:87}的{npc:251507}任务链教的内容一样。",
	["At 10, {npc:254084}, a hunter trainer on {zone:2521}, may send you on to {area:16638} with {quest:94007}. It is only a pointer: skip it if you are already in {area:16638}."] = "10级时，{zone:2521}上的猎人训练师{npc:254084}可能会用{quest:94007}派你前往{area:16638}。这只是指路任务：如果你已经在{area:16638}，就跳过它。",
	["Dismiss the boar first (right-click the pet portrait, {spell:2641}): a released practice pet can turn on you. Gray Forest Wolves (level 7-8) run in the woods east of {area:87}, east of {area:18}."] = "先解散野猪（右键点击宠物头像，{spell:2641}）：放生的练习宠物可能会反咬你。灰森林狼（7-8级）在{area:87}以东、{area:18}以东的树林里奔跑。",
	["Dismiss the boar first (right-click the pet portrait, {spell:2641}): a released practice pet can turn on you. Snow Leopards (level 7-8) prowl the slopes south-east of {area:131}, more north-west and west of it; the smaller Juvenile Snow Leopards do not count."] = "先解散野猪（右键点击宠物头像，{spell:2641}）：放生的练习宠物可能会反咬你。雪豹（7-8级）在{area:131}东南的山坡徘徊，西北和西边也有更多；体型较小的幼年雪豹不算。",
	["Dismiss the cat. Strigid Screechers (level 7-8), owls, perch in the woods south, south-west and west of {area:186}."] = "解散猫。夜枭尖啸者（7-8级，属猫头鹰）栖息在{area:186}以南、西南和西边的树林。",
	["Dismiss the crawler first (right-click the pet portrait, {spell:2641}). Ornery Galestriders graze in the {area:16626}, the fields a short walk west and south-west of {area:16638}."] = "先解散爬行者（右键点击宠物头像，{spell:2641}）。暴躁风行者（Ornery Galestrider）在{area:16626}吃草，那片田野就在{area:16638}西面和西南面不远处。",
	["Dismiss the galestrider. Vuldren Alphas hunt in the same {area:16626}, a little further south."] = "解散风行者。鹫龙首领在同一片{area:16626}狩猎，位置稍偏南。",
	["Dismiss the leopard. Ice Claw Bears (level 7-8) roam the hills around {area:131}, many south-east of it and more north-west toward {area:77}; their {spell:3130} hits hard, so start at full health."] = "解散豹。冰爪熊（7-8级）在{area:131}周围的山丘游荡，很多在东南，西北靠{area:77}方向更多；它们的{spell:3130}很疼，所以满血开始。",
	["Dismiss the spider first (right-click the pet portrait, {spell:2641}): a released practice pet can turn on you. Nightsaber Stalkers (level 7-8) lie on the hillside south of {area:259}, south of {area:186}; the plain Nightsabers by the village do not count."] = "先解散蜘蛛（右键点击宠物头像，{spell:2641}）：放生的练习宠物可能会反咬你。夜刃豹潜行者（7-8级）在{area:259}以南、{area:186}以南的山坡上；村子旁的普通夜刃豹不算。",
	["Dismiss the wolf. Young Forest Bears (level 8-9) roam the woods just south of {area:87}, with more south-west and south-east of town."] = "解散狼。幼森林熊（8-9级）在{area:87}正南的树林里游荡，镇子西南和东南也有更多。",
	["Gray Forest Wolf"] = "灰森林狼",
	["Happiness: the face on the pet frame. An unhappy pet does three quarters of its damage, a happy one a quarter more. Happiness drains slowly, faster when the pet dies; a pet left unhappy too long can run away."] = "快乐值：宠物框上的表情。不快乐的宠物只能造成四分之三的伤害，快乐的则多四分之一。快乐值会缓慢下降，宠物死亡时下降更快；宠物不快乐太久可能会跑掉。",
	["Hunter"] = "猎人",
	["Ice Claw Bear"] = "冰爪熊",
	["Large Crag Boar"] = "大型峭壁野猪",
	["Large Crag Boars (level 6-7) root around the fields west, south and north-west of {area:131} and respawn every 3 minutes. How the rod works: target a living beast, use the {item:15908} and stand still for the whole channel while it hits you. Moving, fighting back, being out of range or anyone else's help breaks it and costs one of the rod's few charges; if they run out, destroy the rod, abandon the quest and take it again from {npc:1231}. The boars use {spell:6268} from 25 yards, so start with the rod, not {spell:75}. Keep each rod: it goes back to {npc:1231}."] = "大型峭壁野猪（6-7级）在{area:131}以西、以南和西北的田野里拱土，每3分钟刷新。魔杖用法：选中一只活着的野兽，使用{item:15908}，在整个引导期间站着不动、任由它攻击你。移动、还手、超出范围或他人帮忙都会中断，并消耗魔杖少量充能之一；若充能耗尽，就摧毁魔杖、放弃任务并回去找{npc:1231}再接。野猪会从25码外使用{spell:6268}，所以先用魔杖，别用{spell:75}。每根魔杖都留着：要还给{npc:1231}。",
	["Loyalty grows with time and kills. Each loyalty rank raises the training points you spend in {spell:5149} (pet level times loyalty rank minus one)."] = "忠诚度随时间与击杀增长。每提升一级忠诚度都会提高你在{spell:5149}中可用的训练点数（宠物等级乘以忠诚等级再减一）。",
	["Near {area:131}: Snow Leopards (cats, level 7-8) prowl all over {zone:1426}, Scarred Crag Boars (9-10) its east toward {zone:1432}; at 10-11, Mountain Boars roam western {zone:1432}."] = "{area:131}附近：雪豹（猫科，7-8级）在{zone:1426}四处徘徊，伤痕峭壁野猪（9-10级）在其东部靠{zone:1432}方向；10-11级时，山地野猪在{zone:1432}西部游荡。",
	["Near {area:16638}: Vuldren Alphas (level 10), the beast of your last practice tame, hunt the {area:16626}; Shriekling Matriarchs (raptors, level 9) nest just west of {area:16638}; Shadowgale Urseras (bears, 10-11) roam the north of {zone:2521}."] = "{area:16638}附近：鹫龙首领（10级，也就是你最后一次练习驯服的野兽）在{area:16626}狩猎；尖啸迅猛龙族长（迅猛龙，9级）在{area:16638}以西筑巢；暗风乌瑟拉斯（熊，10-11级）在{zone:2521}北部游荡。",
	["Near {area:186}: Elder Nightsabers (cats, level 8-9) and Feral Nightsabers (cats, 10-11) prowl the woods of north-western {zone:1438}."] = "{area:186}附近：老年夜刃豹（猫科，8-9级）和野性夜刃豹（猫科，10-11级）在{zone:1438}西北部的树林里徘徊。",
	["Near {area:87} there are no cats: Prowlers (wolves, level 9-10) roam eastern Elwynn, Longsnouts (boars, 10-11) its far south-west by the {zone:1436} border; at 12-13, Young Goretusks (boars) graze the fields of northern {zone:1436}."] = "{area:87}附近没有猫科：徘徊者（狼，9-10级）在艾尔文森林东部游荡，长鼻野猪（野猪，10-11级）在最西南靠{zone:1436}边界一带；12-13级时，幼年血牙野猪（野猪）在{zone:1436}北部的田野吃草。",
	["Nightsaber Stalker"] = "夜刃豹潜行者",
	["Ornery Galestrider"] = "暴躁风行者",
	["Pet trainers sell {spell:1853} ranks and resistances. Alliance: {npc:258930} in {area:87}, {npc:2879} by the hunter trainers in {zone:1453}'s {object:28027}, {npc:2878} in {area:131}, {npc:10090} in {zone:1455}'s {object:32390}, Keldas in {area:186}, Silvaria in {zone:1457}' Cenarion Enclave, {npc:254411} in {area:16638}."] = "宠物训练师出售{spell:1853}的各级和抗性。联盟：{area:87}的{npc:258930}、{zone:1453}的{object:28027}里猎人训练师旁的{npc:2879}、{area:131}的{npc:2878}、{zone:1455}的{object:32390}里的{npc:10090}、{area:186}的凯尔达斯、{zone:1457}塞纳里奥区的西尔瓦里娅、{area:16638}的{npc:254411}。",
	["Rockhide Boar"] = "石皮野猪",
	["Rockhide Boars (level 7-8) graze in three herds south and south-east of {area:87}, toward the {area:64}. How the rod works: target a living beast, use the {item:15908} and stand still for the whole channel while it hits you. Moving, fighting back, a heal from someone else or anyone else hitting the beast breaks it and costs one of the rod's few charges; if they run out, destroy the rod, abandon the quest and take it again. The boars use {spell:6268}, so start with the rod, not {spell:75}. Killing a boar does not count. Keep each rod: it goes back to Josephine. A Dwarf or Night Elf who took Josephine's rod instead of their home trainer's is led through {area:87} from here."] = "石皮野猪（7-8级）在{area:87}以南和东南、靠{area:64}方向分三群吃草。魔杖用法：选中一只活着的野兽，使用{item:15908}，在整个引导期间站着不动、任由它攻击你。移动、还手、他人治疗或任何人攻击该野兽都会中断，并消耗魔杖少量充能之一；若充能耗尽，就摧毁魔杖、放弃任务并再接一次。野猪会使用{spell:6268}，所以先用魔杖，别用{spell:75}。杀死野猪不算数。每根魔杖都留着：要还给约瑟芬。矮人或暗夜精灵拿了约瑟芬的魔杖而不是家乡训练师的，会从这里被引导走完{area:87}。",
	["Snow Leopard"] = "雪豹",
	["Strigid Screecher"] = "夜枭尖啸者",
	["Take the road west from {area:186} to {zone:1457}. {npc:4146} stands inside the {area:1658} with the hunter trainers; Silvaria, the pet trainer, is up the ramp next to her."] = "从{area:186}沿路向西到{zone:1457}。{npc:4146}和猎人训练师们站在{area:1658}内；宠物训练师西尔瓦里娅在她旁边、坡道上方。",
	["Tame a beast of your level to keep"] = "驯服一只与你等级相当的野兽作为永久宠物",
	["Tame {npc:1922}"] = "驯服{npc:1922}",
	["Tame {npc:250874}"] = "驯服{npc:250874}",
	["Tame {npc:251707}"] = "驯服{npc:251707}",
	["Tame {npc:254588}"] = "驯服{npc:254588}",
	["Tame {npc:524}"] = "驯服{npc:524}",
	["Tame {npc:822}"] = "驯服{npc:822}",
	["Use the {item:15908} on a living alpha"] = "对活着的首领使用{item:15908}",
	["Use the {item:15908} on a living bear"] = "对活着的熊使用{item:15908}",
	["Use the {item:15908} on a living boar"] = "对活着的野猪使用{item:15908}",
	["Use the {item:15908} on a living crawler"] = "对活着的爬行者使用{item:15908}",
	["Use the {item:15908} on a living galestrider"] = "对活着的风行者使用{item:15908}",
	["Use the {item:15908} on a living leopard"] = "对活着的豹使用{item:15908}",
	["Use the {item:15908} on a living owl"] = "对活着的猫头鹰使用{item:15908}",
	["Use the {item:15908} on a living spider"] = "对活着的蜘蛛使用{item:15908}",
	["Use the {item:15908} on a living stalker"] = "对活着的潜伏者使用{item:15908}",
	["Use the {item:15908} on a living wolf"] = "对活着的狼使用{item:15908}",
	["Vuldren Alpha"] = "鹫龙首领",
	["Webwood Lurker"] = "蛛网潜伏者",
	["Webwood Lurkers (level 5-6) creep through the woods just north-east, south-west and east of {area:186}. How the rod works: target a living beast, use the {item:15908} and stand still for the whole channel while it hits you; moving, attacking it or anyone else's help breaks it and costs one of the rod's few charges (out of charges: destroy the rod, abandon the quest, take it again). Their {spell:1265843} roots you but does not break the channel if you keep still. Keep each rod: it goes back to {npc:3601}."] = "蛛网潜伏者（5-6级）在{area:186}东北、西南和东边的树林里爬行。魔杖用法：选中一只活着的野兽，使用{item:15908}，在整个引导期间站着不动、任由它攻击你；移动、攻击它或他人帮忙都会中断，并消耗魔杖少量充能之一（充能耗尽：摧毁魔杖，放弃任务，再接一次）。它们的{spell:1265843}会定住你，但只要你保持不动就不会打断引导。每根魔杖都留着：要还给{npc:3601}。",
	["Windsong Crawler"] = "鸣风爬行者",
	["Windsong Crawlers live only by water: the nearest scuttle along the shore south-west of {area:16638}, among the crabs. How the rod works: target a living crawler, use the {item:15908} and stand still for the whole channel while it hits you; moving, fighting back or anyone else's help breaks it and costs one of the rod's few charges. Killing one does not count. Keep each rod: it goes back to {npc:252389}."] = "鸣风爬行者只生活在有水的地方：最近的一群在{area:16638}西南面的岸边，混在螃蟹之间。魔杖用法：选中一只活着的爬行者，使用{item:15908}，在整个引导期间站着不动、任由它攻击你；移动、还手或他人帮忙都会中断，并消耗魔杖少量充能之一。杀死它不算数。每根魔杖都留着：要还给{npc:252389}。",
	["Young Forest Bear"] = "幼森林熊",
	["Your first pet"] = "你的第一只宠物",
	["Your own pet at 10: three practice tames with a {item:15908} teach {spell:1515}, then {spell:5149}."] = "10级获得自己的宠物：用{item:15908}完成三次驯服练习，学会{spell:1515}，然后学会{spell:5149}。",
	["{npc:10090} in {zone:1455}"] = "{npc:10090}，在{zone:1455}",
	["{npc:10090}, the pet trainer, stands in the {object:32390} in {zone:1455}'s {object:32359}, by the hunter trainers."] = "{npc:10090}，宠物训练师，站在{zone:1455}的{object:32359}里的{object:32390}内，就在猎人训练师旁。",
	["{npc:1231} in {area:131}"] = "{npc:1231}，在{area:131}",
	["{npc:1231}: the first {item:15908}"] = "{npc:1231}：第一根{item:15908}",
	["{npc:251507} in {area:87}"] = "{npc:251507}，在{area:87}",
	["{npc:251507}: the first {item:15908}"] = "{npc:251507}：第一根{item:15908}",
	["{npc:252389} in {area:16638}"] = "{npc:252389}，在{area:16638}",
	["{npc:252389} stands with the trainers by {area:16638}'s west gate, {npc:254411} beside her."] = "{npc:252389}和训练师们一起站在{area:16638}西门旁，{npc:254411}就在她身边。",
	["{npc:252389}: the first {item:15908}"] = "{npc:252389}：第一根{item:15908}",
	["{npc:254411}, beside her: {spell:5149}"] = "她身边的{npc:254411}：{spell:5149}",
	["{npc:258930}, beside her: {spell:5149}"] = "{npc:258930}，在她旁边：{spell:5149}",
	["{npc:3601} in {area:186}"] = "{npc:3601}，在{area:186}",
	["{npc:3601}: the first {item:15908}"] = "{npc:3601}：第一根{item:15908}",
	["{npc:4146} in {zone:1457}"] = "{npc:4146}，在{zone:1457}",
	["{quest:6063} (Alliance)"] = "{quest:6063}（联盟）",
	["{spell:1515} works like the rod: a beast of your level or lower, a channel you must not move during, the beast hitting you all the while. A pet keeps the level you tame it at and levels up with you; it can never be above your level, so tame one close to yours. Each family has its own ability on Forever (a boar's Charge, for example). For levelling, a cat hits hardest (Claw and {spell:17253}) and a boar takes more punishment."] = "{spell:1515}的用法和魔杖一样：目标须是与你同级或更低级的野兽，引导期间不能移动，野兽会一直攻击你。宠物会保持你驯服它时的等级，并随你一起升级；它永远不会高于你的等级，所以抓一只等级接近你的。在Forever上每个科系都有自己的技能（比如野猪的冲锋）。练级时，猫科伤害最高（爪击与{spell:17253}），野猪则更耐打。",
	["{spell:1584}: open your spellbook, cast {spell:1584} and click a food your pet's family eats (the pet's tooltip lists them: cats eat meat and fish, boars almost anything). Raw meat looted from beasts counts. To buy: Toddrick the butcher in {area:87}, Jaeana in {zone:1457} and the innkeepers on {zone:2521} sell meat; the innkeepers of {area:131} and {area:186} sell bread. Food near the pet's level makes it happiest; much lower food gives about half. You cannot feed in combat."] = "{spell:1584}：打开法术书，施放{spell:1584}，然后点击一份你宠物科系会吃的食物（宠物提示里会列出：猫科吃肉和鱼，野猪几乎什么都吃）。从野兽身上拾取的生肉也算。购买：{area:87}的屠夫托德里克、{zone:1457}的贾安娜和{zone:2521}上的旅店老板卖肉；{area:131}和{area:186}的旅店老板卖面包。食物等级接近宠物等级时它最快乐；食物低太多只能得到大约一半效果。战斗中不能喂食。",
	["{spell:5149} (spellbook, General tab) teaches your current pet the abilities you know. To learn a new ability or rank: leave your pet with a stable master (Erma in {area:87}, {npc:9980} in {area:131}, Seriadne in {area:186}, {npc:265756} on {zone:2521}), tame a beast that has it (its pet spellbook tab shows what it knows), use the ability in fights until the game says you learned it, then take your own pet back and teach it with {spell:5149}. A pet holds four active abilities at most."] = "{spell:5149}（法术书，通用页）会把你已学会的技能教给当前宠物。要学新技能或更高等级：把宠物寄放在兽栏管理员处（{area:87}的厄玛、{area:131}的{npc:9980}、{area:186}的塞丽亚德妮、{zone:2521}上的{npc:265756}），驯服一只拥有该技能的野兽（它的宠物法术书页会显示它会什么），在战斗中反复使用该技能直到游戏提示你已学会，然后接回自己的宠物并用{spell:5149}教它。宠物最多同时拥有四个主动技能。",
	["{spell:883}, {spell:2641} and {spell:982} are in your spellbook now; {spell:136} comes from your trainer at 12. A dead pet needs {spell:982}; one that is away more than about 100 yards is dismissed and comes back with {spell:883}."] = "{spell:883}、{spell:2641}和{spell:982}现在已在你的法术书里；{spell:136}会在12级时由训练师教你。死掉的宠物需要{spell:982}；离你超过约100码的宠物会被解散，用{spell:883}召回。",
}

G["forever/class/mage/astral-knot-garment"] = {
	["A robe or a blouse for Alliance mages in their late 20s."] = "为二十多级的联盟法师准备的长袍或短衫。",
	["Back to Andromath"] = "回到高阶巫师安多玛斯那里",
	["Carrion Recluses"] = "食腐独行蛛",
	["Head east through {zone:1429} into Redridge, or fly to {area:69}. The {area:96} stands alone in the east of the zone. Climb to the very top floor (not the one below): the treatise is the book sticking out of the shelf where the stairs come up. Two gnoll dogs and a gnoll caster guard the shelf; the dogs' {spell:2691} interrupts the click, so fight them on the stairs out of their sight. Morganth (level 26 elite) stands across the top floor: you do not need him, keep to the left edge of the ramp so he stays put. The book is back two seconds after anyone takes it. If you die, your ghost can run up and come back to life beside it."] = "向东穿过{zone:1429}进入赤脊山，或飞往{area:69}。{area:96}孤立在区域东部。爬到最高层（不是下面那层）：论文就是从楼梯上来处书架上露出的那本书。两只豺狼人猎犬和一名豺狼人施法者看守书架；猎犬的{spell:2691}会打断点击，所以在楼梯上避开它们视线战斗。摩根斯（26级精英）站在顶层对面：你不需要他，贴着斜坡左边缘走，让他待在原地。任何人拿走书后两秒书就会刷新。如果你死了，你的鬼魂可以跑上去，在书旁复活。",
	["Mage"] = "法师",
	["The {area:96}"] = "{area:96}",
	["You do not need a letter: at 26 climb the Wizard's Sanctum, the violet tower of {zone:1453}'s {object:2101}. {npc:5694} waits on the spiral walkway, just past the door of the portal room near the top, and has the quest for you. ({npc:5497} may also offer you {npc:5694}, the pointer quest; it is only a pointer and you can skip it.)"] = "你不需要信：26级时爬上巫师圣殿，即{zone:1453}的{object:2101}中的紫色高塔。{npc:5694}在螺旋回廊上等候，就在靠近顶部的传送门房间门外，会给你任务。（{npc:5497}也可能把{npc:5694}——指引任务——交给你；它只是指引，可以跳过。）",
	["{area:492} in western {zone:1431}: the six Carrion Recluses (level 25-26, green, {spell:3609}) walk the graves, the central statue and the riverbank, and every one drops a silk; they come back after 5 minutes. The Black Widow Hatchlings (24-25) on the slopes east of the cemetery drop it about one time in six, so mix them in while you wait. {npc:522}, a level 35 elite skeleton, walks the cemetery: watch for him."] = "{zone:1431}西部的{area:492}：六只食腐隐士（25-26级，绿色，{spell:3609}）在坟墓、中央雕像和河岸游荡，每只都会掉落一块丝绸；5分钟后刷新。墓园东边斜坡上的黑寡妇幼蛛（24-25级）约六次掉一次，所以等待时可以混着刷。35级精英骷髅{npc:522}在墓园巡逻：小心他。",
	["{npc:1309} works at {object:23296} in the {object:2101}. The robe gives intellect, stamina and spirit; the blouse more intellect and stamina but no spirit."] = "{npc:1309}在{object:2101}内的{object:23296}处工作。长袍提供智力、耐力和精神；上衣提供更多智力和耐力，但没有精神。",
	["{npc:5144} teaches mages in {zone:1455}'s {object:32362}. Take the {area:2257} from {object:171524} to {zone:1453} afterwards."] = "{npc:5144}在{zone:1455}的{object:32362}教导法师。之后从{object:171524}乘{area:2257}前往{zone:1453}。",
	["{npc:5497} stands at the top of the Wizard's Sanctum, the violet tower of the {object:2101}; the portal near the top of the spiral ramp takes you to her."] = "{npc:5497}站在巫师圣殿的顶部，即{object:2101}的紫色高塔；螺旋斜坡靠近顶部的传送门会把你送到她那里。",
	["{npc:5694} (Skyborne)"] = "{npc:5694}（天裔）",
	["{quest:1939} waits on the spiral walkway of the Wizard's Sanctum, just past the door of the portal room as you walk down from the trainers."] = "{quest:1939}在巫师圣殿的螺旋回廊上等候，就在你从训练师那里往下走时经过的传送门房间门外。",
}

G["forever/class/mage/manaweave-robe"] = {
	["A robe at 15 for Alliance mages, from {zone:1453} and {zone:1432}."] = "联盟法师15级时的长袍，来自{zone:1453}和{zone:1432}。",
	["Any humanoid drops {item:2589}, and the Tunnel Rats in the {area:149} drop it while you gather the gems; the Auction House in the {object:2096} sells it. You hand in ten."] = "任何人形怪都会掉落{item:2589}，{area:149}里的隧道鼠在你采集宝石时也会掉；{object:2096}的拍卖行有售。你需要交十个。",
	["Back to {npc:5497}"] = "回到{npc:5497}那里",
	["Back to {zone:1453} by the tram. {npc:1309} works at {object:23296} in the {object:2101}."] = "乘地铁回到{zone:1453}。{npc:1309}在{object:2101}的{object:23296}工作。",
	["Mage"] = "法师",
	["Rift Spawn"] = "裂隙生物",
	["Take the {area:2257} to {zone:1455}, then the road east through the South Gate tunnel into {zone:1432}. The {area:149} is at the north end of the loch, north of {area:144}; Tunnel Rat kobolds hold it. The gems come only from the tall stacked {object:271} (the cursor shows a cog over them; single boxes hold nothing): every crate gives one, there are fourteen and they come back after 3 to 5 minutes. You may have to go as deep as the end chamber for six. The same crates serve the dwarves' Filthy Paws quest."] = "乘{area:2257}到{zone:1455}，然后沿路向东，穿过南门隧道进入{zone:1432}。{area:149}在湖的北端、{area:144}以北；隧道鼠狗头人占据那里。宝石只来自堆叠的{object:271}（鼠标指针移到上面会显示齿轮；单个箱子什么都没有）：每个木箱给一颗，共十四个，3到5分钟后刷新。为了六颗，你可能得深入到最后面的房间。同样的木箱也用于矮人的“肮脏的爪子”任务。",
	["The {area:149}"] = "{area:149}",
	["{item:7247}, on the stunned {npc:6492}"] = "{item:7247}，在昏迷的{npc:6492}身上",
	["{npc:328} is the {area:87} mage trainer, upstairs in the Lion's Pride Inn."] = "{npc:328}是{area:87}的法师训练师，在狮王之傲旅店楼上。",
	["{npc:5497} stands at the top of the Wizard's Sanctum, the violet tower of the {object:2101}: climb the spiral ramp and take the portal near the top. The {item:7247} and the {item:7308} lie on the table behind her (both come back 5 minutes after someone takes them). You hand both in at the end, so keep them."] = "{npc:5497}站在巫师圣殿顶端，即{object:2101}的紫色高塔：沿螺旋坡道爬到顶上，用靠近顶部的传送门。{item:7247}和{item:7308}放在她身后的桌上（被人拿走后都会在5分钟后刷新）。两者最后都要交上去，所以都留着。",
	["{npc:6492}, down to the stun"] = "{npc:6492}，打到昏迷为止",
	["{npc:7312} teaches mages in {zone:1455}'s {object:32362}. Take the {area:2257} from {object:171524} to {zone:1453} afterwards."] = "{npc:7312}在{zone:1455}的{object:32362}教导法师。之后从{object:171524}乘{area:2257}前往{zone:1453}。",
	["{object:2169} is the tavern in the {object:2101}. Read the {item:7308} inside to make the invisible Rift Spawns (level 16-17) show: in the basement it brings out one, on the balcony or in the kitchen two, in the main room or by the door three, so read it downstairs. They hit hard and break out of {spell:122} fast. Beat one down: it does not die but sits stunned with a spiral over its head; use the {item:7247} on it while it is stunned, then click the {item:7292} it leaves on the floor (clicking before it appears wastes a charge). You need three, and the cantation works only once every 5 minutes (logging out does not reset it), so plan on three rounds."] = "{object:2169}是{object:2101}里的酒馆。在里面阅读{item:7308}，让隐形的裂隙生物（16-17级）现形：在地下室读到会引出一只，在阳台或厨房读到引出两只，在主厅或门旁读到引出三只，所以要在楼下读。它们攻击很疼，而且很快就能挣脱{spell:122}。打倒一只：它不会死，而是头顶螺旋、昏迷地坐着；趁它昏迷时对它使用{item:7247}，然后点击它落在地上的{item:7292}（在它出现前点击会浪费一次充能）。你需要三只，而吟唱每5分钟才能生效一次（登出不会重置），所以按三轮准备。",
}

G["forever/class/mage/staff-or-orb-alliance"] = {
	["A staff or an off-hand orb at 10 from your home town's mage trainer; Skyborne add a wand."] = "10级时在主城的法师训练师处获得一根法杖或一个副手宝珠；天行者额外获得一根魔杖。",
	["At 10 {npc:1228}, the {area:131} mage trainer in the {area:2102}, sends you to {npc:5144} in {zone:1455}. Taking it shuts out {npc:5497}'s {quest:1861}; you get one staff-or-orb quest. (A Gnome who took {npc:328}'s quest in {area:87} instead follows the {quest:1861} steps; a Human who took this one, the Gizmonitor steps.)"] = "10级时，{area:2102}中{area:131}的法师训练师{npc:1228}派你去找{zone:1455}的{npc:5144}。接受了它，{npc:5497}的{quest:1861}就不会出现；你只能做一条法杖或宝珠任务。（若侏儒在{area:87}接了{npc:328}的任务，则改走{quest:1861}的步骤；若人类接了这条，则走基兹莫尼特的步骤。）",
	["At 10 {npc:252373}, the {area:16638} mage trainer, sends you to {npc:256507}, the staff merchant a few steps away in the same town."] = "10级时，{area:16638}的法师训练师{npc:252373}会让你去找{npc:256507}，那是同镇几步之外的杖类商人。",
	["At 10 {npc:328}, the {area:87} mage trainer, upstairs in the Lion's Pride Inn, sends you to {npc:5497} in {zone:1453}. Taking it shuts out {npc:5144}'s quest in {zone:1455}; you get one staff-or-orb quest."] = "10级时，狮王之傲旅店楼上的{area:87}法师训练师{npc:328}会让你去找{zone:1453}的{npc:5497}。接受了它，{zone:1455}的{npc:5144}的任务就不会出现；你只能做一条法杖或宝珠任务。",
	["Back to {npc:256507}"] = "回到{npc:256507}",
	["Back to {npc:5144}"] = "回到{npc:5144}",
	["Back to {npc:5497}"] = "回到{npc:5497}那里",
	["Back up the Wizard's Sanctum and through the portal. The orb is an off-hand for a one-hand weapon; the staff is a two-hander."] = "回到巫师圣殿上层，穿过传送门。宝珠是单手武器的副手；法杖是双手武器。",
	["Follow the road north into {zone:1453} and west to the {object:2101}. {npc:5497} stands at the top of the Wizard's Sanctum, the tall violet tower: climb the spiral ramp and step into the portal near the top, which puts you beside her. She hands you {item:7207}. Skyborne mages take {quest:1861} from her when they first reach {zone:1453}, at about 15."] = "沿路向北进入{zone:1453}，再向西到{object:2101}。{npc:5497}站在巫师圣殿顶部，那座高大的紫色塔：沿螺旋坡道向上，走进顶部的传送门，就会到她身旁。她交给你{item:7207}。天裔法师第一次到{zone:1453}时（约15级）会从她那里接{quest:1861}。",
	["Head west along the road to {area:133}. Just north of its entrance stand two huts; the toolbox is in the taller, eastern one, the hut with the lift: a small grey box on the ground floor, half under the table beside the lift. Leper Gnomes (level 8) guard the huts: pull them singly. There is only one toolbox and it takes 15 minutes to come back after someone opens it, so wait nearby if it is gone."] = "沿路向西前往{area:133}。入口正北有两座小屋；工具箱在较高、靠东的那座，也就是带升降机的小屋：一楼的一只灰色小盒子，一半在升降机旁的桌子下面。麻风侏儒（8级）看守着小屋：一只一只拉。工具箱只有一个，被人打开后要15分钟才会重新出现，所以如果它不见了就在附近等。",
	["Leave {zone:1453} by the main gate and head south-west to the waterfall that feeds {quest:1861}. Wade in under the falling water to the rock behind it and use {item:7207} there (a 5 second cast); it fails anywhere else. Level 10 Defias casters stand on the rocks either side of the falls and shoot from range: pull them one at a time or fill the flask from the water."] = "从正门离开{zone:1453}，向西南前往{quest:1861}所对应的瀑布。蹚进落水下方，走到瀑布后的岩石，在那里使用{item:7207}（5秒施法）；在其他任何地方都会失败。10级迪菲亚施法者站在瀑布两侧的岩石上远程射击：一只一只拉，或者直接从水里灌满瓶子。",
	["Ley or {item:9514} or Orb (Alliance)"] = "魔网、{item:9514}或宝珠（联盟）",
	["Mage"] = "法师",
	["The Windstone Formations"] = "Windstone Formation",
	["The bough lies on the ground among the Windstone Formations, the wind shrine on the rise west of Fillion's camp, south of {area:16636}. It does not sparkle, so look at the ground by the stones; there are two spots for it."] = "树枝躺在风石阵之间的地面上，那是菲里昂营地以西高地上的风之神龛，{area:16636}以南。它不会闪光，所以在石头旁的地面上找；有两个可能的位置。",
	["The {quest:1861} waterfall"] = "{quest:1861}瀑布",
	["{item:7207}, under the falls"] = "{item:7207}，瀑布下",
	["{npc:256507}'s quest is open to Human and Gnome mages too, if you ever visit {area:16638} on {zone:2521}, the Skyborne home: {npc:252373}, the town's mage trainer, sends you to {npc:256507} next door, who wants a {item:262668} from the ground by the Windstone Formations south of {area:16636}, for the {item:263430}. It does not shut out the staff or the orb."] = "{npc:256507}的任务也向人类和侏儒法师开放，只要你有一天到访天裔的家园{zone:2521}上的{area:16638}：镇上的法师训练师{npc:252373}会让你去找隔壁的{npc:256507}，他要一个来自{area:16636}以南风石阵旁地面的{item:262668}，用来换{item:263430}。它不会关闭法杖或宝珠任务。",
	["{npc:256507}'s wand (optional)"] = "{npc:256507}的魔杖（可选）",
	["{npc:5144} teaches mages in the {object:32362}, at the back of {zone:1455} past the {object:32386}."] = "{npc:5144}在{object:32362}里教法师，那里是{zone:1455}的后部，穿过{object:32386}就到。",
	["{npc:5144}: {item:7507} or {item:9514}"] = "{npc:5144}：{item:7507}或{item:9514}",
	["{npc:5497}: {item:7508} or {item:9513}"] = "{npc:5497}：{item:7508}或{item:9513}",
	["{quest:1861} (the next steps) waits for you with {npc:5497} in {zone:1453}, at about 15."] = "{quest:1861}（后续步骤）会在{zone:1453}的{npc:5497}那里等你，约15级。",
}

G["forever/class/mage/teleports-alliance"] = {
	["At 20 go to the Wizard's Sanctum, the violet tower of {zone:1453}'s {object:2101}. {npc:2485}, the portal trainer, stands at the very top: climb the spiral ramp and take the portal near the top. She teaches {spell:3561} for 20 silver. Every teleport burns one {item:17031} (10 silver at any reagent vendor; {npc:1308} sells them at the foot of the tower), so carry a few."] = "20级时去巫师圣殿，即{zone:1453}的{object:2101}中的紫罗兰高塔。传送门训练师{npc:2485}就在最顶层：沿螺旋坡道爬上去，乘靠近顶部的传送门。她以20银教授{spell:3561}。每次传送消耗一个{item:17031}（任意施法材料商10银；{npc:1308}在塔底出售），所以多带几个。",
	["At 30. Take the boat from {area:17203} to {area:442} in {zone:1439}, then the boat to {area:702} and the pink portal up into {zone:1457}. {npc:4165}, the portal trainer, teaches {spell:3565} for 80 silver."] = "30级时。从{area:17203}乘船到{zone:1439}的{area:442}，再乘船到{area:702}，然后走粉色传送门进入{zone:1457}。传送门训练师{npc:4165}以80银教授{spell:3565}。",
	["At 40 the portal trainers teach the portals: a gateway your whole group can step through, for 1 gold 50 silver each. Each portal burns one {item:17032} (20 silver at any reagent vendor). {npc:2485} has {spell:10059} at the top of the Wizard's Sanctum; then the tram to {npc:2489} in {zone:1455}'s {object:32362} for {spell:11416}."] = "40级时传送门训练师会教传送门：一道整队都能穿过的传送门，每个1金50银。每道传送门消耗一个{item:17032}（任意施法材料商20银）。{npc:2485}在巫师圣殿顶层教{spell:10059}；然后乘地铁到{zone:1455}的{object:32362}找{npc:2489}学{spell:11416}。",
	["At 50 {npc:4165} in {zone:1457} teaches the last one, {spell:11419}, for 3 gold 20 silver. Use your {spell:3565} to get there."] = "50级时{zone:1457}的{npc:4165}教授最后一个{spell:11419}，3金20银。用你的{spell:3565}过去。",
	["Mage"] = "法师",
	["Portals to {zone:1453} and {zone:1455}"] = "通往{zone:1453}和{zone:1455}的传送门",
	["Take the {area:2257} from {zone:1453}'s {object:28027} to {zone:1455}. {npc:2489}, the portal trainer, stands with the mage trainers in the {object:32362} at the back of the city: {spell:3562}, 20 silver."] = "从{zone:1453}的{object:28027}乘{area:2257}到{zone:1455}。传送门训练师{npc:2489}与法师训练师一起站在城市后部的{object:32362}里：{spell:3562}，20银。",
	["Teleports and Portals (Alliance)"] = "传送术与传送门（联盟）",
	["Your city teleports at 20 and 30 and the group portals at 40 and 50, from each city's portal trainer."] = "20级和30级学习主城传送术，40级和50级学习小队传送门，均可在各主城的传送门训练师处学习。",
	["{item:17031}, 10s each"] = "{item:17031}，每个10银",
	["{item:17032}, 20s each"] = "{item:17032}，每个20银",
}

G["forever/class/paladin/cloak-of-the-divine-storm"] = {
	["A rare cloak at 30 from the old {spell:407778} story; for now only Alliance paladins can finish it."] = "30级可获得的一件稀有披风，出自旧的{spell:407778}任务线；目前只有联盟圣骑士能完成它。",
	["Back to {npc:3663} at {area:413} in western {zone:1440}, across the whole zone."] = "回到{zone:1440}西部{area:413}的{npc:3663}处，要横穿整个区域。",
	["Back to {npc:5495}"] = "回到{npc:5495}处",
	["Climb to the top of the {area:444} in northern {zone:1439}. The Dark Strand Fanatics around it are easy (level 16-17), but four Dark Strand Voidcallers (level 28-29) stand in the tower on the way to the orb: each calls a voidwalker and casts {spell:686} from range. At 22-25 bring a friend or two, pull them one at a time and step behind a wall so they have to come to you. Loot the Strange Orb at the top: it gives you the Althalaxx Orb; right-click it to start the quest. Keep the orb in your bags until the {object:409311}: three later quests need it."] = "爬到{zone:1439}北部{area:444}的顶端。周围的暗滩狂热者很好对付（16-17级），但通往法球的塔里有四个暗滩虚空召唤者（28-29级）：每个都会召唤一个虚空行者并从远处施放{spell:686}。22-25级时带一两个朋友，一次拉一个，并躲到墙后，迫使他们走过来。在顶端拾取奇怪的法球：它会变成奥萨拉克斯法球；右键点击以开启任务。把法球留在包里直到{object:409311}：之后有三个任务需要它。",
	["Motes of Mannoroth"] = "玛诺洛斯微粒",
	["Paladin"] = "圣骑士",
	["Strange Orb atop the {area:444}: right-click the Althalaxx Orb it gives"] = "{area:444}顶端的Strange Orb：右键点击它给的奥萨拉克斯宝珠",
	["The Blackrock Summoners, Champions and Trackers (level 22-25, not elite) camp in the north-west of Redridge and drop the {item:209778}; you need 14. Two elite Blackrock Shadowcasters (22-23) stand at the cave mouth at the camp's east end: pull around them. The Blackrock camps east of {area:69} drop the salt too, but their Shadowcasters, Sentries and Hunters are elite (level 21-24), and so is {npc:334} (26): stay in the north-west."] = "黑石召唤者、勇士和追踪者（22-25级，非精英）在赤脊山西北部扎营，掉落{item:209778}；你需要14个。两个精英黑石暗影法师（22-23级）站在营地东端的洞口：绕开他们拉怪。{area:69}以东的黑石营地也掉这种盐，但那里的暗影法师、哨兵和猎人是精英（21-24级），{npc:334}（26级）也是：留在西北部。",
	["The Strange Orb"] = "Strange Orb",
	["The {object:409311}"] = "{object:409311}",
	["The {object:409311} stands at the east end of {area:435}. Hand in the motes at the spear with the Althalaxx Orb in your bags: the orb shatters, and the {object:409315} beside it starts the last quest."] = "{object:409311}立在{area:435}东端。带着奥萨拉克斯法球在长矛处交付微粒：法球会碎裂，旁边的{object:409315}会开启最后一个任务。",
	["from the {object:409315}"] = "来自{object:409315}",
	["{area:435} is in south-east {zone:1440}, east of {area:431} (a Horde camp: go round it). The Mannoroc Lashers, Searing Infernals, Felguards and Legion Hounds (level 29-30, not elite) drop the Motes of Mannoroth; you need 12. Below about 27 they are hard alone: come with a second player or later. Felguards knock you down, Lashers cast {spell:686} and {spell:348}, Infernals keep a fire shield up. They respawn in five minutes."] = "{area:435}位于{zone:1440}东南、{area:431}以东（部落营地：绕过去）。玛诺洛克鞭笞者、灼热的地狱火、恶魔卫士和军团猎犬（29-30级，非精英）掉落玛诺洛斯微粒；你需要12个。低于约27级时单人会很难：带另一名玩家或以后再来。恶魔卫士会把你击倒，鞭笞者施放{spell:686}和{spell:348}，地狱火保持火焰护盾。它们五分钟刷新。",
	["{npc:3663} stands at {area:413} in western {zone:1440}, south of the {zone:1439} road. He sends you to {zone:1453} with the orb."] = "{npc:3663}站在{zone:1440}西部的{area:413}，在{zone:1439}道路以南。他让你带着法球前往{zone:1453}。",
	["{npc:5492} stands in the Cathedral of Light; she sends you to a warlock for a second opinion."] = "{npc:5492}站在圣光大教堂；她让你去找一名术士求证。",
	["{npc:5495}, the warlock trainer, is in the {object:2101}'s warlock sanctum, down in the {object:2164}'s cellar. She wants 14 {item:209778} to read the orb."] = "术士训练师{npc:5495}在{object:2101}的术士圣所里，位于{object:2164}的地下室。她需要14个{item:209778}来解读法球。",
}

G["forever/class/paladin/holy-mightstone"] = {
	["A one-use stone that makes you much stronger against undead for 10 minutes; the old item choice may be gone in Forever."] = "一次性石头，10分钟内大幅增强你对亡灵的战斗力；在Forever服务器中，旧的物品选择可能已经取消。",
	["At 50 {npc:5149}, the paladin trainer in the {object:32362}, sends you to {area:3197} in the {zone:1422}. {npc:928} in {zone:1453} gives the same quest."] = "50级时，{object:32362}里的圣骑士训练师{npc:5149}会让你去{zone:1422}的{area:3197}。{zone:1453}的{npc:928}给同样的任务。",
	["At 50 {npc:928}, the paladin trainer in the Cathedral of Light, sends you to {area:3197} in the {zone:1422}. {npc:5149} in {zone:1455} gives the same quest."] = "50级时，光明大教堂的圣骑士训练师{npc:928}会让你去{zone:1422}的{area:3197}。{zone:1455}的{npc:5149}给同样的任务。",
	["Back to Ashlam in {area:3197}: he forges the {item:20620}. Look at the reward window before you hand in: Classic also offered the {item:20505}, the {item:20504} or the {item:20512}, and Forever's notes say that choice may be gone. Use the stone before a fight against undead ({area:2279}, {area:2057}): it lasts ten minutes and is gone after one use."] = "回到{area:3197}的阿什兰处：他锻造{item:20620}。交任务前先看奖励窗口：经典版还会提供{item:20505}、{item:20504}或{item:20512}，而Forever的说明称该选择可能已经取消。在与亡灵战斗前使用石头（{area:2279}、{area:2057}）：它持续十分钟，用一次就消失。",
	["Back to {area:3197}. Ashlam needs the voodoo of the {area:1417}'s trolls for the stone."] = "回到{area:3197}。阿什兰需要{area:1417}巨魔的巫毒来制作石头。",
	["Kill the Scourge of the {zone:1422} with the Commission on: skeletons, ghouls and cultists (level 50-58) drop a {item:12840} about two kills in five. {area:197}, just east of {area:3197} around {area:196}, is the closest farm. Avoid the Flesh Golems that patrol the fields; Skeletal Guardians cast {spell:120} and {spell:1449} up close, Dark Summoners run for help at low health."] = "戴着委任徽章在{zone:1422}杀天灾：骷髅、食尸鬼和教徒（50-58级）约五次击杀掉两个{item:12840}。{area:197}，就在{area:3197}以东、{area:196}周围，是最近的刷怪点。避开在田野巡逻的血肉傀儡；骷髅守卫会近身施放{spell:120}和{spell:1449}，黑暗召唤者低血量时会逃跑求援。",
	["Minion's Scourgestones"] = "爪牙的天灾石",
	["Paladin"] = "圣骑士",
	["The Scourge drop no Scourgestones unless you wear an {item:12846}. {npc:10840} gives you one through her quest, {item:12846}, which you hand in straight away (if you already have one from {area:2268}, wear that). Equip it in a trinket slot: it shows as a buff that never runs out. Keep it on until you have 20 stones."] = "除非戴着{item:12846}，否则天灾不会掉落天灾石。{npc:10840}会通过她的任务给你一个{item:12846}，接到后立刻交还（如果你已经从{area:2268}拿到一个，就戴那个）。把它装备在饰品栏：它会显示为一个永不消失的增益。一直戴着，直到你攒够20块石头。",
	["The {area:1417}"] = "{area:1417}",
	["The {item:12846}"] = "{item:12846}",
	["{area:1477}, the {area:1417}, lies in the {area:74} in eastern {zone:1435}: go up the ruin's stairs, dive into the flooded hall and follow the stairs down to the portal. It is a dungeon for a group of five at about 50-55. Six elite troll minibosses (level 51-52) stand on the balconies around the temple's great round room, each behind a pack of elites on its side path. Each drops its feather every time: Gasher and {npc:5716} the Amber, Hukku and Mijan the Blue, Zolo and Loro the Green; you need all six. Hukku calls guardians and throws Shadow Bolt Volleys, Mijan heals: kill them first."] = "{area:1477}，即{area:1417}，位于{zone:1435}东部{area:74}里：走上废墟的台阶，潜入被水淹没的大厅，沿楼梯向下走到传送门。这是一个约50-55级五人小队的地下城。六个精英巨魔小头目（51-52级）站在神庙大圆厅周围的阳台上，各自守在其侧路的一群精英之后。它们每次都会掉落自己的羽毛：加舍尔和琥珀色的{npc:5716}、胡库和蓝色的米詹、佐洛和绿色的洛罗；六根都需要。胡库会召唤守卫并投掷暗影箭雨，米詹会治疗：先杀它们。",
	["{area:3197} is the Alliance camp at the south end of the {zone:1422}, north of the Alterac foothills. {npc:10838} commands it; {npc:10840} stands in the same camp."] = "{area:3197}是{zone:1422}南端的联盟营地，在奥特兰克丘陵以北。{npc:10838}负责指挥；{npc:10840}也在同一营地。",
	["{item:12840} x20"] = "{item:12840} x20",
	["{item:12846}: equip it"] = "{item:12846}：装备它",
	["{item:20606} x2: Gasher, {npc:5716}"] = "{item:20606} x2：加舍尔、{npc:5716}",
	["{item:20607} x2: Hukku, Mijan"] = "{item:20607} x2：胡库、米詹",
	["{item:20608} x2: Zolo, Loro"] = "{item:20608} x2：佐洛、洛罗",
	["{npc:1854} keeps watch at {area:196} on {area:197}, east of the camp. He turns your 20 stones into one {item:20612}: keep it."] = "{npc:1854}在营地以东{area:197}的{area:196}守望。他会把你的20块天灾石合成一个{item:20612}：留着它。",
}

G["forever/class/paladin/tome-of-divinity"] = {
	["At 12 {npc:5149}, the paladin trainer in {zone:1455}'s {object:32362}, sends you upstairs to {npc:6179}. The errand is optional, a little XP: {npc:1232} in {area:131} and {npc:928} in {zone:1453} give the same one (taking one closes the others), and {npc:6179} starts the chain without it."] = "12级时，{zone:1455}的{object:32362}里的圣骑士训练师{npc:5149}会派你上楼去找{npc:6179}。这个差事是可选的，能给一点经验：{area:131}的{npc:1232}和{zone:1453}的{npc:928}给同样的任务（接其中一个会关闭其他），而且不接它{npc:6179}也会开启这条任务链。",
	["At 12 {npc:927}, the paladin trainer in {area:87}, sends you to {npc:6171} in {zone:1453}'s Cathedral of Light. The errand is optional, a little XP: {npc:5149} in {zone:1455} gives the same one (taking one closes the other), and {npc:6171} starts the chain without it."] = "12级时，{area:87}的圣骑士训练师{npc:927}会让你去{zone:1453}光明大教堂的{npc:6171}。这个差事是可选的，能给一点经验：{zone:1455}的{npc:5149}给同样的任务（接其中一个会关闭另一个），而且不接它{npc:6171}也会开启这条任务链。",
	["Back to the Cathedral of Light: {npc:6173} takes the script, {npc:6171} teaches you {spell:7328}."] = "回到光明大教堂：{npc:6173}收下名册，{npc:6171}教你{spell:7328}。",
	["Back to the Cathedral. {npc:6171} gives you the {item:6866}; {npc:6173} lies wounded by the altar of the same hall. Keep the symbol: you need it on {npc:6172}. If you lose it, {npc:6171} gives you another (The {item:6866})."] = "回到大教堂。{npc:6171}给你{item:6866}；{npc:6173}受伤躺在同一座大厅的祭坛旁。留着这个符号：在{npc:6172}身上要用到。如果丢了，{npc:6171}会再给你一个（{item:6866}）。",
	["Back up to the {object:32386}: {npc:6178} takes the script, {npc:6179} teaches you {spell:7328}."] = "回到{object:32386}上层：{npc:6178}收下名册，{npc:6179}教你{spell:7328}。",
	["Back upstairs in the {object:32386}. {npc:6179} gives you the {item:6866}; her husband {npc:6178} rests on the same floor. Keep the symbol: you need it on {npc:6177}. If you lose it, {npc:6179} gives you another (The {item:6866})."] = "回到{object:32386}楼上。{npc:6179}给你{item:6866}；她的丈夫{npc:6178}在同一层休息。留着这个符号：在{npc:6177}身上要用到。如果丢了，{npc:6179}会再给你一个（{item:6866}）。",
	["Paladin"] = "圣骑士",
	["Right-click the {item:6775}"] = "右键点击{item:6775}",
	["Right-click the {item:6916}"] = "右键点击{item:6916}",
	["The Dark Iron Spies (level 9-11, twelve of them) sneak around the little house below the lake, just south of Narm; you see them from his hill. About one kill in two drops the {item:6847}. They run for help at low health: finish them or step back. They respawn in three minutes."] = "黑铁间谍（9-11级，共十二个）在湖下方的小屋周围潜行，就在纳姆以南；从他所在的山丘能看见它们。约两次击杀掉一个{item:6847}。它们低血量时会逃跑求援：杀掉它们或者后退。三分钟刷新。",
	["The Defias Rogue Wizards around the big stone tablet east of {npc:6172} carry the {item:6846}: about one kill in two drops it, but some players need many kills. They respawn in three minutes."] = "在{npc:6172}以东那座大石板周围，迪菲亚流氓巫师身上带着{item:6846}：约两次击杀掉一个，但有些玩家杀了很多次才出。三分钟刷新。",
	["The summons (Dwarf)"] = "召唤（矮人）",
	["The summons (Human)"] = "召唤（人类）",
	["The {item:6846}"] = "{item:6846}",
	["The {item:6847}"] = "{item:6847}",
	["The {item:6866}"] = "{item:6866}",
	["{item:2589} x10"] = "{item:2589} x10",
	["{item:6846}: Defias Rogue Wizards"] = "{item:6846}：迪菲亚流浪巫师",
	["{item:6847}: Dark Iron Spies"] = "{item:6847}：黑铁间谍",
	["{item:6866} on {npc:6172}'s body"] = "{item:6866}在{npc:6172}的尸体上",
	["{item:6866} on {npc:6177}'s body"] = "{item:6866}在{npc:6177}的尸体上",
	["{npc:6171} stands inside the Cathedral of Light. He hands you the {item:6775}: right-click it in your bags to start the next quest. If the book says the quest is already done, destroy it and ask {npc:6171} for a new copy. Bring 10 {item:2589} for the next step if you have it."] = "{npc:6171}站在光明大教堂里。他交给你{item:6775}：在背包里右键点击它来开始下一个任务。如果书上说该任务已完成，就销毁它，再找{npc:6171}要一份新的。如果手上有10块{item:2589}，下一步会用到。",
	["{npc:6171}, Cathedral of Light"] = "{npc:6171}，光明大教堂",
	["{npc:6172} lies dead on {area:56}, the island in {area:86} in eastern Elwynn, on top of one of the mounds around the stone circle. Target his body and use the {item:6866} to raise him, then speak to him. If another paladin just raised him, his body is back within about three minutes. The Defias Rogue Wizards on the island (level 9-10) cast {spell:116} from far off: they stand apart, so pull one at a time."] = "{npc:6172}死在{area:56}上，那是艾尔文东部{area:86}中的小岛，就在石阵周围一座土丘顶上。选中他的尸体并使用{item:6866}把他复活，然后与他交谈。如果刚有另一个圣骑士复活了他，他的尸体会在约三分钟内重新出现。岛上的迪菲亚流氓巫师（9-10级）会远程施放{spell:116}：它们站得分散，所以一只一只拉。",
	["{npc:6174} stands at a corner in the middle of the {object:2096}, outside a general goods store. She wants 10 {item:2589}: humanoids drop it (Riverpaw gnolls in {zone:1436} about every other kill, Defias and kobolds a little less), or buy it at the Auction House a few steps away in the {object:2096}."] = "{npc:6174}站在{object:2096}中部的一个转角，一家杂货店门外。她要10块{item:2589}：人形怪会掉落（{zone:1436}的河爪豺狼人约每两次击杀掉一个，迪菲亚和狗头人略少一些），或者在几步之外{object:2096}里的拍卖行购买。",
	["{npc:6175} walks the outer ring of the Commons, past the front gate, the bank and the Auction House. He wants 10 {item:2589}: humanoids drop it ({npc:1245} in {area:131} every time, Dark Iron Ambushers about two kills in five), or buy it at the Auction House on his ring."] = "{npc:6175}在平民区的外环走动，经过前门、银行和拍卖行。他要10块{item:2589}：人形怪会掉落（{area:131}的{npc:1245}每次都掉，黑铁伏击者约五次击杀掉两个），或者在他所在外环的拍卖行购买。",
	["{npc:6177} lies dead in {zone:1426}, not {zone:1432}: east past {area:131}, north-east of Ironband's compound, on the smallest of three little hills between {area:212} and the {object:147516} camp. Target his body and use the {item:6866} to raise him, then speak to him. If another paladin just raised him, his body is back within about three minutes."] = "{npc:6177}死在{zone:1426}，而不是{zone:1432}：向东经过{area:131}，在铁带营地东北，{area:212}与{object:147516}营地之间三座小丘中最矮的那座顶上。选中他的尸体并使用{item:6866}把他复活，然后与他交谈。如果刚有另一个圣骑士复活了他，他的尸体会在约三分钟内重新出现。",
	["{npc:6179} stands upstairs in the {object:32386}, in the {object:32362}: take the ramp at the back of the hall. She hands you the {item:6916}: right-click it in your bags to start the next quest. If the book says the quest is already done, destroy it and ask {npc:6179} for a new copy. Bring 10 {item:2589} for the next step if you have it."] = "{npc:6179}站在{object:32362}里{object:32386}的楼上：走大厅后部的坡道。她交给你{item:6916}：在背包里右键点击它来开始下一个任务。如果书上说该任务已完成，就销毁它，再找{npc:6179}要一份新的。如果手上有10块{item:2589}，下一步会用到。",
	["{npc:6179}, upstairs in the {object:32386}"] = "{npc:6179}，{object:32386}楼上",
	["{spell:7328} (Alliance)"] = "{spell:7328}（联盟）",
	["{spell:7328} at 12, the paladin's resurrection: an easy chain through your capital and its home zone."] = "12级学习{spell:7328}，圣骑士的复活技能：一条简单的任务链，途经你的主城及其所在地区。",
}

G["forever/class/paladin/verigans-fist"] = {
	["At 20 {npc:6179}, upstairs in the {object:32386} in the {object:32362}, gives you the {item:6776}. Right-click it: it sends you to {npc:6171} in {zone:1453}'s Cathedral of Light. Take the {area:2257} from {zone:1455} to {zone:1453}."] = "20级时，{object:32362}中{object:32386}楼上的{npc:6179}会给你{item:6776}。右键点击它：它会让你去{zone:1453}圣光大教堂的{npc:6171}处。乘{area:2257}从{zone:1455}到{zone:1453}。",
	["Back to the Cathedral of Light: {npc:6171} gives you the {item:9607} shield and teaches you {spell:5502}."] = "回到圣光大教堂：{npc:6171}给你{item:9607}盾牌，并教你{spell:5502}。",
	["Back to {npc:3649} in {area:442}: he purifies the gem."] = "回到{area:442}找{npc:3649}：他会净化宝石。",
	["Back to {npc:6241}"] = "回到{npc:6241}处",
	["Bring the four parts to {npc:6181} outside {zone:1455}. Accept his last quest and wait by him while he forges the mace at his anvil."] = "把四件部件带给{zone:1455}城外的{npc:6181}。接受他最后一个任务，并在他在铁砧上锻造战锤时守在他身旁。",
	["Goblin Woodcarvers, inside"] = "地精木匠，在副本内",
	["Paladin"] = "圣骑士",
	["Protect {npc:6182}: three waves"] = "保护{npc:6182}：三波",
	["Right-click the {item:6776}"] = "右键点击{item:6776}",
	["The Alliance paladin's rare two-handed mace for the 20s, with a shield and {spell:5502} on the way."] = "联盟圣骑士20多级的稀有双手锤，途中还能拿到一面盾牌和{spell:5502}。",
	["The Blackfathom naga in the flooded passages around the {area:2797} entrance, on {zone:1440}'s north-west coast, drop the {item:6995}: Tide Priestesses (level 20-21), Oracles (21-22) and Sea Witches (23-24), one in two. You do not need to enter the instance. All are elite: grouping up is encouraged; players solo them one at a time, with difficulty. They heal themselves, run for help at low health, satyrs stand near some, and the Sea Witches cast {spell:122} up close. Some players report no drop while in a raid group."] = "{zone:1440}西北海岸{area:2797}入口周围的水淹通道里，黑渊纳迦掉落{item:6995}：潮汐女祭司（20-21级）、神谕者（21-22级）和海巫（23-24级），约每两只掉一个。你不需要进入副本。它们全是精英：建议组队；玩家们通常一次单挑一只，但很困难。它们会自疗，残血时跑去求援，有些旁边站着萨特，海巫会近身施放{spell:122}。有玩家反映在团队中不掉落。",
	["The crate of ore sits outdoors in the middle of the Mo'grosh ogre camp in north-east {zone:1432}, beside a big tree and a broken wagon, between the caves. The camp holds about fifteen Mo'grosh ogres, elite (level 18-19), who knock you down and come back after five minutes: grouping up is encouraged; at 20-22 it needs a group of about three. The crate is back two seconds after each loot, so every paladin in the group gets one."] = "矿石箱露天放在{zone:1432}东北部莫格罗什食人魔营地的中央，在一棵大树和一辆破车旁，位于洞穴之间。营地约有十五个莫格罗什食人魔，精英（18-19级），会把你击倒并在五分钟后回来：建议组队；20-22级时大约需要三人小队。每次拾取后两秒箱子就会刷新，所以队伍里每个圣骑士都能拿到一个。",
	["The {item:6995}"] = "{item:6995}",
	["The {item:7083}"] = "{item:7083}",
	["{area:1581} is a group of five under {area:20}; the instance portal is at the bottom of the {area:20} mine. The Goblin Woodcarvers (elite, level 18-19) in the mast room with Sneed drop the lumber every time."] = "{area:1581}是{area:20}下方的一个五人副本；副本传送门在{area:20}矿坑底部。桅杆室里斯尼德身边的哥布林木雕师（精英，18-19级）每次都掉落木材。",
	["{area:1581}, in the {area:20} mine"] = "{area:1581}，在{area:20}的矿洞里",
	["{area:236} is a dungeon for a group of five in the low to mid 20s, in southern {zone:1421}, Horde land: a long trip for the Alliance, through the {zone:1437}, Arathi and {area:287}. The hammer lies on a crate across from the horses in the stables, early in the dungeon, at the far end of the courtyard before the ramp up; it is back five minutes after someone takes it."] = "{area:236}是适合20级出头到25级左右的五人地下城，位于{zone:1421}南部，属于部落领地：对联盟来说路途遥远，要穿过{zone:1437}、阿拉希和{area:287}。战锤在副本前段、上坡前的院子尽头，马厩里马匹对面的箱子上；有人拿走后五分钟刷新。",
	["{npc:3649} is in {area:442}. Take his quest before you hunt naga: the Kor Gem never drops without it."] = "{npc:3649}在{area:442}。猎杀纳迦前先接他的任务：没有任务时柯尔宝石绝不会掉落。",
	["{npc:6171} stands in the Cathedral of Light. Humans get the {item:6776} from him. Right-click the book to start its quest and hand it straight back to him."] = "{npc:6171}站在圣光大教堂。人类可以从他那里拿到{item:6776}。右键点击书本来开启它的任务，然后直接交还给他。",
	["{npc:6181} works outside the gates of {zone:1455}, not inside. He gives you {item:6996}: four parts, in any order. Keep the notes."] = "{npc:6181}在{zone:1455}城门外工作，不在城内。他给你{item:6996}：四件部件，顺序不限。保留笔记。",
	["{npc:6182}'s farmhouse stands on the south-west coast of {zone:1436}, south of {area:20}: take the path that runs south beside the {area:1581}' back exit. When you take her quest, she walks from her orchard to the house and three waves of Defias Raiders (level 17-18) attack: three, then four, then five. Fight close to her so they do not swarm her, and heal her when she drops. You get time to eat and drink between waves, and she heals to full. If you or {npc:6182} die, the quest fails: abandon it and take it again from her (she is back five minutes after dying). Players find it hard alone before about 24."] = "{npc:6182}的农舍在{zone:1436}西南海岸、{area:20}以南：走{area:1581}后出口旁向南的小路。接她的任务后，她会从果园走向农舍，三波迪菲亚袭击者（17-18级）会来袭：先三个，再四个，然后五个。靠近她战斗，免得他们围攻她；她血量下降时给她治疗。两波之间你有时间吃喝，她也会回满血。如果你或{npc:6182}死亡，任务失败：放弃任务再找她接（她死后五分钟回来）。玩家普遍觉得24级前单人很难。",
	["{npc:6241} is downstairs in the house of {area:144} that has a tailoring merchant outside. His quest only opens once you hold Jordan's."] = "{npc:6241}在{area:144}那栋外面有裁缝商人的房子楼下。只有你持有乔丹的部件后，他的任务才会开放。",
	["{npc:6241} turns the ore into {item:6993}, the part Jordan wants."] = "{npc:6241}把矿石变成{item:6993}，也就是乔丹想要的那件部件。",
	["{object:91138}, inside"] = "{object:91138}，在副本内",
	["{object:92420} crate"] = "{object:92420}箱子",
}

G["forever/class/priest/confounding-flash-and-contingency-plan"] = {
	["Any {quest:94820} letter goes to {npc:258785} in the {object:32386}, {zone:1455}'s {object:32362}."] = "任何{quest:94820}信件都交给{zone:1455}的{object:32362}内、{object:32386}中的{npc:258785}。",
	["Any {quest:94823} letter goes to {npc:258785} in the {object:32386}, {zone:1455}'s {object:32362}."] = "任何{quest:94823}信件都交给{zone:1455}的{object:32362}内、{object:32386}中的{npc:258785}。",
	["Any {quest:94825} letter goes to {npc:258785} in the {object:32386}, {zone:1455}'s {object:32362}."] = "任何{quest:94825}信件都交给{zone:1455}的{object:32362}内、{object:32386}中的{npc:258785}。",
	["Any {quest:94826} letter goes to {npc:258785} in the {object:32386}, {zone:1455}'s {object:32362}."] = "任何{quest:94826}信件都交给{zone:1455}的{object:32362}内、{object:32386}中的{npc:258785}。",
	["At 10 in {zone:1429}, {npc:377}, upstairs in the Lion's Pride Inn in {area:87}, hands you a {quest:94817} letter for {npc:258785} in {zone:1455}."] = "10级时在{zone:1429}，{area:87}狮王之傲旅店楼上的{npc:377}会交给你一封给{npc:258785}（位于{zone:1455}）的{quest:94817}信件。",
	["At 10 in {zone:1453}, {npc:376} at the altar of the Cathedral of Light hands you a {quest:94817} letter for {npc:258785} in {zone:1455} (the {area:2257} from the {object:28027})."] = "10级时在{zone:1453}，光明大教堂祭坛旁的{npc:376}会交给你一封给{npc:258785}（位于{zone:1455}）的{quest:94817}信件（乘{object:28027}的{area:2257}）。",
	["At 10, go to {npc:258785} in the {object:32386}, {zone:1455}'s {object:32362} (north-west of the city), right beside {npc:11406}: she gives {quest:94817} and takes it back at once. No letter needed. {quest:94817} confuses up to five enemies around you for 3 seconds (any damage wakes them) on a 2-minute cooldown: time to step back and heal, or to run."] = "10级时，前往{zone:1455}的{object:32362}内、{object:32386}中的{npc:258785}（城市西北），就在{npc:11406}旁边：她会给出{quest:94817}并立刻收回。不需要信。{quest:94817}使周围最多五名敌人迷惑3秒（任何伤害都会唤醒他们），冷却2分钟：用来后撤治疗或逃跑。",
	["At 10, {npc:1226}, the priest trainer inside the {area:2102} in {area:131}, hands you a {quest:94817} letter for {npc:258785} in {zone:1455}. {area:131} is on the road up to the city."] = "10级时，{area:131}的{area:2102}内的牧师训练师{npc:1226}会交给你一封给{npc:258785}（位于{zone:1455}）的{quest:94817}信件。{area:131}在通往城市的路上。",
	["At 20 in {zone:1453}, {npc:376} at the altar of the Cathedral of Light hands you a {quest:94818} letter for {npc:258785} in {zone:1455} (the {area:2257} from the {object:28027})."] = "20级时在{zone:1453}，光明大教堂祭坛旁的{npc:376}会交给你一封给{npc:258785}（位于{zone:1455}）的{quest:94818}信件（乘{object:28027}的{area:2257}）。",
	["At 20, {npc:258785} in the {object:32386} teaches {quest:94818} with a quest she gives and takes back at once. {quest:94818} wards a friend for 30 seconds: if they drop below 35% health, they get a shield and a heal over time at once (it stacks with {spell:139} and {spell:17}). 5-minute cooldown."] = "20级时，{object:32386}中的{npc:258785}通过一个她给出并立刻收回的任务教授{quest:94818}。{quest:94818}为一个友方提供30秒守护：如果其生命值降到35%以下，立刻获得一个护盾和持续治疗（可与{spell:139}和{spell:17}叠加）。冷却5分钟。",
	["Follow the road up from {area:131} into {zone:1455} and to the {object:32362}: {npc:258785} in the {object:32386} takes the letter and teaches {quest:94824}."] = "沿路从{area:131}向上进入{zone:1455}，到达{object:32362}：{object:32386}中的{npc:258785}收下信件并教授{quest:94824}。",
	["Hand Laurena's letter to {npc:258785} in the {object:32386}, {zone:1455}'s {object:32362}: the {area:2257} from {zone:1453}'s {object:28027}."] = "把劳瑞娜的信交给{zone:1455}的{object:32362}内、{object:32386}中的{npc:258785}：乘{zone:1453}的{object:28027}的{area:2257}。",
	["Hand the letter to {npc:258785} in the {object:32386}, {zone:1455}'s {object:32362}: the {area:2257} from {zone:1453}'s {object:28027}."] = "把信交给{zone:1455}的{object:32362}内、{object:32386}中的{npc:258785}：乘{zone:1453}的{object:28027}的{area:2257}。",
	["Priest"] = "牧师",
	["The Gnome priest spells, new in Forever: {quest:94817} at 10, {quest:94818} at 20. Free, no objectives."] = "Forever新增的侏儒牧师法术：10级学{quest:94817}，20级学{quest:94818}。免费，没有任务目标。",
	["{npc:1226}: take his {quest:94817} letter"] = "{npc:1226}：接取他的{quest:94817}信件",
	["{npc:376}: take her {quest:94817} letter"] = "{npc:376}：接取她的{quest:94817}信件",
	["{npc:376}: take her {quest:94818} letter"] = "{npc:376}：接取她的{quest:94818}信件",
	["{npc:377}: take her {quest:94817} letter"] = "{npc:377}：接取她的{quest:94817}信件",
	["{quest:94817} and {quest:94818}"] = "{quest:94817}和{quest:94818}",
	["{quest:94819}: Laurena's letter"] = "{quest:94819}：劳瑞娜的信",
	["{quest:94820}: a letter from another trainer"] = "{quest:94820}：另一位训练师的来信",
	["{quest:94821}: Laurena's letter"] = "{quest:94821}：劳瑞娜的信",
	["{quest:94822}: Josetta's letter"] = "{quest:94822}：乔塞塔的信",
	["{quest:94823}: a letter from another trainer"] = "{quest:94823}：另一位训练师的来信",
	["{quest:94824}: {npc:1226}'s letter"] = "{quest:94824}：{npc:1226}的信",
	["{quest:94825}: a letter from another trainer"] = "{quest:94825}：另一位训练师的来信",
