G["forever/class/priest/desperate-prayer-and-chastise"] = {
	["At 10 in {zone:1429}, {npc:377}, upstairs in the Lion's Pride Inn in {area:87}, hands you a {quest:5634} letter for {npc:11406} in {zone:1455} (the {area:2257} from {zone:1453}'s {object:28027})."] = "10级时在{zone:1429}，{area:87}狮王之傲旅店楼上的{npc:377}会给你一封给{zone:1455}的{npc:11406}的{quest:5634}信件（从{zone:1453}的{object:28027}乘{area:2257}）。",
	["At 10 in {zone:1438}, {npc:3600}, in the building at the north edge of {area:186}, hands you a {quest:5634} letter for {npc:11406} in {zone:1455}."] = "10级时在{zone:1438}，{area:186}北边缘建筑里的{npc:3600}会给你一封给{zone:1455}的{npc:11406}的{quest:5634}信件。",
	["At 10 in {zone:1453}, {npc:11397}, the priest trainer in the Park (the night elf quarter on the city's west side), hands you a {quest:5634} letter for {npc:11406} in {zone:1455}. {npc:376} in the Cathedral has none for Dwarves."] = "10级时在{zone:1453}，公园（城市西侧的暗夜精灵区）里的牧师训练师{npc:11397}会给你一封给{zone:1455}的{npc:11406}的{quest:5634}信件。大教堂里的{npc:376}没有给矮人的。",
	["At 10 in {zone:1457}, {npc:11401}, on the upper balcony of the Temple of the Moon beside {npc:7999}, hands you a {quest:5634} letter for {npc:11406} in {zone:1455}."] = "10级时在{zone:1457}，月神殿上层阳台{npc:7999}旁的{npc:11401}会给你一封给{zone:1455}的{npc:11406}的{quest:5634}信件。",
	["At 10, go to {npc:11406} in the {object:32386}, in {zone:1455}'s {object:32362} (north-west of the city): he gives {quest:5634} and takes it back at once. No letter needed. {quest:5634} heals you instantly, costs no mana and has a long cooldown: keep it for emergencies."] = "10级时，去{zone:1455}的{object:32362}（城市西北）里的{object:32386}找{npc:11406}：他会给你{quest:5634}并立刻收回。不需要信件。{quest:5634}会瞬间治疗你，不耗法力且冷却很长：留着应急。",
	["At 10, {npc:1226}, the priest trainer inside the {area:2102} in {area:131}, hands you a {quest:5634} letter for {npc:11406}. {area:131} is on the road up to {zone:1455}."] = "10级时，{area:131}的{area:2102}里的牧师训练师{npc:1226}会给你一封给{npc:11406}的{quest:5634}信件。{area:131}在通往{zone:1455}的路上。",
	["At 20 in {zone:1453}, {npc:376} at the altar of the Cathedral of Light hands you a {quest:5641} letter for {npc:11406} in {zone:1455} (the {area:2257} from the {object:28027})."] = "20级时在{zone:1453}，光明大教堂祭坛旁的{npc:376}会给你一封给{zone:1455}的{npc:11406}的{quest:5641}信件（从{object:28027}乘{area:2257}）。",
	["At 20 in {zone:1457}, {npc:11401}, on the upper balcony of the Temple of the Moon beside {npc:7999}, hands you a {quest:5641} letter for {npc:11406} in {zone:1455}."] = "20级时在{zone:1457}，月神殿上层阳台{npc:7999}旁的{npc:11401}会给你一封给{zone:1455}的{npc:11406}的{quest:5641}信件。",
	["At 20, {npc:11406} in the {object:32386} teaches {quest:5641} with a quest he gives and takes back at once. Forever renamed it from A Lack of Fear: {quest:5641} damages a humanoid and roots it for 2 seconds (instant, 2-minute cooldown), and every priest now trains {spell:6346}."] = "20级时，{object:32386}里的{npc:11406}用一个给了就立刻收回的任务教你{quest:5641}。Forever 把它从“毫无畏惧”改了名：{quest:5641}对一个人形生物造成伤害并定身2秒（瞬发，2分钟冷却），现在每个牧师都会训练{spell:6346}。",
	["Follow the road up from {area:131} into {zone:1455} and west to the {object:32362}: {npc:11406} in the {object:32386} takes the letter and teaches {quest:5637}. The letter tells you to head to {zone:1453}, but the one who wants you is Rohan in {zone:1455}."] = "顺着从{area:131}通往{zone:1455}的路向上，再向西到{object:32362}：{object:32386}里的{npc:11406}收下信件并教你{quest:5637}。信上让你去{zone:1453}，但真正要找你的是{zone:1455}的罗翰。",
	["Hand Alathea's letter to {npc:11406} in the {object:32386}, {zone:1455}'s {object:32362}: from {zone:1457}, the boats via {area:702} and {area:442} to {area:150}, then the road north through the {zone:1437} and {zone:1432} (or the boat to {area:17203} and the {area:2257})."] = "把阿拉希亚的信交给{zone:1455}的{object:32362}中{object:32386}里的{npc:11406}：从{zone:1457}出发，经{area:702}和{area:442}乘船到{area:150}，然后沿路向北穿过{zone:1437}和{zone:1432}（或乘船到{area:17203}再乘{area:2257}）。",
	["Hand Laurena's letter to {npc:11406} in the {object:32386}, {zone:1455}'s {object:32362}: he teaches {quest:5645}."] = "把劳伦娜的信交给{zone:1455}的{object:32362}中{object:32386}里的{npc:11406}：他教你{quest:5645}。",
	["Hand the letter to {npc:11406} in the {object:32386}, {zone:1455}'s {object:32362}: from {zone:1438}, the boat from {area:702} to {area:442}, the boat to {area:150} and the road north through the {zone:1437} and {zone:1432} (or the boat to {area:17203} and the {area:2257})."] = "把信交给{zone:1455}的{object:32362}中{object:32386}里的{npc:11406}：从{zone:1438}出发，从{area:702}乘船到{area:442}，再乘船到{area:150}并沿路向北穿过{zone:1437}和{zone:1432}（或乘船到{area:17203}再乘{area:2257}）。",
	["Hand the letter to {npc:11406} in the {object:32386}, {zone:1455}'s {object:32362}: its text says {zone:1453}, but Rohan is in {zone:1455}. From {zone:1457}, the portal down to {area:702}, the boat to {area:442}, then {area:150} and the road north (or {area:17203} and the {area:2257})."] = "把信交给{zone:1455}的{object:32362}中{object:32386}里的{npc:11406}：信上写的是{zone:1453}，但罗翰在{zone:1455}。从{zone:1457}出发，走传送门下到{area:702}，乘船到{area:442}，再到{area:150}沿路向北（或{area:17203}和{area:2257}）。",
	["Hand the letter to {npc:11406} in the {object:32386}, {zone:1455}'s {object:32362}: the {area:2257} from {zone:1453}'s {object:28027}."] = "把信交给{zone:1455}的{object:32362}中{object:32386}里的{npc:11406}：从{zone:1453}的{object:28027}乘{area:2257}。",
	["Priest"] = "牧师",
	["The Dwarf priest spells: {quest:5634} at 10, {quest:5641} (new in Forever) at 20. Free, no objectives."] = "矮人牧师的法术：10级的{quest:5634}，20级的{quest:5641}（Forever 新增）。免费，无目标。",
	["This letter also goes to {npc:11406} in the {object:32386}, {zone:1455}'s {object:32362}."] = "这封信也是交给{zone:1455}的{object:32362}中{object:32386}里的{npc:11406}。",
	["{npc:11397}: take her {quest:5634} letter"] = "{npc:11397}：拿她的{quest:5634}信件",
	["{npc:11401}: take her {quest:5634} letter"] = "{npc:11401}：拿她的{quest:5634}信件",
	["{npc:11401}: take her {quest:5641} letter"] = "{npc:11401}：拿她的{quest:5641}信件",
	["{npc:1226}: take his {quest:5634} letter"] = "{npc:1226}：拿他的{quest:5634}信件",
	["{npc:3600}: take her {quest:5634} letter"] = "{npc:3600}：拿她的{quest:5634}信件",
	["{npc:376}: take her {quest:5641} letter"] = "{npc:376}：拿她的{quest:5641}信件",
	["{npc:377}: take her {quest:5634} letter"] = "{npc:377}：拿她的{quest:5634}信件",
	["{quest:5634} and {quest:5641}"] = "{quest:5634}与{quest:5641}",
	["{quest:5634}: an old letter"] = "{quest:5634}：一封旧信",
	["{quest:5635}: Josetta's letter"] = "{quest:5635}：乔塞塔的信",
	["{quest:5636}: {npc:3600}'s letter"] = "{quest:5636}：{npc:3600}的信",
	["{quest:5637}: {npc:1226}'s letter"] = "{quest:5637}：{npc:1226}的信",
	["{quest:5638}: Nara's letter"] = "{quest:5638}：娜拉的信",
	["{quest:5640}: Alathea's letter"] = "{quest:5640}：阿拉希亚的信",
	["{quest:5645}: Laurena's letter"] = "{quest:5645}：劳伦娜的信",
	["{quest:5647}: Alathea's letter"] = "{quest:5647}：阿拉希亚的信",
}

G["forever/class/priest/divine-grace-and-feedback"] = {
	["A Human priest in {zone:1438} at 10: {npc:3600}, in the building at the north edge of {area:186}, hands you a letter for {npc:376} in {zone:1453}."] = "人类牧师10级时在{zone:1438}：{area:186}北缘建筑里的{npc:3600}会给你一封写给{zone:1453}的{npc:376}的信。",
	["Any {quest:94776} letter goes to {npc:376} at the altar of the Cathedral of Light."] = "任何{quest:94776}信都交给光明大教堂祭坛的{npc:376}。",
	["Any {quest:94777} letter goes to {npc:376} at the altar of the Cathedral of Light."] = "任何{quest:94777}信都交给光明大教堂祭坛的{npc:376}。",
	["Any {quest:94778} letter goes to {npc:376} at the altar of the Cathedral of Light."] = "任何{quest:94778}信都交给光明大教堂祭坛的{npc:376}。",
	["Any {quest:94779} letter goes to {npc:376} at the altar of the Cathedral of Light."] = "任何{quest:94779}信都交给光明大教堂祭坛的{npc:376}。",
	["At 10, go to {npc:376} at the altar of the Cathedral of Light, in {zone:1453}'s {object:2098}, and take her quest: she teaches {quest:94773} on the spot. No letter needed; one from another trainer works too (next steps). {quest:94773} instantly heals a friend below half health and clears {spell:6788}, so you can shield them again (5-minute cooldown); it does not work on yourself. Human priests do not get Desperate Prayer in Forever: this is their spell instead."] = "10级时去找光明大教堂祭坛的{npc:376}，就在{zone:1453}的{object:2098}里，接下她的任务：她会当场教你{quest:94773}。无需信件；别的训练师给的信同样可以（见后续步骤）。{quest:94773}立刻治疗生命值低于一半的队友并清除{spell:6788}，让你能再次为他上盾（冷却5分钟）；对自己无效。人类牧师在Forever中不会获得绝望祈祷：取而代之的就是这个法术。",
	["At 10, {npc:377}, upstairs in the Lion's Pride Inn in {area:87}, hands you a letter for {npc:376}. {area:87} is on the road north to {zone:1453}, so it costs no detour."] = "10级时，{area:87}狮王之傲旅店楼上的{npc:377}会给你一封写给{npc:376}的信。{area:87}就在向北通往{zone:1453}的大路旁，不会绕路。",
	["At 20 in {zone:1455}, {npc:11406} in the {object:32386} ({object:32362}) hands you a letter for {npc:376} in {zone:1453}. The {area:2257} from {object:171524} takes you there."] = "20级时在{zone:1455}，{object:32386}（{object:32362}）里的{npc:11406}会给你一封写给{zone:1453}的{npc:376}的信。从{object:171524}乘{area:2257}即可到达。",
	["At 20 in {zone:1457}, {npc:11401}, on the upper balcony of the Temple of the Moon beside {npc:7999}, hands you a letter for {npc:376} in {zone:1453}."] = "20级时在{zone:1457}，月神殿上层露台{npc:7999}旁的{npc:11401}会给你一封写给{zone:1453}的{npc:376}的信。",
	["At 20, {npc:376} at the altar of the Cathedral of Light teaches {spell:13896} with a quest she gives and takes back at once."] = "20级时，光明大教堂祭坛的{npc:376}会用一个她给出后立刻收回的任务教你{spell:13896}。",
	["Hand Alathea's letter to {npc:376} at the altar of {zone:1453}'s Cathedral of Light (from {zone:1457}: the portal down to {area:702}, the boat to {area:442}, then the boat to {area:17203}): she teaches {spell:13896}."] = "把阿拉希亚的信交给{zone:1453}光明大教堂祭坛的{npc:376}（从{zone:1457}出发：乘传送门下去到{area:702}，坐船到{area:442}，再坐船到{area:17203}）：她教你{spell:13896}。",
	["Hand Josetta's letter to {npc:376} at the altar of the Cathedral of Light: she teaches {quest:94774}."] = "把乔塞塔的信交给光明大教堂祭坛的{npc:376}：她教你{quest:94774}。",
	["Hand Rohan's letter to {npc:376} at the altar of {zone:1453}'s Cathedral of Light (the {area:2257} from {object:171524} in {zone:1455}): she teaches {spell:13896}."] = "把罗翰的信交给{zone:1453}光明大教堂祭坛的{npc:376}（在{zone:1455}从{object:171524}乘{area:2257}）：她教你{spell:13896}。",
	["Hand {npc:3600}'s letter to {npc:376} at the altar of {zone:1453}'s Cathedral of Light (from {zone:1438}: the boat from {area:702} to {area:442}, then the boat to {area:17203}): she teaches {quest:94775}."] = "把{npc:3600}的信交给{zone:1453}光明大教堂祭坛的{npc:376}（从{zone:1438}出发：从{area:702}坐船到{area:442}，再坐船到{area:17203}）：她教你{quest:94775}。",
	["Priest"] = "牧师",
	["The Human priest spells: {quest:94773} at 10 (new in Forever), {spell:13896} at 20. Free, no objectives."] = "人类牧师的法术：10级的{quest:94773}（Forever新增），20级的{spell:13896}。免费，无目标。",
	["{npc:11401}: take her {quest:5676} letter"] = "{npc:11401}：拿她的{quest:5676}信",
	["{npc:11406}: take his {quest:5676} letter"] = "{npc:11406}：拿他的{quest:5676}信",
	["{npc:3600}: take her {quest:94773} letter"] = "{npc:3600}：拿她的{quest:94773}信",
	["{npc:377}: take her {quest:94773} letter"] = "{npc:377}：拿她的{quest:94773}信",
	["{quest:94773} and {spell:13896}"] = "{quest:94773}与{spell:13896}",
	["{quest:94774}: Josetta's letter"] = "{quest:94774}：乔塞塔的信",
	["{quest:94775}: {npc:3600}'s letter"] = "{quest:94775}：{npc:3600}的信",
	["{quest:94776}: a letter from another trainer"] = "{quest:94776}：另一个训练师的信",
	["{quest:94777}: a letter from another trainer"] = "{quest:94777}：另一个训练师的信",
	["{quest:94778}: a letter from another trainer"] = "{quest:94778}：另一个训练师的信",
	["{quest:94779}: a letter from another trainer"] = "{quest:94779}：另一个训练师的信",
	["{spell:13896}: Alathea's letter"] = "{spell:13896}：阿拉希亚的信",
	["{spell:13896}: Rohan's letter"] = "{spell:13896}：罗翰的信",
