G["forever/class/priest/priest-robes-alliance"] = {
	["A free uncommon robe at 5: heal and fortify a wounded guard near your first town."] = "5级即可免费获得一件优秀长袍：治疗并强化你第一个城镇附近的一名受伤卫兵。",
	["At 5, {npc:3595}, the priest trainer on the second level of {area:256}, the great tree in {area:188}, sends you to {npc:3600} in {area:186}. Train {spell:613} (Rank 2) from her while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank."] = "5级时，{area:188}中巨树{area:256}二楼的牧师训练师{npc:3595}会让你去找{area:186}的{npc:3600}。既然来了，就向她学习{spell:613}（2级）：该技能4级开放，花费1银，下一个任务正好需要这个等级。",
	["At 5, {npc:375}, the priest trainer inside {area:24}, sends you to {npc:377} in {area:87}. Train {spell:613} (Rank 2) from Anetta while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank."] = "5级时，{area:24}内的牧师训练师{npc:375}会让你去找{area:87}的{npc:377}。既然来了，就向安妮塔学习{spell:613}（2级）：该技能4级开放，花费1银，下一个任务正好需要这个等级。",
	["At 5, {npc:837}, the priest trainer inside {area:77} in {area:132}, sends you to {npc:1226} in {area:131}. Train {spell:613} (Rank 2) from him while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank."] = "5级时，{area:132}中{area:77}内的牧师训练师{npc:837}会让你去找{area:131}的{npc:1226}。既然来了，就向他学习{spell:613}（2级）：该技能4级开放，花费1银，下一个任务正好需要这个等级。",
	["Back at the north edge of {area:186}: {npc:3600} gives you the {item:16604}."] = "回到{area:186}北缘：{npc:3600}给你{item:16604}。",
	["Back inside the {area:2102}: {npc:1226} gives you {item:16605}."] = "回到{area:2102}内：{npc:1226}给你{item:16605}。",
	["Back upstairs in the Lion's Pride Inn: Josetta gives you {item:16605}."] = "回到狮王之傲旅店楼上：乔塞塔给你{item:16605}。",
	["Follow the road south out of {area:9} to {area:87}. {npc:377} is upstairs in the Lion's Pride Inn."] = "沿路向南离开{area:9}前往{area:87}。{npc:377}在狮王之傲旅店楼上。",
	["Guard Roberts"] = "卫兵罗伯茨",
	["Heal and fortify {npc:12423}"] = "治疗并加持{npc:12423}",
	["Heal and fortify {npc:12427}"] = "治疗并加持{npc:12427}",
	["Heal and fortify {npc:12429}"] = "治疗并加持{npc:12429}",
	["Leave {area:188} by the ramp and follow the road south-west to {area:186}. {npc:3600} is in the building at the north edge of the village."] = "从斜坡离开{area:188}，沿路向西南前往{area:186}。{npc:3600}在村北缘的建筑里。",
	["Mountaineer Dolf"] = "巡山者多尔夫",
	["Priest"] = "牧师",
	["Priest Robes at 5 (Alliance)"] = "5级牧师长袍（联盟）",
	["Sentinel Shaya"] = "哨兵沙娅",
	["Take the tunnel north-east out of {area:132} and follow the road east to {area:131}. {npc:1226} is inside the {area:2102}."] = "从{area:132}走隧道向东北出去，再沿路向东前往{area:131}。{npc:1226}在{area:2102}内。",
	["{npc:12423} kneels by a tree on the lake shore east of {area:87}, off the road: walk along the shore, the minimap misses him from the road. Cast {spell:613} (Rank 2) on him first, then {spell:1243}. Rank 1 of {spell:613} does not count; drag Rank 2 onto your bar from the spellbook (or cast both from the spellbook if an action bar addon gets in the way). He walks off once both land and is back in about 3 minutes."] = "{npc:12423}跪在{area:87}以东湖岸边的一棵树旁，不在路上：沿湖岸走，从路上看小地图会漏掉他。先对他施放{spell:613}（2级），再放{spell:1243}。{spell:613}的1级不算数；从法术书中把2级拖到动作条上（如果动作条插件碍事，就直接从法术书施放两个法术）。两个法术都命中后他就会走开，大约3分钟后回来。",
	["{npc:12427} kneels on a ridge between two low walls just south of {area:131}, across the road from the hunter pet trainer: if the road starts going downhill, you have passed him. Cast {spell:613} (Rank 2) on him first, then {spell:1243}; he speaks after each spell. Rank 1 of {spell:613} does not count."] = "{npc:12427}跪在{area:131}正南两道矮墙之间的山脊上，在猎人宠物训练师的路对面：如果路开始下坡，说明你已经走过他了。先对他施放{spell:613}（2级），再放{spell:1243}；他会在每个法术之后说话。{spell:613}的1级不算数。",
	["{npc:12429} kneels on the rocks at the edge of {area:259}, about 100 yards south of {area:186}, with no quest mark over her. Cast {spell:613} (Rank 2) on her first, then {spell:1243}; she runs off toward the lake once both land and is back in about 5 minutes. Rank 1 of {spell:613} does not count."] = "{npc:12429}跪在{area:259}边缘的岩石上，位于{area:186}以南约100码，头顶没有任务标记。先对她施放{spell:613}（2级），再放{spell:1243}；两个法术都命中后她会朝湖跑去，大约5分钟后回来。{spell:613}的1级不算数。",
	["{spell:613} (Rank 2), if Anetta did not teach it yet"] = "{spell:613}（2级），如果安妮塔还没教你",
	["{spell:613} (Rank 2), if {npc:3595} did not teach it yet"] = "{spell:613}（2级），如果{npc:3595}还没教你",
	["{spell:613} (Rank 2), if {npc:837} did not teach it yet"] = "{spell:613}（2级），如果{npc:837}还没教你",
}

G["forever/class/priest/starshards-and-elunes-grace"] = {
	["At 10 in {zone:1426}, {npc:1226}, the priest trainer inside the {area:2102} in {area:131}, hands you {quest:5628}, a letter for {npc:11401} in {zone:1457}."] = "10级时在{zone:1426}，{area:131}中{area:2102}里的牧师训练师{npc:1226}会给你{quest:5628}，一封写给{zone:1457}的{npc:11401}的信。",
	["At 10 in {zone:1429}, {npc:377}, upstairs in the Lion's Pride Inn in {area:87}, hands you {quest:5628}, a letter for {npc:11401} in {zone:1457}."] = "10级时在{zone:1429}，{area:87}狮王之傲旅店楼上的{npc:377}会给你{quest:5628}，一封写给{zone:1457}的{npc:11401}的信。",
	["At 10 in {zone:1453}, {npc:5489} at the altar of the Cathedral of Light hands you {quest:5628}, a letter for {npc:11401} in {zone:1457}. {npc:11397} in the Park has the same letter."] = "10级时在{zone:1453}，光明大教堂祭坛旁的{npc:5489}会给你{quest:5628}，一封写给{zone:1457}的{npc:11401}的信。公园里的{npc:11397}也有同样的信。",
	["At 10 in {zone:1455}, {npc:5142} in the {object:32386} ({object:32362}) hands you {quest:5628}, a letter for {npc:11401} in {zone:1457}."] = "10级时在{zone:1455}，{object:32386}（{object:32362}）里的{npc:5142}会给你{quest:5628}，一封写给{zone:1457}的{npc:11401}的信。",
	["At 10, go to {npc:11401} on the upper balcony of the Temple of the Moon, at the south end of {zone:1457}: take the ramp up from the temple floor; she stands beside {npc:7999}. {quest:5627} is given and taken back at once and teaches {spell:10797}. No letter needed. Forever made {spell:10797} hit much harder, on a 30-second cooldown."] = "10级时去找{npc:11401}，她在{zone:1457}南端月神殿的上层露台：从神殿地面沿坡道上去；她站在{npc:7999}旁边。{quest:5627}给出后立刻收回，教你{spell:10797}。无需信件。Forever让{spell:10797}伤害大幅提高，冷却30秒。",
	["At 10, {npc:3600}, the priest trainer in the building at the north edge of {area:186}, hands you {quest:5628}, a letter for {npc:11401} in {zone:1457}. {area:186} is on the road west to {zone:1457}."] = "10级时，{area:186}北缘建筑里的牧师训练师{npc:3600}会给你{quest:5628}，一封写给{zone:1457}的{npc:11401}的信。{area:186}就在向西通往{zone:1457}的大路旁。",
	["At 20 in {zone:1453}, {npc:376} at the altar of the Cathedral of Light hands you an {spell:2651} letter for {npc:11401} in {zone:1457}. {npc:11397} in the Park has the same letter."] = "20级时在{zone:1453}，光明大教堂祭坛旁的{npc:376}会给你一封{spell:2651}信，写给{zone:1457}的{npc:11401}。公园里的{npc:11397}也有同样的信。",
	["At 20 in {zone:1455}, {npc:11406} in the {object:32386} ({object:32362}) hands you an {spell:2651} letter for {npc:11401} in {zone:1457}."] = "20级时在{zone:1455}，{object:32386}（{object:32362}）里的{npc:11406}会给你一封{spell:2651}信，写给{zone:1457}的{npc:11401}。",
	["At 20, {npc:11401} on the upper balcony of the Temple of the Moon, beside {npc:7999}, teaches {quest:5672} with a quest she gives and takes back at once. In Forever, {quest:5672} halves the chance for melee and ranged attacks to hit you for 15 seconds or until three attacks miss."] = "20级时，月神殿上层露台{npc:7999}旁的{npc:11401}用一个她给出后立刻收回的任务教你{quest:5672}。在Forever中，{quest:5672}使近战和远程攻击命中你的几率减半，持续15秒或直到三次攻击未命中。",
	["Hand Laurena's letter to {npc:11401}, on the upper balcony of the Temple of the Moon in {zone:1457}, beside {npc:7999}: the boat from {area:17203} (or {area:150}) to {area:442}, the boat on to {area:702}, then the portal up into {zone:1457}."] = "把劳伦娜的信交给{npc:11401}，她在{zone:1457}月神殿的上层露台、{npc:7999}旁边：从{area:17203}（或{area:150}）坐船到{area:442}，再坐船到{area:702}，然后乘传送门上去进入{zone:1457}。",
	["Hand Nara's letter to {npc:11401}, on the upper balcony of the Temple of the Moon in {zone:1457}, beside {npc:7999}: the boat from {area:17203} (or {area:150}) to {area:442}, the boat on to {area:702}, then the portal up into {zone:1457}."] = "把娜拉的信交给{npc:11401}，她在{zone:1457}月神殿的上层露台、{npc:7999}旁边：从{area:17203}（或{area:150}）坐船到{area:442}，再坐船到{area:702}，然后乘传送门上去进入{zone:1457}。",
	["Hand Rohan's letter to {npc:11401}, on the upper balcony of the Temple of the Moon in {zone:1457}, beside {npc:7999}: the boat from {area:17203} (or {area:150}) to {area:442}, the boat on to {area:702}, then the portal up into {zone:1457}."] = "把罗翰的信交给{npc:11401}，她在{zone:1457}月神殿的上层露台、{npc:7999}旁边：从{area:17203}（或{area:150}）坐船到{area:442}，再坐船到{area:702}，然后乘传送门上去进入{zone:1457}。",
	["Priest"] = "牧师",
	["Take the road west from {area:186} into {zone:1457} and go up to the upper balcony of the Temple of the Moon, beside {npc:7999}: {npc:11401} takes {quest:5629} and teaches {spell:10797}."] = "从{area:186}沿路向西进入{zone:1457}，上到月神殿上层露台、{npc:7999}旁边：{npc:11401}收下{quest:5629}并教你{spell:10797}。",
	["The Night Elf priest spells: {spell:10797} at 10, {spell:2651} at 20. Free, no objectives."] = "暗夜精灵牧师法术：10级{spell:10797}，20级{spell:2651}。免费，无任务目标。",
	["{npc:11406}: take his {spell:2651} letter"] = "{npc:11406}：拿他的{spell:2651}信",
	["{npc:1226}: take {quest:5628}"] = "{npc:1226}：拿{quest:5628}",
