	["{npc:5142}: take {quest:5628}"] = "{npc:5142}：拿{quest:5628}",
	["{npc:5489}: take {quest:5628}"] = "{npc:5489}：拿{quest:5628}",
	["{quest:5628} goes to {npc:11401}, on the upper balcony of the Temple of the Moon in {zone:1457}, beside {npc:7999}: take the boat from {area:17203} (or {area:150}) to {area:442}, the boat on to {area:702}, then the portal up into {zone:1457}."] = "{quest:5628}交给{npc:11401}，她在{zone:1457}月神殿的上层露台、{npc:7999}旁边：从{area:17203}（或{area:150}）坐船到{area:442}，再坐船到{area:702}，然后乘传送门上去进入{zone:1457}。",
	["{quest:5630} goes to {npc:11401}, on the upper balcony of the Temple of the Moon in {zone:1457}, beside {npc:7999}: take the boat from {area:17203} (or {area:150}) to {area:442}, the boat on to {area:702}, then the portal up into {zone:1457}."] = "{quest:5630}交给{npc:11401}，她在{zone:1457}月神殿的上层露台、{npc:7999}旁边：从{area:17203}（或{area:150}）坐船到{area:442}，再坐船到{area:702}，然后乘传送门上去进入{zone:1457}。",
	["{quest:5631} goes to {npc:11401}, on the upper balcony of the Temple of the Moon in {zone:1457}, beside {npc:7999}: take the boat from {area:17203} (or {area:150}) to {area:442}, the boat on to {area:702}, then the portal up into {zone:1457}."] = "{quest:5631}交给{npc:11401}，她在{zone:1457}月神殿的上层露台、{npc:7999}旁边：从{area:17203}（或{area:150}）坐船到{area:442}，再坐船到{area:702}，然后乘传送门上去进入{zone:1457}。",
	["{quest:5632} goes to {npc:11401}, on the upper balcony of the Temple of the Moon in {zone:1457}, beside {npc:7999}: take the boat from {area:17203} (or {area:150}) to {area:442}, the boat on to {area:702}, then the portal up into {zone:1457}."] = "{quest:5632}交给{npc:11401}，她在{zone:1457}月神殿的上层露台、{npc:7999}旁边：从{area:17203}（或{area:150}）坐船到{area:442}，再坐船到{area:702}，然后乘传送门上去进入{zone:1457}。",
	["{quest:5633} goes to {npc:11401}, on the upper balcony of the Temple of the Moon in {zone:1457}, beside {npc:7999}: take the boat from {area:17203} (or {area:150}) to {area:442}, the boat on to {area:702}, then the portal up into {zone:1457}."] = "{quest:5633}交给{npc:11401}，她在{zone:1457}月神殿的上层露台、{npc:7999}旁边：从{area:17203}（或{area:150}）坐船到{area:442}，再坐船到{area:702}，然后乘传送门上去进入{zone:1457}。",
