G["forever/class/rogue/blade-of-cunning-alliance"] = {
	["A dagger at 10 from your home town's rogue quests."] = "10级时来自你家乡潜行者任务的匕首。",
	["At 10 {npc:1234}, the rogue trainer in the {area:2102} in {area:131}, sends you to {npc:5165} in {zone:1455}."] = "10级时，{area:131}{area:2102}的潜行者训练师{npc:1234}会让你去找{zone:1455}的{npc:5165}。",
	["At 10 {npc:3599}, the rogue trainer in the {area:186} inn, gives you a rose for {npc:4163} in {zone:1457}. If you lose the rose, abandon the quest and take it again."] = "10级时，{area:186}旅店里的盗贼训练师{npc:3599}会给你一朵玫瑰，送给{zone:1457}的{npc:4163}。如果玫瑰丢了，放弃任务重新接。",
	["At 10 {npc:917}, the rogue trainer upstairs in the Lion's Pride Inn in {area:87}, gives you a package for {npc:332} in {zone:1453}. Train {spell:921} if you lack it: this chain needs it."] = "10级时，{area:87}狮王之傲旅店楼上的盗贼训练师{npc:917}会给你一个包裹，送给{zone:1453}的{npc:332}。如果还没学{spell:921}就先学：这条任务链需要它。",
	["Back to Mathias Shaw"] = "回到马迪亚斯·肖尔处",
	["Back to {npc:4163}"] = "回到{npc:4163}处",
	["Back to {npc:5165}"] = "回到{npc:5165}处",
	["Head north to {zone:1453}. Shaw stands upstairs in the SI:7 building in {object:2100} (the quest says the Barracks; it means SI:7)."] = "向北前往{zone:1453}。肖尔站在{object:2100}军情七处大楼的楼上（任务里说是兵营，其实指军情七处）。",
	["Head west to {area:133}. Beside the road to its entrance stands a wooden spiral tower: {npc:6886} waits stealthed on the top platform, next to a level 10 {npc:1211}, so you only see him up close."] = "向西前往{area:133}。通往入口的路边立着一座木制螺旋塔：{npc:6886}潜行等在顶层平台上，旁边有一只10级的{npc:1211}，所以只有靠近才能看见他。",
	["Head west to {zone:1457}. {npc:4163} is below ground in the {area:1658}: the way down is the opening at the foot of the split tree left of the Arch Druid's tree, near the nightsaber trainer. Her map marker shows above ground."] = "向西前往{zone:1457}。{npc:4163}在{area:1658}的地下：下去的路口在大德鲁伊树左侧那棵分叉树脚下，靠近夜刃豹训练师。她的地图标记显示在地面以上。",
	["Pick Pocket Sethir the Ancient for {item:7737}"] = "对远古者塞希尔使用搜索，获得{item:7737}",
	["Rogue"] = "潜行者",
	["The {npc:6846} (level 10, a goblin) works in the dock house at {area:797}, on the river at Elwynn's southern edge, south of {area:87}. Stealth in and {spell:921} him from behind: the schedule never drops from his corpse. Do not open with {spell:2070} or a fight: he calls in three waves of bodyguards. Keep away from the fireplaces in the house; they burn you out of stealth. He is back 2 to 5 minutes after a death."] = "{npc:6846}（10级，地精）在{area:797}的码头小屋干活，那里是艾尔文森林南缘的河边，{area:87}以南。潜行进去从背后{spell:921}他：日程表永远不会从他尸体上掉落。不要用{spell:2070}起手，也别直接开打：他会叫来三波保镖。避开屋里的壁炉，它们会把你烧出潜行。他死亡后2到5分钟刷新。",
	["{item:7298} (Alliance)"] = "{item:7298}（联盟）",
	["{item:7675}: {spell:921} the {npc:6846}"] = "{item:7675}：对{npc:6846}使用{spell:921}",
	["{item:7737}: Pick Pocket Sethir the Ancient"] = "{item:7737}：偷窃上古者塞希尔",
	["{npc:332}, SI:7"] = "{npc:332}，军情七处",
	["{npc:5165} is in the {object:32383}, the rogue quarter in the north of {zone:1455}: go into the building with a shady dealer outside and down the stairs."] = "{npc:5165}在{object:32383}，即{zone:1455}北部的盗贼区：走进门外有个鬼祟商人的那栋建筑，下楼。",
	["{npc:6909} (level 12 satyr) lives out on a great branch north of the {area:264}: go through the V-shaped gap in the wall north of the glade and out along the branch. Pick his pocket for the journal; killing him does not give it, and a fight brings out three Minions of Sethir. He walks between the main branch and a side branch: wait stealthed at the far end of the main branch and pick him from behind when he comes back. Then {spell:2983} away. He is back 8 1/2 minutes after a death."] = "{npc:6909}（12级萨特）住在{area:264}以北的一根巨枝上：从林地北面墙上的V形缺口穿过去，沿巨枝向外走。偷他的口袋拿日志；杀他不会掉落，而且开打会引出三个塞希尔的爪牙。他在主枝和侧枝之间走动：潜行在主枝尽头等候，等他回来时从背后偷。然后用{spell:2983}脱身。他死亡后8分半钟刷新。",
}

G["forever/class/rogue/certificate-of-thievery"] = {
	["At 16 {npc:1234} in the {area:2102} in {area:131} sends you to {npc:5165} in {zone:1455}'s {object:32383}."] = "16级时，{area:131}的{area:2102}里的{npc:1234}会让你去找{zone:1455}的{object:32383}中的{npc:5165}。",
	["At 16 {npc:3599} in the {area:186} inn sends you to {quest:2259} in {zone:1457}."] = "16级时，{area:186}旅店里的{npc:3599}会让你去{zone:1457}接{quest:2259}。",
	["At 16 {npc:917}, the rogue trainer upstairs in the Lion's Pride Inn in {area:87}, sends you to {npc:6946} in {zone:1453}. Taking it shuts out the other towns' breadcrumbs."] = "16级时，{area:87}狮王之傲旅店楼上那个盗贼训练师{npc:917}会让你去找{zone:1453}的{npc:6946}。接了它，其他城镇的引路任务就不会出现。",
	["Back to {npc:6966}"] = "回到{npc:6966}那里",
	["Head east through {zone:1429} into Redridge, or fly to {area:69}. {npc:6966} stands on a crate on one of the {area:69} docks, south of town; he gives you {item:5060} with the job ({npc:3090} in {area:69} sells more). {spell:1804} does not work without the tools in your bags."] = "向东穿过{zone:1429}进入赤脊山，或飞往{area:69}。{npc:6966}站在{area:69}某处码头的一个木箱上，在小镇南边；他会给你{item:5060}和任务（{area:69}的{npc:3090}还有更多卖）。背包里没有工具时{spell:1804}无法使用。",
	["Rogue"] = "盗贼",
	["Your first lockpicking job at 16: {npc:6966}'s lockbox at {quest:2282}, for {quest:2300}."] = "16级时你的第一份开锁工作：为{quest:2300}打开{quest:2282}的{npc:6966}的锁箱。",
	["{npc:4214} stands in the {area:1658}. Then the boat from {area:702} to {area:442}, and the boat from {area:442} to {area:17203}."] = "{npc:4214}站在{area:1658}。然后从{area:702}乘船到{area:442}，再从{area:442}乘船到{area:17203}。",
	["{npc:5165} is in the house with a shady dealer outside, in the {object:32383}, down the stairs. Then fly or take the {area:2257} to {zone:1453}."] = "{npc:5165}在门口有可疑商人的那间房子里，位于{object:32383}，沿楼梯下去。然后飞往或乘{area:2257}到{zone:1453}。",
	["{npc:6946} stands upstairs in the {quest:2300} building in {object:2100}, behind the rogue trainers. Before you leave: if you lack {spell:1804}, {npc:13283} in the {quest:2300} building teaches it; Lockpicking is the test of the next quest."] = "{npc:6946}站在{object:2100}的{quest:2300}建筑楼上，在盗贼训练师身后。离开前：如果你没有{spell:1804}，{quest:2300}建筑里的{npc:13283}会教你；开锁是下一个任务的考核内容。",
	["{quest:2282} stands east of {area:69}, up off the road; Blackrock orcs roam near it. Inside, the Practice Lockboxes come back almost at once: pick them until {object:121264} opens for you (about 25 Lockpicking). Your Lockpicking cap rises 5 per level, so a low character may stall. Some boxes are trapped (a frost trap, for one); the skill still goes up. On Forever level 20 spiders wander near the boxes: clear them first or bring a friend. The lockbox always holds the token and is back two seconds after use. Practise on while it still gives skill: the next class quest needs about 75."] = "{quest:2282}位于{area:69}以东、路边的高处；黑石兽人在附近游荡。里面的练习锁箱几乎立刻刷新：反复开锁，直到{object:121264}为你打开（约25点开锁技能）。你的开锁上限每级提升5点，所以等级低时可能卡住。有些箱子带陷阱（比如冰冻陷阱）；技能照样会涨。在Forever服务器，20级的蜘蛛会在箱子附近游荡：先清掉它们，或者带上朋友。锁箱里始终放着信物，使用后两秒就回来。在还能涨技能时继续练：下一个职业任务需要约75点。",
}

G["forever/class/rogue/poisons-alliance"] = {
	["/lay with the Doc targeted"] = "选中医生后输入 /lay",
	["All four are in {zone:1453}. {item:3421}: Bernard or {npc:1303}'s flower shop by the {object:2096} canal. A {item:3372}: many general goods and alchemy vendors ({npc:1257}, {npc:1325} and others). A {item:4371}: an engineering supplier, who keeps only a few (or an engineer or the Auction House). The {item:8431} lies on the floor beside the left end of the counter in {object:2177}, the tailor's shop on the canals; you can only pick it up with this quest. If you skip the cure, an {item:6452} ({skill:129}) or a druid's {spell:526} also clears the {spell:9810}."] = "这四样都在{zone:1453}。{item:3421}：伯纳德或{npc:1303}的花店，在{object:2096}运河旁。{item:3372}：许多杂货和炼金商人（{npc:1257}、{npc:1325}等）有售。{item:4371}：工程学供应商，存货很少（或者找工程师，或去拍卖行）。{item:8431}在运河边裁缝店{object:2177}柜台左端旁的地上；只有接了这个任务才能拾取。如果不做解毒，{item:6452}（{skill:129}）或德鲁伊的{spell:526}也能解除{spell:9810}。",
	["At 20 {npc:332}, upstairs in the SI:7 building in {object:2100}, sends you to {npc:7024} in {zone:1436}. This chain is how you learn Poisons on Forever, so do not skip it."] = "20级时，{object:2100}军情七处大楼楼上的{npc:332}会派你去{zone:1436}找{npc:7024}。在 Forever 上，毒药就是通过这条任务链学会的，别跳过。",
	["Back to {npc:7207}"] = "回到{npc:7207}处",
	["Forever teaches Poisons through this chain, not the trainer; the {item:7676} recipe comes with it."] = "Forever 通过这条任务线而不是训练师教授毒药；同时获得{item:7676}的配方。",
	["Get the key first. The {npc:7051} (level 23, not elite) starts at the tower entrance and walks a loop around the outside; it is the spiky-haired one trailing yellow sparkles. Stealth up and {spell:921} it from behind: it always has the key. It hits hard: if stealth breaks, {spell:2983} away. Watch for the pair of Defias Drones that also patrol."] = "先拿钥匙。{npc:7051}（23级，非精英）从塔楼入口出发，沿外围绕圈；就是那个留着尖刺头发、身后拖着黄色闪光的。潜行过去，从背后用{spell:921}偷它：它总是带着钥匙。它打得很疼：如果潜行被打破，就用{spell:2983}跑开。注意也会巡逻的一对迪菲亚雄蜂。",
	["Head north through Elwynn to {zone:1453}; Mathias Shaw is upstairs in SI:7. He teaches Poisons and gives you the {item:7676} recipe. Poisons are made, not bought: each batch of {item:6947} takes a {item:2928} and an {item:3371}, which {npc:1325} and {npc:1326} sell in {object:2100} next to SI:7. Buy a stack of each, open Poisons from your spellbook to make them, then use a poison on your weapon."] = "穿过艾尔文森林向北到{zone:1453}；马迪亚斯·肖尔在军情七处楼上。他教毒药，并给你{item:7676}的配方。毒药是做的，不是买的：每批{item:6947}需要{item:2928}和{item:3371}，{npc:1325}和{npc:1326}在军情七处旁的{object:2100}有售。各买一组，从法术书里打开毒药制作，然后给武器涂上毒药。",
	["Kearnen hides stealthed against the west side of a big tree with two small trees in front of it, just north of {npc:7053}'s Defias tower in the far east of {zone:1436}, by the {zone:1431} border. Read {item:8046} for the tower's layout if you like."] = "凯尔南潜行躲在一棵大树西侧，树前有两棵小树，就在{zone:1436}最东边{npc:7053}的迪菲亚塔楼以北、靠近{zone:1431}边界的地方。想看塔楼布局的话，读{item:8046}。",
	["Klaven's journal"] = "克拉文的手记",
	["Poisons (Alliance)"] = "毒药（联盟）",
	["Rogue"] = "潜行者",
	["Sneak up the tower. Defias Tower Patrollers (23) and Sentries (24) guard the floors; an Ambush with a dagger kills them outright if you would rather clear them. {npc:7053}, a level 26 elite, waits on the top floor: Sap him, or bring a friend. The {object:123214} beside his desk needs Lockpicking of about 70-75 (practise on the boxes at {area:97} in Redridge first). A trick: while the Sentries are away, jump from the chair to the lamp to the bookshelf above the chest, step out of stealth and open the chest from there. Opening it poisons you with the {spell:9810}, which stops your stealth for a while and lets the drone see you; that is why the key comes first. Then get out."] = "潜行上塔。迪菲亚塔楼巡逻者（23级）和哨兵（24级）守在各层；如果想清掉他们，用匕首伏击能直接秒杀。{npc:7053}，26级精英，在顶层等着：闷棍他，或者带个同伴。他桌子旁的{object:123214}需要约70-75点开锁（先在赤脊山{area:97}的箱子上练手）。小技巧：趁哨兵走开时，从椅子跳到灯，再跳到箱子上方的书架，脱离潜行，从那里开箱子。打开它会使你中{spell:9810}的毒，一段时间内无法潜行，雄蜂就会看到你；所以要先去拿钥匙。然后离开。",
	["The cure's ingredients"] = "解药的材料",
	["The {item:7923}"] = "{item:7923}",
	["{item:7908}: the {object:123214}, top floor"] = "{item:7908}：{object:123214}，顶层",
	["{item:7923}: {spell:921} the {npc:7051}"] = "{item:7923}：对{npc:7051}使用{spell:921}",
	["{npc:332}: Poisons"] = "{npc:332}：毒药",
	["{quest:2607} still sits on you. {npc:7207} works in the cellar of the SI:7 building: the stairs down are under the stairs to the upper floor, behind {npc:1325}. Target him and type /lay (nothing after it) to be examined, then wait. If he does nothing, abandon the quest, take it again and wait until he asks you to lie down."] = "{quest:2607}还在你身上。{npc:7207}在军情七处大楼的地窖里工作：下去的楼梯在通往楼上的楼梯下面，{npc:1325}身后。选中他，输入 /lay（后面不要加任何内容）让他检查，然后等着。如果他什么都不做，放弃任务，再接一次，等到他让你躺下。",
}

G["forever/class/shaman/call-of-air-alliance"] = {
	["At 30 {npc:258098}, the shaman trainer in {zone:1455}, sends you to {npc:259023} in {zone:1417}. Your level 30 air totems (Grounding, {spell:10596}) need the {item:5178} he gives."] = "30级时，{zone:1455}的萨满训练师{npc:258098}派你去找{zone:1417}的{npc:259023}。你30级的空气图腾（根基图腾、{spell:10596}）需要他给的{item:5178}。",
	["Five Twisted Air Totems. The Maraudine centaurs (level 36-40) north and north-east of {area:2408} in western {zone:1443} carry them; the Scouts drop one nearly every other kill. Wranglers Net and Disarm, Windchasers heal, Stormers throw {spell:9654}: pull one at a time. Respawn about five minutes."] = "五个畸变空气图腾。{zone:1443}西部{area:2408}以北和东北的玛洛丁半人马（36-40级）携带它们；斥候几乎每两次击杀就掉一个。驯兽者会撒网和缴械，逐风者会治疗，风暴者会投掷{spell:9654}：一次拉一个。刷新约五分钟。",
	["Five Twisted Earth Totems. The Lost Ones (murlocs, level 34-39) north and north-east of {area:75} in the {zone:1435} carry them; most run for help when hurt."] = "五个畸变大地图腾。{zone:1435}中{area:75}以北和东北的失落者（鱼人，34-39级）携带它们；大多数受伤时会逃跑求援。",
	["Five Twisted Fire Totems. The Stonevault troggs (Skullthumpers, Bonesnappers and Shamans, level 37-41) south of {area:338} in the {zone:1418} carry them; the Shamans drop Fire Nova Totems and a {npc:3560}, the Bonesnappers run for help when hurt. Respawn about five minutes."] = "五个畸变火焰图腾。{zone:1418}中{area:338}以南的石穹穴居怪（碎颅者、碎骨者和萨满，37-41级）携带它们；萨满会放下火焰新星图腾和一个{npc:3560}，碎骨者受伤时会逃跑求援。刷新约五分钟。",
	["Five Twisted Water Totems. The Mirefin murlocs (level 35-38) north-east of {area:496} in northern {zone:1445} carry them."] = "五个畸变水图腾。{zone:1445}北部{area:496}东北的泥鳍鱼人（35-38级）携带它们。",
	["Shaman"] = "萨满",
	["The steam pools"] = "蒸汽池",
	["The {item:5178} that lets you place air totems, then a weapon of your choice at 40."] = "让你放置空气图腾的{item:5178}，然后在40级获得一把自选武器。",
	["Twisted Air Totems"] = "扭曲的空气图腾",
	["Twisted Earth Totems"] = "扭曲的大地图腾",
	["Twisted Fire Totems"] = "扭曲的火焰图腾",
	["Twisted Water Totems"] = "扭曲的水之图腾",
	["{area:1717} is a five-player dungeon at the southern edge of the {zone:1413} (the arrow points at its entrance); {npc:4421} (level 33 elite) is its last boss. She casts {spell:8292}, {spell:139} on her allies and Purity; the {item:274463} drops only from her."] = "{area:1717}是{zone:1413}南缘的五人副本（箭头指向它的入口）；{npc:4421}（33级精英）是最终首领。她会施放{spell:8292}、对盟友施放{spell:139}和纯净；{item:274463}只有她会掉落。",
	["{item:212792}, from the {npc:216474}"] = "{item:212792}，来自{npc:216474}",
	["{item:274463}, from {npc:4421}"] = "{item:274463}，来自{npc:4421}",
	["{npc:259023} camps in the hills just west of {area:321}, the Horde town in the north-east of Arathi: mind its guards. Fly to {area:320} and head north-east."] = "{npc:259023}在{area:321}正西的丘陵扎营，那是阿拉希东北的部落城镇：小心它的卫兵。飞往{area:320}，然后向东北走。",
	["{npc:259023} hands you the {item:268582}. {zone:1441} is far: the boat to Theramore and the road west, or fly to {area:489} on the {zone:1444} border and head east into the canyon. Place the {item:268582} at the steam pools north-west of {area:484} to call the corrupted elementals and then the {npc:216474}; Razormane quilboar join the fight while the ritual runs. A group quest: bring at least one or two friends. The {item:212792} drops about every other kill, and every group member can loot it."] = "{npc:259023}交给你{item:268582}。{zone:1441}很远：可以乘船去塞拉摩再走西路，或者飞到{zone:1444}边界的{area:489}，再向东进入峡谷。把{item:268582}放在{area:484}西北的蒸汽池，召唤被腐蚀的元素，然后是{npc:216474}；仪式进行时钢鬃野猪人会加入战斗。这是一个组队任务：至少带一两个朋友。{item:212792}约每两次击杀掉一个，每个队员都能拾取。",
	["{npc:259023}: your {item:5178}"] = "{npc:259023}：你的{item:5178}",
	["{npc:6176} camps in the ruins in the east of {zone:1416}: from {area:272} follow the river east of town north into the hills. Pick your weapon: {item:280607}, {item:280605} or {item:280604}."] = "{npc:6176}在{zone:1416}东部的废墟扎营：从{area:272}沿镇东的河流向北进入丘陵。选择你的武器：{item:280607}、{item:280605}或{item:280604}。",
	["{npc:6176}: the {item:280696} and your weapon"] = "{npc:6176}：{item:280696}和你的武器",
	["{quest:94789} and the Tempest's Weapons (Alliance)"] = "{quest:94789}和The Tempest's Weapons（联盟）",
}

G["forever/class/shaman/call-of-earth-alliance"] = {
	["Back to Teo inside {area:77}. He hands you the {item:6635}: do not drink it yet."] = "回到{area:77}里的提奥。他会给你{item:6635}：先别喝。",
	["Bring the {item:6656} back to Teo inside {area:77}. Keep the {item:5175} in your bags for good: every earth totem needs it."] = "把{item:6656}带回{area:77}里的提奥。把{item:5175}永久留在背包里：每个大地图腾都需要它。",
	["Iceclaw Bear Pendants"] = "冰爪熊吊坠",
	["Lost the {quest:94472}?"] = "{quest:94472}丢了？",
	["Only if the {quest:94472} is gone from your bags (drunk away from the stone, or sold): Teo gives you another."] = "只有当{quest:94472}从你背包里消失时（在石块以外的地方喝掉或卖掉）：提奥会再给你一个。",
	["Shaman"] = "萨满祭司",
	["The Frostmane Troll Whelps (level 3-4) hold the snowy slopes west and south-west of {area:77}, and the Frostmane Novices (level 3-4, they throw Frostbolts from range) camp south of it. Both carry the pendants; they respawn in about three minutes."] = "霜鬃巨魔幼崽（3-4级）占据{area:77}西边和西南的雪坡，霜鬃新兵（3-4级，会远程投掷寒冰箭）扎营在其南边。两者都携带吊坠；约三分钟刷新。",
	["The Spirit Stone"] = "灵魂之石",
	["The Spirit Stone stands on a snowy ridge north-west of {area:77}. The trail is easy to miss: it climbs the hill from the valley floor; at the small camp near the top turn left and the stone comes into view. Stand beside it, drink the {item:6635} and speak to the {npc:5891} before it fades."] = "灵魂之石立在{area:77}西北的雪脊上。小路很容易错过：它从谷底爬上山丘；在接近顶部的小营地左转就能看见石头。站在石旁，喝下{item:6635}，趁它消失前与{npc:5891}交谈。",
	["Your {item:5175}: without it no earth totem can be cast. {spell:8071} comes with it at level 4."] = "你的{item:5175}：没有它就无法施放任何大地图腾。4级时随之获得{spell:8071}。",
	["it hands you the {item:6656}: keep it"] = "它会给你{item:6656}：留着",
	["the level 4 shaman spells"] = "4级萨满法术",
	["{item:6635}, beside the Spirit Stone"] = "{item:6635}，在灵魂石旁",
	["{npc:257446} trains shamans inside {area:77}, the hall at the south end of {area:132}. The quest opens at level 4. Never took it and now 10 or more? {npc:258098} in {zone:1455} or {npc:258113} in {area:131} gives you {quest:94373}, a pointer back to Teo: take it for the experience on the way."] = "{npc:257446}在{area:132}南端大厅、{area:77}内训练萨满。任务4级开放。从没接过而现在已10级以上？{zone:1455}的{npc:258098}或{area:131}的{npc:258113}会给你{quest:94373}，指向提奥：顺路接下拿经验。",
	["{npc:257446}: a new {quest:94472}"] = "{npc:257446}：新的{quest:94472}",
	["{npc:257446}: {spell:8071} and your {item:5175}"] = "{npc:257446}：{spell:8071}与你的{item:5175}",
	["{quest:94373} (Alliance)"] = "{quest:94373}（联盟）",
}

G["forever/class/shaman/call-of-fire-alliance"] = {
	["At 10 {npc:258113}, the shaman trainer in {area:131}, or {npc:258098}, the shaman trainer in {zone:1455}, sends you to {npc:257597}."] = "10级时，{area:131}的萨满训练师{npc:258113}，或{zone:1455}的萨满训练师{npc:258098}，会派你去找{npc:257597}。",
	["Back through the South Gate tunnel and up the trail to {npc:257597}' cave. Keep the {item:5176} in your bags for good: every fire totem needs it."] = "穿过南门隧道返回，沿小路向上到{npc:257597}的洞穴。把{item:5176}永久留在背包里：每个火焰图腾都需要它。",
	["Back up the trail to {npc:257808}. He makes the {item:6636} from the tar and the pouch: keep it with the torch."] = "沿小路返回{npc:257808}处。他用焦油和袋子制作{item:6636}：把它和火把一起留着。",
	["Click the {object:61934} atop the shrine with the torch in your bags to place the ember, then click it again for the next quest: the lit {item:277329}."] = "背包里带着火把，点击神龛顶部的{object:61934}放置余烬，然后再点击它接取下一个任务：点燃的{item:277329}。",
	["Climb on past {npc:257808} to the peak. Drink the {item:6636} beside the rock statue there to see the {npc:5893} (level 12): it waits until you strike, but grows stronger the longer it is left, and it is immune to fire. Open at once with {spell:8017} and {spell:8042}. Its {item:6655} drops every time."] = "经过{npc:257808}继续爬到山顶。在岩石雕像旁喝下{item:6636}，就能看到{npc:5893}（12级）：它会一直等你出手，但放置越久就越强，而且免疫火焰。立刻用{spell:8017}和{spell:8042}起手。它每次都会掉落{item:6655}。",
	["Follow the road east to the tunnel towards {area:806}. Out of the first tunnel, keep left past {npc:1959} and the tower: a slim trail, hard to see but shown on the minimap, winds up the mountain to {npc:257597}' cave above the farm. He hands you the {item:6653}: keep it until the end of the chain."] = "沿路向东到通往{area:806}的隧道。出第一个隧道后，靠左经过{npc:1959}和塔楼：一条细窄的小路虽然难看清，但小地图上会显示，它盘山而上通往农场上方的{npc:257597}洞穴。他给你{item:6653}：留到任务链结束。",
	["From {npc:257597}' ledge you can drop carefully down the mountain into {zone:1432}, or walk back through the tunnel. {npc:257808} keeps the shrine on the peak just south of {area:144}: a hidden trail along a cliff ledge, marked by stone totems, climbs to it from the road north of the peak."] = "从{npc:257597}的岩架，你可以小心地从山上跳到{zone:1432}，或从隧道走回去。{npc:257808}守着{area:144}正南方山顶上的神龛：一条沿悬崖岩架、由石图腾标记的隐秘小路，从山顶北边的道路向上通往那里。",
	["Lost the {quest:94473}?"] = "弄丢了{quest:94473}？",
	["Only if the {quest:94473} is gone from your bags: {npc:257808} gives you another."] = "只有在{quest:94473}从你的包里消失时：{npc:257808}会再给你一个。",
	["Shaman"] = "萨满",
	["The Shrine of Eternal Flame"] = "永恒之焰神龛",
	["The Stonesplinter Seers (level 13-14) stand among the troggs of {area:923} in the south of the loch, and in the trogg camps north-east of {area:144}. They throw {spell:1245113} from 40 yards and run for help when hurt: pull one at a time. Respawn about five minutes."] = "石裂先知（13-14级）混在湖泊南部{area:923}的穴居人中，也在{area:144}东北的穴居人营地。他们会从40码外投掷{spell:1245113}，受伤时会跑去求援：一次拉一只。约5分钟刷新。",
	["The Tunnel Rat Geomancers (level 12-13) work only inside the {area:149} at the north end of the loch, past {area:144}. They cast {spell:2136} behind a {spell:134} and run for help at low health."] = "隧道鼠地卜师（12-13级）只在湖泊北端、过了{area:144}之后的{area:149}内活动。他们会躲在{spell:134}后面施放{spell:2136}，低血量时跑去求援。",
	["The {object:61934}"] = "{object:61934}",
	["Your {item:5176} for every fire totem, {spell:3599} with it, and Forever's {item:263412}."] = "获得用于所有火焰图腾的{item:5176}、借此学会的{spell:3599}，以及Forever的{item:263412}。",
	["{item:6636}, beside the statue"] = "{item:6636}，雕像旁",
	["{npc:257597}: {spell:3599}, your {item:5176} and the {item:263412}"] = "{npc:257597}：{spell:3599}、你的{item:5176}和{item:263412}",
	["{npc:257808}: a new {quest:94473}"] = "{npc:257808}：新的{quest:94473}",
	["{npc:258113}, {area:131}; or {npc:258098}, {zone:1455}"] = "{npc:258113}，{area:131}；或{npc:258098}，{zone:1455}",
	["{quest:94449} (Alliance)"] = "{quest:94449}（联盟）",
}

G["forever/class/shaman/call-of-water-alliance"] = {
	["At 20 {npc:258098}, the shaman trainer in {zone:1455}'s {object:32362}, sends you to {npc:258043} in {zone:1432}."] = "20级时，{zone:1455}的{object:32362}中的萨满训练师{npc:258098}派你去找{zone:1432}的{npc:258043}。",
	["Back to {npc:258043} by {area:146} with the {item:7810}. He hands you the {item:6637} and the {item:7811}: keep both for {zone:1436}."] = "带着{item:7810}回到{area:146}旁的{npc:258043}处。他会交给你{item:6637}和{item:7811}：两样都留着，去{zone:1436}要用。",
	["Back to {npc:258043} with the {item:7813}. Keep the {item:5177} in your bags for good: every water totem needs it."] = "带着{item:7813}回到{npc:258043}处。把{item:5177}永久留在背包里：每个水图腾都要用它。",
	["Fill the {item:265732} at the bottom of the waterfalls below {npc:258203}'s cave, where the fresh water meets the brackish. {object:147516} dwarves roam near the falls."] = "在{npc:258203}洞穴下方瀑布的底部、淡水与咸水交汇处，装满{item:265732}。{object:147516}矮人在瀑布附近游荡。",
	["Fly to {area:108} and head south to {area:20}: {area:919} and the {object:619896} lie just north of it. Drink the {item:6637} by the shrine to see the {npc:5894} (level 22, {spell:8056} and {spell:122}; one spawn, back three minutes after a kill), defeat it for its bracers (always dropped), then place them and the {item:7811} on the {object:619896} (this, not {npc:258043}, ends the quest). Click the shrine again: the {npc:5895} rises beside it; speak to it before you walk off (if it is gone, abandon and take the quest again at the shrine). It gives you the {item:7813}."] = "飞往{area:108}，再向南到{area:20}：{area:919}和{object:619896}就在它北边。在神龛旁喝下{item:6637}，就能看到{npc:5894}（22级，会施放{spell:8056}和{spell:122}；只有一个刷新点，被杀后三分钟回来），击败它拿到护腕（必掉），然后把护腕和{item:7811}放到{object:619896}上（结束任务的是这一步，不是{npc:258043}）。再次点击神龛：{npc:5895}会浮现在旁边；离开前先和它交谈（如果它消失了，就放弃任务，在神龛处重新接取）。它会给你{item:7813}。",
	["Lost the {quest:94616}?"] = "把{quest:94616}弄丢了？",
	["Only if the {quest:94616} is gone from your bags: {npc:258043} gives you another before you leave for {zone:1436}."] = "只有当{quest:94616}从背包里消失时才需要：出发去{zone:1436}前，{npc:258043}会再给你一份。",
	["Shaman"] = "萨满",
	["Take the boat from {area:150} to {area:442} (it stops in {area:271} on the way), then fly or walk south through {zone:1439} to {area:415} in {zone:1440}. Fill the {item:265772} in the lake around the town, then the boat back to Menethil."] = "从{area:150}坐船到{area:442}（途中会停靠{area:271}），然后向南飞或步行穿过{zone:1439}，到{zone:1440}的{area:415}。在城镇周围的湖里装满{item:265772}，再坐船回米奈希尔。",
	["The blue waterskin"] = "蓝色水袋",
	["The brown waterskin"] = "棕色水袋",
	["The red waterskin"] = "红色水袋",
	["The {item:5177} that lets you place water totems, and {spell:5394} with it."] = "让你能放置水图腾的{item:5177}，以及随之而来的{spell:5394}。",
	["the {item:7810}, for {npc:258043}"] = "{item:7810}，交给{npc:258043}",
	["{area:71} pour out of {area:68} at the east end of Redridge (fly from {zone:1455} to {area:69}). Fill the {item:265747} at their foot, where the Murloc Nightcrawlers gather; pull the murlocs off the spot first. If the skin vanishes without counting, abandon the quest and take it again from {npc:258203} for a new one."] = "{area:71}从赤脊山东部{area:68}中涌出（从{zone:1455}飞往{area:69}）。在它们脚下、鱼人夜行者聚集的地方装满{item:265747}；先把鱼人从那里引开。如果皮囊在没有计数的情况下消失，就放弃任务，回去找{npc:258203}再接一次，拿个新的。",
	["{npc:258043}'s burrow hut stands on the north-western shore of the loch, below {area:146}, north of {area:144}."] = "{npc:258043}的洞穴小屋位于湖的西北岸，{area:146}下方、{area:144}以北。",
	["{npc:258043}: a new {quest:94616}"] = "{npc:258043}：新的{quest:94616}",
	["{npc:258043}: your {item:6637}"] = "{npc:258043}：你的{item:6637}",
	["{npc:258043}: {spell:5394} and your {item:5177}"] = "{npc:258043}：{spell:5394}和你的{item:5177}",
	["{npc:258203}'s family lives in a cave beneath the southern falls of the {zone:1437}, east of {area:836}: not in a town. Through the Algaz tunnel north of {zone:1432}, then east off the road."] = "{npc:258203}的家人住在{zone:1437}南部瀑布下方的洞穴里，{area:836}以东：不在镇上。穿过{zone:1432}以北的阿尔加兹隧道，然后离开道路向东走。",
	["{npc:5895}, at the shrine"] = "{npc:5895}，在神龛处",
	["{quest:94494} (Alliance)"] = "{quest:94494}（联盟）",
}

G["forever/class/warlock/dread-mage-hat"] = {
	["A cloth hat in your late 20s: Zardeth's errand for any Alliance player pays warlocks this extra."] = "28级左右可得的布甲头盔：任何联盟玩家都能接扎尔戴斯的差事，术士会额外获得这件奖励。",
	["At 25 {npc:1435}, in the cellar of the {object:2164} in the {object:2101} (beside the warlock trainers), wants two ingredients for a brew. Do it when your leveling takes you to {zone:1431} and the {zone:1437}."] = "25级时，{object:2101}里{object:2164}的地窖中（术士训练师旁）的{npc:1435}要两种材料来配药。等你练级到{zone:1431}和{zone:1437}时再做。",
	["Back to Zardeth once more: he offers warlocks a reward, which his imp {npc:1733}, standing beside him, hands over."] = "再次回到扎尔迪斯：他给术士一份奖励，由他身旁的小鬼{npc:1733}交给你。",
	["Back to Zardeth. He brews the {item:2788} and gives it to you for {npc:1439} in the Hall of Petitioners, the first hall on the right inside {object:2117}."] = "回到扎尔迪斯。他酿好{item:2788}交给你，再拿去给{object:2117}内右侧第一个大厅——请愿者大厅——里的{npc:1439}。",
	["The root grows at the water's edge in the pool below the small falls east of {area:836}, beside the {object:147516} cave below the {area:146}: a tall, spiky wooden root, not at the foot of the dam itself."] = "根生长在{area:836}东边小瀑布下池塘的水边，在{area:146}下方{object:147516}洞穴旁：一根高大、带尖刺的木根，不在水坝脚下。",
	["Warlock"] = "术士",
	["{area:1098} stands in the north-east of {zone:1431}, north of {area:42}. The {object:321} is a small white flower low in the grass of the fenced garden beside Stalvan's house: hard to see, so sweep the garden with your mouse. Fetid Corpses (level 29) wander the grounds and come quickly: at 25, send your voidwalker at the nearest one, grab the flower and leave. {npc:315} (32) is inside the house; leave him alone."] = "{area:1098}在{zone:1431}东北、{area:42}以北。{object:321}是一朵小白花，低低地长在斯塔文房子旁围栏花园的草丛里：很难看见，用鼠标在花园里扫一遍。腐臭的尸体（29级）在院子里游荡，来得很快：25级时派虚空行者去最近的尸体，采花后离开。{npc:315}（32级）在屋里；别惹他。",
}

G["forever/class/warlock/felhunter-alliance"] = {
	["At 30 {npc:6120}, in the {object:32383}, sends you to {npc:6251} in {area:392}."] = "30级时，{object:32383}的{npc:6120}会让你去{area:392}找{npc:6251}。",
	["At 30 {npc:6122}, in the cellar of the {object:2164} in the {object:2101}, sends you to {npc:6251} in {area:392}."] = "30级时，{object:2101}{object:2164}地下室的{npc:6122}会让你去{area:392}找{npc:6251}。",
	["Back to {npc:6251} in {area:392}. When you accept, he draws the summoning circle and his acolytes channel a greater circle over it: wait inside the tower until both are done. Then use the {quest:1804} on the circle. The felhunter (level 30, not elite) silences and eats mana, and it vanishes after two minutes: have your voidwalker out, open with your damage over time at once and let the voidwalker tank. If you die or it wins, abandon {quest:1795} and take it again from {npc:6251}. Keep the tome: {npc:6251} takes it back."] = "回到{area:392}找{npc:6251}。接受任务后，他会画出召唤法阵，他的助手们会在上面引导一个更大的法阵：在塔里等到两个法阵都完成。然后在法阵上使用{quest:1804}。地狱犬（30级，非精英）会沉默并吸取法力，两分钟后消失：先放出你的虚空行者，立刻挂上持续伤害，让虚空行者负责扛。如果你死了或它赢了，放弃{quest:1795}，再从{npc:6251}那里重新接。留着那本书：{npc:6251}会把它收回去。",
	["Back to {npc:6294}"] = "回到{npc:6294}",
	["Felhunter (Alliance)"] = "地狱猎犬（联盟）",
	["Rods of Channeling"] = "导能魔棒",
	["Rods of Channeling, from the Dragonmaw casters"] = "导能法杖，由龙喉施法者掉落",
	["Summoned Felhunter"] = "召唤的地狱犬",
	["The Dragonmaw hold {area:1036} in the hills east of the road from {area:150} to {area:836}. Only the casters drop the rods, four kills in five: the Bonewarders (level 27, with skeleton pets) and Shadowwarders (28). A steep path north of the central spirit healer leads up into the camp past most of the warriors."] = "龙喉兽人占据着{area:1036}，在从{area:150}到{area:836}的路东丘陵中。只有施法者会掉法杖，约五次击杀掉四根：白骨看守者（27级，带骷髅宠物）和暗影看守者（28级）。中央灵魂医者以北的一条陡峭小路能绕过大部分战士，直上营地。",
	["The centaur cave opens in the cliffs north of {area:484}, a Horde town: keep clear of its guards. Inside, keep right at each fork, cross the pool by the small waterfall, and open the small dark box against the wall beside a larger chest: the larger one is the wrong one. You can open it only while on the quest. The centaurs respawn behind you on the way out."] = "半人马洞穴开在{area:484}以北的峭壁里，那是部落城镇：避开它的卫兵。进洞后每个岔路都向右，穿过小瀑布旁的水池，打开靠墙、在一个大箱子旁边的小暗箱：大的那个是错的。只有做任务时你才能打开它。出来时，半人马会在你身后刷新。",
	["The felhunter, the demon to bring against spellcasters, and a {item:22244} for your shards."] = "地狱猎犬，对付施法者的恶魔，外加一个用来装灵魂碎片的{item:22244}。",
	["The tome is a small grey-blue book lying in the sand of a murloc camp on the shore south-west of {area:271}, near the water's edge. Six or seven murlocs guard it and more lurk underwater: they come in groups, so Fear one and keep your voidwalker on the rest. Walk down to the water to click it; from the hillside the crates block the cursor."] = "那本书是一本灰蓝色的小书，躺在{area:271}西南海岸一处鱼人营地的沙地上，靠近水边。六七只鱼人守着它，水下还藏着一批：它们成群出现，所以恐惧一只，让虚空行者对付其余的。走到水边才能点它；从山坡上点会被木箱挡住光标。",
	["Warlock"] = "术士",
	["{area:392} is a neutral goblin port on the {zone:1413} coast: the boat from {area:35} docks there. {npc:6251} stands on the hill above the town, behind the engineers' hut, by his little tower; {npc:6266} and two acolytes are with him. He sends you to {npc:6294} in {zone:1455}."] = "{area:392}是{zone:1413}海岸上的中立地精港口：从{area:35}来的船在那里停靠。{npc:6251}站在镇上方的小山上，工程师小屋后面、他的小塔旁；{npc:6266}和两个助手跟他在一起。他派你去{zone:1455}的{npc:6294}那里。",
	["{item:6931}, from the {quest:1802} on the sand"] = "{item:6931}，来自沙滩上的{quest:1802}",
	["{item:6997}, in the {object:92423}"] = "{item:6997}，在{object:92423}里",
	["{npc:6294} is in the library of the {object:32356}. He wants two lost pieces of the {quest:1758}: one on the {area:287} coast, one in {zone:1441}."] = "{npc:6294}在{object:32356}的图书馆里。他要{quest:1758}中遗失的两块碎片：一块在{area:287}海岸，一块在{zone:1441}。",
	["{npc:6294} pieces the tome together and gives you the {item:7006}: keep it, {npc:6251} takes it with the rods."] = "{npc:6294}把书拼好，交给你{item:7006}：留着它，{npc:6251}会和法杖一起收走。",
	["{quest:1804}, on the circle"] = "{quest:1804}，在法阵上",
}

G["forever/class/warlock/imp-alliance"] = {
	["Feather Charms"] = "羽毛护符",
	["Imp (Alliance)"] = "小鬼（联盟）",
	["The Defias tent stands in the vineyard east of the Abbey. The book is small: it lies on the ground just right of the tent's opening, beside a blue jug. Three Defias Thugs (level 3-4) guard the tent; pull them one at a time, or step inside the tent and click the book, where they cannot reach you. The book respawns three minutes after someone takes it."] = "迪菲亚帐篷搭在修道院以东的葡萄园里。那本书很小：就放在帐篷入口右侧的地上，旁边有个蓝色罐子。三个迪菲亚暴徒（3-4级）守着帐篷；一只一只地拉，或者走进帐篷再点击书本，他们在那里够不到你。书被拿走后三分钟刷新。",
	["The Frostmane Novices (level 3-4) sit at the back of the troll cave south of {area:77}, near Grek'nir the Cold by the icy pool: take the left tunnel past the entrance. Four kills in five drop a charm, but only two or three novices spawn, so you may wait out their three-minute respawn. They throw frostbolts from range; the Troll Whelps at the cave mouth jump anyone who passes. With the charms, your hearthstone takes you straight back: a new character's is set to {area:132}."] = "霜鬃新兵（3-4级）坐在{area:77}以南巨魔洞穴的深处，靠近冰池旁冷酷的格雷克尼尔：进洞后走左边的通道。五次击杀中有四次掉落护符，但只会刷出两三个新兵，所以可能得等他们三分钟刷新。他们会远程投掷寒冰箭；洞口的巨魔幼崽会扑向任何路过的人。凑齐护符后，炉石可以直接送你回去：新角色的炉石绑定在{area:132}。",
	["The {object:83763}"] = "{object:83763}",
	["Warlock"] = "术士",
	["Your first demon at level 1-4: the imp, from your start zone's warlock trainer."] = "1-4级的第一个恶魔：小鬼，在你初始地区的术士训练师处获得。",
	["Your first letter ({item:9576}, from {npc:197} after Kobold Camp Cleanup) points you to {npc:459}, the warlock trainer in the little graveyard beside {area:24}. She asks for a book the Defias stole."] = "你的第一封信（{item:9576}，完成“清理狗头人营地”后由{npc:197}给予）让你去找{npc:459}，即{area:24}旁小墓地里的术士训练师。她要一本被迪菲亚偷走的书。",
	["Your first letter ({item:9577}, from {npc:658} after Dwarven Outfitters) points you to {npc:460}, the warlock trainer upstairs inside {area:77}. He asks for three Feather Charms."] = "你的第一封信（{item:9577}，完成“矮人装备”后由{npc:658}给予）让你去找{npc:460}，即{area:77}内楼上的术士训练师。他要三个羽毛护符。",
	["{item:6785}, from the {object:83763}"] = "{item:6785}，来自{object:83763}",
	["{npc:459} (Humans)"] = "{npc:459}（人类）",
	["{npc:459} teaches you {spell:688} at the hand-in: summon it right away, it costs nothing and fights beside you."] = "{npc:459}在交付时教你{spell:688}：立刻召唤它，不消耗任何东西，还会和你并肩作战。",
	["{npc:460} (Gnomes)"] = "{npc:460}（侏儒）",
	["{npc:460} teaches you {spell:688} at the hand-in: summon it right away, it costs nothing and fights beside you."] = "{npc:460}在交付时教你{spell:688}：立刻召唤它，不消耗任何东西，还会和你并肩作战。",
}

G["forever/class/warlock/incubus-alliance"] = {
	["At 20 {npc:6120}, the warlock trainer in {zone:1455}'s {object:32383}, sends you to {npc:6122} in {zone:1453}. Take the {area:2257}."] = "20级时，{zone:1455}的{object:32383}里的术士训练师{npc:6120}派你去{zone:1453}的{npc:6122}处。乘坐{area:2257}。",
	["At 20 {npc:6122}, in the cellar of the {object:2164} in the {object:2101}, sends you to {npc:6244} in the {zone:1413}: a long trip for the Alliance. Take the boat from {area:150} to Theramore and head west through {zone:1445}, or the boat from {area:35} to {area:392}."] = "20级时，{object:2101}里{object:2164}地下室中的{npc:6122}派你去{zone:1413}的{npc:6244}：对联盟来说是一趟长途。从{area:150}乘船到塞拉摩，向西穿过{zone:1445}；或者从{area:35}乘船到{area:392}。",
	["At 20: the succubus and Forever's incubus, its male twin, each with a soul pouch for your shards."] = "20级时：魅魔，以及Forever服务器特有的夜魔——魅魔的男性孪生恶魔，各附带一个装灵魂碎片的灵魂袋。",
	["Back to {npc:6122} with the {quest:1738}. He hands you the {item:6913}: take the stairs behind him down to the crypt; part way along the lowest corridor a side stair on the left leads to the room with the purple circle. Stand on it and use the core. Summon your voidwalker first and keep the succubus (level 20, not elite) on the circle, or the guards may kill her and the kill does not count. If she wins, use the core again; keep it, {npc:6122} takes it back."] = "带着{quest:1738}回到{npc:6122}处。他交给你{item:6913}：从他身后的楼梯下去进入墓穴；沿最下面的走廊走一段，左侧有一道侧梯通往带紫色法阵的房间。站上去，使用宝珠。先召唤你的虚空行者，让魅魔（20级，非精英）留在法阵上，否则卫兵可能杀死她，击杀就不算数。如果她赢了，再次使用宝珠；留着它，{npc:6122}会收回去。",
	["Give Gakin the figurine, then use the {item:190309} at the middle of the same circle and defeat the incubus it calls (level 20, not elite; it can charm you) with your voidwalker tanking. Keep the figurine: {npc:6122} takes it back."] = "把小雕像交给加金，然后在同一个法阵中央使用{item:190309}，击败它召唤的男魅魔（20级，非精英；它会魅惑你），让虚空行者扛。留着雕像：{npc:6122}会收回去。",
	["Ordil'Aran lies in north-west {zone:1440}, north of {area:415} along the road toward {zone:1439}. About twenty Dark Strand cultists hold the ruins around the great tree: keep to the outer wall, and click the {quest:1738} from as far away as it lets you. It is turned in to {npc:6122}, not to Takar."] = "奥狄尔阿兰位于{zone:1440}西北，在{area:415}以北、通往{zone:1439}的路上。约二十名暗滩教徒占据着大树周围的废墟：贴着外墙走，尽量在能点的最远处点击{quest:1738}。它交给{npc:6122}，不是交给塔卡尔。",
	["Succubus and Incubus (Alliance)"] = "魅魔与夜魔（联盟）",
	["Summoned Incubus"] = "被召唤的男魅魔",
	["Summoned Succubus"] = "召唤的魅魔",
	["The house stands alone in the trees of north-western {zone:1440}, north-west of Ordil'Aran and well north of {area:413}: do it on the same trip as the {quest:1738}. Take the {item:190307} from the table outside, light it at a campfire (a {object:29784} of your own, or Talen's fire on {area:414}), and go straight back: the {item:190308} burns out after five minutes, so a fire of your own beside the house is quickest. Without it the figure in the house stops you. The figurine is upstairs."] = "那座房子孤零零地立在{zone:1440}西北的树林中，在奥狄尔阿兰西北、{area:413}以北很远处：与{quest:1738}同一次出门做掉。从外面的桌上拿{item:190307}，在营火处点燃（自己摆一个{object:29784}，或用{area:414}上塔伦的火），然后立刻回去：{item:190308}五分钟后烧完，所以在房子旁边自己生一堆火最快。没有它，屋里的那个人偶会拦住你。雕像在楼上。",
	["The {item:190309}"] = "{item:190309}",
	["Warlock"] = "术士",
	["the incubus"] = "男魅魔",
	["the succubus"] = "魅魔",
	["{item:190307}, on the table outside"] = "{item:190307}，在外面桌上",
	["{item:190309}, upstairs"] = "{item:190309}，楼上",
	["{item:6913}, on the circle in the crypt"] = "{item:6913}，在墓穴法阵上",
	["{npc:185335}, at the circle in the crypt"] = "{npc:185335}，在墓穴法阵旁",
	["{npc:6244} camps at a tent with a campfire just north-east of {area:378}, by a fork in the road: Horde ground, so come in from the east and keep clear of the Taurajo guards. {npc:6247} beside him starts the {item:6898}. Takar offers both branches: take both."] = "{npc:6244}在{area:378}东北不远处、一个路口旁的带营火帐篷扎营：那是部落地盘，所以从东边进入，避开陶拉祖卫兵。他身旁的{npc:6247}会开启{item:6898}。塔卡尔提供两个分支：都接。",
	["{quest:1717} (Gnomes)"] = "{quest:1717}（侏儒）",
	["{quest:1739}: succubus"] = "{quest:1739}：魅魔",
	["{quest:65603}: incubus"] = "{quest:65603}：男魅魔",
}

G["forever/class/warlock/voidwalker-alliance"] = {
	["At 10 {npc:6120}, the warlock trainer in {zone:1455}'s {object:32383}, sends you to {npc:6122} in {zone:1453}. Take the {area:2257} from {object:171524}. If {npc:6120} does not offer it, go to {npc:6122} anyway: he still gives you the next quest."] = "10级时，{zone:1455}的{object:32383}里的术士训练师{npc:6120}会让你去找{zone:1453}的{npc:6122}。从{object:171524}乘{area:2257}过去。如果{npc:6120}没有给你任务，也直接去找{npc:6122}：他照样会给你下一个任务。",
	["At 10 {npc:6121}, in the cellar of the Lion's Pride Inn in {area:87} (the stairs down are in the back room past the butcher's table), sends you to {npc:6122} in {zone:1453}."] = "10级时，{area:87}狮王之傲旅店地窖里的{npc:6121}（下去的楼梯在里屋、经过屠夫的桌子）会让你去找{zone:1453}的{npc:6122}。",
	["Back to {npc:6122}. He hands you the {item:6928}. The circle is hard to find: take the stairs behind {npc:6122} down; part way along the lowest corridor a side stair on the left leads into a room with a glowing purple circle in the middle. Stand on it and use the choker. The voidwalker (level 10, not elite) gets dangerous below 30% health: {spell:14868}, Corruption and {spell:348} with your imp on it, Fear when it gets close. If it beats you, use the choker again. Keep the choker: {npc:6122} takes it back."] = "回到{npc:6122}。他把{item:6928}交给你。法阵很难找：走{npc:6122}身后的楼梯下去；走到最底层走廊的中段，左侧有一条侧梯通向一个中间有发光紫色法阵的房间。站在法阵上使用项圈。虚空行者（10级，非精英）血量低于30%时很危险：让小鬼攻击它，用{spell:14868}、腐蚀术和{spell:348}，它靠近时用恐惧。如果它打败你，再用一次项圈。项圈要留着：{npc:6122}会收回。",
	["Summoned Voidwalker"] = "被召唤的虚空行者",
	["Surena Caledon"] = "苏雷娜·卡莱顿",
	["Voidwalker (Alliance)"] = "虚空行者（联盟）",
	["Warlock"] = "术士",
	["Your tank demon at 10: the voidwalker, after a dark sorceress's choker and a fight in {npc:6122}'s crypt."] = "10级的坦克恶魔：虚空行者。先取得一名黑暗女巫的项圈，再到{npc:6122}的墓穴中打一场。",
	["{item:6928}, on the circle in the crypt"] = "{item:6928}，在墓穴的法阵上",
	["{npc:6121}, Lion's Pride Inn cellar"] = "{npc:6121}，狮王之傲旅店地窖",
	["{npc:881} (level 9) is inside the farmhouse at the {area:62}, south-east Elwynn near the Redridge road. {npc:473} (level 10) and a warrior stand with her and join the fight; Morgan gouges and goes for your imp, so keep him Feared. Put your damage over time on {npc:881} first, Fear the others, and loot her choker before you finish them: it stays yours even if you die after. She throws fireballs from range and is back three minutes after she dies. Have the quest before you kill her, or the choker does not drop."] = "{npc:881}（9级）在{area:62}的农舍里，位于艾尔文森林东南、靠近赤脊山道路。{npc:473}（10级）和一名战士与她站在一起，会加入战斗；摩根会凿击并攻击你的小鬼，所以让他一直处于恐惧状态。先给{npc:881}上持续伤害，恐惧其他人，在解决他们之前先拾取她的项圈：即便之后你死了，项圈也归你。她从远处扔火球，死后三分钟刷新。杀她之前要先接到任务，否则项圈不会掉落。",
	["{quest:1685} (Humans)"] = "{quest:1685}（人类）",
	["{quest:1715} (Gnomes)"] = "{quest:1715}（侏儒）",
	["{quest:1715} is the tavern in the {object:2101}; {npc:6122} is in its cellar, down the stairs inside."] = "{quest:1715}是{object:2101}里的旅店；{npc:6122}在其地窖，从里面楼梯下去。",
}

G["forever/class/warrior/fire-hardened-armor"] = {
	["A hauberk at 28, a coif, leggings and gauntlets from three smiths, and a shield on the way."] = "28级的锁甲，三位铁匠分别给出罩帽、护腿和护手，途中还有一面盾牌。",
	["At 20, {npc:5113}, the warrior trainer of {zone:1455}, sends you to {quest:1698} in Redridge."] = "20级时，{zone:1455}的战士训练师{npc:5113}会让你去赤脊山找{quest:1698}。",
	["At 20, {npc:5479}, beside {npc:5480} in the warrior trainers' building of {object:2100}, sends you to {quest:1698} in Redridge."] = "20级时，{object:2100}战士训练师建筑里{npc:5480}身旁的{npc:5479}派你去赤脊山找{quest:1698}。",
	["At 20, {npc:7315}, the warrior trainer of {zone:1457}, sends you to {quest:1698} in Redridge."] = "20级时，{zone:1457}的战士训练师{npc:7315}会让你去赤脊山找{quest:1698}。",
	["Back to {npc:5413} in the {object:28027} for the hauberk. He then sends you to the smith of your race; the other two smiths' pieces are open to you as well: talk to them directly."] = "回{object:28027}找{npc:5413}领锁甲上衣。然后他会派你去找本种族的铁匠；另外两位铁匠的部件你也可以做：直接找他们谈。",
	["Charred and Galvanized Horns"] = "烧焦的奇美拉角和光滑的奇美拉角",
	["Enter the {area:98} and come back"] = "进入{area:98}后返回",
	["Fire Hardened Armor"] = "淬火护甲",
	["Ride the {area:2257} from {zone:1453} to {zone:1455}. {quest:1704}, a gnome smith, works in {object:171524} near the engineering trainers. He wants 20 {item:6848}."] = "从{zone:1453}乘{area:2257}到{zone:1455}。侏儒铁匠{quest:1704}在{object:171524}工程训练师附近干活。他要20个{item:6848}。",
	["Roogug in {area:1717}"] = "{area:1717}中的鲁古格",
	["Roogug is an elite quilboar (level 28) inside {area:1717}, the dungeon at the south end of the {zone:1413}; a five-player dungeon: needs a group of five, and his guards come with him. Inside take the left path at the first fork, cross the root bridge, go past the big empty cauldron: he is in a dead end on the right, with about ten elites on the way. He casts {spell:403} and calls Earth Rumblers. The vial always drops."] = "鲁古格是{zone:1413}南端地下城{area:1717}里的精英野猪人（28级）；这是五人地下城：需要五人小队，他的卫兵会跟他一起来。进去后在第一个岔路走左边，穿过树根桥，经过那个空的大锅：他在右侧的死路里，路上约有十个精英。他会施放{spell:403}并召唤大地轰响者。药瓶必掉。",
	["Scorched Spider Fangs"] = "烧焦的蜘蛛牙",
	["The Nightbane worgen of {zone:1431} (Dark Runners, Vile Fangs, Shadow Weavers, Worgen and Tainted Ones, level 26-31) south and west of {area:42} drop the {quest:1705} four kills in five. {npc:6170} (level 32, not elite) carries the {item:6845} (also four in five): he walks between the inside and the mouth of the {area:2161} mine south-east of {area:42}, so wait at the entrance and pull him outside. {npc:6170} and the Tainted Ones poison and howl; Vile Fangs cause {spell:3427}."] = "{zone:1431}的夜祸狼人（黑暗奔跑者、邪牙、织影者、狼人和腐化者，26-31级）在{area:42}以南和以西活动，五次击杀有四次掉落{quest:1705}。{npc:6170}（32级，非精英）携带{item:6845}（同样是五次四次）：他在{area:42}东南的{area:2161}矿洞内口与洞口之间走动，所以在入口等着，把他拉到外面打。{npc:6170}和腐化者会下毒和嚎叫；邪牙会造成{spell:3427}。",
	["The chimaeras live south-west of {area:460} in the {area:465}: you need 12 Charred Horns from the Fledgling (level 25-27) and Young Chimaeras (23-25), four kills in five, and the {item:6840} from the {npc:6167} (28, the big one), also four in five. Only three Fledglings, two Young and one Matriarch live there, each back in 5 minutes, so expect to wait. Fledglings and the Matriarch spit {spell:3396}, the Young cast {spell:403}. Alliance: fly to {area:467} and head south."] = "奇美拉住在{area:460}西南的{area:465}：你需要12根烧焦的角，来自幼年奇美拉（25-27级）和青年奇美拉（23-25级），五次四次掉落；还要从{npc:6167}（28级，那只大的）拿{item:6840}，同样五次四次。那里只有三只幼年、两只青年和一只族长，各5分钟刷新，所以要做好等待的准备。幼年和族长会喷{spell:3396}，青年会施放{spell:403}。联盟：飞到{area:467}后向南。",
	["The shells lie on the ground under the wyvern nests at {area:482} in western {zone:1441}, deeper into the gorge. Only nine exist and each returns 3 minutes after you pick it, so you will wait; some shell-like things there cannot be looted. Highperch Wyverns (level 28-31) guard them and sometimes come several at once."] = "贝壳躺在{area:482}风蛇巢下方的地上，位于{zone:1441}西部、峡谷更深处。那里只有九个，每个采集后3分钟刷新，所以你会等上一阵；有些像贝壳的东西无法拾取。高崖风蛇（28-31级）守护着它们，有时会几只一起过来。",
	["The {quest:1708} grows on the sea floor just south of {area:150}, by the murloc huts and a wrecked boat: eight there and two south-east of the harbor, each back in 3 minutes, so you will wait for respawns to reach 20. The murlocs can net you underwater: watch your breath, and an {item:5996} removes the risk."] = "{quest:1708}生长在{area:150}正南的海底，鱼人小屋和一条破船旁：那里有八株，港口东南有两株，各3分钟刷新，所以要等刷新凑够20个。鱼人在水下会用网困住你：留意呼吸条，一瓶{item:5996}就能消除风险。",
	["Warrior"] = "战士",
	["You have one hour, and {npc:6166}'s {spell:8553} leaves you drunk for 8-10 minutes. Run north-west into the {area:98}, keeping close to the cliff wall to miss most gnoll packs, and go in as far as the first fork; then come back to {npc:6166} (from the ridge you can jump down into {area:69}). Dying and releasing your spirit fails the quest: abandon it and {npc:6166} gives it again."] = "你有一个小时，而{npc:6166}的{spell:8553}会让你醉酒8-10分钟。向西北跑进{area:98}，贴着崖壁走以避开大多数豺狼人群，一直进入到第一个岔路；然后回到{npc:6166}（从山脊上可以直接跳进{area:69}）。死亡并释放灵魂会导致任务失败：放弃任务，{npc:6166}会再给你一次。",
	["You need 50 fangs. The Leech Stalkers and Cave Stalkers (level 21-22) crawl in the middle of the {zone:1437}, north of {area:836}; every one drops a fang. They poison; back in 5 minutes."] = "你需要50颗牙。吸血潜伏者和洞穴潜伏者（21-22级）爬行在{zone:1437}中部、{area:836}以北；每只都掉一颗牙。它们会下毒；5分钟刷新。",
	["{item:6839}, from the young chimaeras"] = "{item:6839}，来自青年奇美拉",
	["{item:6840}, from the {npc:6167}"] = "{item:6840}，来自{npc:6167}",
	["{item:6841}, from Roogug"] = "{item:6841}，来自鲁古格",
	["{item:6845}, from {npc:6170}"] = "{item:6845}，来自{npc:6170}",
	["{item:6848}, from {quest:1708}"] = "{item:6848}，来自{quest:1708}",
	["{npc:1416} keeps the weapon shop in the north-west of the {object:28027}, a short walk from {npc:5413}. He wants 20 {quest:1705} and the {item:6845}."] = "{npc:1416}在{object:28027}西北角经营武器店，离{npc:5413}只几步路。他要20个{quest:1705}和{item:6845}。",
	["{npc:5413} works in the Dwarven District of Stormwind. He takes the {item:6843} (lost it? abandon the quest and {npc:6166} gives a new one) and gives you {item:6970}, a shield; {quest:1701} is a level 28 quest, with {item:6842} listing what it needs."] = "{npc:5413}在暴风城矮人区干活。他收下{item:6843}（弄丢了？放弃任务，{npc:6166}会给一个新的）并给你{item:6970}，一面盾；{quest:1701}是28级任务，{item:6842}里列着所需材料。",
	["{quest:1698} sits in the inn at {area:69}. His test is timed: before you take it, clear the Redridge gnolls on the path to the {area:98} in the hills north-west of {area:69}, including the two on the rock by the cave mouth (climb it from its right side)."] = "{quest:1698}待在{area:69}的旅店里。他的考验限时：接任务前，先清掉{area:69}西北丘陵中通往{area:98}路上的赤脊豺狼人，包括洞口岩石上的那两只（从岩石右侧爬上去）。",
	["{quest:1703} works on the south side of the {area:1660} in {zone:1457}. He wants 20 {quest:1710}."] = "{quest:1703}在{zone:1457}的{area:1660}南侧干活。他要20个{quest:1710}。",
	["{quest:1705}, from the Nightbane worgen"] = "{quest:1705}，来自夜祸狼人",
}

G["forever/class/warrior/haggards-weapons"] = {
	["At 10, {npc:1229}, the warrior trainer in {area:131}, sends you to {quest:1679} in {zone:1455}. Any Alliance warrior may take one of the three roads, never two: in {zone:1453} at 10 anyway? {npc:5480}'s {quest:1638} is the quickest stance (one fight in a tavern), with a Haggard's weapon after it."] = "10级时，{area:131}的战士训练师{npc:1229}会让你去{zone:1455}的{quest:1679}处。任何联盟战士都可以走三条路线之一，但不能同时走两条：10级时反正也要去{zone:1453}吗？{npc:5480}的{quest:1638}是最快的姿态任务（在酒馆里打一场），之后还能拿到哈加德的武器。",
	["At 10, {npc:252377} stands with the trainers by {area:16638}'s west gate. A cultist, {npc:257196}, holds her family's shield at the {area:16629}."] = "10级时，{npc:252377}和训练师们站在{area:16638}西门旁。邪教徒{npc:257196}在{area:16629}拿着她家族的盾牌。",
	["At 10, {npc:3598}, the warrior trainer in {area:186}, or {npc:2151}, who patrols the road west of {area:186}, sends you to {quest:1684} on the {area:1660} in {zone:1457}. Any Alliance warrior may take one of the three roads, never two: in {zone:1453} at 10 anyway? {npc:5480}'s {quest:1638} teaches the same stance after one fight in a tavern."] = "10级时，{area:186}的战士训练师{npc:3598}，或在{area:186}以西路上巡逻的{npc:2151}，会让你去{zone:1457}的{area:1660}上找{quest:1684}。任何联盟战士都可以走三条路线之一，但不能同时走两条：10级时反正也要去{zone:1453}吗？{npc:5480}的{quest:1638}在酒馆里打一场后也能教同样的姿态。",
	["At 10, {npc:913}, the warrior trainer by the inn in {area:87}, sends you to {npc:6089} in {zone:1453}; {npc:5480}, the warrior trainer in {zone:1453}'s {object:2100}, offers it too."] = "10级时，{area:87}旅店旁的战士训练师{npc:913}会让你去{zone:1453}的{npc:6089}处；{zone:1453}中{object:2100}里的战士训练师{npc:5480}也提供这个任务。",
	["Back on the {area:1660}: {npc:4088} hands you the {item:6812}; {npc:6142} works on the far, south side of the same terrace, easy to miss."] = "回到{area:1660}：{npc:4088}交给你{item:6812}；{npc:6142}在同一平台的远端南侧工作，很容易错过。",
	["Back to {npc:252377} in {area:16638}. She teaches {spell:71} and gives you the {item:275290}, a shield to use it with. {npc:6090}'s road below still gives a weapon, once you reach {zone:1453}."] = "回到{area:16638}找{npc:252377}。她教你{spell:71}，并给你{item:275290}，一面配合该技能使用的盾牌。下面{npc:6090}的路线仍会给一件武器，等你到达{zone:1453}后。",
	["Back to {npc:294}"] = "回到{npc:294}处",
	["Back to {npc:6114} for {spell:71}, then to {quest:1680} at the {object:32372} in the middle of {zone:1455}."] = "回到{npc:6114}处学{spell:71}，然后去{zone:1455}中央{object:32372}处的{quest:1680}。",
	["Bartleby"] = "巴特比",
	["Elunite under {area:442}"] = "{area:442}下方的艾露恩矿石",
	["Head north-west from {area:16638} to the {area:16629}. {npc:257196} stands west of the shrine's approach, among the cult's Guardians, Spiritcallers and Blademasters: pull them one at a time before you take him. He drops the {item:263993}."] = "从{area:16638}向西北前往{area:16629}。{npc:257196}站在神殿通道的西侧，混在教派的守卫者、唤灵者和剑师中间：先一个一个拉掉他们，再动他。他掉落{item:263993}。",
	["Take the boat from {area:702} to {area:442}. The wreck lies underwater just south of {area:442}'s southern pier, where the Menethil boat docks. Open Crates of Elunite on the sea floor around the wreck, by a huge sunken turtle, toward the beach and under the pier until you have eight; every crate holds ore and comes back in 3-5 minutes. The grey {npc:6133} (level 11) drifts around the middle of the wreck and always drops the medallion: target it when you see it, so you can find it after surfacing for air. Watch your breath; Threshers can join in."] = "从{area:702}坐船到{area:442}。残骸在水下，就在{area:442}南码头以南、米奈希尔船只停靠的地方。在残骸周围的海底打开艾露恩矿石箱，直到凑够八个：箱子分布在巨大的沉没海龟旁、靠近沙滩处和码头下方；每个箱子都有矿石，3-5分钟刷新。灰色的{npc:6133}（11级）在残骸中部漂游，必掉徽章：看到它就选中，这样浮上水面换气后还能找到它。注意呼吸；鲨鱼可能会加入。",
	["Warrior"] = "战士",
	["Zaal Stormshield"] = "扎尔·风盾",
	["from {npc:6093}"] = "来自{npc:6093}",
	["{item:263993}, from {npc:257196}"] = "{item:263993}，来自{npc:257196}",
	["{item:6782}, from {object:85563}"] = "{item:6782}，来自{object:85563}",
	["{item:6800}, from {object:85562}"] = "{item:6800}，来自{object:85562}",
	["{item:6808}, from Crates of Elunite"] = "{item:6808}，来自艾露恩矿石箱",
	["{item:6809}, from the {npc:6133}"] = "{item:6809}，来自{npc:6133}",
	["{npc:252377} in {area:16638}"] = "{area:16638}的{npc:252377}",
	["{npc:294}'s manor stands at the south-east edge of the {area:88} in eastern Elwynn, at the end of a short road that does not join the main one."] = "{npc:294}的庄园位于艾尔文森林东部{area:88}的东南边缘，在一条不与主路相连的小路尽头。",
	["{npc:6089} and {npc:6090} are in the Pig and Whistle tavern in {object:2100}; {npc:6090} is the drunk at the far end of the bar. {npc:6090} (level 10) hits harder than his level, so start at full health; he gives up at low health instead of dying. If he wins, he disappears for about three minutes: keep the quest and talk to him again when he is back. A Dwarf, Gnome or Night Elf who took {quest:1638} from {npc:5480} instead of their home road is led through {zone:1453} from here."] = "{npc:6089}和{npc:6090}在{object:2100}的猪与哨子酒馆里；{npc:6090}是酒吧最里端的醉汉。{npc:6090}（10级）攻击力超出其等级，所以满血开打；他残血时会认输而不是死亡。如果他赢了，他会消失约三分钟：留着任务，等他回来再谈。矮人、侏儒或暗夜精灵若从{npc:5480}处接了{quest:1638}而非本族路线，会从这里被引导穿过{zone:1453}。",
	["{npc:6093} (level 11) camps in the far south-east of Elwynn. A guard stands beside him and Defias and wolves are spread around the camp (now and then a rarer guard too): clear them one at a time, then kill Jack. He always drops {item:6783}; open {object:85563} in the crates by him for {item:6782}. Jack returns 3 minutes after dying, the box 1 minute after opening."] = "{npc:6093}（11级）在艾尔文森林最东南角扎营。一名卫兵站在他旁边，迪菲亚和狼散布在营地周围（偶尔还有更稀有的卫兵）：一次清一个，然后杀杰克。他必掉{item:6783}；打开他旁边箱子里的{object:85563}可获得{item:6782}。杰克死后3分钟回来，箱子打开后1分钟刷新。",
	["{quest:1678} (level 11, a lone troll) waits at his hut on a hill south of {area:135}, near the mountains at the top of a short ramp, with no other trolls around; the hut at the front of {area:135} is the wrong one. He fights in {spell:71} and sunders your armor; {spell:6343} slows him. His head always drops; he returns about 8 minutes after dying."] = "{quest:1678}（11级，落单的巨魔）在{area:135}以南一座山丘上的小屋中等候，靠近山脉、在一段短斜坡顶端，周围没有其他巨魔；{area:135}前部的小屋不是他。他会切姿态{spell:71}并破你的甲；{spell:6343}能减速他。他的头必掉；死后约8分钟回来。",
	["{quest:1679} in {zone:1455}"] = "{zone:1455}的{quest:1679}",
	["{quest:1679} stands in the {object:32390} in the {object:32359}."] = "{quest:1679}在{object:32359}中的{object:32390}里。",
	["{quest:1681} lies in eastern {zone:1426}, below {area:212} on its south side. Dark Iron Spies (level 8-10) stand along the way, far enough apart to pull one at a time. {object:85562} is in the basement of the southernmost house; {npc:6124} (level 11) stands by it and charges on sight. The box always holds the ore and refills 15 minutes after opening."] = "{quest:1681}在{zone:1426}东部、{area:212}南侧下方。黑铁间谍（8-10级）沿途站着，彼此距离够远，可以一次拉一只。{object:85562}在最南边房屋的地下室里；{npc:6124}（11级）站在旁边，一看到你就冲过来。箱子里必有矿石，打开后15分钟刷新。",
	["{quest:1683} (level 10, a satyr) stands at a hidden moonwell up a hillside west of {area:186}. The trail is hard to spot: it starts behind a Gnarlpine camp and climbs in switchbacks lined with lamp posts. The furbolgs below can come in groups. His horn always drops; he returns 5 minutes after dying."] = "{quest:1683}（10级，萨特）站在{area:186}以西山坡上一处隐蔽的月亮井旁。小路很难发现：它从一处纳尔派营地后方开始，以之字形爬升，两旁立着灯柱。下面的熊怪可能成群出现。他的角必掉；死后5分钟回来。",
	["{quest:1684} in {zone:1457}"] = "{zone:1457}的{quest:1684}",
	["{quest:1684} stands on the {area:1660}."] = "{quest:1684}在{area:1660}上。",
	["{spell:71} and a Weapon (Alliance)"] = "{spell:71}和一把武器（联盟）",
	["{spell:71} at 10 and a one-hand weapon of your choice from {zone:1453}, {zone:1455} or {zone:1457}."] = "10级获得{spell:71}，并从{zone:1453}、{zone:1455}或{zone:1457}获得一把自选的单手武器。",
}

G["forever/collectibles/mounts/alliance/black-war-mounts"] = {
	["Black War Mounts"] = "黑色战斗坐骑",
	["PvP rank 11"] = "PvP军衔11级",
	["{item:18243}, {spell:10907}, 100g"] = "{item:18243}，{spell:10907}，100金",
	["{item:18244}, {spell:826}, 100g"] = "{item:18244}，{spell:826}，100金",
	["{npc:12783} sells the mounts in {zone:1453}'s {object:2100} by the {area:2918}, beside the other honor quartermasters. The Forever client lists each at 100g. Each one also needs its kind's riding: Humans ride the steed, Night Elves the tiger, Gnomes the battlestrider, Dwarves the ram. A Skyborne, or anyone choosing another race's mount, first needs that riding from its trainer (Exalted with the race's city)."] = "{npc:12783}在{zone:1453}的{object:2100}里、{area:2918}旁出售坐骑，就在其他荣誉军需官旁边。Forever客户端标价每种100金。每种还都需要对应种族的骑术：人类骑战马，暗夜精灵骑虎，侏儒骑机械陆行鸟，矮人骑山羊。天裔或任何选择其他种族坐骑的人，须先在该种族训练师处学会对应骑术（需该种族主城崇拜）。",
	["{npc:14332}, {spell:824}, 100g"] = "{npc:14332}，{spell:824}，100金",
	["{spell:1299382} come from battlegrounds, PvP quests and the season's weekly tasks, with a weekly cap; Commander (rank 11) unlocks the Black War mounts. The Player vs. Player tab of your character pane shows your rank and what you may buy. {skill:762} one at full speed needs Journeyman {skill:762} (level 60). Polestar cannot read your rank, so this step waits for level 60 and Journeyman {skill:762}."] = "{spell:1299382}来自战场、PvP任务和赛季每周任务，每周有上限；达到指挥官（军衔11级）可解锁黑色战争坐骑。角色面板的“玩家对玩家”标签页显示你的军衔和可购买物品。全速骑乘需要{skill:762}，而且必须学会中级{skill:762}（60级）。Polestar读不到你的军衔，所以这一步要等到60级且学会中级{skill:762}。",
	["{spell:22723}, {spell:828}, 100g"] = "{spell:22723}，{spell:828}，100金",
}

G["forever/collectibles/mounts/alliance/horse"] = {
	["Any Alliance race can buy these horses, but riding one also takes {spell:824}, which only Humans get with {skill:762}. {npc:4732} teaches it to other races once they are Exalted with {faction:72} (the Stormwind Reputation guide shows the way). Until then, don't buy a horse for this character."] = "任何联盟种族都能买这些马，但骑乘还需要{spell:824}，只有人类能随{skill:762}获得。其他种族达到{faction:72}崇拜后可由{npc:4732}教授（暴风城声望攻略给出了路线）。在此之前，别给这个角色买马。",
	["Horse"] = "马",
	["Learn to ride"] = "学习骑术",
	["Pick a colour"] = "挑选颜色",
	["The {npc:5404} is not at {npc:384}: {npc:1460} sells it, at the stables of {area:150} in the {zone:1437} (20g in the Forever client). Skip this unless you want that colour."] = "{npc:5404}不在{npc:384}处：它由{npc:1460}出售，地点在{zone:1437}的{area:150}马厩（Forever客户端里20金）。除非你想要那个颜色，否则跳过。",
	["{item:2411}, 20g, {npc:1460}"] = "{item:2411}，20金，{npc:1460}",
	["{item:2414}, 20g"] = "{item:2414}，20金",
	["{item:5655}, 20g"] = "{item:5655}，20金",
	["{item:5656}, 20g"] = "{item:5656}，20金",
	["{npc:384} sells the other colours (20g each in the Forever client). Buy any you want, or none if the mount you were given is the one you like."] = "{npc:384}出售其他颜色（Forever 客户端中每只20金）。想要哪只就买哪只；如果喜欢送你的那只，也可以不买。",
	["{npc:4732} and {npc:384}'s horse pen are at {area:88} in eastern {zone:1429}. At 40 {npc:4732} teaches {skill:762} to Humans for 100g (10% less at Honored with {faction:72}), and it comes with a horse. Other races learn {skill:762}, with their own first mount, at their own race's riding trainer."] = "{npc:4732}和{npc:384}的马厩在{zone:1429}东部的{area:88}。40级时{npc:4732}以100金教人类{skill:762}（{faction:72}尊敬时便宜10%），并附赠一匹马。其他种族在本族的骑术训练师处学习{skill:762}，同时获得自己的第一只坐骑。",
	["{npc:4732}, riding trainer"] = "{npc:4732}，骑术训练师",
	["{npc:5404} in {area:150}"] = "{npc:5404}在{area:150}",
	["{spell:824} for other races"] = "其他种族的{spell:824}",
}

G["forever/collectibles/mounts/alliance/mechanostrider"] = {
	["Any Alliance race can buy these mechanostriders, but riding one also takes {spell:10907}, which only Gnomes get with {skill:762}. {npc:7954} teaches it to other races once they are Exalted with {faction:54} (the Gnomeregan Exiles Reputation guide shows the way). Until then, don't buy a mechanostrider for this character."] = "任何联盟种族都能买这些机械陆行鸟，但骑乘还需要{spell:10907}，只有侏儒通过{skill:762}才能获得。其他种族在{faction:54}达到崇拜后，{npc:7954}会教他们（诺莫瑞根流亡者声望指南有详细路线）。在此之前，别给这个角色买机械陆行鸟。",
	["In Classic only Dwarves and Gnomes could ride mechanostriders; in Forever every Alliance race can learn {spell:10907}."] = "经典旧世里只有矮人和侏儒能骑机械陆行鸟；在 Forever 里所有联盟种族都能学会{spell:10907}。",
	["Learn to ride"] = "学习骑术",
	["Mechanostrider"] = "机械陆行鸟",
	["Pick a colour"] = "选择颜色",
	["{area:189} is just east of {area:131}; {npc:7954} stands beside {npc:7955}'s mechanostriders. At 40 {npc:7954} teaches {skill:762} to Gnomes for 100g (10% less at Honored with {faction:54}), and it comes with a mechanostrider. Other races learn {skill:762}, with their own first mount, at their own race's riding trainer."] = "{area:189}就在{area:131}以东；{npc:7954}站在{npc:7955}的机械陆行鸟旁。40级时{npc:7954}以100金教侏儒{skill:762}（在{faction:54}尊敬时便宜10%），还附赠一只机械陆行鸟。其他种族在自己种族的骑术训练师那里学习{skill:762}，并获得自己的第一只坐骑。",
	["{item:13321}, 20g"] = "{item:13321}，20金",
	["{item:13322}, 20g"] = "{item:13322}，20金",
	["{item:8563}, 20g"] = "{item:8563}，20金",
	["{item:8595}, 20g"] = "{item:8595}，20金",
	["{npc:7954}, riding trainer"] = "{npc:7954}，骑术训练师",
	["{npc:7955} sells the other colours (20g each in the Forever client). Buy any you want, or none if the mount you were given is the one you like."] = "{npc:7955}出售其他颜色（Forever客户端中每匹20金）。想要哪个就买哪个；如果喜欢已获得的坐骑，也可以不买。",
	["{spell:10907} for other races"] = "其他种族的{spell:10907}",
}

G["forever/collectibles/mounts/alliance/pack-kodo"] = {
	["6,000 Merchant's Favor"] = "6,000 Merchant's Favor",
	["The camp is at {area:1002} in western {zone:1433}, where the roads from {zone:1429}, {zone:1431} and {area:69} meet. {npc:256736} sells the {npc:10636} only once you are Exalted with the {faction:2586}, and it costs 6,000 Merchant's Favor. Crates pay only Favor (about 15 a crate return); the reputation comes from Craftsman's Writs and the one-time {item:280179}, so follow the Supply Factions Reputation guide and keep 6,000 Favor aside."] = "营地位于{zone:1433}西部的{area:1002}，来自{zone:1429}、{zone:1431}和{area:69}的道路在此交汇。只有当你在{faction:2586}的声望达到崇拜后，{npc:256736}才出售{npc:10636}，价格为6,000点商人的恩惠。交板条箱只给恩惠（每次交还约15点）；声望来自工匠令状和一次性的{item:280179}，所以请参照补给声望指南进行，并预留出6,000点恩惠。",
	["The reins need level 60 and Journeyman Riding to ride (Forever client); you can buy them earlier."] = "缰绳需要60级和中级骑术才能骑乘（Forever 客户端）；可以提前购买。",
	["{faction:2586} camp"] = "{faction:2586}营地",
}

G["forever/collectibles/mounts/alliance/paladin-charger"] = {
	["An {item:12800} comes from Thorium veins and obsidian, about one vein in a hundred; a {item:18335} drops rarely from elites of level 59 and up (Revanchion and {npc:14695} about one kill in nine and one in a hundred). The Auction House is the usual source of both."] = "一个{item:12800}来自瑟银矿脉和黑曜石，大约每一百个矿脉出一个；{item:18335}由59级以上精英稀有掉落（雷万奇恩和{npc:14695}大约九次击杀出一次、每一百次出一次）。两者通常都在拍卖行买。",
	["Arcanite Bars x6: an alchemist, or the Trade District Auction House"] = "奥金锭 x6：找炼金师，或去贸易区拍卖行",
	["At 60 {npc:5149} in the {object:32362} sends you to {quest:7638} in {zone:1453}'s Cathedral of Light."] = "60级时，{object:32362}的{npc:5149}会让你去找{zone:1453}光明大教堂的{quest:7638}。",
	["Back to Lord Grayson"] = "回到格雷森·沙东布瑞克公爵处",
	["Bring the materials and 150 gold, taken at the hand-in. {npc:1416} walks to his forge and hands you the {item:18753}."] = "带上材料，外加150金币，交任务时收取。{npc:1416}会走到他的锻造炉旁，把{item:18753}交给你。",
	["Dire Maul West's door"] = "厄运之槌西区的门",
	["Enriched Manna Biscuits"] = "可口的魔法点心",
	["Enriched Manna Biscuits: {npc:10857}, {area:3197}"] = "可口的魔法点心：{npc:10857}，{area:3197}",
	["Lord Grayson blesses the censer into the {item:18752} for {area:2627}."] = "格雷森领主把香炉祝福成{item:18752}，用于{area:2627}。",
	["Lord Grayson hands you {item:18804}: open it for the {item:18746} and the {item:18792}. Keep both."] = "格雷森领主交给你{item:18804}：打开它，取出{item:18746}和{item:18792}。两样都留着。",
	["Lord Grayson keeps the barding for now: you get it back with the next quest."] = "格雷森领主暂时保留马铠：下一个任务会还给你。",
	["Lord Grayson takes the censer back."] = "格雷森领主收回了香炉。",
	["Paladin"] = "圣骑士",
	["Paladin Charger"] = "圣骑士军马",
	["Stratholme Supply Crates, inside"] = "斯坦索姆补给箱，室内",
	["Tendris Warpwood"] = "坦德里斯·曲木",
	["Terrordale Spirit"] = "恐惧谷幽灵",
	["Terrordale Spirits x25"] = "恐惧谷幽灵×25",
	["The {spell:23214} chain is long: {area:2279}, Dire Maul West and {area:2057} with a group, 350 gold in donations, and materials worth several hundred more (6 Arcanite Bars, 40 {item:14047}, 10 {item:8836}, two diamonds). Start saving early. Lord Grayson stands in the Cathedral of Light, {npc:6171} nearby."] = "{spell:23214}的任务链很长：要组队去{area:2279}、厄运之槌西区和{area:2057}，捐款350金币，材料还值好几百金（6块奥金锭、40个{item:14047}、10个{item:8836}、两颗钻石）。尽早开始攒钱。格雷森领主站在光明大教堂里，{npc:6171}就在旁边。",
	["Two diamonds"] = "两颗钻石",
	["Your epic mount at 60, summoned at will: the faster step up from the Warhorse."] = "60级的史诗坐骑，可随时召唤：比战马更快的升级。",
	["{area:2057} lies under {area:2298}, the island town in the south-east of the {zone:1422}; the door needs the {item:13704} (The Key to {area:2057}). Clear the {object:179746}, Rattlegore's room in the basement, then use the {item:18746} at its centre. Four waves of spirits come, each ending with an Aspect: players judge them with {spell:1105}, Justice, Righteousness and then Light, which stuns them. {npc:14516} (level 62 elite) comes after the last; he mind-controls players. Loot the {item:18749}, use it inside the Ossuary to redeem it, and give it and the {item:18792} to {npc:14568}. If the group wipes, the gates lock and the scryer is gone: abandon the quest and take it again from Lord Grayson for a new satchel. A group of five at 60. Again Into the {object:179746}, after the mount, lets you fight him again."] = "{area:2057}位于{area:2298}下方，那是{zone:1422}东南的岛上城镇；进门需要{item:13704}（通往{area:2057}的钥匙）。清空{object:179746}，也就是地下室的响骨房间，然后在房间中央使用{item:18746}。会来四波幽灵，每波最后都有一个化身：玩家依次用{spell:1105}、正义、公正和光明审判它们，光明会击晕它们。最后一波之后{npc:14516}（62级精英）会出现；他会精神控制玩家。拾取{item:18749}，在藏骨堂里使用以救赎它，然后把它和{item:18792}交给{npc:14568}。如果队伍团灭，大门会锁上，占卜镜也消失了：放弃任务，回去找格雷森领主再接一次，拿个新背包。需要5人队，60级。拿到坐骑后再进一次{object:179746}，可以再和他打一场。",
	["{area:2279} is a dungeon for a group of five at 58-60, at the north end of the {zone:1423}. Stratholme Supply Crates along the streets of both halves hold the Holy Water, one to three each; they come back after three minutes. Some crates let out a swarm of plagued rats or maggots: be ready. The main gate (the Scarlet half) needs no key."] = "{area:2279}是供58-60级五人小队进入的地下城，位于{zone:1423}北端。两半城区街道旁的斯坦索姆补给箱里装着圣水，每个一到三份；三分钟后恢复。有些箱子会放出一群瘟疫鼠或蛆虫：做好准备。正门（血色区那一半）不需要钥匙。",
	["{area:2577} lies in central {zone:1444}. From the gate at the foot of the ruins, walk up through the outer courtyards to the West wing's door at their north end; it needs a {item:18249} (from Pusillin in Dire Maul East) or a rogue's lockpicking. {npc:11489} (level 60 elite) stands at the far end of the West wing's first courtyard. Once attacked he calls every {npc:11459} still alive in the courtyard: kill them first. His death frees the {quest:7643}: talk to it to give it the horse feed and the {item:18753}, and it blesses the barding. A group of five at 60."] = "{area:2577}位于{zone:1444}中部。从废墟脚下的入口进去，穿过外围庭院，走到北端西翼的门；门需要{item:18249}（来自厄运之槌东区的普希林），或者找盗贼开锁。{npc:11489}（60级精英）站在西翼第一个庭院的尽头。一旦被攻击，他会召唤庭院里所有还活着的{npc:11459}：先杀掉它们。他死后会释放{quest:7643}：与它交谈，给它马饲料和{item:18753}，它就会祝福马铠。需要5人队，60级。",
	["{area:2627} lies in the far north-west of the {zone:1423}, west of the {area:2279} gates. Stand inside a green glowing patch on the ground (a {object:179747}; some are inside the ruined houses) and use the {item:18752}: up to three Terrordale Spirits (level 59-60) rise and attack. Their {spell:7713} lowers all your stats by 30%: fight them one at a time and use {spell:2878}. The patches come back quickly; several paladins can work side by side."] = "{area:2627}位于{zone:1423}最西北，{area:2279}大门以西。站在地上绿色发光的斑块里（是一个{object:179747}；有些在废墟房屋内），使用{item:18752}：最多三个恐惧谷幽灵（59-60级）会升起攻击。它们的{spell:7713}会把你所有属性降低30%：一次只打一个，并使用{spell:2878}。斑块恢复很快；几名圣骑士可以并肩作业。",
	["{item:14047} drops from humanoids of level 50 and up ({area:2255}'s Bruisers, the Scarlet Crusade in the Plaguelands, the {area:2577} ogres). {item:8836} is a Plaguelands herb ({skill:182} 220), common around {area:3197}. An {item:12360} is an alchemist's transmute from a {item:12359} and an {item:12363}, once every two days per alchemist: ask a guild alchemist early, or buy the bars. The Auction House sells all three."] = "{item:14047}由50级以上人形生物掉落（{area:2255}的打手、瘟疫之地的血色十字军、{area:2577}的食人魔）。{item:8836}是瘟疫之地的草药（{skill:182} 220），在{area:3197}一带常见。一个{item:12360}是炼金师用{item:12359}和{item:12363}转化来的，每位炼金师每两天一次：早点找公会炼金师，或者直接买锭。这三样拍卖行都有卖。",
	["{item:14047} x40"] = "{item:14047}×40",
	["{item:18749}, inside the {object:179746}"] = "{item:18749}，{object:179746}内",
	["{item:18752}, inside a green patch"] = "{item:18752}，在绿色斑块内",
	["{item:18792}, from the satchel"] = "{item:18792}，来自背包",
	["{item:8836} x10"] = "{item:8836}×10",
	["{npc:11406}, the priest trainer, walks about the {object:32386} in {zone:1455}'s {object:32362}. He gives you his censer for a donation of 150 gold, taken at the hand-in. Keep the censer."] = "{npc:11406}，牧师训练师，在{zone:1455}的{object:32362}中的{object:32386}一带走动。只要你捐150金币（交任务时收取），他就会把香炉给你。把香炉留着。",
	["{npc:11406}: 150 gold"] = "{npc:11406}：150金",
	["{npc:11489}, inside the West wing"] = "{npc:11489}，在西区内",
	["{npc:1416} works in {zone:1453}'s {object:28027}. He forges the {item:18753} from your materials and 150 gold."] = "{npc:1416}在{zone:1453}的{object:28027}里工作。他用你的材料和150金币锻造{item:18753}。",
	["{npc:1416}'s materials"] = "{npc:1416}的材料",
	["{npc:1416}: 150 gold"] = "{npc:1416}：150金",
	["{npc:2357} breeds horses in {area:271}'s stable. She makes the {quest:7645} from the 20 biscuits and 50 gold, taken at the hand-in."] = "{npc:2357}在{area:271}的马厩里养马。她用20块饼干和50金币制作{quest:7645}，交任务时收取。",
	["{npc:6171}, Cathedral of Light"] = "{npc:6171}，光明大教堂",
	["{npc:928}: the {item:18753}"] = "{npc:928}：{item:18753}",
	["{object:2160} quartermasters sell Enriched Manna Biscuits, five for 60 silver, once the {object:92525} is Friendly with you: {npc:10857} at {area:3197} or {npc:11536} at {area:2268}. Scourgestones and the Plaguelands quests raise the standing."] = "{object:2160}军需官出售强化玛纳饼干，五块60银，前提是{object:92525}对你好感达到友善：{area:3197}的{npc:10857}或{area:2268}的{npc:11536}。天灾石和瘟疫之地的任务可以提升声望。",
}

G["forever/collectibles/mounts/alliance/paladin-warhorse"] = {
	["At 40 {npc:6179}, upstairs in the {object:32386}, sends you to {npc:6171} in {zone:1453} ({npc:5149} downstairs gives the same errand; take one). Take the {area:2257} to {zone:1453}."] = "40级时，{object:32386}楼上的{npc:6179}会让你去找{zone:1453}的{npc:6171}（楼下的{npc:5149}给同样的差事；接一个即可）。乘{area:2257}到{zone:1453}。",
	["Paladin"] = "圣骑士",
	["Paladin Warhorse"] = "圣骑士战马",
	["Your first mount at 40, summoned at will: a paladin buys no horse."] = "40级获得的第一匹坐骑，可随时召唤：圣骑士无需购买马匹。",
	["{npc:6171} stands in the Cathedral of Light. At 40 he offers {quest:1661}: accept it and hand it straight back to learn {spell:13819}. Paladins do not buy a horse."] = "{npc:6171}站在光明大教堂。40级时他会提供{quest:1661}：接受后直接交还，就能学会{spell:13819}。圣骑士不用买马。",
}

G["forever/collectibles/mounts/alliance/ram"] = {
	["Any Alliance race can buy these rams, but riding one also takes {spell:826}, which only Dwarves get with {skill:762}. {npc:4772} teaches it to other races once they are Exalted with {faction:47} (the Ironforge Reputation guide shows the way). Until then, don't buy a ram for this character."] = "任何联盟种族都能购买这些山羊，但骑乘还需要{spell:826}，只有矮人通过{skill:762}获得。{npc:4772}会在其他种族与{faction:47}达到崇拜后教授它（铁炉堡声望攻略有详细指引）。在此之前，不要为这个角色购买山羊。",
	["Learn to ride"] = "学习骑术",
	["Pick a colour"] = "选择颜色",
	["Ram"] = "山羊",
	["{area:803} is east of {area:131} on the road to {zone:1432}; {npc:4772} stands beside {npc:1261}'s rams. At 40 {npc:4772} teaches {skill:762} to Dwarves for 100g (10% less at Honored with {faction:47}), and it comes with a ram. Other races learn {skill:762}, with their own first mount, at their own race's riding trainer."] = "{area:803}位于{area:131}东边、通往{zone:1432}的路上；{npc:4772}站在{npc:1261}的山羊旁。40级时，{npc:4772}以100金向矮人教授{skill:762}（与{faction:47}达到尊敬时便宜10%），并附带一只山羊。其他种族可在本族的骑术训练师处学习{skill:762}，并获得自己的第一只坐骑。",
	["{item:5864}, 20g"] = "{item:5864}，20金",
	["{item:5872}, 20g"] = "{item:5872}，20金",
	["{item:5873}, 20g"] = "{item:5873}，20金",
	["{npc:1261} sells the other colours (20g each in the Forever client). Buy any you want, or none if the mount you were given is the one you like."] = "{npc:1261}出售其他颜色（Forever客户端中每匹20金）。想要哪个就买哪个；如果喜欢已获得的坐骑，也可以不买。",
	["{npc:4772}, riding trainer"] = "{npc:4772}，骑术训练师",
	["{spell:826} for other races"] = "其他种族需要{spell:826}",
}

G["forever/collectibles/mounts/alliance/saber"] = {
	["Any Alliance race can buy these sabers, but riding one also takes {spell:828}, which only Night Elves get with {skill:762}. {npc:4753} teaches it to other races once they are Exalted with {faction:69} (the Darnassus Reputation guide shows the way). Until then, don't buy a saber for this character."] = "任何联盟种族都能买这些夜刃豹，但骑乘还需{spell:828}，只有暗夜精灵随{skill:762}获得。其他种族在{faction:69}达到崇拜后，{npc:4753}会教它（达纳苏斯声望指南有路线）。在此之前，别为这个角色买夜刃豹。",
	["Learn to ride"] = "学习骑术",
	["Pick a colour"] = "选择颜色",
	["Saber"] = "豹",
	["new in Forever, 20g; beta players found it here"] = "Forever新增，20金；测试服玩家在这里发现",
	["{item:8629}, 20g"] = "{item:8629}，20金",
	["{item:8631}, 20g"] = "{item:8631}，20金",
	["{item:8632}, 20g"] = "{item:8632}，20金",
	["{npc:4730} sells the other colours (20g each in the Forever client). Buy any you want, or none if the mount you were given is the one you like."] = "{npc:4730}出售其他颜色（Forever 客户端中每个20金）。想要就买，如果喜欢获赠的那匹也可以不买。",
	["{npc:4753} and {npc:4730}'s sabers are in the {area:1658}'s riding grounds in {faction:69}. At 40 {npc:4753} teaches {skill:762} to Night Elves for 100g (10% less at Honored with {faction:69}), and it comes with a saber. Other races learn {skill:762}, with their own first mount, at their own race's riding trainer."] = "{npc:4753}和{npc:4730}的夜刃豹在{faction:69}的{area:1658}骑术训练场。40级时{npc:4753}以100金教暗夜精灵{skill:762}（{faction:69}尊敬时便宜10%），并附赠一只夜刃豹。其他种族在本族的骑术训练师处学习{skill:762}，同时获得自己的第一只坐骑。",
	["{npc:4753}, riding trainer"] = "{npc:4753}，骑术训练师",
	["{spell:828} for other races"] = "其他种族的{spell:828}",
}

G["forever/collectibles/mounts/alliance/stormpike-battle-charger"] = {
	["The Forever client lists it at 200g and level 60. It runs at full speed, so riding it needs Journeyman {skill:762}; any Alliance race can ride it."] = "Forever客户端标价200金、60级。它以全速奔跑，因此骑乘需要中级{skill:762}；任何联盟种族都可骑乘。",
	["{area:2839} (level 51+) raises {faction:730}: win, capture towers and graveyards, and hand in the battleground's turn-ins; the Alterac Valley Reputation guide shows the fastest way. {npc:13217} waits outside the battleground on the {zone:1416} border above {area:287}; {npc:13216} inside {area:2839} sells the same mount."] = "{area:2839}（51级以上）提升{faction:730}：获胜、占领塔和墓地、交战场任务物品；奥特兰克山谷声望指南有最快路线。{npc:13217}在战场外{zone:1416}边界、{area:287}上方等候；{area:2839}内的{npc:13216}出售同样的坐骑。",
	["{npc:13217}, 200g"] = "{npc:13217}，200金",
}

G["forever/collectibles/mounts/alliance/swift-horse"] = {
	["Any Alliance race can buy these horses, but riding one also takes {spell:824}, which only Humans get with {skill:762}. {npc:4732} teaches it to other races once they are Exalted with {faction:72} (the Stormwind Reputation guide shows the way). Until then, don't buy a horse for this character."] = "任何联盟种族都能买这些马，但骑乘还需要{spell:824}，只有人类能随{skill:762}获得。其他种族达到{faction:72}崇拜后可由{npc:4732}教授（暴风城声望攻略给出了路线）。在此之前，别给这个角色买马。",
	["Journeyman {skill:762}"] = "中级{skill:762}",
	["Pick a colour"] = "挑选颜色",
	["Swift Horse"] = "迅捷战马",
	["{item:18776}, 200g"] = "{item:18776}，200金",
	["{item:18777}, 200g"] = "{item:18777}，200金",
	["{item:18778}, 200g"] = "{item:18778}，200金",
	["{npc:384} sells the other colours (200g each in the Forever client). Buy any you want, or none if the mount you were given is the one you like."] = "{npc:384}出售其他颜色（Forever 客户端中每只200金）。想要哪只就买哪只；如果喜欢送你的那只，也可以不买。",
	["{npc:4732} and {npc:384}'s horse pen are at {area:88} in eastern {zone:1429}. At 60 {npc:4732} teaches Journeyman {skill:762} to Humans for 1,000g (10% less at Honored with {faction:72}); Blizzard says it comes with a mount. Other races train it at their own race's riding trainer. Each swift horse costs 200g here."] = "{npc:4732}和{npc:384}的马厩在{zone:1429}东部的{area:88}。60级时{npc:4732}以1000金向人类教授中级{skill:762}（{faction:72}尊敬时减10%）；暴雪称会附带一匹马。其他种族在本族的骑术训练师处学习。这里的迅捷马每匹200金。",
	["{npc:4732}, riding trainer"] = "{npc:4732}，骑术训练师",
	["{spell:824} for other races"] = "其他种族的{spell:824}",
}

G["forever/collectibles/mounts/alliance/swift-mechanostrider"] = {
