G["forever/collectibles/mounts/alliance/winterspring-frostsaber"] = {
	["The Forever client lists it at 200g and level 60. It runs at full speed yet needs no riding training at all, only Honored with the {faction:589}, so you can skip the 1,000g Journeyman Riding if this is your fast mount."] = "Forever客户端把它标为200金、60级。它以全速奔跑，却完全不需要骑术训练，只要对{faction:589}达到尊敬，所以如果这就是你的快速坐骑，你可以省下1000金的初级骑术。",
	["{npc:10618} stands on top of {area:2241} in the far north of {zone:1452}. Only the Alliance can earn the {faction:589}' favour, from level 58: three repeatable quests worth 50 each, about 840 turn-ins from Neutral to Exalted. Frostsaber Provisions is open from the start, Winterfall Intrusion from halfway through Neutral and Rampaging Giants from Honored. The Wintersaber Trainers Reputation guide takes you through it."] = "{npc:10618}站在{zone:1452}最北端的{area:2241}顶上。只有联盟能获得{faction:589}的好感，从58级开始：三个可重复任务，每个50点声望，从中立到崇拜大约要交840次。霜刃豹补给从一开始就能做，冬泉入侵从中立过半开始，狂暴巨人从尊敬开始。冬刃豹训练师声望攻略会带你走完。",
	["{npc:10618}, 200g"] = "{npc:10618}，200金",
}

G["forever/collectibles/pets/chicken-egg"] = {
	["Buy one {item:11109} (25 copper) from {npc:233} at his farm first: it is not a quest item, and the chicken stays friendly only for a short while."] = "先在他农场从{npc:233}处买一个{item:11109}（25铜）：它不是任务物品，而小鸡保持友善的时间很短。",
	["Loot the {object:161513} the chicken lays"] = "拾取小鸡下的{object:161513}",
	["Target one of the chickens around Saldean's farm and type /chicken at it, again and again, until it offers {quest:3861}; this can take several minutes. Then /cheer at a chicken until it turns friendly (green) and hand in the feed; right-clicking a chicken before it is friendly attacks it. The chicken lays an egg on the ground: loot it for your {item:11110}."] = "选中萨尔丁农场周围的一只小鸡，反复对它输入 /chicken，直到它提供{quest:3861}；这可能需要好几分钟。然后对一只小鸡输入 /cheer，直到它变为友善（绿色），再交付饲料；在小鸡变得友善之前右键点击它会攻击它。小鸡会在地上下一个蛋：拾取它即可获得你的{item:11110}。",
}

G["forever/collectibles/pets/donni-anthania"] = {
	["{item:8485}, 40s"] = "{item:8485}，40银",
	["{item:8486}, 40s"] = "{item:8486}，40银",
	["{item:8487}, 40s"] = "{item:8487}，40银",
	["{item:8488}, 40s"] = "{item:8488}，40银",
	["{npc:6367} has a farmhouse north of {area:87}. Each cat carrier costs 40s, 1g 60s for all four. Each pet item teaches its companion when you use it; the goals stay ticked afterwards."] = "{npc:6367}在{area:87}以北有一间农舍。每个猫咪笼40银，四个全买1金60银。每个宠物物品在使用时会教会对应的伙伴；之后目标仍保持勾选。",
	["{npc:6367}'s Cats"] = "{npc:6367}的猫",
}

G["forever/collectibles/pets/shylenai"] = {
	["50s"] = "50银",
	["{item:8500}, 50s"] = "{item:8500}，50银",
	["{item:8501}, 50s"] = "{item:8501}，50银",
	["{npc:8665}'s Owls"] = "{npc:8665}的猫头鹰",
	["{npc:8665}, the owl trainer, stands on the {area:1659} in {zone:1457}, beside the food and general goods vendors. She sells three owls (50s each); the {item:280803} is new in Forever. Each pet item teaches its companion when you use it; the goals stay ticked afterwards."] = "{npc:8665}，猫头鹰训练师，站在{zone:1457}的{area:1659}，在食品和杂货商旁。她出售三种猫头鹰（每只50银）；{item:280803}是 Forever 新增的。每个宠物物品使用后都会教会对应的小伙伴；目标完成后仍保持勾选。",
}

G["forever/collectibles/pets/yarlyn-amberstill"] = {
	["20s"] = "20银",
	["{item:8497}, 20s"] = "{item:8497}，20银",
	["{npc:1263} stands at {area:803}, east of {area:131} on the road to {zone:1432}, beside {npc:1261}, the ram breeder. Each rabbit crate costs 20s; the Arctic and Brown crates are new in Forever. Each pet item teaches its companion when you use it; the goals stay ticked afterwards."] = "{npc:1263}站在{area:803}，位于{area:131}以东、通往{zone:1432}的路上，旁边是公羊饲养员{npc:1261}。每个兔子笼售价20银；北极兔和棕兔笼是Forever新增的。每个宠物物品使用时都会教给对应的伙伴；之后目标仍保持勾选。",
	["{npc:1263}'s Rabbits"] = "{npc:1263}的兔子",
}

G["forever/reputation/darnassus"] = {
	["About 3,700 {faction:69} reputation from low-level quests in {zone:1438} and {zone:1439} (in Classic, a fifth of it at 60)"] = "{zone:1438}和{zone:1439}的低等级任务约给3,700点{faction:69}声望（经典版中60级时只有五分之一）",
	["Black Broodling"] = "黑色雏龙",
	["Black Dragonspawn"] = "黑色龙人",
	["Black Drake"] = "黑色幼龙",
	["Black Wyrmkin"] = "黑色龙兽",
	["Blackwood Pathfinder"] = "黑木探路者",
	["Blackwood Windtalker"] = "黑木语风者",
	["Cloth, {item:11040} and the {zone:1438} and {zone:1439} hubs: the quests pay most while you level."] = "布料、{item:11040}以及{zone:1438}和{zone:1439}的任务据点：升级期间做任务给的声望最多。",
	["Darnassus Reputation"] = "达纳苏斯声望",
	["Den Mother"] = "母熊",
	["Dig {quest:3764} from the dirt mounds all over the crater; most of the crater's beasts and the Gorishi silithids drop it too, about one kill in three. Take far more than 20: every pouch use takes 2, about 18 for each 10 {item:11040}."] = "在环形山各处的土堆里挖{quest:3764}；环形山的大多数野兽和戈里什异种虫也会掉落，约三次击杀掉一个。多挖远超20个：每次使用袋子消耗2个，每10个{item:11040}约需18个。",
	["Every 10 {item:11040}: 50 reputation at {npc:4217}. Keep the pouch and buy seeds as you go. It is slow: about 9 casings, 90 minutes of pouch waits, 18 {quest:3764} and 9 seed packets for each hand-in, a little over 30 reputation an hour, so run it beside the {item:14047}. {npc:7879} at {area:1116} in {zone:1444} takes {item:11040} at the same rate, 25 for 5, after his own quest."] = "每10个{item:11040}：在{npc:4217}处换50点声望。留着袋子，边做边买种子。这很慢：每次交任务约需9个荚壳、90分钟的袋子等待、18个{quest:3764}和9包种子，每小时略多于30点声望，所以把它和{item:14047}一起做。{zone:1444}中{area:1116}的{npc:7879}在他自己的任务之后也按同样比例收{item:11040}，5个换25点。",
	["Exalted with {faction:69}: in Classic, other races may buy the nightsabers"] = "{faction:69}崇拜：在经典版中，其他种族可购买夜刃豹",
	["Gnarlpine Ambusher"] = "瘤背伏击者",
	["Gnarlpine Mystic"] = "瘤背秘法师",
	["Honored: in Classic Darnassus's vendors take 10% off for you, Lelanai's nightsabers (20g, the swift ones 200g) included; Forever has not settled it, and guide sites report 5% at Friendly rising to 20% at Exalted. Honored to Revered is 12,000 reputation: 240 turn-ins, 4,800 {item:14047}."] = "尊敬：经典版中达纳苏斯的商人会给你打九折，包括莱拉奈的夜刃豹（20金，迅捷款200金）；Forever尚未确定，攻略网站称友善时为5%，到崇拜升到20%。尊敬到崇敬需要12,000点声望：240次交任务，4,800个{item:14047}。",
	["Mangy Nightsaber"] = "癞皮夜刃豹",
	["Optional: the Night Elf start glade in north-east {zone:1438}, about 1,050 reputation (210 at a fifth) in 30 minutes at 60. The givers stand around {area:256}, the great tree. In Classic, quests 6+ levels below you pay less (a fifth at 60); a Forever beta report says they paid in full. Your first turn-in shows which: if it pays a fifth, skip these hubs. Skip this step to skip the hub."] = "可选：{zone:1438}东北的暗夜精灵起始林间空地，60级时30分钟约1,050点声望（按五分之一算是210点）。发布任务的NPC站在大树{area:256}周围。经典版中，比你低6级以上的任务收益会减少（60级时为五分之一）；一份Forever测试服报告称它们仍按全额给。第一次交任务就能看出是哪种：如果只给五分之一，就跳过这些枢纽。跳过这一步就等于跳过该枢纽。",
	["Optional: the village on the road to {faction:69}, about 1,250 reputation (250 at a fifth) in 45 minutes at 60. In Classic, quests 6+ levels below you pay less (a fifth at 60); a Forever beta report says they paid in full. Your first turn-in shows which: if it pays a fifth, skip these hubs. Skip this step to skip the hub."] = "可选：通往{faction:69}的路上的村庄，60级时45分钟约1,250点声望（按五分之一算是250点）。经典版中，比你低6级以上的任务收益会减少（60级时为五分之一）；一份Forever测试服报告称它们仍按全额给。第一次交任务就能看出是哪种：如果只给五分之一，就跳过这些枢纽。跳过这一步就等于跳过该枢纽。",
	["Optional: {area:442} in {zone:1439}, a boat trip from {area:702}, about 1,400 reputation (280 at a fifth) in an hour at 60. The givers stand along the town's street and pier. In Classic, quests 6+ levels below you pay less (a fifth at 60); a Forever beta report says they paid in full. Your first turn-in shows which: if it pays a fifth, skip these hubs. Skip this step to skip the hub."] = "可选：{zone:1439}的{area:442}，从{area:702}坐船可达，60级时一小时约1,400点声望（按五分之一算是280点）。发布任务的NPC站在镇上的街道和码头沿线。经典版中，比你低6级以上的任务收益会减少（60级时为五分之一）；一份Forever测试服报告称它们仍按全额给。第一次交任务就能看出是哪种：如果只给五分之一，就跳过这些枢纽。跳过这一步就等于跳过该枢纽。",
	["Rabid Thistle Bear"] = "狂暴蓟熊",
	["Reputation · Cities"] = "声望·主城",
	["Revered to Exalted is 21,000 reputation: 420 turn-ins, 8,400 {item:14047}. At Exalted, Lelanai at the {area:1658} in {faction:69} sells her nightsabers to other races in Classic; the Saber and Swift Saber guides cover them."] = "崇敬到崇拜需要21,000点声望：420次交任务，8,400个{item:14047}。崇拜后，经典版中{faction:69}的{area:1658}处的莱拉奈会向其他种族出售她的夜刃豹；夜刃豹和迅捷夜刃豹指南有介绍。",
	["The Blackwood furbolgs camp south of town; the grells of {quest:955}, east of town, drop the earrings; the sea turtle remains lie on the beach west of town."] = "黑木熊怪在镇南扎营；镇东{quest:955}的格雷尔掉落耳环；海龟残骸躺在镇西的海滩上。",
	["The four relics of Wakening lie in the {area:262}, south-west of {area:186}; Ferocitas and the Gnarlpine Mystics camp east of the village."] = "四件觉醒遗物位于{area:186}西南的{area:262}；费罗西塔斯和瘤背秘法师在村东扎营。",
	["The furbolg camp south of town counts for How Big a Threat; the Rabid Thistle Bears roam the woods south of town; the Highborne ghosts of the Ruins of Ameth'Aran, south-east of town, carry the relics, and Anaya's ghost walks there too; the bones lie on the beach south of town; the mushrooms grow in the {area:445} cave to the north-east."] = "镇南的熊怪营地算作“威胁有多大”；狂暴蓟熊在镇南的树林游荡；镇东南阿米斯阿兰废墟的上层精灵幽灵带着遗物，阿纳雅的鬼魂也在那里游走；骸骨躺在镇南的海滩上；蘑菇生长在东北{area:445}的洞穴里。",
	["The nightsabers and boars roam the glade; the grells around {area:256} drop the {item:3297}; the totems stand in the furbolg camp north-west of the tree; the Webwood spiders live in the cave north of the glade. {npc:8584} waits outside that cave."] = "夜刃豹和野猪在林间空地游荡；{area:256}周围的格雷尔掉落{item:3297}；图腾立在树西北的熊怪营地；蛛网林地蜘蛛住在空地以北的洞穴里。{npc:8584}在那个洞外等着。",
	["The timberlings by the lake drop seeds and sprouts; the Gnarlpine Ambushers lurk on the road west to {faction:69}; {npc:2038} waits deep in {area:258}, north-west of the village; the dreamcatcher lies in the furbolg camp east of the village, by {npc:2107}; the Nightsabers west of the village carry the pelts."] = "湖边的林精掉落种子和幼苗；瘤背伏击者潜伏在向西通往{faction:69}的路上；{npc:2038}在村西北{area:258}深处等着；捕梦器在村东的熊怪营地里、{npc:2107}旁边；村西的夜刃豹身上带着毛皮。",
	["The {item:5338} drops from the satyrs of {quest:956}; destroy the seal at the flame there. The {npc:6788} lairs north-east of {quest:956}; the Moonstalker Sires and Matriarchs roam the south of {zone:1439}."] = "{item:5338}由{quest:956}的萨特掉落；在那里火焰旁摧毁封印。{npc:6788}巢居在{quest:956}东北；月行者公豹和母豹在{zone:1439}南部游荡。",
	["The {quest:917} lies at the back of the spider cave; the mushrooms grow by the trees, the lilies by the pools, and the {item:10640} drops from the Webwood Lurkers."] = "{quest:917}在蜘蛛洞穴深处；蘑菇长在树旁，百合长在水塘边，{item:10640}由蛛网林地潜伏者掉落。",
	["Thistle Boar"] = "蓟野猪",
	["Ursal the Mauler"] = "重击者乌尔萨",
	["Young Nightsaber"] = "年幼的夜刃豹",
	["Young Thistle Boar"] = "年幼的蓟野猪",
	["the blue aura in the ruins of {quest:954}"] = "{quest:954}废墟中的蓝色光环",
	["the seal at the ancient flame"] = "古老火焰处的封印",
	["{area:186}: first hand-in"] = "{area:186}：第一次交任务",
	["{area:186}: the relics and Ferocitas"] = "{area:186}：遗物与费罗西塔斯",
	["{area:186}: the woods around the village"] = "{area:186}：村庄周围的树林",
	["{area:186}: {npc:2080} and the lake"] = "{area:186}：{npc:2080}与湖泊",
	["{area:188}: first hand-in"] = "{area:188}：第一次交任务",
	["{area:188}: last hand-in"] = "{area:188}：最后一次交任务",
	["{area:188}: the egg and the antidote"] = "{area:188}：蛋与解药",
	["{area:188}: the glade and the spider den"] = "{area:188}：林间空地与被蜘蛛巢",
	["{area:442}: first hand-in"] = "{area:442}：第一次交任务",
	["{area:442}: second hand-in"] = "{area:442}：第二次交任务",
	["{area:442}: the coast and the woods"] = "{area:442}：海岸与树林",
	["{area:442}: the furbolgs, the bears and the grells"] = "{area:442}：熊怪、熊与格雷尔",
	["{area:442}: the seal, the {npc:6788} and the pelts"] = "{area:442}：封印、{npc:6788}与毛皮",
	["{item:11040} (optional)"] = "{item:11040}（可选）",
	["{item:11040}: grow it here and open the casings"] = "{item:11040}：在这里种植并打开荚壳",
	["{item:14047} drops from humanoids level 50 and up: the Deadwood furbolgs of {zone:1448}, the Winterfall furbolgs of {zone:1452}, the Scourge cultists of the Plaguelands. Keep any {item:14047} past the first 60 for {quest:7801}."] = "{item:14047}由50级及以上人形怪掉落：{zone:1448}的枯木熊怪、{zone:1452}的冬泉熊怪、瘟疫之地的天灾教徒。头60个之后的{item:14047}都留给{quest:7801}。",
	["{item:2592}: furbolgs, satyrs and naga in {zone:1439} and {zone:1440}"] = "{item:2592}：{zone:1439}和{zone:1440}的熊怪、萨特和纳迦",
	["{item:4306} drops from humanoids level 23 to 40: the satyrs and furbolgs of {zone:1440}, the Thistlefur and Foulweald camps, the Grimtotem of Stonetalon."] = "{item:4306}由23到40级人形怪掉落：{zone:1440}的萨特和熊怪、蓟皮和邪林营地、石爪山的恐怖图腾。",
	["{item:4338} drops from humanoids level 35 to 50: the Hatecrest naga and Gordunni ogres of {zone:1444}, the Dunemaul ogres of {zone:1446}."] = "{item:4338}由35到50级人形怪掉落：{zone:1444}的憎恨之冠纳迦和戈杜尼食人魔、{zone:1446}的砂槌食人魔。",
	["{item:8050}, from {quest:2459}"] = "{item:8050}，来自{quest:2459}",
	["{npc:14725} takes cloth for {faction:69}; he stands in the {area:1659}, in the north-east of {faction:69}, by the tailors. Each first donation of 60 Wool, Silk, Mageweave and {item:14047} pays 150 reputation once; after the {item:14047} one, {quest:7801} pays 50 for every 20 {item:14047}, as often as you like. The Auction House in the {area:1662} is the quickest source of cloth. In Classic, quests pay full reputation while they are at most 5 levels below you, so do {zone:1438} (levels 1-12), {zone:1439} (11-20) and {zone:1440} (18-30) while you level through them. After the donations come {quest:4183} in the {zone:1428} and {item:11040}, a second repeatable turn-in; then the optional hubs, best rate first: {area:188} (about 35 a minute at full value), {area:186} (28), {area:442} (23). Every {faction:69} gain also gives a quarter as much to {zone:1453}, {zone:1455} and the Gnomeregan Exiles, except quests in the level 1-10 start areas. Legacy Diplomat adds up to 10% to every gain."] = "{npc:14725}为{faction:69}收布料；他站在{faction:69}东北的{area:1659}，裁缝铺旁。首次各捐60个毛料、丝绸、魔纹布和{item:14047}，各给一次150点声望；捐过{item:14047}之后，{quest:7801}每20个{item:14047}给50点，想做多少次都行。{area:1662}的拍卖行是获取布料最快的来源。经典版中，任务最多比你低5级时仍给全额声望，所以趁升级时做{zone:1438}（1-12级）、{zone:1439}（11-20级）和{zone:1440}（18-30级）。捐完之后，还有{zone:1428}的{quest:4183}和{item:11040}这第二种可重复交任务；接着是可选的枢纽，按时效从高到低：{area:188}（全额时约每分钟35点）、{area:186}（28）、{area:442}（23）。除1-10级起始区域的任务外，每获得一点{faction:69}声望，也会给{zone:1453}、{zone:1455}和诺莫瑞根流亡者四分之一。Legacy Diplomat最多为每笔声望加成10%。",
	["{npc:14725}, the cloth quartermaster"] = "{npc:14725}，布料军需官",
	["{npc:2080} tends his garden on the south-east shore of {area:259}; {npc:2107} stands upstairs in a house in {area:260}, east of {area:186}: go up inside, the arrow cannot tell the floors apart."] = "{npc:2080}在{area:259}东南岸照料他的园子；{npc:2107}站在{area:186}以东{area:260}一座房子的楼上：从里面上去，箭头分不清楼层。",
	["{npc:344} waits in the town hall of {area:69}; his next quest takes you to {object:2117} (the {zone:1453} guide follows it). Other {faction:69} quests at this level, for when you pass by: {npc:7916} in {area:702} has a wildkin chain into {zone:1452} (325 in all, with Ranshalla's escort), Arei's escort in {zone:1448} pays 150 after the {area:2479}'s chain, {npc:10739} at the {area:202} in the {zone:1422} 100 for the {item:12663}, and Put Her Down in Upper Blackrock Spire 100 with a group."] = "{npc:344}在{area:69}的镇公所等着；他的下一个任务会把你引向{object:2117}（随后接{zone:1453}指南）。这个等级其他{faction:69}任务，路过时可以顺带做：{area:702}的{npc:7916}有一条通往{zone:1452}的野性生物任务链（含兰莎拉的护送共325点）；{zone:1448}的阿雷伊护送在{area:2479}任务链之后给150点；{zone:1422}的{area:202}处{npc:10739}为{item:12663}给100点；还有上层黑石塔的“放倒她”，组队给100点。",
	["{npc:4217}: {quest:3803}, +50"] = "{npc:4217}：{quest:3803}，+50",
	["{npc:8584}, outside the spider cave"] = "{npc:8584}，蜘蛛洞穴外",
	["{npc:9047}, beside Fandral in the {area:1658}, takes the soil. {npc:4217} sells the {item:11020} and Packets of Tharlendris Seeds. With a seed packet and 2 {quest:3764} in your bags, use the pouch to grow an {item:11024} and open it: about one casing in three holds {item:11040} (1 to 5), the rest other herbs. The pouch works once every 10 minutes, so use it whenever it is ready while you do other things."] = "{npc:9047}在{area:1658}范达尔身旁收泥土。{npc:4217}出售{item:11020}和塔伦德里斯种子包。背包里有种子包和2个{quest:3764}时，用袋子种出一个{item:11024}并打开它：约三分之一的荚壳含{item:11040}（1到5个），其余是别的草药。袋子每10分钟只能用一次，所以做别的事时一好就用。",
	["{npc:9562} at {area:2418}, in the south-east of the {zone:1428}, starts {quest:4183}: 175 {faction:69} reputation for two quests (level 54: in Classic 140 at 60), and the chain goes on to {object:2117} for 175 {zone:1453}. The Black Broodlings and the {npc:7044} live on the slopes north of the Vigil; the {npc:7040} and {npc:7041} west of it, in the middle of the zone."] = "{zone:1428}东南{area:2418}的{npc:9562}开启{quest:4183}：两个任务共175点{faction:69}声望（54级：经典版60级时140点），任务链继续到{object:2117}，给175点{zone:1453}声望。黑色雏龙和{npc:7044}住在守望岗哨以北的山坡；{npc:7040}和{npc:7041}在其以西、区域中部。",
	["{quest:3763}, +10"] = "{quest:3763}，+10",
	["{quest:3764}, +100"] = "{quest:3764}，+100",
	["{quest:3781}, +10"] = "{quest:3781}，+10",
	["{quest:3781}, +100"] = "{quest:3781}，+100",
	["{quest:3803} takes 10 {item:11040} for 50, as often as you like, and pays in full at 60. The chain before it is level 50 (in Classic a fifth at 60): 220 at full. {npc:6735} sends you to {npc:3516} in the {area:1658}; he wants 20 {quest:3764}. (The innkeepers of {zone:1453} and {zone:1455} give the same start.)"] = "{quest:3803}每10个{item:11040}换50点，想做多少次都行，60级时仍给全额。它之前的任务链是50级（经典版60级时给五分之一）：全额220点。{npc:6735}派你去{area:1658}的{npc:3516}；他要20个{quest:3764}。（{zone:1453}和{zone:1455}的旅店老板也提供同样的起点。）",
	["{quest:3803}: 50 reputation for every 10 {item:11040}, as often as you like"] = "{quest:3803}：每10个{item:11040}给50点声望，可无限重复",
	["{quest:4182}, +100"] = "{quest:4182}，+100",
	["{quest:4183}, +75"] = "{quest:4183}，+75",
	["{quest:486}, a big bear, roams the {area:478} in south-west {zone:1438}."] = "{quest:486}，一只大熊，在{zone:1438}西南的{area:478}游荡。",
	["{quest:7801} to Exalted"] = "{quest:7801}刷到崇拜",
	["{quest:7801} to Honored"] = "{quest:7801}刷到尊敬",
	["{quest:7801} to Revered"] = "{quest:7801}刷到崇敬",
	["{quest:7801}: 50 reputation for 20 {item:14047}, as often as you like. After the four first donations a Human, Dwarf or Gnome stands at Friendly 700 of 6,000, so Honored is 5,300 away: 106 turn-ins, 2,120 {item:14047} (Night Elves start 900 higher: 88 turn-ins; Skyborne start at Neutral 500, so 7,900 away: 158, two fewer after Exploring the Alliance). {quest:4183} and the {item:11040} chain above take 8 turn-ins off, and every 10 {item:11040} you hand in counts as one more; each hub you did takes 20 to 28 more off if it paid in full. More quests pay {faction:69}, in full while they are no more than 5 levels below you: the rest of {zone:1439} (about 3,400 more), {area:415} in {zone:1440} (about 3,900) and Feathermoon in {zone:1444} (about 1,700). Every city gain also gives a quarter as much to the other three Alliance cities (not counted here). Hand in all your {item:14047} at once."] = "{quest:7801}：每20个{item:14047}换50点声望，想做多少次都行。完成最初四次捐献后，人类、矮人或侏儒处于友善6,000中的700，离尊敬还差5,300点：106次交任务，2,120个{item:14047}（暗夜精灵起始高900点：88次；天裔从中立500起步，所以差7,900点：158次，完成“探索联盟”后少两次）。上面的{quest:4183}和{item:11040}任务链能抵掉8次交任务，每交10个{item:11040}又算多一次；你每做满一个枢纽（若给全额）能再抵20到28次。还有更多任务给{faction:69}声望，任务最多比你低5级时给全额：{zone:1439}其余部分（约3,400点）、{zone:1440}的{area:415}（约3,900点）以及{zone:1444}的羽月（约1,700点）。每获一点主城声望，也会给其他三个联盟主城四分之一（此处不计）。把所有{item:14047}一次性交完。",
}

G["forever/reputation/gnomeregan-exiles"] = {
	["400 {area:133} reputation from {npc:9616}'s ooze jars and {quest:4262} (level 52-54)"] = "{npc:9616}的软泥瓶和{quest:4262}（52-54级）带来的400点{area:133}声望",
	["About 3,000 {area:133} reputation from low-level quests in {zone:1426}, paid to {zone:1455} too (in Classic, a fifth of it at 60)"] = "约3,000点{area:133}声望来自{zone:1426}的低级任务，同时也会给{zone:1455}（经典旧世里60级时只有五分之一）",
	["Burly Rockjaw Trogg"] = "强壮的石颚穴居人",
	["Cloth, {npc:9616}'s ooze quests and the {zone:1426} hubs, which pay {zone:1455} too: best done while leveling."] = "布料、{npc:9616}的软泥怪任务以及{zone:1426}的任务点，同时也会提升{zone:1455}声望：最好在升级时完成。",
	["Coldridge: on to {area:131}"] = "寒脊山谷：前往{area:131}",
	["Coldridge: the hot Mornbrew"] = "寒脊山谷：滚烫的晨酿",
	["Coldridge: wolves, troggs and {npc:8416}'s things"] = "寒脊山谷：狼、穴居人和{npc:8416}的东西",
	["Coldridge: {area:77} and {npc:714}"] = "寒脊山谷：{area:77}和{npc:714}",
	["Coldridge: {npc:786} and the troll cave"] = "寒脊山谷：{npc:786}和巨魔洞",
	["Dark Iron Spy"] = "黑铁间谍",
	["Elder Crag Boar"] = "老峭壁野猪",
	["Exalted with {faction:54}: in Classic, other races may buy the mechanostriders"] = "{faction:54}达到崇拜：在经典版中，其他种族可购买机械陆行鸟",
	["Frostmane Headhunter"] = "霜鬃猎头者",
	["Frostmane Troll Whelp"] = "霜鬃巨魔幼崽",
	["Gnomeregan Exiles Reputation"] = "诺莫瑞根流亡者声望",
	["Honored: in Classic the {faction:54}' vendors take 10% off for you, {npc:7955}'s mechanostriders (20g, the swift ones 200g) included; Forever has not settled it, and guide sites report 5% at Friendly rising to 20% at Exalted. Honored to Revered is 12,000 reputation: 240 turn-ins, 4,800 {item:14047}."] = "尊敬：经典旧世里{faction:54}的商人给你打九折，包括{npc:7955}的机械陆行鸟（20金，迅捷款200金）；Forever 还没有定论，攻略网站称友善时5%，崇拜时升到20%。尊敬到崇敬是12,000点声望：240次上交，4,800个{item:14047}。",
	["Ice Claw Bear"] = "冰爪熊",
	["Optional: eastern {zone:1426}, from {npc:264936}'s camp to the {area:134} and {area:803}, about 500 reputation (100 at a fifth) in 30 minutes at 60. In Classic, quests 6+ levels below you pay less (a fifth at 60); a Forever beta report says they paid in full. Your first turn-in shows which: if it pays a fifth, skip these hubs. Skip this step to skip the hub."] = "可选：{zone:1426}东部，从{npc:264936}的营地到{area:134}和{area:803}，60级时30分钟约500点声望（按五分之一算是100）。经典旧世里，低于你6级以上的任务奖励更少（60级时为五分之一）；一份 Forever 测试报告称会全额发放。第一次上交就能看出是哪种：如果只给五分之一，就跳过这些任务点。跳过这一步就跳过该任务点。",
	["Optional: the Dwarf and Gnome start valley south-west of {area:131}, about 1,150 reputation (230 at a fifth) in 30 minutes at 60. {npc:658} and {npc:713} stand at {area:77}. In Classic, quests 6+ levels below you pay less (a fifth at 60); a Forever beta report says they paid in full. Your first turn-in shows which: if it pays a fifth, skip these hubs. Skip this step to skip the hub."] = "可选：{area:131}西南的矮人与侏儒新手山谷，60级时30分钟约1,150点声望（按五分之一算是230）。{npc:658}和{npc:713}站在{area:77}。经典旧世里，低于你6级以上的任务奖励更少（60级时为五分之一）；一份 Forever 测试报告称会全额发放。第一次上交就能看出是哪种：如果只给五分之一，就跳过这些任务点。跳过这一步就跳过该任务点。",
	["Optional: {area:131} and the Brewnall and {area:133} roads around it, about 1,300 reputation (260 at a fifth) in 50 minutes at 60. Most givers stand in and around the {area:2102} and at {area:189} east of it. In Classic, quests 6+ levels below you pay less (a fifth at 60); a Forever beta report says they paid in full. Your first turn-in shows which: if it pays a fifth, skip these hubs. Skip this step to skip the hub."] = "可选：{area:131}以及周围布瑞恩诺尔和{area:133}的道路，60级时50分钟约1,300点声望（按五分之一算是260）。大多数任务发布者站在{area:2102}及其周边，以及它东边的{area:189}。经典旧世里，低于你6级以上的任务奖励更少（60级时为五分之一）；一份 Forever 测试报告称会全额发放。第一次上交就能看出是哪种：如果只给五分之一，就跳过这些任务点。跳过这一步就跳过该任务点。",
	["Overmaster Pyron"] = "至尊匹隆",
	["Reputation · Cities"] = "声望 · 城市",
	["Revered to Exalted is 21,000 reputation: 420 turn-ins, 8,400 {item:14047}. At Exalted, {npc:7955} at {area:189} in {zone:1426} sells her mechanostriders to other races in Classic; the Mechanostrider and Swift Mechanostrider guides cover them."] = "崇敬到崇拜是21,000点声望：420次上交，8,400个{item:14047}。崇拜后，经典旧世里{zone:1426}的{area:189}处{npc:7955}会把她的机械陆行鸟卖给其他种族；机械陆行鸟和迅捷机械陆行鸟指南有详细介绍。",
	["Rockjaw Bonesnapper"] = "石颚碎骨者",
	["Rockjaw Skullthumper"] = "石颚碎颅者",
	["Rockjaw Trogg"] = "石颚穴居人",
	["Small Crag Boar"] = "小型峭壁野猪",
	["Snow Leopard"] = "雪豹",
	["The Cursed and Tainted Oozes slide about the streams and fel pools around {area:1763} and {area:1765}: kill one and use an empty jar on its remains."] = "被诅咒的软泥怪和受污染的软泥怪在{area:1763}和{area:1765}周围的溪流和邪能水池里滑行：杀一只，在它的残骸上使用空瓶。",
	["The Dark Iron Spies lurk around Farsen's camp; the troggs dig in the {area:134}; {npc:1388}, a big snow leopard, prowls the hills above {area:803}."] = "黑铁间谍潜伏在法尔森营地附近；穴居人在{area:134}挖掘；{npc:1388}，一只大雪豹，在{area:803}上方的山丘游荡。",
	["The Primal Oozes live in the pools around {area:537} in the middle of the crater; the Muculent and Glutinous Oozes fill the jars too. Kill one and use a jar on its remains."] = "原始软泥怪生活在火山口中央{area:537}周围的水池里；黏液软泥怪和胶质软泥怪也能装满瓶子。杀一只，在它的残骸上使用瓶子。",
	["The Scalding Mornbrew cools in five minutes: run straight to {npc:836} at {area:77}."] = "滚烫的晨酿五分钟后就会凉：直接跑到{area:77}的{npc:836}那里。",
	["The boars and bears roam around {area:131}; the wendigos live in the {area:136} south-west of town; the leper gnomes at the {area:133} road carry the cogs and gears; Rumbleshot's ammo lies at his camp west of town."] = "野猪和熊在{area:131}周围游荡；温迪戈住在小镇西南的{area:136}；{area:133}路上的麻风侏儒带着齿轮和零件；朗布尔肖特的弹药在他的营地、小镇西边。",
	["The quarry and {area:803}"] = "采石场与{area:803}",
	["The quarry: troggs, spies and {npc:1388}"] = "采石场：穴居人、间谍和{npc:1388}",
	["The wolves roam the valley floor; the troggs dig in the camps east of {area:77}; {npc:8416}'s box, chest and bucket lie in the trogg camps."] = "狼在山谷底部游荡；穴居人在{area:77}东边的营地挖掘；{npc:8416}的箱子、木箱和水桶在穴居人营地里。",
	["walk to the back of the cave"] = "走到洞穴深处",
	["{area:131}: Brewnall and {quest:287}"] = "{area:131}：布瑞恩诺尔和{quest:287}",
	["{area:131}: back in town"] = "{area:131}：回到镇上",
	["{area:131}: last hand-in"] = "{area:131}：最后一次交任务",
	["{area:131}: the hills and the depot"] = "{area:131}：山丘与补给站",
	["{area:2418}: hand in"] = "{area:2418}：交任务",
	["{area:254} stands in the west of the {zone:1428}. {quest:4262}, a fire elemental, walks the lava paths inside it, near the door of {area:1584} but outside the dungeon: at 60 you take him alone."] = "{area:254}位于{zone:1428}西部。{quest:4262}，一个火元素，在里面的熔岩路径上走动，靠近{area:1584}门口但在副本外：60级时可以单挑他。",
	["{item:14047} drops from humanoids level 50 and up: the Scourge cultists and Scarlet Crusade in the Plaguelands, the Deadwood furbolgs of {zone:1448}, the Winterfall furbolgs of {zone:1452}. Keep any {item:14047} past the first 60 for {quest:7812}."] = "{item:14047}由50级及以上的人形怪掉落：瘟疫之地的天灾教徒和血色十字军、{zone:1448}的死木熊怪、{zone:1452}的冬泉熊怪。前60个之外的{item:14047}都留着给{quest:7812}。",
	["{item:2592}: troggs, gnolls and kobolds in {zone:1432} and the {zone:1437}"] = "{item:2592}：{zone:1432}和{zone:1437}的穴居人、豺狼人和狗头人",
	["{item:4306} drops from humanoids level 23 to 40: the Dragonmaw of the {zone:1437}, the Syndicate of Alterac and Arathi, Stranglethorn's trolls."] = "{item:4306}由23到40级的人形怪掉落：{zone:1437}的龙喉、奥特兰克和阿拉希的辛迪加、荆棘谷的巨魔。",
	["{item:4338} drops from humanoids level 35 to 50: the Shadowforge and {object:147516} dwarves of the {zone:1418} and {zone:1427}, the Dunemaul ogres of {zone:1446}, the Hatecrest naga of {zone:1444}."] = "{item:4338}由35到50级的人形怪掉落：{zone:1418}和{zone:1427}的暗炉和{object:147516}矮人、{zone:1446}的砂槌食人魔、{zone:1444}的憎恨之鳞纳迦。",
	["{npc:1252}, in {area:131}"] = "{npc:1252}，在{area:131}",
	["{npc:1274}, in the throne room"] = "{npc:1274}，在王座厅",
	["{npc:1374} stands by {area:137} on the lake north-west of {area:131}; {quest:287} is the troll cave west of it."] = "{npc:1374}站在{area:131}西北湖边{area:137}旁；{quest:287}在它西边的巨魔洞。",
	["{npc:14724} takes cloth for the {faction:54}; he stands in {object:171524} in {zone:1455}, by the tram. Each first donation of 60 Wool, Silk, Mageweave and {item:14047} pays 150 reputation once; after the {item:14047} one, {quest:7812} pays 50 for every 20 {item:14047}, as often as you like. The Auction House in the Commons is the quickest source of cloth. In Classic, quests pay full reputation while they are at most 5 levels below you, so do {zone:1426} (levels 1-12) and {npc:4077}'s quests in Stonetalon (20-25) while you level. After the donations come {npc:9616}'s ooze quests and {quest:4262} (400), then the optional {zone:1426} hubs, best rate first: {area:132} (about 38 a minute at full value), {area:131} (26), the quarry (17). Every {area:133} gain also gives a quarter as much to {zone:1453}, {zone:1455} and {zone:1457}, except quests in the level 1-10 start areas. Legacy Diplomat adds up to 10% to every gain."] = "{npc:14724}为{faction:54}收布；他站在{zone:1455}地铁旁的{object:171524}。首次各捐60个毛料、丝绸、魔纹布和{item:14047}，每次给150点声望；交完{item:14047}那次后，{quest:7812}每20个{item:14047}给50点，想交多少次都行。公共区的拍卖行是最快的布匹来源。经典旧世里，只要任务最多低于你5级，就按全额给声望，所以练级时做{zone:1426}（1-12级）和{npc:4077}在石爪山的任务（20-25级）。捐赠之后是{npc:9616}的软泥任务和{quest:4262}（400点），然后是可选{zone:1426}任务点，按效率从高到低：{area:132}（全额时每分钟约38）、{area:131}（26）、采石场（17）。每一份{area:133}声望收益还会以四分之一的比例给{zone:1453}、{zone:1455}和{zone:1457}，1-10级新手区的任务除外。传承外交官能让每份收益最多提高10%。",
	["{npc:14724}, the cloth quartermaster"] = "{npc:14724}，布匹军需官",
	["{npc:6806}, in the inn"] = "{npc:6806}，在旅店里",
	["{npc:786} camps south of {area:77}, at the mouth of the troll cave; the journal lies at the back of the cave."] = "{npc:786}在{area:77}以南扎营，就在巨魔洞口；手记在洞穴深处。",
	["{npc:9561} at {area:2418}, in the south-east of the {zone:1428}, wants {quest:4262} dead: 100 {area:133} reputation (level 52: in Classic 40 at 60). Her next quest, Incendius!, needs a {area:1584} group: 100 more, in full."] = "{npc:9561}在{area:2418}，位于{zone:1428}东南部，要{quest:4262}死：100点{area:133}声望（52级：经典旧世里60级时40点）。她的下一个任务“Incendius!”需要一个{area:1584}队伍：再给100点，全额。",
	["{npc:9616} in {object:171524} wants ooze samples for her research: 150 {area:133} reputation for each of her two quests (level 52 and 54: in Classic 60 and 120 of it at 60). She hands you the empty jars."] = "{object:171524}处的{npc:9616}要为研究收集软泥样本：她的两个任务（52级和54级）各给150点{area:133}声望（经典旧世里60级时分别是60点和120点）。她会把空瓶交给你。",
	["{object:171524}: hand in"] = "{object:171524}：交任务",
	["{object:171524}: the second jars"] = "{object:171524}：第二批瓶子",
	["{quest:4262}, +100"] = "{quest:4262}，+100",
	["{quest:4512}, +150"] = "{quest:4512}，+150",
	["{quest:7812} to Exalted"] = "{quest:7812}刷到崇拜",
	["{quest:7812} to Honored"] = "{quest:7812}刷到尊敬",
	["{quest:7812} to Revered"] = "{quest:7812}刷到崇敬",
	["{quest:7812}: 50 reputation for 20 {item:14047}, as often as you like. After the four first donations a Human, Dwarf or Night Elf stands at Friendly 700 of 6,000, so Honored is 5,300 away: 106 turn-ins, 2,120 {item:14047} (Gnomes start 900 higher: 88 turn-ins; Skyborne start at Neutral 2,000, so 6,400 away: 128, two fewer after Exploring the Alliance). {npc:9616}'s and {npc:9561}'s quests above take 8 turn-ins off; each {zone:1426} hub you did takes 10 to 26 more off if it paid in full. Outside Dun Morogh Gnomeregan pays little: {npc:4077}'s quests in Stonetalon (about 500) and {object:171524}'s {area:133} dungeon quests. Every city gain also gives a quarter as much to the other three Alliance cities (not counted here). Hand in all your {item:14047} at once."] = "{quest:7812}：每20个{item:14047}换50点声望，想交多少次都行。四次首次捐赠之后，人类、矮人或暗夜精灵处在友善700/6,000，离尊敬还差5,300点：106次上交、2,120个{item:14047}（侏儒初始高900点：88次；天裔从中立2,000开始，差6,400点：128次，做了“探索联盟”后少两次）。上面{npc:9616}和{npc:9561}的任务能减掉8次上交；你做过的每个{zone:1426}任务点，如果按全额给，还能再减10到26次。丹莫罗以外，诺莫瑞根的声望给得很少：{npc:4077}在石爪山的任务（约500点）和{object:171524}的{area:133}副本任务。每份主城声望收益还会以四分之一的比例给其他三个联盟主城（这里未计入）。把所有{item:14047}一次交清。",
	["{zone:1448}: Cursed and Tainted Oozes"] = "{zone:1448}：被诅咒的软泥怪和受污染的软泥怪",
	["{zone:1449}: Primal Oozes"] = "{zone:1449}：原始软泥怪",
}

G["forever/reputation/ironforge"] = {
	["About 2,900 {faction:47} reputation from low-level quests in {zone:1426}, most of it paid to {area:133} too (in Classic, a fifth of it at 60)"] = "在{zone:1426}做低级任务可获得约2,900点{faction:47}声望，其中大部分也会给{area:133}（经典旧世里60级时只有五分之一）",
	["About 600 {faction:47} reputation from level 52-59 quests in the {zone:1428} and {zone:1452}; {zone:1459}'s quests pay {faction:47} too"] = "{zone:1428}和{zone:1452}的52-59级任务约提供600点{faction:47}声望；{zone:1459}的任务也会提升{faction:47}声望",
	["Burly Rockjaw Trogg"] = "强壮的石颚穴居人",
	["Cloth, the {zone:1428} quests and the {zone:1426} hubs, which pay {area:133} too; {zone:1459} adds more."] = "布匹、{zone:1428}的任务和{zone:1426}的各任务点，同时也会给{area:133}；{zone:1459}还能再加一些。",
	["Coldridge: on to {area:131}"] = "寒脊山谷：前往{area:131}",
	["Coldridge: the hot Mornbrew"] = "寒脊山谷：滚烫的晨酿",
	["Coldridge: wolves, troggs and {npc:8416}'s things"] = "寒脊山谷：狼、穴居人和{npc:8416}的东西",
	["Coldridge: {area:77} and {npc:714}"] = "寒脊山谷：{area:77}和{npc:714}",
	["Coldridge: {npc:786} and the troll cave"] = "寒脊山谷：{npc:786}和巨魔洞",
	["Dark Iron Spy"] = "黑铁间谍",
	["Elder Crag Boar"] = "老峭壁野猪",
	["Exalted with {faction:47}: in Classic, other races may buy the rams"] = "{faction:47}达到崇拜：在经典版中，其他种族可购买山羊",
	["Firegut Brute"] = "火腹蛮兵",
	["Firegut Ogre"] = "火腹食人魔",
	["Firegut Ogre Mage"] = "火腹食人魔法师",
	["Frostmane Headhunter"] = "霜鬃猎头者",
	["Frostmane Troll Whelp"] = "霜鬃巨魔幼崽",
	["Hear {npc:8879} out"] = "听{npc:8879}说完",
	["Honored: in Classic Ironforge's vendors take 10% off for you, {npc:1261}'s rams (20g, the swift ones 200g) included; Forever has not settled it, and guide sites report 5% at Friendly rising to 20% at Exalted. Honored to Revered is 12,000 reputation: 240 turn-ins, 4,800 {item:14047}."] = "尊敬：经典旧世里铁炉堡的商人给你打九折，包括{npc:1261}的山羊（20金，迅捷款200金）；Forever 还没有定论，攻略网站称友善时5%，崇拜时升到20%。尊敬到崇敬是12,000点声望：240次上交，4,800个{item:14047}。",
	["Ice Claw Bear"] = "冰爪熊",
	["Ironforge Reputation"] = "铁炉堡声望",
	["Optional: eastern {zone:1426}, from {npc:264936}'s camp to the {area:134} and {area:803}, about 500 reputation (100 at a fifth) in 30 minutes at 60. In Classic, quests 6+ levels below you pay less (a fifth at 60); a Forever beta report says they paid in full. Your first turn-in shows which: if it pays a fifth, skip these hubs. Skip this step to skip the hub."] = "可选：{zone:1426}东部，从{npc:264936}的营地到{area:134}和{area:803}，60级时30分钟约500点声望（按五分之一算是100）。经典旧世里，低于你6级以上的任务奖励更少（60级时为五分之一）；一份 Forever 测试报告称会全额发放。第一次上交就能看出是哪种：如果只给五分之一，就跳过这些任务点。跳过这一步就跳过该任务点。",
	["Optional: the Dwarf and Gnome start valley south-west of {area:131}, about 1,100 reputation (220 at a fifth) in 30 minutes at 60. {npc:658} and {npc:713} stand at {area:77}. In Classic, quests 6+ levels below you pay less (a fifth at 60); a Forever beta report says they paid in full. Your first turn-in shows which: if it pays a fifth, skip these hubs. Skip this step to skip the hub."] = "可选：{area:131}西南的矮人与侏儒新手山谷，60级时30分钟约1,100点声望（按五分之一算是220）。{npc:658}和{npc:713}站在{area:77}。经典旧世里，低于你6级以上的任务奖励更少（60级时为五分之一）；一份 Forever 测试报告称会全额发放。第一次上交就能看出是哪种：如果只给五分之一，就跳过这些任务点。跳过这一步就跳过该任务点。",
	["Optional: {area:131} and the Brewnall and {area:133} roads around it, about 1,300 reputation (260 at a fifth) in 50 minutes at 60. Most givers stand in and around the {area:2102} and at {area:189} east of it. In Classic, quests 6+ levels below you pay less (a fifth at 60); a Forever beta report says they paid in full. Your first turn-in shows which: if it pays a fifth, skip these hubs. Skip this step to skip the hub."] = "可选：{area:131}以及周围布瑞恩诺尔和{area:133}的道路，60级时50分钟约1,300点声望（按五分之一算是260）。大多数任务发布者站在{area:2102}及其周边，以及它东边的{area:189}。经典旧世里，低于你6级以上的任务奖励更少（60级时为五分之一）；一份 Forever 测试报告称会全额发放。第一次上交就能看出是哪种：如果只给五分之一，就跳过这些任务点。跳过这一步就跳过该任务点。",
	["Plant {npc:9176}'s head on the soft dirt mound at the top of {area:249}."] = "把{npc:9176}的头颅插在{area:249}顶部松软的土堆上。",
	["Reputation · Cities"] = "声望 · 城市",
	["Revered to Exalted is 21,000 reputation: 420 turn-ins, 8,400 {item:14047}. At Exalted, {npc:1261} at {area:803} in eastern {zone:1426} sells his rams to other races in Classic; the Ram and Swift Ram guides cover them."] = "崇敬到崇拜是21,000点声望：420次上交，8,400个{item:14047}。崇拜后，经典旧世里{zone:1426}东部{area:803}的{npc:1261}会把他的山羊卖给其他种族；山羊与迅捷山羊攻略中有介绍。",
	["Rockjaw Bonesnapper"] = "石颚碎骨者",
	["Rockjaw Skullthumper"] = "石颚碎颅者",
	["Rockjaw Trogg"] = "石颚穴居人",
	["Royal Historian Archesonus"] = "皇家史学家阿克森努斯",
	["Small Crag Boar"] = "小型峭壁野猪",
	["Snow Leopard"] = "雪豹",
	["Thaurissan and {area:252}"] = "索瑞森与{area:252}",
	["The Dark Iron Spies lurk around Farsen's camp; the troggs dig in the {area:134}; {npc:1388}, a big snow leopard, prowls the hills above {area:803}."] = "黑铁间谍潜伏在法尔森营地附近；穴居人在{area:134}挖掘；{npc:1388}，一只大雪豹，在{area:803}上方的山丘游荡。",
	["The Scalding Mornbrew cools in five minutes: run straight to {npc:836} at {area:77}."] = "滚烫的晨酿五分钟后就会凉：直接跑到{area:77}的{npc:836}那里。",
	["The Thaurissan relics are the carved stones in the ruins around {area:251}, west along the road: click twelve of them. {npc:9176} and the Blackrock orcs and worgs hold the camps at the foot of {area:254}, further west; each may drop a {item:11467} (about one kill in three), and {npc:9177} wants fifty. The orcs are level 50 and up, so they drop {item:14047} too: keep it for {quest:7806}."] = "索瑞森的遗物是沿路向西{area:251}周围废墟里的雕刻石，点击其中十二块。{npc:9176}和黑石兽人、座狼占据更西边{area:254}脚下的营地；它们每个都可能掉落{item:11467}（约三次杀一只），而{npc:9177}要五十个。兽人是50级及以上，所以也会掉{item:14047}：留着给{quest:7806}。",
	["The boars and bears roam around {area:131}; the wendigos live in the {area:136} south-west of town; the leper gnomes at the {area:133} road carry the cogs and gears; Rumbleshot's ammo lies at his camp west of town."] = "野猪和熊在{area:131}周围游荡；温迪戈住在小镇西南的{area:136}；{area:133}路上的麻风侏儒带着齿轮和零件；朗布尔肖特的弹药在他的营地、小镇西边。",
	["The quarry and {area:803}"] = "采石场与{area:803}",
	["The quarry: troggs, spies and {npc:1388}"] = "采石场：穴居人、间谍和{npc:1388}",
	["The wolves roam the valley floor; the troggs dig in the camps east of {area:77}; {npc:8416}'s box, chest and bucket lie in the trogg camps."] = "狼在山谷底部游荡；穴居人在{area:77}东边的营地挖掘；{npc:8416}的箱子、木箱和水桶在穴居人营地里。",
	["These quests are level 52 to 59, so they pay in full at 60, or nearly: about 600 {faction:47} reputation (in Classic about 450 at 60, as the {zone:1428} ones are level 52 to 54). {npc:8879} stands beside King Magni in the {object:171709}; he sends you to the ruins of Thaurissan in the {zone:1428}."] = "这些任务是52到59级，所以60级时仍能全额或接近全额：约600点{faction:47}声望（经典旧世里60级时约450点，因为{zone:1428}的那些任务是52到54级）。{npc:8879}站在{object:171709}里麦格尼国王身旁；他派你去{zone:1428}的索瑞森废墟。",
	["With a group, {area:1584} pays more: Archesonus's chain goes on with {npc:9021} (100) and The Fate of the Kingdom (Emperor Thaurissan, 150), and {npc:9177} takes 20 Dark Iron Fanny Packs from the dwarves inside (The Good Stuff, 100). {zone:1459}, from level 51, pays {faction:47} too: its one-time quests about 1,900 as your Stormpike standing grows (the {zone:1459} guide walks them), and inside the battle 25 for every 10 Irondeep or {item:17542} and 50 for 5 Storm Crystals, as often as you like."] = "组队时，{area:1584}给的更多：阿克森努斯的任务链会继续，{npc:9021}（100点）以及“王国的命运”（索瑞森皇帝，150点），{npc:9177}还会收里面矮人身上的20个黑铁腰包（“好东西”，100点）。{zone:1459}从51级起也会给{faction:47}：随着你的雷矛声望增长，它的一次性任务约给1,900点（{zone:1459}攻略有逐步说明），战场内每10个深铁矿或{item:17542}给25点，5个风暴水晶给50点，想交多少次都行。",
	["walk to the back of the cave"] = "走到洞穴深处",
	["{area:131}: Brewnall and {quest:287}"] = "{area:131}：布瑞恩诺尔和{quest:287}",
	["{area:131}: back in town"] = "{area:131}：回到镇上",
	["{area:131}: last hand-in"] = "{area:131}：最后一次交任务",
	["{area:131}: the hills and the depot"] = "{area:131}：山丘与补给站",
	["{area:2418} sits in the south-east of the {zone:1428}, at the top of the pass up from Redridge. {npc:9177} wants the Firegut ogres of {area:249}, north of the Vigil, thinned out; the Brutes keep to the rock's east side."] = "{area:2418}位于{zone:1428}东南部，在从赤脊山向上的山口顶端。{npc:9177}想让你清理摩根岗哨以北{area:249}的火腹食人魔；蛮兵守在石头的东侧。",
	["{area:2418}: hand in"] = "{area:2418}：交任务",
	["{faction:47}: Archesonus again"] = "{faction:47}：再找阿克森努斯",
	["{item:14047} drops from humanoids level 50 and up: the Scourge cultists and Scarlet Crusade in the Plaguelands, the Deadwood furbolgs of {zone:1448}, the Winterfall furbolgs of {zone:1452}. Keep any {item:14047} past the first 60 for {quest:7806}."] = "{item:14047}由50级及以上的人形怪掉落：瘟疫之地的天灾教徒和血色十字军、{zone:1448}的死木熊怪、{zone:1452}的冬泉熊怪。前60个之外的{item:14047}都留着给{quest:7806}。",
	["{item:2592}: troggs, gnolls and kobolds in {zone:1432} and the {zone:1437}"] = "{item:2592}：{zone:1432}和{zone:1437}的穴居人、豺狼人和狗头人",
	["{item:4306} drops from humanoids level 23 to 40: the Dragonmaw of the {zone:1437}, the Syndicate of Alterac and Arathi, Stranglethorn's trolls."] = "{item:4306}由23到40级的人形怪掉落：{zone:1437}的龙喉、奥特兰克和阿拉希的辛迪加、荆棘谷的巨魔。",
	["{item:4338} drops from humanoids level 35 to 50: the Shadowforge and {object:147516} dwarves of the {zone:1418} and {zone:1427}, the Dunemaul ogres of {zone:1446}, the Hatecrest naga of {zone:1444}."] = "{item:4338}由35到50级的人形怪掉落：{zone:1418}和{zone:1427}的暗炉和{object:147516}矮人、{zone:1446}的砂槌食人魔、{zone:1444}的憎恨之鳞纳迦。",
	["{npc:11755} in {area:2255} sends you west to {npc:10301} at {area:2253}. {npc:10301}'s damaged crate and wrecked wagon lie at {area:2245}, down the valley to the south-east; his supplies lie around the wagon and the owlbeasts nearby carry his amulet. The last quest is level 59: 100 {faction:47} in full."] = "{area:2255}的{npc:11755}派你向西去找{area:2253}的{npc:10301}。{npc:10301}损坏的木箱和毁坏的货车在{area:2245}，沿山谷往东南下去；他的补给散落在货车周围，附近的猫头鹰兽带着他的护符。最后一个任务是59级：全额100点{faction:47}。",
	["{npc:1252}, in {area:131}"] = "{npc:1252}，在{area:131}",
	["{npc:1274}, in the throne room"] = "{npc:1274}，在王座厅",
	["{npc:1374} stands by {area:137} on the lake north-west of {area:131}; {quest:287} is the troll cave west of it."] = "{npc:1374}站在{area:131}西北湖边{area:137}旁；{quest:287}在它西边的巨魔洞。",
	["{npc:14723} takes cloth for {faction:47}; she stands outside the clothier on the north side of the {object:32372}, among the tailors. Each first donation of 60 Wool, Silk, Mageweave and {item:14047} pays 150 reputation once; after the {item:14047} one, {quest:7806} pays 50 for every 20 {item:14047}, as often as you like. The Auction House in the Commons is the quickest source of cloth. In Classic, quests pay full reputation while they are at most 5 levels below you, so do {zone:1426} (levels 1-12), {zone:1432} (10-20) and the {zone:1437} (20-30) while you level through them. After the donations come the level 52-59 quests of the {zone:1428} and {zone:1452} (about 600), then the optional {zone:1426} hubs, best rate first: {area:132} (about 37 a minute at full value), {area:131} (26), the quarry (17). Every {faction:47} gain also gives a quarter as much to {zone:1453}, {zone:1457} and the Gnomeregan Exiles, except quests in the level 1-10 start areas. Legacy Diplomat adds up to 10% to every gain."] = "{npc:14723}为{faction:47}收布；她站在{object:32372}北侧裁缝店外，混在裁缝中间。首次各捐60个毛料、丝绸、魔纹布和{item:14047}，每次给150点声望；交完{item:14047}那次后，{quest:7806}每20个{item:14047}给50点，想交多少次都行。公共区的拍卖行是最快的布匹来源。经典旧世里，只要任务最多低于你5级，就按全额给声望，所以练级时做{zone:1426}（1-12级）、{zone:1432}（10-20级）和{zone:1437}（20-30级）。捐赠之后是{zone:1428}和{zone:1452}的52-59级任务（约600点），然后是可选{zone:1426}任务点，按效率从高到低：{area:132}（全额时每分钟约37）、{area:131}（26）、采石场（17）。每一份{faction:47}声望收益还会以四分之一的比例给{zone:1453}、{zone:1457}和诺莫瑞根流亡者，1-10级新手区的任务除外。传承外交官能让每份收益最多提高10%。",
	["{npc:14723}, the cloth quartermaster"] = "{npc:14723}，布匹军需官",
	["{npc:6806}, in the inn"] = "{npc:6806}，在旅店里",
	["{npc:786} camps south of {area:77}, at the mouth of the troll cave; the journal lies at the back of the cave."] = "{npc:786}在{area:77}以南扎营，就在巨魔洞口；手记在洞穴深处。",
	["{quest:3701}, +10"] = "{quest:3701}，+10",
	["{quest:3701}, +100"] = "{quest:3701}，+100",
	["{quest:3823}, +100"] = "{quest:3823}，+100",
	["{quest:3824}, +100"] = "{quest:3824}，+100",
	["{quest:3825}, +100"] = "{quest:3825}，+100",
	["{quest:4283}, +100"] = "{quest:4283}，+100",
	["{quest:4861}, +100"] = "{quest:4861}，+100",
	["{quest:7806} to Exalted"] = "{quest:7806}刷到崇拜",
	["{quest:7806} to Honored"] = "{quest:7806}刷到尊敬",
	["{quest:7806} to Revered"] = "{quest:7806}刷到崇敬",
	["{quest:7806}: 50 reputation for 20 {item:14047}, as often as you like. After the four first donations a Human, Night Elf or Gnome stands at Friendly 700 of 6,000, so Honored is 5,300 away: 106 turn-ins, 2,120 {item:14047} (Dwarves start 900 higher: 88 turn-ins; Skyborne start at Neutral 2,000, so 6,400 away: 128, two fewer after Exploring the Alliance). The level 52-59 quests above take 12 turn-ins off; each {zone:1426} hub you did takes 10 to 26 more off if it paid in full. More hubs pay {faction:47}, in full while they are no more than 5 levels below you: {area:144} in {zone:1432} (about 3,500 in all) and {area:150} in the {zone:1437} (about 2,500). From level 51 {zone:1459}'s one-time quests add about 1,900. Every city gain also gives a quarter as much to the other three Alliance cities (not counted here). Hand in all your {item:14047} at once."] = "{quest:7806}：每20个{item:14047}换50点声望，想交多少次都行。四次首次捐赠之后，人类、暗夜精灵或侏儒处在友善700/6,000，离尊敬还差5,300点：106次上交、2,120个{item:14047}（矮人初始高900点：88次；天裔从中立2,000开始，差6,400点：128次，做了“探索联盟”后少两次）。上面52-59级的任务能减掉12次上交；你做过的每个{zone:1426}任务点，如果按全额给，还能再减10到26次。更多任务点会给{faction:47}，只要最多低于你5级就按全额：{zone:1432}的{area:144}（共约3,500点）和{zone:1437}的{area:150}（约2,500点）。从51级起，{zone:1459}的一次性任务再加约1,900点。每份主城声望收益还会以四分之一的比例给其他三个联盟主城（这里未计入）。把所有{item:14047}一次交清。",
}

G["forever/reputation/kirin-tor"] = {
	["Alliance Skyborne start Friendly with the {faction:2740}, and their arrival quests The Magical City of Dalaran and Exploring the Alliance pay 100 more each, so {npc:32287} sells you the Azure recipes at once (10g each, they need skill 175). He stands upstairs in the building with the {faction:2740} banners in {area:279}, past the Sky Enclave. Buy the ones for your profession."] = "联盟天裔与{faction:2740}初始为友善，他们的到来任务“魔法之城达拉然”和“探索联盟”各多给100点，所以{npc:32287}会立刻向你出售碧蓝配方（每个10金，需要技能175）。他站在{area:279}里挂有{faction:2740}旗帜的建筑楼上，过了天空营地就是。买你专业对应的那些。",
	["Back to Modera's image"] = "返回茉德拉的影像",
	["Back to {npc:264265}"] = "返回{npc:264265}",
	["City of Dalaran runs to Exalted"] = "刷“达拉然城”到崇拜",
	["City of Dalaran runs to Friendly"] = "刷“达拉然城”到友善",
	["Eight Azure helm and shoulder recipes at Friendly ({skill:164}, {skill:165}, {skill:197})"] = "友善时可购八种蔚蓝头盔和护肩配方（{skill:164}、{skill:165}、{skill:197}）",
	["Kirin Tor Reputation"] = "肯瑞托声望",
	["Mana Echo"] = "法力回响",
	["New in Forever: {area:279}'s mages sell Azure armour recipes at Friendly and their tabard at Exalted."] = "Forever 新增：{area:279}的法师在友善时出售碧蓝护甲配方，崇拜时出售他们的战袍。",
	["Nothing is sold at Honored or Revered in the game's data. Friendly to Exalted is 39,000 reputation, all from City of Dalaran kills. In Classic most dungeon kills stop paying at Honored or Revered; whether these do is not known yet."] = "游戏数据里，尊敬或崇敬时没有出售任何东西。友善到崇拜是39,000点声望，全部来自“达拉然城”的击杀。经典旧世里大多数副本击杀在尊敬或崇敬时就停止给声望；这些是否会停尚不清楚。",
	["Reputation · World"] = "声望 · 世界",
	["Saturated Remnant"] = "饱和残渣",
	["Seeking Remnant"] = "寻觅残渣",
	["Skyborne: the recipes now"] = "天裔：立刻买配方",
	["The City of Dalaran"] = "达拉然城",
	["The City of Dalaran is a dungeon for levels 28 to 33: go in through the sewers with the key Modera gave you. The arcane elementals throughout the city count for {quest:92457}. The {npc:246020}, the last boss, waits in the Purple Parlor above the Violet Citadel (a portal by {npc:246748} in the Citadel takes you up) and drops the {item:251961}. Beta players saw every kill in the dungeon pay {faction:2740} reputation, the bosses the most. Group of five advised below level 35."] = "“达拉然城”是28到33级的副本：用茉德拉给你的钥匙从下水道进入。城中各处的奥术元素都计入{quest:92457}。最后的首领{npc:246020}在紫罗兰城堡上方的紫色会客厅等待（城堡里{npc:246748}旁有传送门送你上去），并掉落{item:251961}。测试服玩家看到副本里每次击杀都给{faction:2740}声望，首领给得最多。35级以下建议五人队。",
	["The quests leave a non-Skyborne at about 320 of the 3,000 Friendly needs. The rest comes from kills in the City of Dalaran dungeon: run it until Friendly. How much each kill pays is not in the game's data; the bosses pay the most. At 60 you clear it alone."] = "这些任务只能让非天裔角色达到友善所需3,000点中的约320点。其余来自“达拉然城”副本的击杀：一直刷到友善。每次击杀给多少不在游戏数据里；首领给得最多。60级时你可以单刷。",
	["The {area:796} stands in the north-east of {zone:1420}; Doan waits at the end of the Library wing. Group of five advised below level 40."] = "{area:796}位于{zone:1420}东北部；杜安在图书馆侧翼尽头等待。40级以下建议五人队。",
	["The {item:285327}"] = "{item:285327}（肯瑞托战袍）",
	["you get the {item:277507} with it"] = "同时获得{item:277507}",
	["{item:251961}, from the {npc:246020}"] = "{item:251961}，来自{npc:246020}",
	["{item:273169}, from {npc:6487}"] = "{item:273169}，来自{npc:6487}",
	["{npc:246748}'s image"] = "{npc:246748}的影像",
	["{npc:247264} of the {faction:2740} waits in {area:271}. He sends you to {npc:246748}'s image by the shore of {area:1338}, outside {area:279}'s walls. The {faction:2740} quests start at level 24 to 30 and pay full reputation while they are at most 5 levels below you; in Classic a quest 6+ levels below you pays less (a fifth at 60)."] = "{faction:2740}的{npc:247264}在{area:271}等待。他派你去{area:279}城墙外、{area:1338}岸边的{npc:246748}影像处。{faction:2740}的任务从24到30级开始，只要最多低于你5级就按全额给声望；经典旧世里低于你6级以上的任务给的更少（60级时为五分之一）。",
	["{npc:252085} waits in the Violet Citadel in {area:279}."] = "{npc:252085}在{area:279}的紫罗兰城堡里等待。",
	["{npc:264265} in {area:279} wants a book back from {npc:6487}, the last boss of the {area:796}'s Library (levels 33 to 41), in {zone:1420}."] = "{area:279}的{npc:264265}想从{zone:1420}的{area:796}图书馆（33到41级）最后首领{npc:6487}那里拿回一本书。",
	["{npc:32287} and {npc:28776}, the tabard vendor in {area:279}, sell the {item:285327} at Exalted for 25g."] = "{npc:32287}和{area:279}的战袍商人{npc:28776}在崇拜时以25金出售{item:285327}。",
	["{npc:32287} sells the Azure helm and shoulder recipes at Friendly, 10g each (skill 175). He stands upstairs in the building with the {faction:2740} banners in {area:279}. Buy the ones for your profession."] = "{npc:32287}在友善时出售碧蓝头盔和护肩配方，每个10金（技能175）。他站在{area:279}里挂有{faction:2740}旗帜的建筑楼上。买你专业对应的那些。",
	["{npc:32287}: the Azure recipes"] = "{npc:32287}：碧蓝配方",
}

G["forever/reputation/stormwind"] = {
	["About 1,150 {faction:72} reputation from level 52-58 quests at {area:3197} and in the {zone:1428}"] = "在{area:3197}和{zone:1428}做52-58级任务可获得约1150点{faction:72}声望",
	["About 4,500 {faction:72} reputation from low-level quests in Elwynn and the {area:717} (in Classic, a fifth of it at 60)"] = "在艾尔文森林和{area:717}做低等级任务可获得约4500点{faction:72}声望（经典版中60级时只有五分之一）",
	["Andorhal Tower Four"] = "安多哈尔四号塔",
	["Andorhal Tower One"] = "安多哈尔一号塔",
	["Andorhal Tower Three"] = "安多哈尔三号塔",
	["Andorhal Tower Two"] = "安多哈尔二号塔",
	["Andorhal and {area:199}"] = "安多哈尔与{area:199}",
	["Arcane Explainer"] = "奥术讲解者",
	["Black Broodling"] = "黑色雏龙",
	["Black Dragonspawn"] = "黑色龙人",
	["Black Drake"] = "黑色幼龙",
	["Black Wyrmkin"] = "黑色龙兽",
	["Cloth, the {zone:1422}' cauldron quests and the Elwynn hubs: the quests pay most while you level."] = "布料、{zone:1422}的大锅任务和艾尔文森林的任务点：升级期间任务给的声望最多。",
	["Defias Convict"] = "迪菲亚罪犯",
	["Defias Insurgent"] = "迪菲亚暴徒",
	["Defias Prisoner"] = "迪菲亚囚犯",
	["Defias Rogue Wizard"] = "迪菲亚流氓法师",
	["Eastvale"] = "东谷",
	["Eastvale: Defias Rogue Wizards"] = "东谷：迪菲亚流氓法师",
	["Eastvale: hand in"] = "东谷：交任务",
	["Eastvale: the work"] = "东谷：干活",
	["Exalted with {faction:72}: in Classic, other races may buy the horses"] = "{faction:72}达到崇拜：在经典版中，其他种族可购买马匹",
	["Honored: in Classic Stormwind's vendors take 10% off for you, {npc:384}'s horses (20g, the swift ones 200g) included; Forever has not settled it, and guide sites report 5% at Friendly rising to 20% at Exalted. Honored to Revered is 12,000 reputation: 240 turn-ins, 4,800 {item:14047}."] = "尊敬：经典版中暴风城商人会给你打九折，包括{npc:384}的马（20金，迅捷马200金）；Forever 尚未确定，攻略站点称友善时5%，崇拜时升至20%。尊敬到崇敬需要12000点声望：240次上交，4800个{item:14047}。",
	["Inside the {area:717}"] = "{area:717}内",
	["Kill the prisoners, convicts and insurgents in the cells; the Red Wool Bandanas drop from the Defias inside. {npc:1716} waits in the far end."] = "杀掉牢房里的囚犯、罪犯和暴徒；红色毛纺头巾由里面的迪菲亚掉落。{npc:1716}在最深处等你。",
	["Kobold Geomancer"] = "狗头人地卜师",
	["Kobold Laborer"] = "狗头人劳工",
	["Kobold Vermin"] = "狗头人害兽",
	["Kobold Worker"] = "狗头人工人",
	["Lady Katrana Prestor"] = "卡特拉娜·普瑞斯托女士",
	["Mark the four watchtowers around Andorhal, north of the camp, with the {item:12815} at each door. {npc:11075} guards the cauldron at {area:199}, west of Andorhal; his key opens it. {npc:10778}'s ghost wanders by the Felstone farmhouse, and her parcel lies inside: it goes to {faction:72} for 150 more."] = "用{item:12815}在营地以北安多哈尔周围四座瞭望塔的每道门上做标记。{npc:11075}守着安多哈尔以西{area:199}的大锅；他的钥匙能打开。{npc:10778}的鬼魂在邪石农舍旁游荡，她的包裹就在里面：交给{faction:72}可再得150点。",
	["Mark {npc:10902} with the {item:12815}"] = "用{item:12815}标记{npc:10902}",
	["Mark {npc:10903} with the {item:12815}"] = "用{item:12815}标记{npc:10903}",
	["Mark {npc:10904} with the {item:12815}"] = "用{item:12815}标记{npc:10904}",
	["Mark {npc:10905} with the {item:12815}"] = "用{item:12815}标记{npc:10905}",
	["Northshire: Echo Ridge, {npc:103} and the vineyard"] = "北郡：回音山脊、{npc:103}与葡萄园",
	["Northshire: back at the abbey"] = "北郡：回到修道院",
	["Northshire: kobolds, wolves and bandanas"] = "北郡：狗头人、狼与头巾",
	["Northshire: last hand-in"] = "北郡：最后一次上交",
	["Northshire: second hand-in"] = "北郡：第二次上交",
	["Northshire: the books end in {area:87}"] = "北郡：书在{area:87}结束",
	["Northshire: the mine and the books"] = "北郡：矿洞与书",
	["Optional: eastern Elwynn, around {npc:261} on the bridge and the {area:91}, about 1,000 reputation (200 at a fifth) in 40 minutes at 60. In Classic, quests 6+ levels below you pay less (a fifth at 60); a Forever beta report says they paid in full. Your first turn-in shows which: if it pays a fifth, skip these hubs. Skip this step to skip the hub."] = "可选：艾尔文森林东部，桥上的{npc:261}和{area:91}附近，60级时约40分钟可得1000点声望（五分之一为200）。经典版中低于你6级以上的任务给的更少（60级时为五分之一）；Forever 测试报告称会全额给。第一次上交就能看出来：若只给五分之一，就跳过这些据点。跳过这一步即跳过该据点。",
	["Optional: four quick deliveries inside {faction:72} for 200 reputation (40 at a fifth) in about five minutes. In Classic, quests 6+ levels below you pay less (a fifth at 60); a Forever beta report says they paid in full. Your first turn-in shows which: if it pays a fifth, skip these hubs. Skip this step to skip the hub."] = "可选：在{faction:72}城内送四次快件，约五分钟可得200点声望（五分之一为40）。经典版中低于你6级以上的任务给的更少（60级时为五分之一）；Forever 测试报告称会全额给。第一次上交就能看出来：若只给五分之一，就跳过这些据点。跳过这一步即跳过该据点。",
	["Optional: the Human start valley north of {area:87}: about 1,600 reputation (320 at a fifth) in 40 minutes at 60, the best rate of the hubs. {npc:823} and {npc:197} stand at {area:24}. In Classic, quests 6+ levels below you pay less (a fifth at 60); a Forever beta report says they paid in full. Your first turn-in shows which: if it pays a fifth, skip these hubs. Skip this step to skip the hub."] = "可选：{area:87}以北的人类新手山谷：60级时约40分钟得1600点声望（五分之一为320），是各据点中效率最高的。{npc:823}和{npc:197}站在{area:24}。经典版中低于你6级以上的任务给的更少（60级时为五分之一）；Forever 测试报告称会全额给。第一次上交就能看出来：若只给五分之一，就跳过这些据点。跳过这一步即跳过该据点。",
	["Optional: the {area:717} is {faction:72}'s prison, a dungeon in the canals of the {object:2101}. At 60 you clear it alone in ten minutes: 300 reputation (60 at a fifth). {npc:1719} stands at the gate, {npc:1721} in {object:2100}. Two more {area:717} quests start outside the city, 100 each, if you pass by: What Comes Around... ({npc:1696}) from {npc:859} in {area:69} and Crime and Punishment ({npc:1663}) from {npc:270} in {area:42}. (The Stockade Riots, 100 more, needs the Unsent Letter from {npc:639} in the {area:1581} first.) In Classic, quests 6+ levels below you pay less (a fifth at 60); a Forever beta report says they paid in full. Your first turn-in shows which: if it pays a fifth, skip these hubs. Skip this step to skip the hub."] = "可选：{area:717}是{faction:72}的监狱，位于{object:2101}运河中的地下城。60级时十分钟即可单刷：300点声望（五分之一为60）。{npc:1719}站在门口，{npc:1721}在{object:2100}。还有两个{area:717}任务在城市外接取，各100点，若顺路可做：因果报应……（{npc:1696}）来自{area:69}的{npc:859}，罪与罚（{npc:1663}）来自{area:42}的{npc:270}。（监狱暴动，另100点，需先拿到{area:1581}里{npc:639}的未寄出的信。）经典版中低于你6级以上的任务给的更少（60级时为五分之一）；Forever 测试报告称会全额给。第一次上交就能看出来：若只给五分之一，就跳过这些据点。跳过这一步即跳过该据点。",
	["Optional: {area:87}, Westbrook and the farms south of {area:87}: about 1,450 reputation (290 at a fifth) in an hour at 60. {npc:240}, {npc:241} and {npc:253} stand around the Lion's Pride Inn. In Classic, quests 6+ levels below you pay less (a fifth at 60); a Forever beta report says they paid in full. Your first turn-in shows which: if it pays a fifth, skip these hubs. Skip this step to skip the hub."] = "可选：{area:87}、西泉和{area:87}以南的农场：60级时约一小时得1450点声望（五分之一为290）。{npc:240}、{npc:241}和{npc:253}站在狮王之傲旅店附近。经典版中低于你6级以上的任务给的更少（60级时为五分之一）；Forever 测试报告称会全额给。第一次上交就能看出来：若只给五分之一，就跳过这些据点。跳过这一步即跳过该据点。",
	["Prowler"] = "徘徊者",
	["Reputation · Cities"] = "声望 · 城市",
	["Revered to Exalted is 21,000 reputation: 420 turn-ins, 8,400 {item:14047}. At Exalted, {npc:384} at {area:88} sells her horses to other races in Classic; the Horse and Swift Horse guides cover them."] = "崇敬到崇拜需要21000点声望：420次上交，8400个{item:14047}。崇拜后，经典版中{area:88}的{npc:384}会向其他种族出售她的马；马与迅捷马攻略中有介绍。",
	["Skeletal Flayer"] = "骷髅剥皮者",
	["Slavering Ghoul"] = "流涎食尸鬼",
	["Speak with {npc:1749}"] = "与{npc:1749}交谈",
	["Stormwind Reputation"] = "暴风城声望",
	["The Kobold Workers are in {area:34} north of the abbey; {npc:103} stands in the Defias camp east of the vineyard; {quest:3904} crates lie in the vineyard; the rats carrying the {object:83763} run about the abbey grounds."] = "狗头人工人在修道院以北的{area:34}；{npc:103}站在葡萄园东边的迪菲亚营地；{quest:3904}的木箱在葡萄园里；带着{object:83763}的老鼠在修道院一带跑动。",
	["The Stonefields' farm and the Maclures' farm lie on either side of the road south of {area:87}. {quest:87} guards the back of {area:57}; {npc:330} the boar roams the {area:62}."] = "石田家和麦克卢尔家的农场位于{area:87}以南道路两侧。{quest:87}守着{area:57}的后方；野猪{npc:330}在{area:62}游荡。",
	["The farms south of {area:87}"] = "{area:87}以南的农场",
	["The murlocs along the river south of the bridge drop the fins; Prowlers and Young Forest Bears roam the woods; the Defias around the Brackwell farm and the {area:91} carry the bandanas; the enchanting supplies lie in their camps north of the tower; the Kobold Geomancers dig at {area:54}; the tools and the river finds lie along the river north of the logging camp."] = "桥南沿河的鱼人掉落鱼鳍；徘徊者与幼年森林熊在林中游荡；布拉克威尔农场和{area:91}附近的迪菲亚携带头巾；附魔材料在他们的营地、塔以北；狗头人地卜师在{area:54}挖掘；工具和河边物品散落在伐木营地以北的河岸。",
	["The {npc:6} dig at the camp north of the abbey; the wolves roam the valley; the Defias at the vineyard east of the abbey drop the bandanas. Keep any {item:247834} a kobold drops: it starts Forever's book chain."] = "{npc:6}在修道院以北的营地挖掘；狼群在山谷中游荡；修道院以东葡萄园的迪菲亚掉落头巾。狗头人掉落的{item:247834}都留着：它能开启 Forever 的书本任务链。",
	["These quests are level 52 to 58, so they pay in full at 60, or nearly. {npc:10838} and {npc:11053} at {area:3197}, in the south of the {zone:1422}, send you against the four Scourge cauldrons: 820 {faction:72} reputation in all and 600 {object:92525} on the side (in Classic about 690 {faction:72} at 60, as the first quests are level 52 and 53). The Skeletal Flayers and Slavering Ghouls roam the fields north of the camp."] = "这些任务为52到58级，所以60级时仍能全额或接近全额。{zone:1422}南部{area:3197}的{npc:10838}和{npc:11053}会派你去对付四口天灾大锅：共820点{faction:72}声望，另有600个{object:92525}（经典版中60级时约690点{faction:72}，因为最初的任务为52和53级）。骷髅剥皮者和流涎食尸鬼在营地以北的田野游荡。",
	["With a group the chain goes on into {area:1584}: {npc:9023}, Jail Break! and The Great Masquerade back in {faction:72} pay about 750 {faction:72} more, Maxwell's Mission (Lower {area:1583}) 250, Delivery to Ridgewell 135. Order Must Be Restored ({npc:11878} in the {zone:1423}) pays 200, The Key to {area:2057} 200; Onyxia's head 400 and Nefarian's 200 when the raids open."] = "组队后任务链会继续进入{area:1584}：{npc:9023}、越狱！以及回到{faction:72}的化装舞会共约再给750点{faction:72}，麦克斯韦的任务（下层{area:1583}）250点，送往山脊维尔的货物135点。必须恢复秩序（{zone:1423}的{npc:11878}）给200点，{area:2057}的钥匙200点；团队副本开放后，奥妮克希亚的头400点，奈法利安的头200点。",
	["Young Forest Bear"] = "幼年森林熊",
	["opens with Thomas' report"] = "从托马斯的报告开始",
	["the {object:176361}"] = "{object:176361}",
	["the {object:176392}"] = "{object:176392}",
	["the {object:176393}"] = "{object:176393}",
	["the {object:177289}"] = "{object:177289}",
	["walk into the mine"] = "走进矿洞",
	["{area:3197}: done"] = "{area:3197}：完成",
	["{area:3197}: the {area:202}"] = "{area:3197}：{area:202}",
	["{area:57} is south of {area:87}, {area:54} north-east of it. The kobolds in both drop the candles and the {item:773}; the wolves around {area:87} the pelts."] = "{area:57}位于{area:87}以南，{area:54}位于其东北。两处的狗头人都掉蜡烛和{item:773}；{area:87}周围的狼掉毛皮。",
	["{area:69}: Solomon again"] = "{area:69}：再找所罗门",
	["{area:717}: hand in"] = "{area:717}：交任务",
	["{area:717}: two quests"] = "{area:717}：两个任务",
	["{area:87}: Westbrook and {npc:448}"] = "{area:87}：西泉与{npc:448}",
	["{area:87}: back at the inn"] = "{area:87}：回到旅店",
	["{area:87}: last hand-in"] = "{area:87}：最后一次上交",
	["{area:87}: the mines"] = "{area:87}：矿洞",
	["{faction:72} errands"] = "{faction:72}跑腿",
	["{faction:72}: {npc:10778}'s parcel"] = "{faction:72}：{npc:10778}的包裹",
	["{item:1006}, from {npc:330}"] = "{item:1006}，来自{npc:330}",
	["{item:1256}, from the murlocs of {area:18}"] = "{item:1256}，来自{area:18}的鱼人",
	["{item:13194}, from {npc:11075}"] = "{item:13194}，来自{npc:11075}",
	["{item:14047} drops from humanoids level 50 and up: the Scourge cultists and Scarlet Crusade in the Plaguelands, the Deadwood furbolgs of {zone:1448}, the Winterfall furbolgs of {zone:1452}. Keep any {item:14047} past the first 60: it all goes to {quest:7796} later."] = "{item:14047}由50级以上人形生物掉落：瘟疫之地的天灾教徒与血色十字军、{zone:1448}的枯木熊怪、{zone:1452}的冬泉熊怪。前60个之外的多余{item:14047}都留着：之后都会交给{quest:7796}。",
	["{item:1931}, from {npc:448}"] = "{item:1931}，来自{npc:448}",
	["{item:247834}, from the kobolds"] = "{item:247834}，来自狗头人",
	["{item:2592}: Defias, gnolls and kobolds in {zone:1436} and Redridge"] = "{item:2592}：{zone:1436}和赤脊山的迪菲亚、豺狼人与狗头人",
	["{item:4306} drops from humanoids level 23 to 40: Syndicate in Alterac and Arathi, the Defias of Duskwood's {area:94}, Stranglethorn's trolls."] = "{item:4306}由23到40级人形生物掉落：奥特兰克和阿拉希的辛迪加、暮色森林{area:94}的迪菲亚、荆棘谷的巨魔。",
	["{item:4338} drops from humanoids level 35 to 50: the Dunemaul ogres of {zone:1446}, the Hatecrest naga of {zone:1444}, the Shadowforge dwarves of the {zone:1418}."] = "{item:4338}由35到50级人形生物掉落：{zone:1446}的砂槌食人魔、{zone:1444}的仇恨之冠纳迦、{zone:1418}的暗炉矮人。",
	["{item:780}, from the murlocs south of the bridge"] = "{item:780}，来自桥南的鱼人",
	["{item:782}, from the Riverpaw gnolls"] = "{item:782}，来自河爪豺狼人",
	["{item:981}, from {quest:87}"] = "{item:981}，来自{quest:87}",
	["{npc:10782} stands in the city hall on {object:2098}, beside {npc:1646}; {npc:3520} walks the canals."] = "{npc:10782}站在{object:2098}的市政厅里，{npc:1646}身旁；{npc:3520}在运河边行走。",
	["{npc:11056} in the camp also ends The Key to {area:2057} (200), after a longer chain that needs a {area:2057} group."] = "营地的{npc:11056}也能结束{area:2057}的钥匙（200点），但需要一条更长的任务链和{area:2057}的队伍。",
	["{npc:11076} guards the cauldron at the {area:202}, the farm east of {area:200}."] = "{npc:11076}守着{area:200}以东农场{area:202}的大锅。",
	["{npc:11077} guards the cauldron at {area:200}, north-east of {area:199}."] = "{npc:11077}守着{area:199}东北{area:200}的大锅。",
	["{npc:11078} guards the cauldron at {area:201}, in the east of the zone."] = "{npc:11078}守着区域东部{area:201}的大锅。",
	["{npc:14722} takes cloth for {faction:72}. The arrow leads to him; he stands upstairs inside his building. Each first donation of 60 Wool, Silk, Mageweave and {item:14047} pays 150 reputation once; after the {item:14047} one, {quest:7796} pays 50 for every 20 {item:14047}, as often as you like. The Auction House is the quickest source of cloth. In Classic, quests pay full reputation while they are at most 5 levels below you, so do Elwynn (levels 1-10), {zone:1436} (10-18), Redridge (15-25) and {zone:1431} (20-30) while you level through them. After the donations come the level 52-58 quests of the {zone:1422} and the {zone:1428} (about 1,150), then the optional low-level hubs, best rate first: Northshire and the city errands (about 40 a minute at full value), the {area:717} (30), Eastvale and {area:87} (25). Every {faction:72} gain also gives a quarter as much to {zone:1455}, {zone:1457} and the Gnomeregan Exiles, except quests in the level 1-10 start areas. Legacy Diplomat adds up to 10% to every gain."] = "{npc:14722}为{faction:72}收取布料。箭头会指向他；他站在自己那栋楼的楼上。首次上交60个毛料、丝绸、魔纹布和{item:14047}各给150点声望一次；交过{item:14047}之后，{quest:7796}每交20个{item:14047}给50点，次数不限。拍卖行是布料最快的来源。经典版中，任务在你高于其不超过5级时给全额声望，所以在你升级经过时做艾尔文森林（1-10级）、{zone:1436}（10-18级）、赤脊山（15-25级）和{zone:1431}（20-30级）。捐献之后是{zone:1422}和{zone:1428}的52-58级任务（约1150），然后再是可选的低级据点，按效率从高到低：北郡和城内跑腿（满额时每分钟约40）、{area:717}（30）、东谷与{area:87}（25）。每次获得{faction:72}声望时，{zone:1455}、{zone:1457}和诺莫瑞根流亡者也会得到四分之一的量，1-10级新手区任务除外。传承外交官最多使每次收益增加10%。",
	["{npc:14722}, the cloth quartermaster"] = "{npc:14722}，布料军需官",
	["{npc:1748} holds court in {object:2117} with {npc:1749} at his side: speak with her for the second of his quests."] = "{npc:1748}在{object:2117}主持朝政，{npc:1749}在他身旁：与她交谈接取他的第二个任务。",
	["{npc:240} stands in front of the Lion's Pride Inn in {area:87}. The Lost Books drop from the kobolds of {area:57} south of {area:87}; the picture book and the two rare books from the named kobolds there."] = "{npc:240}站在{area:87}狮王之傲旅店前。失落的书由{area:87}以南{area:57}的狗头人掉落；图画书和两本稀有书来自那里的有名狗头人。",
	["{npc:279}, in the {object:2096}"] = "{npc:279}，在{object:2096}里",
	["{npc:344} waits in the town hall of {area:69}."] = "{npc:344}在{area:69}的市政厅等候。",
	["{npc:448} is an elite gnoll west of {area:120}; at 60 he is no trouble. The Wanted poster hangs on the garrison."] = "{npc:448}是{area:120}以西的精英豺狼人；60级时不成问题。通缉令挂在要塞上。",
	["{npc:80}, deep in {area:34}"] = "{npc:80}，{area:34}深处",
	["{npc:951}, back at the abbey"] = "{npc:951}，回到修道院",
	["{npc:9562} at {area:2418}, in the south-east of the {zone:1428}, starts {quest:4183}: a chain to {area:69} and {object:2117}, 175 {faction:72} and 175 {zone:1457} reputation (level 54: in Classic four fifths of it at 60). The Black Broodlings and the {npc:7044} live on the slopes north of the Vigil; the {npc:7040} and {npc:7041} west of it, in the middle of the zone."] = "{zone:1428}东南{area:2418}的{npc:9562}会开启{quest:4183}：一条通往{area:69}和{object:2117}的任务链，175点{faction:72}和175点{zone:1457}声望（54级任务：经典版中60级时为五分之四）。黑色雏龙和{npc:7044}住在守夜营地以北的山坡；{npc:7040}和{npc:7041}在其以西、区域中部。",
	["{object:175894}, in the farmhouse"] = "{object:175894}，在农舍里",
	["{object:563442}, east of the abbey"] = "{object:563442}，修道院以东",
	["{quest:4182}, +100 {zone:1457}"] = "{quest:4182}，+100{zone:1457}声望",
	["{quest:4183}, +75"] = "{quest:4183}，+75",
	["{quest:4183}, +75 {zone:1457}"] = "{quest:4183}，+75{zone:1457}声望",
	["{quest:4184}, +100"] = "{quest:4184}，+100",
	["{quest:5021}, +50"] = "{quest:5021}，+50",
	["{quest:5048}, +100"] = "{quest:5048}，+100",
	["{quest:5092}, +100"] = "{quest:5092}，+100",
	["{quest:5097}, +100"] = "{quest:5097}，+100",
	["{quest:5215}, +10"] = "{quest:5215}，+10",
	["{quest:5216}, +100"] = "{quest:5216}，+100",
	["{quest:5217}, +50"] = "{quest:5217}，+50",
	["{quest:5219}, +100"] = "{quest:5219}，+100",
	["{quest:5220}, +50"] = "{quest:5220}，+50",
	["{quest:5222}, +100"] = "{quest:5222}，+100",
	["{quest:5223}, +50"] = "{quest:5223}，+50",
	["{quest:5225}, +100"] = "{quest:5225}，+100",
	["{quest:5226}, +50"] = "{quest:5226}，+50",
	["{quest:7796} to Exalted"] = "{quest:7796}刷到崇拜",
	["{quest:7796} to Honored"] = "{quest:7796}刷到尊敬",
	["{quest:7796} to Revered"] = "{quest:7796}刷到崇敬",
	["{quest:7796}: 50 reputation for 20 {item:14047}, as often as you like. After the four first donations a non-Human stands at Friendly 700 of 6,000, so Honored is 5,300 away: 106 turn-ins, 2,120 {item:14047} (Humans start 900 higher: 88 turn-ins; a Skyborne's Exploring the Alliance paid 100, two fewer). The level 52-58 quests above take 23 turn-ins off; every Elwynn hub you did takes 20 to 30 more off if it paid in full. More quest hubs pay {faction:72}, in full while they are no more than 5 levels below you: {zone:1436} (about 2,500 in all), Redridge's {area:69} (about 3,000) and {zone:1431}'s {area:42} (about 2,900). Every city gain also gives a quarter as much to the other three Alliance cities (not counted here). Hand in all your {item:14047} at once."] = "{quest:7796}：每20个{item:14047}换50点声望，次数不限。四次首次捐献之后，非人类角色处于友善700/6000，所以距尊敬还差5300点：106次上交，2120个{item:14047}（人类起始高900点：88次上交；一位天裔的“探索联盟”给了100点，少两次）。上面的52-58级任务可抵掉23次；你每做一个艾尔文森林据点，若它全额给声望，还能再抵20到30次。还有更多据点给{faction:72}声望，在你高于其不超过5级时全额：{zone:1436}（共约2500）、赤脊山的{area:69}（约3000）和{zone:1431}的{area:42}（约2900）。每次城市声望收益还会给另外三座联盟城市四分之一的量（此处未计入）。把所有{item:14047}一次性上交。",
	["{quest:87} and the kelp"] = "{quest:87}与海藻",
}

G["forever/reputation/wintersaber-trainers"] = {
	["At Honored Rivern Frostwind adds {quest:5981}: 4 Frostmaul Giants and 4 Frostmaul Preservers, elite giants in {area:2249} in the south-east of {zone:1452}; the path down into the gorge starts at its north-west end. Take it on a trip south with a friend or two, or when {area:2244} is crowded; the {npc:7446} by the gorge drop {item:12622} most often. Honored to Exalted is 33,000: 660 turn-ins."] = "尊敬后，里文·霜风会追加{quest:5981}：4个霜槌巨人和4个霜槌守护者，都是{zone:1452}东南部{area:2249}里的精英巨人；下到峡谷的小路从它西北端开始。和一两个朋友南下时接，或者{area:2244}人多时接；峡谷旁的{npc:7446}最常掉{item:12622}。尊敬到崇拜是33,000点：660次上交。",
	["Back to {npc:10618}"] = "返回{npc:10618}",
	["Friendly to Honored"] = "友善到尊敬",
	["Friendly to Honored is 6,000: 120 turn-ins. {quest:5201} is the quickest; do {quest:4970} when the village is crowded or you pass the bears and chimaeras anyway. Every Winterfall furbolg you kill counts for {area:1769} too: 50 Timbermaw reputation per {quest:5201} up to the end of Honored with them, and about four {item:21383}. Take Salfa's Winterfall Activity (the Timbermaw guide) the first time you are in the village, and keep the beads until your Timbermaw kills stop counting: then each 5 pay 50. You will reach Exalted with the Timbermaw long before the {faction:589}."] = "友善到尊敬是6,000点：120次上交。{quest:5201}最快；村子人多或本来就要经过熊和奇美拉时做{quest:4970}。你杀的每个冬泉熊怪也计入{area:1769}：每完成一次{quest:5201}给50点木喉声望，直到与他们尊敬满，还能拿到约四个{item:21383}。第一次到村子时就接萨尔法的“冬泉活动”（木喉攻略里有），把念珠留着，直到你的木喉击杀不再计数：之后每5个给50点。你会远早于{faction:589}达到木喉崇拜。",
	["Frostmaul Giant"] = "霜槌巨人",
	["Frostmaul Preserver"] = "霜槌守护者",
	["Honored to Exalted: {quest:5981} too"] = "尊敬到崇拜：也要做{quest:5981}",
	["Neutral to Friendly: {quest:4970}, then {quest:5201}"] = "中立到友善：先做{quest:4970}，再做{quest:5201}",
	["Repeat {quest:4970}: 30 turn-ins reach Neutral 1,500, and then {quest:5201} opens: 5 Winterfall Shamans and 5 Winterfall Ursas in {area:2244}, just east of {area:2255}. The village has only a few Shamans, but every furbolg there shares their spawn points: kill all of them, not just the ones you need, and more Shamans and Ursas appear; more Ursas walk the ridge just south-west of the village. Take both quests on every trip: kill the furbolgs, pick up meat on the way back. Neutral to Friendly is 60 turn-ins."] = "重复{quest:4970}：30次上交达到中立1,500，然后{quest:5201}开放：5个冬泉萨满祭司和5个冬泉巨熊，在{area:2255}正东的{area:2244}。村子里只有几个萨满，但那里每个熊怪共享刷新点：把全部杀掉，而不只是你要的那些，就会有更多萨满和巨熊出现；村子西南的山脊上还有更多巨熊在走动。每次来都接这两个任务：杀熊怪，返程时捡肉。中立到友善是60次上交。",
	["Reputation · World"] = "声望 · 世界",
	["Shardtooth and Chillwind meat"] = "碎齿熊与寒风奇美拉的肉",
	["The meat only drops while the quest is in your log, and a group shares no loot: farm it alone. The best droppers live right below the rock: {npc:7445} bears (about half the time) and Chillwind Ravagers (half the time) roam the snowfields east and south-east of it. Around {area:2255} the Chillwind Chimaeras drop it as often and the Shardtooth Bears a little less; the {npc:7446} by the giants' gorge in the south drop it most often (six in ten)."] = "这个肉只在你任务日志里有该任务时才会掉落，而且队伍不共享拾取：独自去刷。最好的掉落者就在岩石下方：{npc:7445}熊（约一半概率）和寒风掠夺者（一半概率）在它东边和东南的雪原上游荡。{area:2255}附近，寒风奇美拉掉率相同，碎齿熊稍低；南边巨人峡谷旁的{npc:7446}掉得最勤（十次有六次）。",
	["The {spell:17229}: 840 quest turn-ins in {zone:1452}, with Timbermaw reputation on the side."] = "{spell:17229}：在{zone:1452}做840次任务上交，顺带还有木喉声望。",
	["Winterfall Shaman"] = "冬泉萨满祭司",
	["Winterfall Ursa"] = "冬泉巨熊",
	["Wintersaber Trainers Reputation"] = "冬刃豹训练师声望",
	["{area:1769} reputation on the side: 50 and about 4 {item:21383} per {quest:5201}"] = "{area:1769}声望顺带获得：每完成一次{quest:5201}给50点，外加约4个{item:21383}",
	["{item:12622}: the bears"] = "{item:12622}：熊",
	["{item:12623}: the chimaeras"] = "{item:12623}：奇美拉",
	["{npc:10618} stands on top of {area:2241}, in the far north of {zone:1452}; the path winds up from the east side. Only the Alliance can earn the {faction:589}' favour, from Neutral, at level 58. All three of her quests pay 50 and repeat as often as you like: 840 turn-ins from Neutral to Exalted. The first one, {quest:4970}, is the only one open at the start."] = "{npc:10618}站在{area:2241}顶上，位于{zone:1452}最北端；小路从东侧蜿蜒而上。只有联盟能获得{faction:589}的好感，从中立开始，需要58级。她的三个任务都各给50点，且可无限重复：从中立到崇拜需840次上交。第一个任务{quest:4970}是开局唯一可接的。",
	["{npc:7428}, elite"] = "{npc:7428}，精英",
	["{npc:7429}, elite"] = "{npc:7429}，精英",
}

