G["forever/alliance/03-darkshore-return"] = {
	["Back to {npc:11802} in {area:2361}, then {npc:11800} there flies Druids straight to {area:702}. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "回到{area:2361}的{npc:11802}处，再找那里的{npc:11800}，他能直接把德鲁伊送到{area:702}。{npc:11802}在他那栋楼的楼上：从里面上楼，箭头分不清楼层。",
	["Cast {spell:18960}"] = "施放{spell:18960}",
	["Cast {spell:18960}. {npc:11802} stands upstairs in his building in {area:2361}: go up inside, the arrow cannot tell the floors apart. Learn the flight path there if you do not have it."] = "施放{spell:18960}。{npc:11802}站在{area:2361}他所在建筑的楼上：从里面上楼，箭头分不清楼层。如果还没有那里的飞行点，顺便开了。",
	["Follow the coast north-east to the {area:443}. {quest:951} lie among the ruins; Stormscale Myrmidons, Sorceresses and Warriors hold them, and Stormscale Beastmistresses walk the shore."] = "沿海岸向东北到{area:443}。{quest:951}散落在废墟中；雷鳞侍从、雷鳞巫师和雷鳞战士占据着那里，雷鳞兽王在岸边巡逻。",
	["Murkdeep"] = "深泥",
	["Night Elves fly from {area:442} to {area:702}; Skyborne take the boat from the {area:442} dock and learn the Rut'theran flight path there. Take the portal up to {npc:4217} in the {area:1658}."] = "暗夜精灵从{area:442}飞往{area:702}；天裔乘{area:442}码头的船前往，并在那里学习鲁瑟兰村的飞行路线。乘传送门上去找{area:1658}的{npc:4217}。",
	["On the way"] = "顺路",
	["Sickly Deer"] = "病弱鹿",
	["Stormscale Myrmidon"] = "雷鳞迈尔米顿",
	["Stormscale Sorceress"] = "雷鳞女巫",
	["Stormscale Warrior"] = "雷鳞战士",
	["The {area:443}"] = "{area:443}",
	["The {quest:952}"] = "{quest:952}",
	["Underwater"] = "水下",
	["{area:442} flight master"] = "{area:442}飞行管理员",
	["{area:450} lies on the coast south of {npc:10323}'s beach. Protect the prospector while he searches for the fossil.\nCareful: Ambushers appear as he passes certain spots: a scout comes out from under the board ramp, and more scouts come out when he checks the tent."] = "{area:450}位于{npc:10323}海滩以南的海岸上。在勘探者寻找化石时保护他。\n注意：他经过某些地点时会出现伏击者：经过木板坡道下方时会钻出一名斥候，他检查帐篷时还会钻出更多斥候。",
	["{area:452}: kill these as you meet them"] = "{area:452}：遇到就杀",
	["{npc:11802} stands upstairs in his building in {area:2361}: go up inside, the arrow cannot tell the floors apart."] = "{npc:11802}站在{area:2361}他那栋楼的楼上：从里面上楼，箭头分不清楼层。",
	["{npc:3692}, inside {area:455}"] = "{npc:3692}，{area:455}内",
	["{quest:948} is the ancient at the Grove; {npc:270269} and {npc:11218} sleep beside him."] = "{quest:948}是树林中的上古者；{npc:270269}和{npc:11218}睡在他身旁。",
	["{quest:98394} (Night Elves) and the {npc:272054} (Skyborne) wait in southern {area:493}. The three relics lie in the {area:2363}, east of them. Reports from the first weeks say a relic gives no loot while another player is looting it: wait a moment and try again."] = "{quest:98394}（暗夜精灵）和{npc:272054}（天裔）在{area:493}南部等候。三件遗物在它们东边的{area:2363}里。最初几周的报告称：其他玩家正在拾取某件遗物时，你拾取不到东西：稍等片刻再试。",
}

