G["forever/alliance/02-westfall"] = {
	["Defias Pillagers and Looters hold the farms west of {area:108}, between the coast road and {area:20}. {object:1166} stands in the farmhouse at the {area:219}, among them: {npc:1646}' compass is inside.\nCareful: The {area:113} cave holds many Defias packed together, so it is easy to pull several at once there."] = "迪菲亚掠夺者和抢劫者占据{area:108}以西的农场，位于海岸道路和{area:20}之间。{object:1166}立在{area:219}的农舍里，就混在他们当中：{npc:1646}的指南针在里面。\n小心：{area:113}的洞穴里挤满了迪菲亚，在那里很容易一次拉来好几只。",
	["Defias Trappers and Smugglers camp in the fields between {area:108} and {area:918}.\nWest of Saldean's. Harvest Watchers and Golems work the fields; they drop the isosprings, gyrostabilizers, {item:732} and sometimes a {item:255155}. {npc:573}, a level 20 rare, walks here: leave it alone.\nYoung Goretusks and Fleshrippers roam every leg of this loop: their livers and meat are for the pie and the stew."] = "迪菲亚捕兽者和走私者扎营在{area:108}和{area:918}之间的田地里。\n萨尔丁农场以西。收割守望者和傀儡在田里干活；它们掉落等距弹簧、陀螺稳定器、{item:732}，偶尔还有{item:255155}。{npc:573}，一只20级稀有，在这里走动：别惹它。\n幼年血牙野猪和撕肉者游荡在这段环路的每一程：它们的肝和肉用来做馅饼和炖菜。",
	["East along the road past {area:18}: {npc:248242} and {npc:248248} stand at the foot of the tower."] = "沿路向东经过{area:18}：{npc:248242}和{npc:248248}站在塔脚下。",
	["East along the road, then into the river south of the bridge: the {item:247813}, Axe and Toolbox lie in it. Prowlers and Young Forest Bears roam its banks."] = "沿路向东，然后下到桥南的河里：{item:247813}、斧头和工具箱都躺在里面。徘徊者和幼年森林熊在河岸上游荡。",
	["Follow the road west to {area:87}, on the way to {area:40}: {npc:240} stands outside the inn."] = "沿路向西前往{area:87}，这里位于通往{area:40}的路上：{npc:240}站在旅店外。",
	["From {area:40}, walk to {zone:1453}; the tram from {zone:1455} arrives in the {object:28027}. {npc:5480} trains warriors in {object:2100}; {npc:6089} and {npc:6090} stand together by the {object:2152} there. {npc:6090} fights you for his mug. If {npc:5480} doesn't offer {quest:1638}, go straight to {npc:6089}: he gives {quest:1639} without it."] = "从{area:40}步行到{zone:1453}；从{zone:1455}开来的地铁到达{object:28027}。{npc:5480}在{object:2100}训练战士；{npc:6089}和{npc:6090}一起站在那里的{object:2152}旁。{npc:6090}会为了他的杯子和你打一架。如果{npc:5480}不提供{quest:1638}，就直接去找{npc:6089}：不用它也会给你{quest:1639}。",
	["On the road from {zone:1453} to {area:40}, {area:87} is the first stop: {npc:241} stands outside the inn, {npc:240} beside him. {npc:241}'s {quest:40} goes straight to Dughan, who then gives {quest:35}; his {quest:109} goes with you to {area:40}."] = "在从{zone:1453}到{area:40}的路上，{area:87}是第一站：{npc:241}站在旅店外，{npc:240}在他旁边。{npc:241}的{quest:40}直接交给杜汉，他随后给你{quest:35}；他的{quest:109}则随你带到{area:40}。",
	["Riverpaw Gnolls and Scouts (level 11-13) roam the hills south of the coast, from above {area:111} east to the {area:916}. The gnolls further south and west are 13-19: stay in the north hills.\nMurloc Coastrunners and Raiders line the beach north of the mine. They flee at low health: pull one at a time.\nCareful: Gnolls that stand close together tend to join a fight as a group. Pulling one at a time is safer.\nCareful: {object:290} stands in the ruined house east of the mine, on the way to the {area:916}. Two Defias stand guard inside, one of them the level 15 named {npc:502}. They are linked, so attacking either one brings both."] = "河爪豺狼人和斥候（11-13级）在海岸以南的丘陵游荡，从{area:111}上方一直到东边的{area:916}。更南边和西边的豺狼人是13-19级：留在北边丘陵。\n鱼人海岸行者和鱼人袭击者分布在矿洞以北的海滩上。它们低血量时会逃跑：一只一只地拉。\n小心：站得很近的豺狼人容易成群加入战斗。一只一只地拉更安全。\n小心：{object:290}立在矿洞以东的破屋里，就在通往{area:916}的路上。屋内有两名迪菲亚守卫，其中一只是15级有名怪物{npc:502}。它们相互联动，攻击任意一只都会引来两只。",
	["The {area:54}'s entrance"] = "{area:54}的入口",
	["Young Goretusks root in the fields along the road south from Saldean's to {area:108}: take their snouts on the way."] = "幼年血牙野猪在从萨尔丁农场沿路向南到{area:108}的田地里拱食：顺路取走它们的猪鼻。",
	["{area:108}'s tower and {npc:523}"] = "{area:108}的塔楼和{npc:523}",
	["{npc:1323}, {object:2156} in {object:2100}"] = "{npc:1323}，{object:2100}里的{object:2156}",
	["{npc:1646}, {object:2098}: his compass is in his old house in {area:40}"] = "{npc:1646}，{object:2098}：他的指南针在{area:40}的老房子里",
	["{npc:234} and {npc:821} stand at the top of the stone tower, {npc:491} inside it, {npc:523} the gryphon master on the south side of the hill with {npc:878} beside him. {npc:523} gives you Lewis' note for {npc:1323} with a free flight to {zone:1453}: take it now. In {zone:1453}, {npc:279}'s shop is in the {object:2096} by the gryphons, {npc:1323}'s shop, {object:2156}, in {object:2100}; {npc:1646} stands in {object:2098} on the way back to {npc:352}, the gryphon master."] = "{npc:234}和{npc:821}站在石塔顶，{npc:491}在塔里，狮鹫管理员{npc:523}在山的南侧，{npc:878}在他旁边。{npc:523}把刘易斯给{npc:1323}的字条交给你，并附带一次飞往{zone:1453}的免费飞行：马上乘坐。在{zone:1453}，{npc:279}的商店在狮鹫旁的{object:2096}里，{npc:1323}的商店{object:2156}在{object:2100}里；{npc:1646}站在{object:2098}里，就在回狮鹫管理员{npc:352}的路上。",
	["{npc:234}: from {npc:963} at Westbrook"] = "{npc:234}：来自西泉要塞的{npc:963}",
	["{npc:261} guards the bridge on the road east; {npc:248265} stands just across it. His tools and Thomas's Prowlers and bears are south of the bridge, on the way back."] = "{npc:261}守卫着向东道路上的桥；{npc:248265}就站在桥对面。他的工具和托马斯的徘徊者与熊都在桥南，在返回的路上。",
	["{npc:279}, {object:2096}, by the gryphons"] = "{npc:279}，狮鹫旁的{object:2096}",
	["{npc:491}, inside: back from {zone:1453}"] = "{npc:491}，在里面：从{zone:1453}回来后",
	["{npc:523}: the free flight he offers goes to {zone:1453}"] = "{npc:523}：他提供的免费飞行飞往{zone:1453}",
	["{npc:7232}, {object:28027}: for his brother in {area:442}"] = "{npc:7232}，{object:28027}：为了他在{area:442}的兄弟",
	["{quest:153}: every Defias drops them, from {area:111} to the {area:916}"] = "{quest:153}：每个迪菲亚都会掉落，从{area:111}到{area:916}",
}

G["forever/alliance/03-darkshore"] = {
	["East of Buzzbox 323, {npc:3661} hides at the foot of the tower among the Dark Strand Fanatics. Keep his letter for Delgren in {zone:1440}."] = "在蜂鸣箱323以东，{npc:3661}躲在塔脚下，混在暗滩狂热者中间。保留他的信，交给{zone:1440}的净化者德尔格伦。",
	["Fishers only: {npc:10216} stands on the pier. His {item:12238} is fished from the pier itself."] = "仅限钓鱼者：{npc:10216}站在码头上。他的{item:12238}就从这座码头上钓上来。",
	["For {quest:948} at the Grove, on {zone:1439}'s southern loop after the trip east"] = "古树之林的{quest:948}：向东那一趟之后，在{zone:1439}的南环线上",
	["The boat docks west of the village: {npc:3644} waits where the pier meets the shore. Go up to {npc:3649} at the north end of the village first, then down the main street to the inn. The flight master stands on the hill south of the inn. {npc:3666} stands upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart."] = "船停靠在村子西边：{npc:3644}在码头与岸边相接处等着。先到村子北端找{npc:3649}，再沿主街往南到旅店。飞行管理员站在旅店南边的山丘上。{npc:3666}站在旅店楼上：从里面上楼梯，箭头分不清楼层。",
}

G["forever/alliance/03-darkshore-return"] = {
	["From the dock, up to the north end of the village first ({npc:3702} by the moonwell, {npc:2913}), then down the main street: the WANTED poster outside the inn, {npc:3693} at its east end, where the road leaves south."] = "从码头先上到村子北端（{npc:3702}在月井旁，{npc:2913}），再沿主街往南：旅店外的通缉令，{npc:3693}在街的东端，也就是道路向南出村的地方。",
	["His walk ends at the road, where Grimclaw waits"] = "他的巡视在道路处结束，怒爪在那里等候",
	["On the way north to {area:442}, the last {quest:4728} lies on the shore west of the Grove."] = "在向北去{area:442}的路上，最后一个{quest:4728}在古树之林以西的岸边。",
	["Take the portal up to {npc:4217}, then fly back to {area:442} for the road south to {zone:1440}."] = "乘传送门上去找{npc:4217}，然后飞回{area:442}，走南边的道路前往{zone:1440}。",
	["The Lunar Fungal Blooms grow in the moonkin caves in the hills just east of {area:442}; the moonkin there are irritable. {item:2449} needs {skill:182}: herbalists pick it all over {zone:1439}, anyone else brings it from {zone:1453} ({npc:1313}) or the Auction House."] = "月光菌菇生长在{area:442}东边山丘上的枭兽洞穴里；那里的枭兽很暴躁。{item:2449}需要{skill:182}：草药师在{zone:1439}各处都能采到，其他人从{zone:1453}（{npc:1313}）或拍卖行带来。",
	["The shore west of the Grove"] = "古树之林以西的岸边",
	["{npc:10323} camps on the beach west of the glaive: kill the murlocs at the camp fire; he comes in the third wave with his hound. Four beached remains lie on the beaches west and south-west of {area:450}: take them on the way north to his camp."] = "{npc:10323}在主宰之剑西边的海滩上扎营：击杀营火旁的鱼人；他会在第三波带着猎犬出现。{area:450}西边和西南边的海滩上有四具搁浅的遗骸：向北去他营地时顺路取走。",
	["{npc:3692} hides in the hills east of the {area:449}. Help him back to the road; he fights on his way out. {npc:3693} takes the escort in {area:442} on the next visit there."] = "{npc:3692}躲在{area:449}东边的山丘上。帮他回到道路上；他会一路战斗出去。{npc:3693}会在下次去{area:442}时接下护送任务。",
	["{npc:3694}: for {npc:3691} in {area:415}, in the next guide"] = "{npc:3694}：为{area:415}的{npc:3691}，下一份指南",
}

G["forever/alliance/03-loch-modan"] = {
	["12 minutes"] = "12分钟",
	["Back down into town: {npc:415} by the smithy, {npc:341} at the north end of the bridge, {npc:381} on the docks."] = "往回下到镇里：{npc:415}在铁匠铺旁，{npc:341}在桥的北端，{npc:381}在码头上。",
	["Back north to {npc:234} and the gryphons."] = "往北回到{npc:234}和狮鹫那里。",
	["Back north up the road to {area:108}. {npc:467} waits at the foot of the tower ramp; if he is missing, someone is escorting him and he is back within minutes."] = "沿路往北回到{area:108}。{npc:467}在塔楼斜坡脚下等着；如果他不在，就是有人正在护送他，几分钟内就会回来。",
	["Back to {area:442} for {zone:1439}'s southern loops: the gryphon to {zone:1453}, then the boat from the harbour."] = "回到{area:442}走{zone:1439}的南环线：先坐狮鹫到{zone:1453}，再从港口乘船。",
	["Back toward town, swim east from the bridge into {area:68}; the chest lies on the lake bed beside a sunken boat. Murloc Flesheaters and Tidecallers line the south shore around it: any of them can carry a {item:1467}."] = "往回朝镇子方向，从桥处向东游进{area:68}；箱子躺在沉船旁的湖底。鱼人食肉者和鱼人唤潮者分布在它周围的南岸：任意一只都可能带着{item:1467}。",
	["Back west along the south shore to {area:144}: {npc:1105} by the inn, then {npc:1572} with the gryphons on the west side of town, on the way south."] = "沿南岸往西回到{area:144}：{npc:1105}在旅店旁，再往南走时顺路到镇子西边的狮鹫旁找{npc:1572}。",
	["Chief Engineer Hinderweir stands on top of the dam, up the ramp at its west end."] = "总工程师辛德韦尔站在大坝顶上，从大坝西端的坡道上去。",
	["Cross the long bridge north into town: {npc:8965} and {npc:8962} play by the shore at its north end, {npc:341} and {npc:382} stand there too, {npc:415} by the smithy, {npc:344} in the town hall, {npc:381} on the docks, {npc:266} upstairs in the inn and {npc:379} and {npc:343} inside it."] = "向北过长桥进入镇子：{npc:8965}和{npc:8962}在桥北端的岸边玩耍，{npc:341}和{npc:382}也站在那里，{npc:415}在铁匠铺旁，{npc:344}在市政厅，{npc:381}在码头上，{npc:266}在旅店楼上，{npc:379}和{npc:343}在店里。",
	["Down the road to {area:108}. {npc:234} stands at the top of the stone tower."] = "沿路往下走到{area:108}。{npc:234}站在石塔顶。",
	["East along the hills to the mine: the Miners' League crates sit in its tunnels among the Tunnel Rat kobolds."] = "沿山丘向东到矿洞：矿工联盟的箱子放在坑道里，混在隧道鼠狗头人中间。",
	["East along the road to the gryphon master; {npc:1070} stands beside her."] = "沿路向东走到狮鹫管理员处；{npc:1070}站在她旁边。",
	["Elder Mountain Boar"] = "老山地野猪",
	["Elder Mountain Boars and {npc:270693}"] = "老山地野猪和{npc:270693}",
	["Follow the road along the south shore of {area:68} to the gryphon master. {npc:1070} stands by the road next to her."] = "沿{area:68}南岸的道路走到狮鹫管理员处。{npc:1070}站在她旁边的路边。",
	["Follow the road east out of Menethil and south through the {area:836} pass. Keep to the road: the {zone:1437} crocolisks and raptors beside it are over your level."] = "沿路向东出米奈希尔，再向南穿过{area:836}山口。沿路走：路边的{zone:1437}鳄鱼和迅猛龙等级比你高。",
	["For {npc:1356} in {zone:1455}"] = "为{zone:1455}的{npc:1356}",
	["For {npc:332} in {zone:1453}"] = "为{zone:1453}的{npc:332}",
	["From level 20 {npc:381} gives {quest:150}: take it now if he offers it (otherwise on the last {area:69} stop). Its murlocs are for your next Redridge visit, at about 24."] = "20级起{npc:381}给{quest:150}：如果他提供就现在接（否则等最后一站到{area:69}时再接）。其中的鱼人留到你约24级下次去赤脊山时再做。",
	["From the gryphons, over the bridge into town: {npc:415} by the smithy, {npc:344} in the town hall."] = "从狮鹫处过桥进镇：{npc:415}在铁匠铺旁，{npc:344}在市政厅。",
	["From the tram, leave {zone:1453} by the main gate and follow the road through {area:87} and east through Elwynn to Redridge."] = "从地铁出来，走大门离开{zone:1453}，沿路穿过{area:87}，再向东穿过艾尔文森林到赤脊山。",
	["Headsplitter"] = "劈头者",
	["Its pikes and rivets come from the gnolls north of the lake, on the loop after {area:40}"] = "它的长矛和铆钉来自湖以北的豺狼人，在{area:40}之后的环线上",
	["Mountain Buzzard"] = "山地秃鹫",
	["Mountain Buzzards"] = "山地秃鹫",
	["Mountain Buzzards circle the hills west and south of the lodge, back toward the dig. {quest:257} runs for 15 minutes."] = "山地秃鹫在旅舍以西和以南的山丘上空盘旋，一直往挖掘场方向。{quest:257}持续15分钟。",
	["North-east to the lodge on the hill. {npc:1154} stands inside, {npc:1187} outside."] = "往东北到山上的旅舍。{npc:1154}在里面，{npc:1187}在外面。",
	["Off the boat, walk up the pier to the flight master by the inn. Nothing to take here yet: Menethil's quests are for your {zone:1437} visit at about 22."] = "下船后沿码头上到旅店旁的飞行管理员处。这里暂时没什么可接的：米奈希尔的任务留到你约22级去{zone:1437}时再做。",
	["Redridge Brute"] = "赤脊蛮兵",
	["Redridge Brutes and Mystics hold the hills north and north-west of town; both carry the Iron Pikes and Rivets. Black Dragon Whelps nest in the same hills.\nCareful: The whelps cast {spell:133} from range, and the gnolls run for help at low health."] = "赤脊蛮兵和赤脊秘法师占据镇子以北和西北的丘陵；两者都带着铁矛和铆钉。黑龙幼崽也窝在同一片丘陵里。\n小心：幼崽会远程施放{spell:133}，豺狼人低血量时会跑去求援。",
	["Redridge Mongrels and Thrashers hold the hills east of {area:1002}, north of the road; Poachers camp south of the road. Great Goretusks root around the same hills and Dire Condors circle south of the lake; Tarantulas crawl round {area:1002}."] = "赤脊杂种和赤脊鞭笞者占据{area:1002}以东、道路以北的丘陵；偷猎者在道路以南扎营。巨型血牙野猪在同一片丘陵里拱食，恐怖秃鹫在湖以南盘旋；狼蛛在{area:1002}周围爬来爬去。",
	["Redridge Mystic"] = "赤脊秘法师",
	["Round the south end of the loch and head east to the dig. {npc:1345} and {npc:1344} stand together at its west edge."] = "绕过湖的南端，向东前往挖掘场。{npc:1345}和{npc:1344}一起站在挖掘场西缘。",
	["Sell and repair in {area:442} first: the next stretch is a long one."] = "先在{area:442}卖东西和修理装备：下一段路很长。",
	["South along the road to {area:20}. The {npc:550} starts in front of the {area:20} smithy and walks north to the {area:113} and the back of the {area:111}, then back: look along his road. Slow him when he runs at 30% health."] = "沿路向南到{area:20}。{npc:550}从{area:20}的铁匠铺前出发，向北走到{area:113}和{area:111}的后方，再折返：沿着他走的这条路找。他在30%血量会逃跑，届时减速他。",
	["South along the west shore. A {object:665289} lies on the loch bed east of {area:144} (it moves between several spots): open it for the {item:278051}, which starts the quest."] = "沿西岸向南。{area:144}以东的湖底有一个{object:665289}（它会在几个位置间移动）：打开它取得{item:278051}，用它开启任务。",
	["South of Thelsamar, Ylva lies dead in the mouth of a trogg cave. Take her banner, raise it beside her and hold the spot: troggs come in waves from both sides, then {npc:269185}."] = "塞尔萨玛以南，伊尔瓦死在一个穴居人洞穴的洞口。拿起她的旗帜，在她身旁竖起并守住这块地方：穴居人会从两侧一波波涌来，之后{npc:269185}登场。",
	["South-west from {area:20} to the lighthouse on the point: {npc:392} waits on its steps. {npc:391} walks the beach and the shallows north-east of it among the murlocs: pull him away from the Oracles."] = "从{area:20}往西南到海角上的灯塔：{npc:392}在灯塔台阶上等着。{npc:391}在它东北边的海滩和浅滩间游荡，混在鱼人里：把他从神谕者身边引开。",
	["Stay with the traitor as he walks south to {area:20}; he does not stop for fights, so clear what follows him. His walk ends at the Defias hideout below {area:20}."] = "跟着叛徒往南走到{area:20}；他不会停下来打架，所以要清掉追在他身后的怪。他的路线终点是{area:20}下方的迪菲亚藏身处。",
	["Stonesplinter Diggers, Geomancers and Berserk Troggs hold the dig east of Ironband; any of them can drop a {item:2636}. Piles of Excavation Tools lie around the dig: open one and right-click the tools to start {quest:86613}, then gather six.\nCareful: Berserk Troggs (19-20) enrage below 40% health."] = "石腭挖掘者、石腭地卜师和狂暴穴居人占据着铁环以东的挖掘场；任意一只都可能掉落{item:2636}。挖掘场周围散落着成堆的挖掘工具：打开一堆并右键点击工具即可开启{quest:86613}，然后收集六个。\n小心：狂暴穴居人（19-20级）在血量低于40%时会狂暴。",
	["The Elder Mountain Boars roam the hills north-west of the lodge, along the east shore. {npc:270693}, a crocolisk, patrols the shore below them. {quest:258} runs for 12 minutes."] = "老山地野猪在旅舍西北、沿东岸的丘陵游荡。{npc:270693}是一只鳄鱼，在它们下方的岸边巡逻。{quest:258}持续12分钟。",
	["The dig site"] = "挖掘场",
	["The loch"] = "湖",
	["The road crosses into Redridge at {area:1002}. {npc:464} walks around the crossroads."] = "道路在{area:1002}处进入赤脊山。{npc:464}在十字路口一带走动。",
	["The tunnel post"] = "隧道岗哨",
	["The {npc:550}"] = "{npc:550}",
	["Then west under the bridge: a {object:154357} mound on the lake bed beside town holds the necklace. Only one mound shows at a time, anywhere from under the dock to past the bridge."] = "然后在桥下往西：镇子旁湖底的一个{object:154357}土堆里放着项链。一次只出现一个土堆，位置从码头下方到桥的另一头都有可能。",
	["Through the South Gate tunnel and west along the road to {zone:1455}."] = "穿过南门隧道，沿路向西到{zone:1455}。",
	["Through town east to west: {npc:8962} and {npc:341} at the north end of the bridge, {npc:381} on the docks, then {npc:342}'s garden at the west end; {npc:379} and {npc:343} are in the inn."] = "从东到西穿过镇子：{npc:8962}和{npc:341}在桥的北端，{npc:381}在码头上，然后是西端{npc:342}的菜园；{npc:379}和{npc:343}在旅店里。",
	["Walk east along the dam, down its eastern ramp, then back west along the foot of the dam on the land side: two Dark Iron Sappers guard the barrel. Kill them, then open the barrel: it ends this quest and starts the next."] = "沿大坝往东走，下东端的坡道，再沿大坝靠陆地一侧的坝脚往西：两名黑铁工兵守着桶。杀掉他们，然后打开桶：这会结束当前任务并开启下一个。",
	["West along the road to {area:1002} first; the gnolls are on the way back east."] = "先沿路向西到{area:1002}；豺狼人留到往东返回时再打。",
	["West out of Redridge by {area:1002} and along the road through Elwynn to {area:87}."] = "经{area:1002}向西出赤脊山，沿路穿过艾尔文森林到{area:87}。",
	["West through Westbrook into {area:40}."] = "向西穿过西泉要塞进入{area:40}。",
	["West to the dwarven post at the tunnel to {zone:1426}."] = "向西到通往{zone:1426}的隧道旁的矮人岗哨。",
	["{item:1081}: Tarantulas"] = "{item:1081}：狼蛛",
	["{item:1221}: Black Dragon Whelps"] = "{item:1221}：黑龙幼崽",
	["{item:1381}: the {npc:550}"] = "{item:1381}：在{npc:550}身上",
	["{item:2640}, from the crates; below ground"] = "{item:2640}，出自箱子；在地下",
	["{npc:1187}: 15 minutes"] = "{npc:1187}：15分钟",
	["{npc:1343} stands at the {area:925}, at the south end of the pass."] = "{npc:1343}站在{area:925}，位于山口南端。",
	["{npc:1573} keeps the gryphons in the {object:32372}; {npc:1356} is in the {object:32356}, north-east of it, on the way to the tram in {object:171524}."] = "{npc:1573}在{object:32372}里照看狮鹫；{npc:1356}在{object:32356}里，位于其东北，在去{object:171524}坐地铁的路上。",
	["{npc:1684} stands on the shore north-east of town, {npc:1105} by the inn."] = "{npc:1684}站在镇子东北方的岸边，{npc:1105}在旅店旁。",
	["{npc:261} guards the bridge on this road east, past the {area:91}: {npc:240}'s {quest:35}, from your walk through {area:87}, goes to him."] = "{npc:261}守着这条向东道路上的桥，在过了{area:91}的地方：你穿过{area:87}时从{npc:240}接到的{quest:35}要交给他。",
	["{npc:261}, on the bridge"] = "{npc:261}，在桥上",
	["{npc:266}, in the inn; upstairs"] = "{npc:266}，在旅店；楼上",
	["{npc:332} is upstairs in the SI:7 building in {object:2100}: the stairs are hard to see at first. {npc:466} sits on his horse at the far end of the bridge outside the main gate, then back to the gryphons in the {object:2096}."] = "{npc:332}在{object:2100}里军情七处大楼的楼上：楼梯一开始不容易看见。{npc:466}骑着马待在大门外桥的另一头，然后回{object:2096}的狮鹫那里。",
	["{npc:332}, SI:7; upstairs"] = "{npc:332}，军情七处；楼上",
	["{npc:341}: {quest:98386}, for your next Redridge visit"] = "{npc:341}：{quest:98386}，留到下次去赤脊山",
	["{npc:344}, in the town hall: for {npc:466} in {zone:1453}"] = "{npc:344}，在市政厅：交给{zone:1453}的{npc:466}",
	["{npc:381}, on the docks"] = "{npc:381}，在码头上",
	["{npc:381}, on the docks: the murlocs are for your next Redridge visit"] = "{npc:381}，在码头上：鱼人留到下次去赤脊山时再打",
	["{npc:382}: the Blackrock camps are for your next Redridge visit, at about 24"] = "{npc:382}：黑石营地留到你约24级下次去赤脊山时",
	["{npc:466}, outside the main gate"] = "{npc:466}，在大门外",
	["{npc:467}, at the foot of the tower ramp"] = "{npc:467}，在塔楼斜坡脚下",
	["{npc:514} works at the {area:87} smithy."] = "{npc:514}在{area:87}的铁匠铺干活。",
	["{quest:86613}: open a pile at the dig"] = "{quest:86613}：在挖掘场打开一堆工具",
}

G["forever/alliance/04-redridge-mountains"] = {
	["Back east through town from {npc:342}'s garden: two Wanted posters hang on the town hall doorway."] = "从{npc:342}的花园向东穿回镇上：市政厅门口挂着两张通缉布告。",
	["Back north along the road from {area:42} to {area:1002}."] = "沿路向北，从{area:42}回到{area:1002}。",
	["Continue west to {quest:163}. The {object:673515} glows by the ruined house south of the road; {npc:288} hides in the house at the west end of the village."] = "继续向西到{quest:163}。{object:673515}在道路南边的废弃房屋旁发光；{npc:288}藏在村子西端的房子里。",
	["Cross the long bridge north into town: {npc:381} on the docks, {npc:900} in the town hall, the innkeeper in the inn, {npc:342} in her garden at the west end. {npc:382}'s Blackrock quests and {quest:98386} came with you from your first Redridge visit."] = "向北过长桥进镇：{npc:381}在码头，{npc:900}在市政厅，旅店老板在旅店里，{npc:342}在西端她的花园里。{npc:382}的黑石任务和{quest:98386}是你第一次来赤脊山时带过来的。",
	["Fly to {area:108} and head north-west to the coast: the {object:177790} lies on the sea floor off the shore. Then head east along the road through Elwynn."] = "飞往{area:108}，向西北前往海岸：{object:177790}躺在近海的海底。然后沿路向东穿过艾尔文森林。",
	["Follow the road along the south shore of {area:68} to the gryphon master. {npc:903} stands by the road next to her."] = "沿{area:68}南岸的道路走到狮鹫管理员处。{npc:903}站在她旁边的路边。",
	["Follow the road south from {area:1002} into {area:10}; {area:42} lies on the east side of the forest.\nNo {item:4371} for {quest:174}? {npc:3133} sells it in the house beside {npc:276}, in limited stock; {npc:1448} in {area:150} sells it too.\n{npc:276}'s house stands at the east end of town. {npc:3133} sells engineering goods in the house beside it."] = "沿路向南从{area:1002}进入{area:10}；{area:42}在森林东侧。\n没有{item:4371}做{quest:174}？{npc:3133}在{npc:276}旁的房子里出售，存货有限；{area:150}的{npc:1448}也卖。\n{npc:276}的房子在小镇东端。{npc:3133}在它旁边的房子里卖工程学商品。",
	["From the keep head back west along the lake's north shore and north up the {area:95} to {area:997}; {area:69}'s hand-ins wait for Keeshan's escort, which ends there. Blackrock Champions camp in the valley."] = "从要塞沿湖北岸向西折回，再向北沿{area:95}上行到{area:997}；{area:69}的待交任务要等基沙恩的护送，护送就在那里结束。黑石勇士在山谷里扎营。",
	["Gar'im keeps to the cave at the camps' south end with his imp and two orcs. Elite: group up if you can; solo, pull the orcs at the mouth first and interrupt his fire cast."] = "加里姆待在营地南端的洞穴里，带着他的小鬼和两名兽人。精英：能组队就组队；单刷的话，先拉洞口的兽人，并打断他的火焰施法。",
	["Into {area:69} from the north with Keeshan: {npc:900} and {npc:344} in the town hall, {npc:382} and {npc:341} at the north end of the bridge, then over the bridge to {npc:903} and the gryphons."] = "带着基沙恩从北边进入{area:69}：{npc:900}和{npc:344}在市政厅，{npc:382}和{npc:341}在桥北端，然后过桥到{npc:903}和狮鹫那里。",
	["Murloc Flesheaters and Tidecallers line the south shore of {area:68}, just east of the gryphons and the bridge. Any of them can carry a fin."] = "鱼人食肉者和唤潮者沿{area:68}的南岸分布，就在狮鹫和桥的东边。它们任何一个都可能带着鱼鳍。",
	["Next: the gryphon to {area:42} for {area:10}'s second loop (05-duskwood)."] = "下一步：乘狮鹫去{area:42}，开始{area:10}的第二趟环线（05-暮色森林）。",
	["North up the valley's east side. Shadowhide gnolls fill it; {npc:703} (26) and his two guards stand at its north end: clear the gnolls around him first and fight at full health. Stay out of {area:2099} to the west until the watch tower: its orcs are elite."] = "沿山谷东侧向北。影皮豺狼人遍布谷中；{npc:703}（26级）和两名守卫站在谷北端：先清掉他周围的豺狼人，满血再打。西边的{area:2099}在到瞭望塔前别进去：那里的兽人是精英。",
	["Rabid Dire Wolves roam the woods around the cemetery and {npc:289}, Starving Dire Wolves the hills north-east of him. Pygmy Venom Web Spiders are the small spiders, and few: most crawl along the {area:1097} west of {quest:163}, fewer up north towards {npc:311}'s camp; they drop the venom too. Every ghoul of the cemetery's northern half can drop a fang. Wolves and the bigger spiders share the {zone:1436} border, so pull with care."] = "狂躁凶狼在墓地和{npc:289}周围的森林游荡，饥饿凶狼在他东北的山丘。小毒网蜘蛛就是那些小蜘蛛，数量不多：多数沿{quest:163}以西的{area:1097}爬行，往北到{npc:311}营地一带更少；它们也掉毒液。墓地北半部的每个食尸鬼都可能掉落獠牙。狼和较大的蜘蛛共处{zone:1436}边界一带，引怪要小心。",
	["South-east from the mill, west of {area:1000}'s gnolls, to the Blackrock camps east of {area:2099}. Renegades, Grunts and Outrunners fill them; keep east of the keep, whose orcs are elite. Weapon racks and swords lie about the camps; meat haunches, grain sacks and water barrels hold the supplies."] = "从磨坊向东南，到{area:1000}豺狼人以西，再到{area:2099}以东的黑石营地。营地里满是叛徒、步兵和先锋；待在要塞以东，那里面的兽人是精英。武器架和长剑散落在营地各处；补给放在腿肉、粮袋和水桶里。",
	["The Wanted poster beside it"] = "它旁边的通缉布告",
	["The Wanted poster on the town hall doorway"] = "市政厅门口的通缉布告",
	["The keep stands beside the tower. {npc:334} (elite) waits in the keep's top room with two guards and a dragon; Blackrock Shadowcasters (elite) and Sentries stand on its west side, so pull one at a time on the way in, and hug the right wall as you enter his room so you don't pull him at once. Elite: group up if you can."] = "要塞就在塔旁。{npc:334}（精英）带着两名守卫和一条龙守在要塞顶层的房间里；黑石暗影施法者（精英）和哨兵站在要塞西侧，进去时一次只拉一只，进他房间时贴着右墙走，免得一下子把他拉过来。精英：能组队就组队。",
	["The road east through Elwynn crosses into Redridge at {area:1002}, where the roads to Redridge, {area:10} and Elwynn meet: south to {area:10} first."] = "向东穿过艾尔文森林的道路在{area:1002}进入赤脊山，通往赤脊山、{area:10}和艾尔文森林的道路在此交汇：先往南去{area:10}。",
	["The {object:31} stands at the valley's east edge."] = "{object:31}立在山谷东缘。",
	["Train, then leave by the main gate and follow the road east through {area:12}."] = "学技能，然后从正门出城，沿路向东穿过{area:12}。",
	["West to the intact watch tower beside {area:2099}: climb it and leave the Glyph in the empty jar at the top."] = "向西到{area:2099}旁完好的瞭望塔：爬上去，把符文放进塔顶的空罐里。",
	["for {npc:272} in {area:42}"] = "交给{area:42}的{npc:272}",
	["{area:68}'s murlocs: kill these as you meet them"] = "{area:68}的鱼人：遇到就杀",
	["{item:280839}: meat haunches, grain sacks, water barrels"] = "{item:280839}：腿肉、粮袋、水桶",
	["{item:280841}: weapon racks and swords on the ground"] = "{item:280841}：地上的武器架和长剑",
	["{npc:272}, in the Scarlet Raven Tavern"] = "{npc:272}，在猩红渡鸦酒馆里",
	["{npc:342}'s garden is at the west end of town."] = "{npc:342}的花园在镇子西端。",
	["{npc:345} (level 24) roots around the pen just west of {area:69}, beside {npc:342}'s garden. Pull him away from the other boars and fight at full health."] = "{npc:345}（24级）在{area:69}以西、{npc:342}花园旁的猪圈里拱土。把他从其他野猪旁拉出来，满血再打。",
	["{npc:633}: {npc:288}, at {quest:163}"] = "{npc:633}：{npc:288}，在{quest:163}",
}

G["forever/alliance/05-duskwood"] = {
	["Back to the {area:69} gryphon master: fly to {area:42} for {zone:1431}'s second loop."] = "回到{area:69}的狮鹫管理员：飞往{area:42}，开始{zone:1431}的第二趟环线。",
	["Head south through the cemetery towards {area:94}. Skeletal Fiends and Skeletal Horrors walk its southern half. {npc:522}, an elite, wanders the graves: keep away from him."] = "向南穿过墓地去{area:94}。骸骨魔和恐怖骸骨在墓地南半部游荡。精英{npc:522}在坟间徘徊：离他远点。",
	["Next: training, then the flight from {zone:1453} to {area:150} for the {zone:1437}."] = "下一步：训练，然后从{zone:1453}飞往{area:150}，再去{zone:1437}。",
	["North from {area:94} through Elwynn: {area:87} is on the road to {zone:1453}."] = "从{area:94}向北穿过艾尔文森林：{area:87}在去{zone:1453}的路上。",
	["On into {zone:1453}: {npc:6173} and {npc:6171} are in the Cathedral of Light, on the way to the gryphon master."] = "继续进入{zone:1453}：{npc:6173}和{npc:6171}在光明大教堂，去狮鹫管理员的路上顺路。",
	["{item:1946}: the {npc:511} in the cemetery's crypt is level 26; it waits for the {zone:1431} return"] = "{item:1946}：墓地地穴里的{npc:511}是26级；留到返回{zone:1431}时再打",
}

G["forever/alliance/06-ashenvale"] = {
	["Back north from the glaive (Druids: south along the road from {area:442}) to the {area:448}, where {npc:11218} sleeps beside Arbal. Take his quest, open his chest for the {item:13536}, use it to wake him and lead him south along the road into {area:331} to {npc:11219} at {area:413}; blow the horn again whenever he falls asleep.\nCareful: Scripted ambushes of three mobs each attack along the road: furbolgs on the {zone:1439} stretch and undead nearer {area:413}."] = "从战刃向北折回（德鲁伊：从{area:442}沿路向南）到{area:448}，{npc:11218}睡在阿巴尔旁边。接下他的任务，打开他的箱子拿到{item:13536}，用它唤醒他，沿路向南把他带进{area:331}，到{area:413}的{npc:11219}那里；他每次睡着时就再吹一次号角。\n注意：路上会有三只怪一组的脚本伏击：{zone:1439}那段是熊怪，靠近{area:413}时是亡灵。",
	["Back north through the {area:1276}: west of {area:421}, the stardust bushes grow among the ruins."] = "向北折回穿过{area:1276}：{area:421}以西的废墟里长着星尘草丛。",
	["Back west along the road into Menethil: {npc:2096} by the road in, {npc:2111} and {npc:1480} at the inn, {npc:2086} in the keep, {npc:2094} on the west side by the docks, {npc:1242} on the pier north of the inn."] = "沿路向西折回米奈希尔：{npc:2096}在进城的路边，{npc:2111}和{npc:1480}在旅店，{npc:2086}在要塞，{npc:2094}在西侧码头旁，{npc:1242}在旅店北边的栈桥上。",
	["Follow the road east to the {area:419}; {npc:3916} stands by the moonwell."] = "沿路向东到{area:419}；{npc:3916}站在月亮井旁。",
	["Follow the road south-east from {area:413} back to {area:415}: {npc:3845} by the flight master, {npc:3691} in the inn, {npc:3894} inside."] = "从{area:413}沿路向东南回到{area:415}：{npc:3845}在飞行管理员旁，{npc:3691}在旅店，{npc:3894}在里面。",
	["From the marsh head east across the {zone:1437}. Young Wetlands Crocolisks lurk in the pools north of the excavation site."] = "从沼泽向东穿过{zone:1437}。幼年湿地鳄鱼潜伏在挖掘场北边的水塘里。",
	["From {npc:3987}'s camp head south-west past {area:415} (its hand-ins wait for the way back) to the {area:412} south of the shrine: {npc:3664} and his voidwalkers hold them. Pull his guards first."] = "从{npc:3987}的营地出发，向西南经过{area:415}（它的待交任务留到回程）到神殿南边的{area:412}：{npc:3664}和他的虚空行者守在那里。先拉他的守卫。",
	["Head south past {area:421} into the {area:1276} tunnel; it comes out in Stonetalon's {area:461}, by the {area:2160}."] = "向南经过{area:421}进入{area:1276}隧道；出口在石爪山的{area:461}，{area:2160}旁边。",
	["His hut stands just north of {npc:4080} and {npc:4077}."] = "他的小屋就在{npc:4080}和{npc:4077}的北边。",
	["Its flint comes from the Mosshide Fenrunners on the way to {area:309}; {npc:1244} takes it on your next {zone:1437} visit"] = "它的燧石出自前往{area:309}途中的苔皮沼奔者；下次{zone:1437}之行时交给{npc:1244}",
	["Mathias Shaw is at SI:7 in {object:2100}, south of the Keep."] = "马迪亚斯·肖尔在{object:2100}的军情七处，要塞以南。",
	["Next: training in {zone:1453}, then the road east through Elwynn and south to {zone:1431}."] = "下一步：在{zone:1453}训练，然后沿路向东穿过艾尔文森林，再向南到{zone:1431}。",
	["North-west from {npc:1244}: Mosshide Fenrunners and Mistweavers roam the riverbanks on the way, and almost every one drops flint. Black, Crimson and Monstrous Oozes fill {area:309}, just west of the road to {area:205} and north of Einar's camp. Any ooze there may hold {npc:2111}'s bag."] = "从{npc:1244}向西北：沿途河岸上有苔皮沼奔者和苔皮织雾者游荡，几乎每只都掉燧石。黑色、猩红和巨型软泥怪遍布{area:309}，就在通往{area:205}的道路以西、埃纳尔营地以北。那里的任意一只软泥怪都可能带着{npc:2111}的包。",
	["Off the boat, walk up the pier: {npc:1242} on the pier, {npc:2094} by the docks to the north, {npc:2086} in the keep, the inn ({npc:1239}) east of it with {npc:1480} and {npc:2111} beside it, {npc:2096} by the north gate on the way out east."] = "下船后沿栈桥往里走：{npc:1242}在栈桥上，{npc:2094}在北边码头旁，{npc:2086}在要塞，旅店（{npc:1239}）在要塞以东，{npc:1480}和{npc:2111}在旅店旁，出城向东时{npc:2096}在北门旁。",
	["Only once {quest:97914} is handed in: for {npc:3649}, back in {area:442} (06-wetlands)"] = "只有在交完{quest:97914}之后：交给回到{area:442}的{npc:3649}（06-湿地）",
	["South of the murlocs, {npc:3585} waits at the {area:416}."] = "在鱼人以南，{npc:3585}在{area:416}等着。",
	["The gryphons land in the {object:32372}. {npc:4081} stands in {object:171524}, east of it, by the {area:2257}."] = "狮鹫降落在{object:32372}。{npc:4081}站在它东边的{object:171524}里，{area:2257}旁。",
	["The road from {area:413} comes in by the flight master: {npc:3845} and {npc:4079} stand there, {npc:3691} in the inn, {npc:3894} inside the building beyond it."] = "从{area:413}来的路通到飞行管理员旁：{npc:3845}和{npc:4079}站在那里，{npc:3691}在旅店，{npc:3894}在旅店后面那栋建筑里。",
	["The tram comes in at the {object:28027}; walk west to the {object:2098}. {npc:1646} stands at its east side, {npc:376} in the Cathedral of Light."] = "矿道地铁到站在{object:28027}；向西走到{object:2098}。{npc:1646}站在它东侧，{npc:376}在光明大教堂。",
	["{item:2611}: Mosshide Fenrunners and Mistweavers"] = "{item:2611}：苔皮沼奔者和苔皮织雾者",
	["{item:5490}: any Wrathtail naga on the strand"] = "{item:5490}：岸边的任意怒尾纳迦",
	["{npc:1078}: the bigger raptors in the valley west of the dig are for your next {zone:1437} visit, at about 27"] = "{npc:1078}：挖掘场西边山谷里更大的迅猛龙留到你下次{zone:1437}之行，大约27级时",
	["{npc:1242}, on the pier"] = "{npc:1242}，在栈桥上",
	["{npc:1571} is the flight master by Menethil's inn: you have both flight paths since your first trip east."] = "{npc:1571}是米奈希尔旅店旁的飞行管理员：首次东行后两条飞行路线你都已开通。",
	["{npc:2086}, in the keep"] = "{npc:2086}，在要塞里",
	["{npc:332}: {npc:7024} in {zone:1436} takes it, at the end of {zone:1431}'s second loop"] = "{npc:332}：{zone:1436}的{npc:7024}会收下它，在{zone:1431}第二趟环线末尾",
	["{npc:3663}: its circles are for your next {area:331} visit, at about 28"] = "{npc:3663}：它的巡逻圈留到你下次{area:331}之行，大约28级时",
	["{npc:3691}: {quest:990}, from {area:442} (others take it on the next {area:331} visit)"] = "{npc:3691}：{quest:990}，来自{area:442}（其他人下次{area:331}之行再接）",
	["{npc:4080} and {npc:4077} camp on the {area:1076}, south-west of the mine."] = "{npc:4080}和{npc:4077}在矿场西南的{area:1076}扎营。",
	["{object:2164} is in the {object:2101}. Warlocks: {npc:6122} is in its cellar."] = "{object:2164}在{object:2101}里。术士：{npc:6122}在它的地窖里。",
}

G["forever/alliance/06-wetlands"] = {
	["A new {item:279996}, for the four titan watchers around the {zone:1437}; below ground. Their hearts drop from level 32 elites on the {area:205} visit"] = "新增的{item:279996}，用于{zone:1437}周围的四个泰坦守望者；地下。它们的心脏由{area:205}之行的32级精英掉落",
	["Back west along the road to {area:150}: {npc:2104} stands on the top floor of {area:2103}."] = "沿路向西折回{area:150}：{npc:2104}站在{area:2103}的顶层。",
	["East from {npc:270637}: {npc:2093} stands beside the road."] = "从{npc:270637}向东：{npc:2093}站在路边。",
	["Flagon of Mead, from {npc:1464}"] = "蜂蜜酒壶，来自{npc:1464}",
	["Follow the coast north out of Menethil into {area:1022}. Three containers in the murloc hovels, south to north: the {object:261}, then the {object:142151}, then the {object:259} at the north end."] = "沿海岸向北出米奈希尔进入{area:1022}。鱼人小屋里的三个容器，从南到北：{object:261}，然后是{object:142151}，最后是北端的{object:259}。",
	["Follow the road east to the {area:1025}; {npc:1244} stands by the river. {quest:277}'s flint came with you from your last {zone:1437} visit."] = "沿路向东到{area:1025}；{npc:1244}站在河边。{quest:277}的燧石是你上次{zone:1437}之行带过来的。",
	["Follow the road east to the {area:419}; {npc:3916} stands by the moonwell."] = "沿路向东到{area:419}；{npc:3916}站在月亮井旁。",
	["Follow the road east: the bigger raptors for {quest:295} hunt in the valley just west of the excavation site."] = "沿路向东：{quest:295}要用的更大迅猛龙在挖掘场西边的山谷里捕猎。",
	["For King Magni in {zone:1455}, at the end of 30-40/01-hillsbrad-foothills"] = "交给{zone:1455}的国王麦格尼·铜须，在30-40/01-希尔斯布莱德丘陵指南结尾",
	["For the Dragonmaw catapult, on the {zone:1437} loop of 30-40/01-hillsbrad-foothills"] = "龙喉投石车，见30-40/01-希尔斯布莱德丘陵的{zone:1437}环线",
	["For {quest:4581} at {area:2358}"] = "用于{area:2358}的{quest:4581}",
	["Goaz Warders"] = "戈阿兹守卫",
	["In from the north: {npc:2094} by the docks, {npc:1242} on the pier, {npc:2104} in the keep, then {npc:1239} in the inn."] = "从北边进来：{npc:2094}在码头旁，{npc:1242}在栈桥上，{npc:2104}在要塞，然后{npc:1239}在旅店。",
	["In {zone:1453}, join the two half pendants into the {item:15885} and cast {spell:18960}: {npc:11802} is in {area:2361}. Then {npc:11800} in {area:2361} flies Druids straight to {area:702}. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "在{zone:1453}，把两半吊坠合成{item:15885}并施放{spell:18960}：{npc:11802}在{area:2361}。然后{area:2361}的{npc:11800}会把德鲁伊直接飞到{area:702}。{npc:11802}站在他所在建筑的楼上：从里面上去，箭头分不清楼层。",
	["North to {area:413}."] = "向北到{area:413}。",
	["Razormaw Incisors: from the raptors by the {area:1038}, on the {zone:1437} loop of 30-40/01-hillsbrad-foothills"] = "镰颚龙门齿：出自{area:1038}旁的迅猛龙，见30-40/01-希尔斯布莱德丘陵的{zone:1437}环线",
	["Red whelps fill the hills west of the gates, Maddened Rotclaws the {area:1025}, Razormaws the northern slopes; Neru stands in the north-east (use the {item:279996}).\nFen Creepers hide in the marsh pools north-west of the {area:1025}.\nCareful: When out of combat, Fen Creepers cast Sneak from time to time, so they are stealthed and hard to see."] = "红色幼龙遍布大门以西的丘陵，发狂的腐爪龙占据{area:1025}，镰颚龙在北坡；内鲁站在东北（使用{item:279996}）。\n沼泽爬行者藏在{area:1025}西北的沼泽水塘里。\n注意：脱离战斗时，沼泽爬行者会不时施放潜行，所以它们处于潜行状态，很难发现。",
	["South-east along the road to {area:415}: {npc:3691} in the inn, {npc:3961} and {npc:3894} inside, the flight master at the west end."] = "沿路向东南到{area:415}：{npc:3691}在旅店，{npc:3961}和{npc:3894}在里面，飞行管理员在西端。",
	["South-east from the dig to the Dragonmaw camp. The four sets of Attack Plans lie in the {area:1036}; {npc:2091}, an elite, stands in the camp too."] = "从挖掘场向东南到龙喉营地。四份进攻计划都在{area:1036}；精英{npc:2091}也站在营地里。",
	["Take the boat from {area:442}'s dock to {area:150}."] = "从{area:442}的码头乘船前往{area:150}。",
	["Take the portal up to the {area:1658}, then fly back to {area:442} for the boat to {area:150}."] = "乘传送门上去到{area:1658}，然后飞回{area:442}乘船前往{area:150}。",
	["The Goaz Warders stand just west of Whelgar's camp: use the {item:279996} he gave you beside one.\n{npc:270892} is elite: grouping up is advised."] = "戈阿兹守卫就守在威尔加营地以西：站到其中一只旁边使用他给你的{item:279996}。\n{npc:270892}是精英：建议组队。",
	["The boat to {area:442} leaves from the far end of Menethil's western pier."] = "去{area:442}的船从米奈希尔西侧栈桥的尽头出发。",
	["The excavation site sits on the hill south of the road: {npc:1078} at the top, {npc:1077} below ground."] = "挖掘场位于路南的山丘上：{npc:1078}在顶上，{npc:1077}在地下。",
	["The two stand together at the western end of the road, south-west of {area:415}."] = "两人并肩站在路的西端，{area:415}西南。",
	["West from {npc:3897} along the southern hills to the {area:416}: Melyria and {npc:3901} stand together by it."] = "从{npc:3897}沿南边的山丘向西到{area:416}：梅莉娅和{npc:3901}一起站在它旁边。",
	["{item:3337}: the camp's Raiders and Swamprunners"] = "{item:3337}：营地里的劫掠者和沼泽奔行者",
	["{npc:1077}, below ground: the {item:279993}, from the elite Goaz Warders"] = "{npc:1077}，地下：{item:279993}，出自精英戈阿兹守卫",
	["{npc:1571} is the flight master by Menethil's inn."] = "{npc:1571}是米奈希尔旅店旁的飞行管理员。",
	["{npc:2093}: for {npc:2094} in Menethil"] = "{npc:2093}：交给米奈希尔的{npc:2094}",
	["{npc:2094}, by the docks"] = "{npc:2094}，码头旁",
	["{npc:2094}, by the docks, on the way to the boat"] = "{npc:2094}，码头旁，去坐船的路上",
	["{npc:2097}, by the north gate: {npc:1071} takes it on 30-40/01-hillsbrad-foothills' {area:205} stop"] = "{npc:2097}，北门旁：{npc:1071}会在30-40/01-希尔斯布莱德丘陵的{area:205}站收下它",
	["{npc:2104}, by the keep; on the top floor"] = "{npc:2104}，要塞旁；在顶层",
	["{npc:2104}: for {npc:270637} in the {area:1025}"] = "{npc:2104}：交给{area:1025}的{npc:270637}",
	["{npc:2104}: {quest:98221}, the Attack Plans in the {area:1036}"] = "{npc:2104}：{quest:98221}，{area:1036}里的进攻计划",
	["{npc:270637} camps among the Fenrunners, just west of {npc:1244}."] = "{npc:270637}在沼奔者群中扎营，就在{npc:1244}以西。",
	["{npc:3649} stands at the north end of {area:442}, {npc:3693} and {npc:3694} by the flight master."] = "{npc:3649}站在{area:442}北端，{npc:3693}和{npc:3694}在飞行管理员旁。",
	["{npc:3693}: Volcor's escort from the end of {zone:1439}"] = "{npc:3693}：{zone:1439}末尾沃尔科的护送任务",
	["{npc:3845} stands by {area:415}'s flight master."] = "{npc:3845}站在{area:415}的飞行管理员旁。",
	["{quest:98283}, an elite raptor, on the {zone:1437} loop of 30-40/01-hillsbrad-foothills"] = "{quest:98283}，一只精英迅猛龙，见30-40/01-希尔斯布莱德丘陵的{zone:1437}环线",
}

G["forever/alliance/07-thousand-needles"] = {
	["Head south-west from {area:42} to the ogre mound. {object:119} sits in the camp at its entrance; Splinter Fist ogres guard it."] = "从{area:42}向西南前往食人魔土丘。{object:119}在入口处的营地；碎拳食人魔看守着它。",
	["The grave stands among the skeletons at the cemetery's north-west corner, on the way to {npc:311}. Its quest and the next are talk-only, to {npc:268} and Commander Althea in {area:42}: level 35 from level 28, but no fight."] = "坟墓立在墓地西北角的骸骨之间，在去{npc:311}的路上。它和下一个任务都只需对话，找{area:42}的{npc:268}和指挥官阿尔西娅：35级的任务28级就能做，但不用打。",
	["{npc:276}'s house stands at the east end of town, on the way to the flight master."] = "{npc:276}的房子在镇子东端，去飞行管理员的路上。",
}

G["forever/alliance/30-40/01-hillsbrad-foothills"] = {
	["Back down the road to {area:205}: {npc:1075} wants the {object:147516} explosives under the far end of the span destroyed."] = "沿路返回{area:205}：{npc:1075}要你毁掉桥远端下面的{object:147516}炸药。",
	["Back over the span and down the road through {area:205} on the way south."] = "折回过桥，沿路向南穿过{area:205}。",
	["Comar Villard"] = "科马尔·维拉德",
	["Comar Villard waits on the road north of {area:205}, towards the {area:880}; {npc:271322} a short walk further north-east, and Ebenezer Rustlocke's corpse lies under the span beside her. Rustlocke's parchment goes back to {npc:1075}."] = "科马尔·维拉德在{area:205}以北、通往{area:880}的路上等着；{npc:271322}再往东北走一小段就到，埃比尼泽·拉斯特洛克的尸体就在桥下她身旁。把拉斯特洛克的羊皮纸交回给{npc:1075}。",
	["Level 30.8"] = "30.8级",
	["Maddened Rotclaws roam the {area:1025} around {npc:1244}."] = "狂乱的腐爪怪在{npc:1244}周围的{area:1025}游荡。",
	["North along the road to {area:205}. {npc:1071}, {npc:1075} and {npc:1072} stand together in the dwarves' camp; the {npc:271481} is held on the west side: lead it out to {npc:1072}."] = "沿道路向北到{area:205}。{npc:1071}、{npc:1075}和{npc:1072}一起站在矮人营地里；{npc:271481}被关在西侧：把它带出去交给{npc:1072}。",
	["Over the {area:880}: the Dark Irons' cache of explosives sits by its Arathi end. {npc:2696} stands a short walk west of it."] = "过了{area:880}：黑铁矮人的炸药储藏点就在它靠阿拉希的一端。{npc:2696}站在它西边不远处。",
	["Skipped {quest:474} and short of 30.8? Kill the Bluegill murlocs on the coast south of Menethil until level 30.8. Or, with a group, run the {area:133} dungeon or the {area:796} dungeon (Graveyard) instead."] = "跳过了{quest:474}还差30.8级？去米奈希尔以南的海岸杀蓝鳃鱼人，直到30.8级。或者组队去刷{area:133}副本或{area:796}副本（墓地）。",
	["South-east from Menethil to the Dragonmaw's {area:1036}: the first catapult stands on the way, and the {object:671518} lies in the camp."] = "从米奈希尔向东南到龙喉的{area:1036}：第一架投石车就在路上，{object:671518}在营地里。",
	["The Syndicate camp sits on the Alterac border in northern {area:287}, west of {area:272} (Horde); the documents lie in the camp, and its Footpads and Thieves are the Syndicate Maleb wants."] = "辛迪加营地在{area:287}北部、奥特兰克边境上，{area:272}（部落）西边；文件在营地里，营地里的拦路贼和窃贼就是马莱布要的辛迪加成员。",
	["The whelps nest in the hills north-east of the {area:1036}; {quest:98283} prowls further north, and the Razormaw raptors hunt the highlands on the way north to {area:205}.\n{quest:98283} is elite: grouping up is advised."] = "幼龙在{area:1036}东北的山丘里筑巢；{quest:98283}在更北处徘徊，向北去{area:205}途中的高地上还有锐颚迅猛龙捕猎。\n{quest:98283}是精英：建议组队。",
	["The yetis live in the cave in the hills north of {area:271}, on the way north to the Syndicate camp."] = "雪人住在{area:271}北边山丘上的洞穴里，就在向北去辛迪加营地的路上。",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:271462}, {npc:271338}, {npc:271458} and {npc:271460} are level 32 elites, each called up by using the {item:279996} beside it. Skip them if you are alone. {npc:271462} stands in the south-eastern hills."] = "这些是精英怪：建议组队，找人一起做。{npc:271462}、{npc:271338}、{npc:271458}和{npc:271460}都是32级精英，每只都要在它旁边使用{item:279996}才能召唤出来。如果只有你一个人就跳过它们。{npc:271462}站在东南边的山丘上。",
	["for {npc:2700} at {area:320}, in 05-arathi-highlands"] = "给{area:320}的{npc:2700}，在 05-arathi-highlands 指南中",
	["the same corpse"] = "同一具尸体",
	["{npc:1356}, {npc:2916} and {npc:5637} stand in the {object:32356}, north-east of the flight master."] = "{npc:1356}、{npc:2916}和{npc:5637}站在飞行管理员东北边的{object:32356}里。",
	["{npc:2438} also wants a {item:3719} ({skill:165}), a {item:2997} ({skill:197}) and {item:2321} (any trade supplier): the cloak is turned in when you are back in {area:271} later."] = "{npc:2438}还要一件{item:3719}（{skill:165}）、一匹{item:2997}（{skill:197}）和{item:2321}（任意专业供应商）：披风之后回到{area:271}时再交。",
	["{npc:2438}: only if you have or can buy a {item:3719} ({skill:165}) and a {item:2997} ({skill:197}); no vendor sells them"] = "{npc:2438}：只有在你已有或能买到{item:3719}（{skill:165}）和{item:2997}（{skill:197}）时才做；没有商人卖这两样",
	["{npc:2708} is in the {object:2164}; {npc:5081} south of the {object:2101}."] = "{npc:2708}在{object:2164}里；{npc:5081}在{object:2101}南边。",
	["{npc:271458} stands in the hills between the {area:1038} and {area:205} (use the {item:279996})."] = "{npc:271458}站在{area:1038}与{area:205}之间的山丘上（使用{item:279996}）。",
	["{npc:271460} stands in the ruins of {area:205} (use the {item:279996})."] = "{npc:271460}站在{area:205}的废墟里（使用{item:279996}）。",
	["{zone:1455} has no druid trainer: {npc:5504} stands in {zone:1453}, north-west of the {object:2101}."] = "{zone:1455}没有德鲁伊训练师：{npc:5504}站在{zone:1453}、{object:2101}的西北边。",
}

G["forever/alliance/30-40/02-desolace"] = {
	["Use {npc:11596}'s {item:13892} on an {npc:4700} and walk the tamed kodo back to his camp. There, talk to the kodo: that counts it and lets you tame the next. Five kodos, one at a time; Aged Kodos also drop the hides, and the Scorpashi Lashers that hunt around the graveyard carry the venom."] = "对一只{npc:4700}使用{npc:11596}的{item:13892}，把驯服的科多兽牵回他的营地。到了那里跟科多兽对话：这样才算数，也才能驯下一只。共五只科多兽，一次一只；老迈的科多兽也会掉皮，在墓地周围捕猎的斯科尔帕什鞭笞者身上带着毒液。",
}

G["forever/alliance/30-40/03-ashenvale"] = {
	["Down the {area:485} into {area:400}, then west to the wyverns' cliffs at {area:482}. Every wyvern there can drop a venom sac."] = "沿{area:485}下去进入{area:400}，再向西到{area:482}的双足飞龙悬崖。那里每只双足飞龙都可能掉落毒囊。",
	["Follow the road west out of Theramore to the burned inn on the road toward the {zone:1413}: the black shield lies in the ashes and the hoofprints are in the mud beside the inn."] = "从塞拉摩沿路向西，到通往{zone:1413}路上的烧毁旅店：黑盾躺在灰烬里，蹄印在旅店旁的泥地里。",
	["For {npc:1416} in {zone:1453}, after Stranglethorn"] = "给{zone:1453}的{npc:1416}，荆棘谷之后",
	["From the raceway follow the road south out of the {area:439} into {zone:1446}; {area:976} is a short walk down it. Keep to the road. {npc:7823}, the Alliance flight master, stands inside the walls."] = "从赛道沿路向南出{area:439}进入{zone:1446}；沿路走一小段就是{area:976}。别离开道路。{npc:7823}是联盟飞行管理员，站在城墙里面。",
	["Saltstone Basilisk"] = "盐石蜥蜴",
	["Saltstone Crystalhide"] = "盐石水晶皮",
	["Saltstone Gazer"] = "盐石凝视者",
	["{npc:4454}: for Martek in the {zone:1418}, at the end of 30-40"] = "{npc:4454}：交给{zone:1418}的马特克，在 30-40 段末尾",
	["{npc:4456} is in the north of town, Captain Vimes in {area:514}; {npc:4941} stands in the town."] = "{npc:4456}在城镇北边，维姆斯上尉在{area:514}；{npc:4941}站在镇里。",
	["{npc:4456}: the wyverns are in {area:400}, later in this guide"] = "{npc:4456}：双足飞龙在{area:400}，本攻略后面会用到",
	["{object:19868} lies all over the flats. Scorpid Reavers and Salt Flats Scavengers roam the north half, Sparkleshell Snappers (tortoises) the whole flats. Saltstone Basilisks and Crystalhides hold the middle; the Gazers (34-35) only the far south."] = "{object:19868}遍布整片平地。毒蝎掠夺者和盐滩拾荒者在北半部游荡，亮壳咬龟（陆龟）遍布整个平地。盐石蜥蜴和水晶皮占据中部；凝视者（34-35级）只在最南端。",
}

G["forever/alliance/30-40/04-stranglethorn-vale"] = {
	["From {area:108} the way leads south out of {zone:1436} into Stranglethorn's north-west, to the {area:310} near the coast; the Crystal Spine Basilisks around it drop the shards.\nThe haunted island lies just off the coast south-west of the mine: just reach it. The Bloodscalp trolls hold the ruins on the coast to the north."] = "从{area:108}向南出{zone:1436}，进入荆棘谷西北部，到海岸附近的{area:310}；周围的水晶脊蜥蜴掉落碎片。\n闹鬼的小岛就在矿场西南的海岸外：到达即可。血顶巨魔占据着北边海岸上的废墟。",
	["From {area:415} head north-west into the hills: the {quest:1738} is a glowing tree north of the road to {area:413}. If you took {quest:65602}, the {item:190309} lies in a house among the trees north of {area:413} (26.6,22.0). Then take the road west to Stonetalon."] = "从{area:415}向西北进入丘陵：{quest:1738}是通往{area:413}道路北侧的一棵发光树。如果你接了{quest:65602}，{item:190309}就在{area:413}以北树林中的一座房子里（26.6,22.0）。然后沿路向西去石爪山脉。",
	["Level 34"] = "34级",
	["The quests from here on are 37: if you are short of 34, keep on the elder tigers in the hills south-west of Nesingwary's camp until level 34. Or, with a group, run the {area:796} dungeon (Library or Armory) instead."] = "从这里开始的任务是37级：如果还不到34级，就继续在奈辛瓦里营地西南山丘里打老年虎，直到34级。或者组队去刷{area:796}副本（图书馆或军械库）。",
	["{npc:2495}: the Snapjaw Crocolisks, on the northern loop"] = "{npc:2495}：碎颚鳄鱼，在北部环线上",
	["{npc:2496}: the water elementals rise around the haunted island, on the northern loop"] = "{npc:2496}：水元素在闹鬼小岛周围浮现，在北部环线上",
	["{npc:469}: {quest:200}'s records, on the northern loop (04b)"] = "{npc:469}：{quest:200}的档案，在北部环线（04b）",
	["{npc:5504}, the druid trainer, stands in {zone:1453}, north-west of the {object:2101}."] = "{npc:5504}是德鲁伊训练师，站在{zone:1453}、{object:2101}的西北边。",
	["{npc:737}: the Tumbled Crystals, on the northern loop"] = "{npc:737}：滚落的水晶，在北部环线上",
}

G["forever/alliance/30-40/04b-stranglethorn-vale"] = {
	["Follow the west coast north to the haunted island off the shore west of Nesingwary's camp: the Lesser Water Elementals rise from the water around it."] = "沿西海岸向北到奈辛瓦里营地以西近海的闹鬼小岛：次级水元素从它周围的水里升起。",
	["From {zone:1431} take the road south; the camp sits in the hills west of the road."] = "从{zone:1431}沿路向南；营地在道路西边的山丘里。",
	["Headshrinkers stand deeper in the compound; the Commandos lurk stealthed around it and in the cave, and Herod's strongbox sits by the cave mouth. Pick up Green Hills pages as they drop.\nCareful: Kurzen Commandos are level 34-35, not elite, and often spawn stealthed; near death they use {spell:7964}."] = "缩颅者站在营地深处；突击队员潜行在营地周围和洞穴里，赫罗德的保险箱就在洞口旁。绿丘书页掉落时顺手捡起。\n注意：库尔森突击队员为34-35级，非精英，经常潜行刷新；濒死时会使用{spell:7964}。",
	["Herod's records lie in a hut on the west side of {area:101}, east of the {area:99}."] = "赫罗德的档案在{area:101}西侧的一间小屋里，就在{area:99}东边。",
	["Mauren, from Stonetalon"] = "莫伦，来自石爪山脉",
	["Snapjaw Crocolisks bask along the river in the middle of the jungle, on the way south to the Skullsplitter ruins."] = "碎颚鳄鱼在丛林中部沿河晒太阳，就在向南去劈颅废墟的路上。",
	["South along the road: the hunters' tents stand just west of it."] = "沿路向南：猎人的帐篷就在路西边不远处。",
	["{npc:733}: the Commandos and Headshrinkers fell in the compound"] = "{npc:733}：在营地里击杀突击队员和缩颅者",
	["{npc:773}: the ore drops from Drywhisker kobolds in {zone:1417}, next"] = "{npc:773}：矿石由{zone:1417}的枯须狗头人掉落，下一步",
	["{quest:205}'s Skullsplitter trolls are 39-42. Below 36? Keep killing the Snapjaw Crocolisks along the river until level 36. Or, with a group, run the {area:796} dungeon (Armory) or the {area:1316} dungeon instead."] = "{quest:205}的劈颅巨魔是39-42级。不到36级？继续沿河杀碎颚鳄鱼，直到36级。或者组队去刷{area:796}副本（军械库）或{area:1316}副本。",
}

G["forever/alliance/30-40/05-arathi-highlands"] = {
	["Escort the professor up the hill to the cave above the cove and guard him while he works. Two level 40 water elementals ambush him there, and they are immune to frost. Hold them at the cave mouth, away from him: if the fight happens inside the cave, he joins in instead of working and more elementals keep coming."] = "护送教授上山到海湾上方的洞穴，并在他工作时守护他。两个40级水元素会在那里伏击他，而且免疫冰霜。把它们挡在洞口、远离他：如果战斗发生在洞内，教授就会参战而不工作，还会不断涌来更多水元素。",
	["South along the west coast to the goblins' cove; Lolo keeps watch on the rocks above it."] = "沿西海岸向南到地精的海湾；鲁鲁在上方岩石上放哨。",
	["South-east from Northfold to the Witherbark trolls in the hills south of {area:314}; Witch Doctors stand in the village, Shadow Hunters guard the far end of the valley. Every troll here can drop a tusk."] = "从诺斯福德向东南到{area:314}以南山丘里的枯木巨魔；枯木巫医站在村子里，枯木暗影猎手守着山谷尽头。这里每只巨魔都可能掉落獠牙。",
	["The wrecked caravan's chest lies at the north end of the {area:76}, beside {npc:5391}'s cage.\nCareful: The camp is full of Lost Ones around level 38. They stand in linked groups of 2-3, many are casters, and they respawn quickly."] = "损毁车队的箱子在{area:76}北端、{npc:5391}的笼子旁。\n注意：营地到处是38级左右的失落者。它们以2-3只连组行动，其中许多是施法者，且刷新很快。",
	["{npc:1356}, {object:32356}: for {npc:1344} in {area:38}, next"] = "{npc:1356}、{object:32356}：给{area:38}的{npc:1344}，下一步",
	["{npc:2438}, if you took his cloak quest"] = "{npc:2438}，如果你接了他的披风任务",
	["{npc:2700}: {npc:1075}'s plea, from 01-hillsbrad-foothills"] = "{npc:2700}：{npc:1075}的请求，来自 01-hillsbrad-foothills",
}

G["forever/alliance/30-40/06-badlands"] = {
	["For {npc:4454} at the {area:2240}: the {zone:1446} guide passes him at 45, keep it"] = "给{area:2240}的{npc:4454}：{zone:1446}的攻略会在45级经过他，留着。",
	["Head south down the road: {npc:4618} and {npc:2817} camp in the {area:1877}, on the way to {area:345}."] = "沿路向南：{npc:4618}和{npc:2817}在{area:1877}扎营，就在去{area:345}的路上。",
	["Off the boat, walk up the pier to Baldruc, the flight master by the gate of {area:514}."] = "下船后沿码头上岸，到{area:514}门口的飞行管理员巴尔德鲁克那里。",
	["The Dustbelcher ogres camp just south of the valley; any of them drops scrap. Buzzards circle the plain to the east.\nThe battered skeleton lies at the edge of the Stonevault trogg camp; {quest:739}, Agmond's killer, walks among the Bonesnappers.\nCareful: Dustbelcher Lords are level 44-45. They use {spell:5242} and {spell:1160}, and below 50% health they call for help from allies within 15 yd. Seven of them stand about 750 yd south of {area:340}."] = "沙腮食人魔就在山谷南边扎营；他们中任何一个都会掉落废料。秃鹫在东边的平原盘旋。\n破烂的骷髅躺在石窟穴居人营地边缘；杀死阿格蒙德的凶手{quest:739}在断骨者中间走动。\n小心：沙腮领主是44-45级。他们会用{spell:5242}和{spell:1160}，生命值低于50%时会呼叫15码内的盟友支援。其中七个站在{area:340}以南约750码处。",
	["The Lesser Rock Elementals wander the {area:1878} west of {npc:2921}; every rock elemental can drop {npc:1470}'s Rock Elemental Shards."] = "次级岩石元素在{npc:2921}西边的{area:1878}游荡；每个石元素都可能掉落{npc:1470}要的石元素碎片。",
	["{npc:2920}, beside {npc:2921}, wants {item:2868}, a blacksmith's craft: skip him unless you carry a pair."] = "{npc:2920}就在{npc:2921}旁边，他要{item:2868}，那是锻造做的：除非你身上带着一对，否则跳过他。",
	["{npc:2921}'s last test is optional: five {item:4628}, which only the Greater Rock Elementals (42-44) in the south-western gulches drop, about one kill in five, well above your level. Take it only if you can handle them one at a time; otherwise hand in the slabs and move on."] = "{npc:2921}的最后一道考验是可选的：五个{item:4628}，只有西南峡谷里的大型岩石元素（42-44级）才掉，大约五只出一个，等级远高于你。只有你能一只只对付时才接；否则交了石板就走。",
	["{npc:5638}: the wreck is on the north-west coast, at the end of the loop"] = "{npc:5638}：残骸在西北海岸，在环线尽头",
	["{quest:739} himself (42) walks among the Bonesnappers: leave him for the later {area:3} guide at 43, and kill the Bonesnappers for this quest now."] = "{quest:739}本人（42级）在断骨者中间走动：把他留到43级时后面的{area:3}指南，现在为这个任务先杀断骨者。",
}

G["forever/alliance/40-50/01-stranglethorn-vale"] = {
	["If you skipped {quest:193}, grind here to level 42.06 to stay on the route's plan. Or, with a group, run the {area:1517} dungeon instead."] = "如果你跳过了{quest:193}，就在这里刷到42.06级，以保持攻略的节奏。或者组队去刷{area:1517}副本。",
	["If you skipped {quest:196}, grind here to level 42.1 to stay on the route's plan. Or, with a group, run the {area:1517} dungeon instead."] = "如果你跳过了{quest:196}，就在这里刷到42.1级，以保持攻略的节奏。或者组队去刷{area:1517}副本。",
	["If you skipped {quest:208}, grind here to level 42.16 to stay on the route's plan. Or, with a group, run the {area:1517} dungeon instead."] = "如果你跳过了{quest:208}，就在这里刷到42.16级，以保持攻略的节奏。或者组队去刷{area:1517}副本。",
	["If you skipped {quest:543}, grind here to level 42.46 to stay on the route's plan. Or, with a group, run the {area:1517} dungeon instead."] = "如果你跳过了{quest:543}，就在这里刷到42.46级，以保持攻略的节奏。或者组队去刷{area:1517}副本。",
	["Level 42.06"] = "42.06级",
	["Level 42.1"] = "42.1级",
	["Level 42.16"] = "42.16级",
	["Ride south down the road to {area:35}."] = "沿道路向南骑到{area:35}。",
	["The burned inn stands on the road west, toward the {area:17}; the guard's badge lies in the ashes."] = "烧毁的旅店在向西通往{area:17}的路上；卫兵的徽章在灰烬里。",
	["{item:5938}, from the Silt Crawlers on the same shore"] = "{item:5938}，来自同一片岸边的淤泥爬虫",
	["{npc:4794}: the crawlers are on the {area:8} shore, keep it"] = "{npc:4794}：爬虫在{area:8}岸边，留着",
	["{npc:4964}, on the top floor of {area:514}"] = "{npc:4964}，在{area:514}的顶层",
	["{npc:5637} is in the Reclaimers' hall by the {object:32356}, {npc:2786} in the {object:32383}."] = "{npc:5637}在{object:32356}旁的寻物公司大厅，{npc:2786}在{object:32383}。",
	["{npc:5694}: for {npc:5464} in {area:42}, on the way to the swamp"] = "{npc:5694}：给{area:42}的{npc:5464}，在去沼泽的路上",
	["{npc:737}, upstairs: the Skullsplitter trolls, on the northern loop"] = "{npc:737}，在楼上：劈颅巨魔，在北部环线上",
}

G["forever/alliance/40-50/02-badlands"] = {
	["{npc:2817}: Blue Pearls from Stranglethorn"] = "{npc:2817}：来自荆棘谷的蓝色珍珠",
	["{npc:3980} preaches by the inn."] = "{npc:3980}在旅店旁布道。",
}

G["forever/alliance/40-50/03-feralas"] = {
	["From {area:489} ride west along the road to the Grimtotem camp north of it. {npc:7956} waits outside it; free the Sprite Darters from the pen in the middle and keep {npc:7956} and at least six of them alive."] = "从{area:489}沿路向西骑到它北边的恐怖图腾营地。{npc:7956}在营地外等着；把精灵龙从中间的围栏里放出来，并保住{npc:7956}和至少六只精灵龙。",
	["Ride east into {area:1105}. {npc:14637}'s quests on the coast need level 45. Or, with a group, run the {area:978} dungeon or the {area:1517} dungeon instead."] = "向东骑进{area:1105}。{npc:14637}在海岸边的任务需要45级。或者组队去刷{area:978}副本或{area:1517}副本。",
	["The {zone:1446} guide starts with the trip east, past {area:489}."] = "{zone:1446}指南从向东、经过{area:489}的行程开始。",
}

G["forever/alliance/40-50/04-tanaris"] = {
	["The {area:2240} lies on the {area:439} in south-east {area:400}: {npc:4454} is in the gnomes' camp beside the track, {npc:4709} by the goblin camp."] = "{area:2240}位于{area:400}东南的{area:439}上：{npc:4454}在赛道旁的侏儒营地，{npc:4709}在地精营地旁。",
	["{npc:4454}: {quest:1137}, from Martek in the {zone:1418}"] = "{npc:4454}：{quest:1137}，来自{zone:1418}的马特克",
	["{npc:5636}, beside the flight master"] = "{npc:5636}，在飞行管理员旁",
}

G["forever/alliance/40-50/05-the-hinterlands"] = {
	["Back to {area:38}"] = "回到{area:38}",
	["Ride back west along the loch to {area:144}."] = "沿湖向西骑回{area:144}。",
}

G["forever/alliance/40-50/06-searing-gorge"] = {
	["Back at the {area:247}: Dorius stands by the road. Escort him north-east to {area:1959} and keep him alive; when it is over, read the {object:175704} he leaves on the road."] = "回到{area:247}：多里乌斯站在路边。护送他向东北到{area:1959}并保住他的命；结束后阅读他留在路上的{object:175704}。",
	["From {area:144} ride south into the {zone:1418}, then west past the Horde town of {area:340} (give it room) and up the trail into {area:51}: the {area:247} is just inside, in the south-east. The prisoner in the wooden outhouse wants 15 {item:4306} and eight dead Dark Iron Geologists from the dig site around it. The outhouse also opens with the key, if you found one."] = "从{area:144}向南骑进{zone:1418}，再向西绕过部落的{area:340}城镇（离它远点），沿小径上行进入{area:51}：{area:247}一进去就是，在东南边。木制茅房里的囚犯要15个{item:4306}，以及其周围挖掘场里的八名黑铁地质学家。如果你找到了钥匙，茅房也可以用钥匙打开。",
	["Heavy War Golems patrol the floor of the Cauldron below Kalaran; Magma Elementals drift among them. Golems and elementals drop the oil, elementals the hearts.\nTaskmasters and Slavers drive the slaves all over the Cauldron, and any of them can carry a {item:10551}. The Steamsmiths work at the furnaces in the middle (the {item:18959}), the Lookouts stand on the southern ridges (the Spyglass). Any {object:147516} may drop the {item:11818}: keep it.\nCareful: Dark Iron Slavers (level 45-46) call for help from allies within 15 yd when pulled, cast Net from up to 15 yd, and use Rend in melee."] = "重型战争傀儡在卡拉兰下方的火山口地面上巡逻；岩浆元素在它们之间游荡。傀儡和元素掉落油，元素掉落心脏。\n监工和奴隶贩子驱赶着奴隶遍布火山口，他们中的任何一个都可能携带{item:10551}。蒸汽铁匠在中央的熔炉干活（{item:18959}），瞭望员站在南边的山脊上（望远镜）。任何{object:147516}都可能掉落{item:11818}：留着。\n注意：黑铁奴隶贩子（45-46级）被拉时向15码内的盟友求援，还会从最多15码外撒网，并在近战中使用撕裂。",
	["If you skipped The {item:3985} or Facing Negolash, grind here to level 48.27 to stay on the route's plan. Or, with a group, run the {area:2100} dungeon or the {area:978} dungeon instead."] = "如果你跳过了{item:3985}或“直面内戈拉什”任务，就在这里刷到48.27级，以保持攻略的节奏。或者组队去刷{area:2100}副本或{area:978}副本。",
	["If you skipped {quest:3452}, grind here to level 48.98 to stay on the route's plan. Or, with a group, run the {area:2100} dungeon or the {area:978} dungeon instead."] = "如果你跳过了{quest:3452}，就在这里刷到48.98级，以保持攻略的节奏。或者组队去刷{area:2100}副本或{area:978}副本。",
	["If you skipped {quest:7701}, grind here to level 48.66 to stay on the route's plan. Or, with a group, run the {area:2100} dungeon or the {area:978} dungeon instead."] = "如果你跳过了{quest:7701}，就在这里刷到48.66级，以保持攻略的节奏。或者组队去刷{area:2100}副本或{area:978}副本。",
	["Ride north-west across the Cauldron to {area:1446}, the scaffolded camp on the north-west rim."] = "向西北骑过火山口到{area:1446}，那是西北边缘搭着脚手架的营地。",
	["The spiders roam the plateaus and lava pools south of {npc:8436}, on the way to Kalaran."] = "蜘蛛在{npc:8436}以南的高地和熔岩池出没，就在去卡拉兰的路上。",
	["Velarok Windblade"] = "维拉罗克·风刃",
}

G["forever/alliance/40-50/07-un-goro-crater"] = {
	["Ride south down the east side. Young Diemetradons graze the eastern jungle and {npc:9165} fly near the eastern cliffs; both drop {npc:9998}'s scales. The crate sits at the abandoned camp in the eastern jungle."] = "沿东侧向南骑行。幼双帆龙在东部丛林吃草，{npc:9165}在东部悬崖附近飞行；两者都掉落{npc:9998}要的鳞片。箱子在东部丛林的废弃营地里。",
	["Ride south-west past {npc:9619}: the silithid hive fills the south of the crater. Use the Scraping Vial on a hatchery, a chamber with hanging larvae. Gorishi wasps and workers drop {quest:3764}; Pterrordax nest on the southern cliffs if you still need kills.\nCareful: Gorishi silithids are level 51-54 and cast {spell:8137} or {spell:14120} in melee; Gorishi Workers have a 50% chance to call for help within 25 yd once they fall below 45% health."] = "向西南骑过{npc:9619}：异种虫巢穴布满火山口南部。在一处孵化室（挂着幼虫的房间）使用刮取小瓶。格里什黄蜂和工虫掉落{quest:3764}；如果还需要击杀数，翼手龙在南边的悬崖筑巢。\n小心：格里什异种虫为51-54级，近战时施放{spell:8137}或{spell:14120}；格里什工虫血量降到45%以下时，有50%几率在25码内呼救。",
	["Top up here to level 49.51 before the hand-ins at {area:541}: they take you to level 50. Or, with a group, run the {area:2100} dungeon instead."] = "先在这里补到49.51级，再去{area:541}交任务：这些任务会把你带到50级。或者组队去刷{area:2100}副本。",
	["Top up here to level 50.4 before the hand-ins at {area:3137}: they take you to level 51. Or, with a group, run the {area:2100} dungeon or the {area:1417} dungeon instead."] = "先在这里补到50.4级，再去{area:3137}交任务：这些任务会把你带到51级。或者组队去刷{area:2100}副本或{area:1417}副本。",
	["{npc:7564}, once he has brewed the elixir: a few seconds"] = "{npc:7564}，等他配好药剂后：几秒钟",
}

G["forever/alliance/50-60/01-burning-steppes"] = {
	["If you skipped {quest:4022}, grind here to level 52.08 to stay on the route's plan. Or, with a group, run the {area:1417} dungeon or the {area:2100} dungeon instead."] = "如果你跳过了{quest:4022}，就在这里刷到52.08级，以保持攻略的节奏。或者组队去打{area:1417}或{area:2100}副本代替。",
	["Ride north from {area:271} up the road through Alterac to {area:3197}."] = "从{area:271}沿路向北骑行，穿过奥特兰克前往{area:3197}。",
	["Top up here to level 52 on the ogres of {area:249}, on the way to {area:251}: the hand-ins there take you to level 53. Or, with a group, run the {area:1417} dungeon or the {area:2100} dungeon instead."] = "在去{area:251}的路上，先在这里刷{area:249}的食人魔补到52级：在那里交任务能升到53级。或者组队去打{area:1417}或{area:2100}副本代替。",
	["grind on {npc:7033}: {npc:9177} gives {quest:4283} from level 51"] = "刷{npc:7033}：{npc:9177}从51级起给{quest:4283}",
	["{npc:10838} stands in the middle of the camp."] = "{npc:10838}站在营地中央。",
}

G["forever/alliance/50-60/02-felwood"] = {
	["If you skipped The Horn of the Beast or The {item:9328}, grind here to level 52.58 to stay on the route's plan. Or, with a group, run the {area:1417} dungeon or the {area:2100} dungeon instead."] = "如果跳过了“野兽的号角”或“{item:9328}”，就在这里刷到52.58级，以保持攻略的节奏。或者组队去打{area:1417}或{area:2100}副本代替。",
	["Ride north out of {area:415} into {area:361} to the {area:2479}, the druids' camp by the road."] = "从{area:415}向北骑出，进入{area:361}，到路边的德鲁伊营地{area:2479}。",
	["The Jadefire satyrs hold the glen west of the road, with {npc:9454} at its back.\nCareful: Jadefire Shadowstalkers (level 51-52) use Sneak and {spell:7992} and are stealthed, so they often join fights uninvited.\nCursed Oozes slide about the glen's streams: kill them and use Laris's Empty Ooze Jar on their remains."] = "碧火萨特占据道路以西的山谷，{npc:9454}在最深处。\n小心：碧火暗影潜伏者（51-52级）会潜行并使用{spell:7992}，常常不请自来地加入战斗。\n诅咒软泥怪在山谷的溪流里四处游荡：杀死它们，再对残骸使用拉里斯的空软泥怪罐。",
	["Top up here to level 52.69 before the hand-ins at {area:1763}: they take you to level 53. Or, with a group, run the {area:1417} dungeon or the {area:2100} dungeon instead."] = "先在这里补到52.69级，再去{area:1763}交任务：这些任务会把你升到53级。或者组队去打{area:1417}或{area:2100}副本代替。",
	["Top up here to level 52.9 before the hand-ins at {area:2479}: they take you to level 53. Or, with a group, run the {area:1417} dungeon or the {area:2100} dungeon instead."] = "在{area:2479}交任务前，先在这里刷到52.9级：交完后能到53级。或者组队去打{area:1417}或{area:2100}副本代替。",
	["{item:11949}: Tainted Oozes slide about {area:1763}'s fel pools"] = "{item:11949}：污染软泥怪在{area:1763}的邪能水池里四处游荡",
	["{npc:11554} the furbolg stands by the road just south of the {area:2479}."] = "熊怪{npc:11554}站在路边，就在{area:2479}以南。",
}

G["forever/alliance/50-60/03-winterspring"] = {
	["Back to the hills: only the Ice Thistle Matriarchs and Patriarchs carry the horns."] = "回到丘陵：只有冰蓟母熊和公熊带着角。",
	["Top up here to level 55.05 before the hand-ins at {area:2255}: they take you to level 56. Grind the Winterfall furbolgs camped by {area:2246} (Pathfinders, Totemics, Den Watchers): killing them raises your Timbermaw reputation, which the quests here and the walk through {area:1769} need. Or, with a group, run the {area:1584} dungeon or the {area:1583} dungeon (Lower) instead."] = "在{area:2255}交任务前，先在这里刷到55.05级：交完能到56级。刷扎营在{area:2246}旁的冬泉熊怪（探路者、图腾师、巢穴守卫）：杀它们能提升木喉声望，这里的任务和穿过{area:1769}的路程都用得上。或者组队去打{area:1584}或{area:1583}（下层）副本代替。",
	["{npc:10739} stands by the farm at the {area:202}, on the road east to the {area:139}."] = "{npc:10739}站在{area:202}的农场旁，就在向东通往{area:139}的路边。",
	["{npc:10838}: the watchtowers are in Andorhal, keep it"] = "{npc:10838}：哨塔在安多哈尔，留着",
	["{npc:11053}: the cauldron is at {area:200}, keep it"] = "{npc:11053}：大锅在{area:200}，留着",
	["{npc:11556} stands right at the {area:618} exit of {area:1769}'s tunnel, where you come out."] = "{npc:11556}就站在{area:1769}隧道的{area:618}出口处，也就是你出来的地方。",
}

G["forever/alliance/50-60/04-western-plaguelands"] = {
	["Fly from {area:976} to {area:541}. {npc:8737}'s hut stands at the {area:538}, west of the refuge; {npc:9117} is up the hill behind it.\n{npc:9997}'s friend {npc:9999} has gone missing."] = "从{area:976}飞往{area:541}。{npc:8737}的小屋在庇护所西边的{area:538}；{npc:9117}在小屋后面的山上。\n{npc:9997}的朋友{npc:9999}失踪了。",
	["If you skipped The {item:9328}, grind here to level 56.89 to stay on the route's plan. Or, with a group, run the {area:1584} dungeon or the {area:1583} dungeon (Lower) instead."] = "如果你跳过了{item:9328}，就在这里刷到56.89级，以保持攻略的节奏。或者组队去打{area:1584}或{area:1583}（下层）副本代替。",
	["Ride north to {area:2627}. {npc:12384} lives in the ruined hut, and his receipt book lies in the ruined inn nearby."] = "向北骑到{area:2627}。{npc:12384}住在破旧的小屋里，他的收据簿在附近的废弃旅店里。",
	["{npc:7876}, north side of town: the tar is in Un'Goro, keep it"] = "{npc:7876}，在城镇北边：焦油在安戈洛，留着",
}

G["forever/alliance/50-60/05-silithus"] = {
	["{npc:11038}, by the graves south of the chapel: Egan is in {area:2627}, keep it"] = "{npc:11038}，在教堂南边的坟墓旁：伊根在{area:2627}，留着",
}

G["forever/alliance/50-60/06-silithus"] = {
	["Cross the river east of {npc:1855} into {area:2627}. The Terrordale Spirits haunt the woods there. Or, with a group, run the {area:2057} dungeon or the {area:2279} dungeon instead."] = "过{npc:1855}东边的河进入{area:2627}。恐惧谷的幽灵在那里的树林中游荡。或者组队去打{area:2057}或{area:2279}副本代替。",
	["Cross the river east of {npc:1855}'s hut into {area:2627}: {npc:11140} stands by Augustus' ruined hut."] = "过{npc:1855}小屋东边的河进入{area:2627}：{npc:11140}站在奥古斯都的破旧小屋旁。",
	["From {area:3137} ride into {area:361}: the {area:2479} is the druids' camp on the road just past the {zone:1440} border."] = "从{area:3137}骑进{area:361}：{area:2479}就是刚过{zone:1440}边界、路边的德鲁伊营地。",
	["Ride back east past {area:2255} and south-east down the valley to {npc:10301}'s damaged crate in the snow at {area:2245}, with his wrecked wagon just east of it."] = "往回向东骑，经过{area:2255}，再向东南沿山谷而下，到{area:2245}雪地里{npc:10301}的破损箱子处，他被毁的马车就在东边。",
	["Ride north up the valley, past {area:2255}, to {area:2253}."] = "沿山谷向北骑行，经过{area:2255}，前往{area:2253}。",
	["Ride north-west up the road to {area:2253}."] = "沿路向西北骑往{area:2253}。",
	["Take the {area:2257} to {zone:1455}. {npc:14724} and {npc:14723} each take sixty Wool, sixty Silk and sixty Mageweave, then sixty {item:14047}: hand in what you carry (or buy at the Auction House), skip the rest."] = "乘坐{area:2257}到{zone:1455}。{npc:14724}和{npc:14723}各收六十个毛料、六十个丝绸和六十个魔纹布，然后再收六十个{item:14047}：交掉身上带的（或在拍卖行买），其余跳过。",
	["{area:2577} fits levels 55 to 60; alone, the {area:2627} grind at the end of this guide gets you to 60."] = "{area:2577}适合55-60级；单人刷本攻略末尾的{area:2627}能练到60级。",
}

G["forever/alliance/dwarf/01-dun-morogh"] = {
	["Back to the tunnel post"] = "回到隧道岗哨",
	["Back to {npc:6122}. Use the {item:6928} at the summoning circle in the {object:2164}'s cellar and defeat the voidwalker it calls. {area:87} and east Elwynn are next, then {zone:1436}."] = "回到{npc:6122}。在{object:2164}地窖里的召唤法阵上使用{item:6928}，击败它召唤出的虚空行者。接下来是{area:87}和艾尔文森林东部，然后去{zone:1436}。",
	["Crag Boars and Young Black Bears roam the fields from Rumbleshot's camp north-east to {area:131} and the depot: kill them on the walk back."] = "从拉姆布肖特营地往东北，直到{area:131}和补给站的田野里，有峭壁野猪和幼年黑熊游荡：回去的路上顺手杀掉。",
	["Deeprun Rat"] = "矿道鼠",
	["East along the hills to the mine at the north end of the loch: the Miners' League crates sit in its tunnels, among more Tunnel Rats."] = "沿丘陵向东到湖北端的矿井：矿工联盟的箱子就在矿洞里，周围还有更多隧道鼠。",
	["East back into {object:171524}: the {area:2257} leaves from its east end. Ride it to {zone:1453}."] = "向东回到{object:171524}：{area:2257}从它的东端出发，坐它去{zone:1453}。",
	["East from the {object:32372} into {object:171524}: the {object:660964} lie by its mailbox. From here the guide goes once round the city: north to the {object:32383}, west to the {object:32362}, south through the Commons to the {object:171709}, east through the {object:32359} and back to {object:171524} for the tram."] = "从{object:32372}向东进入{object:171524}：{object:660964}就在它的邮箱旁。从这里攻略绕城一圈：向北到{object:32383}，向西到{object:32362}，向南穿过平民区到{object:171709}，向东穿过{object:32359}，再回到{object:171524}坐地铁。",
	["East through the South Gate tunnel into {area:38}. {npc:1089} and {npc:1092} stand at the dwarven post just past it."] = "穿过南门隧道向东进入{area:38}。{npc:1089}和{npc:1092}守在刚出隧道的矮人岗哨。",
	["East to the {object:32359}: the warrior trainers and {npc:11865} in the {object:32390}, the hunter trainers beside it."] = "向东到{object:32359}：战士训练师和{npc:11865}在{object:32390}里，猎人训练师就在旁边。",
	["From the {object:28027} south-west to {object:2098}: {npc:1646}'s compass is in his old house in {zone:1436}, on the way. The flight master and the {object:2096} are south of the square."] = "从{object:28027}向西南到{object:2098}：顺路去{zone:1436}里{npc:1646}的老房子，他的罗盘在那儿。飞行管理员和{object:2096}在广场南边。",
	["From {zone:1436}, walk to {zone:1453}; the tram from {zone:1455} arrives in the {object:28027}. {npc:5480} trains warriors in {object:2100}; {npc:6089} and {npc:6090} stand together by the {object:2152} there. {npc:6090} fights you for his mug. If {npc:5480} doesn't offer {quest:1638}, go straight to {npc:6089}: he gives {quest:1639} without it."] = "从{zone:1436}步行到{zone:1453}；从{zone:1455}来的地铁到达{object:28027}。{npc:5480}在{object:2100}训练战士；{npc:6089}和{npc:6090}一起站在那里的{object:2152}旁。{npc:6090}会为了他的杯子和你打一架。如果{npc:5480}不给{quest:1638}，就直接找{npc:6089}：没有它也会给你{quest:1639}。",
	["Leave {zone:1453} by the main gate and follow the road south to {area:87}: east Elwynn comes before {zone:1436}."] = "从正门离开{zone:1453}，沿路向南到{area:87}：先走艾尔文森林东部，再去{zone:1436}。",
	["North of the post, west of the road: the Stonesplinter troggs and scouts camp in the hills. Both drop the Trogg Stone Teeth."] = "岗哨以北、道路以西：碎石穴居人和侦察兵在丘陵里扎营，两者都掉落穴居人的石牙。",
	["North of the {object:32372}: {npc:258098}, the shaman trainer, stands at the south end of the {object:32383}, the rogue and warlock trainers and {npc:6120} just north of him."] = "在{object:32372}以北：萨满祭司训练师{npc:258098}站在{object:32383}的南端，盗贼和术士训练师以及{npc:6120}就在他北边。",
	["North through the hills west of the road to {npc:1343} at the {area:925}. The Tunnel Rat kobolds dig in the hills on the way; Elder Black Bears, Mountain Boars and Forest Lurkers roam the same ground."] = "穿过道路以西的丘陵向北，到{area:925}的{npc:1343}。沿途有隧道鼠狗头人在丘陵里挖洞；老年黑熊、山地野猪和森林潜伏者也在同一片地方游荡。",
	["North up the road to {area:144}. {npc:1340} walks the road through town, {npc:1963} stands outside the {area:2101}, {npc:1681} on the east side of town; {npc:1572} keeps the gryphons."] = "沿路向北到{area:144}。{npc:1340}在穿过镇子的路上巡逻，{npc:1963}站在{area:2101}外，{npc:1681}在镇子东边；{npc:1572}照看狮鹫。",
	["On the {zone:1455} platform of the {area:2257}, {npc:12997} asks for help with the rats: use his {item:17117} on the Deeprun Rats around the platform, hand them in, then take his letter to his brother {npc:13018} at the {zone:1453} end."] = "在{area:2257}的{zone:1455}站台，{npc:12997}请你帮忙灭鼠：用他的{item:17117}对付站台周围的矿道鼠，交掉之后，再把他的信带给{zone:1453}那头的兄弟{npc:13018}。",
	["Ride the tram to {zone:1453}: {npc:13018} waits on the {zone:1453} platform. {npc:5413} stands in the {object:28027}, just outside the tram."] = "坐地铁到{zone:1453}：{npc:13018}在{zone:1453}站台等着。{npc:5413}站在{object:28027}里，就在地铁车厢外。",
	["Rockjaw Ambushers by {area:212}, north of the quarry, and Rockjaw Backbreakers further east drop the {quest:95214}. Dark Iron Spies sneak around the lake shore east of the quarry; one of them drops the {item:274268}."] = "{area:212}旁、采石场以北的石颚伏击者，以及更东边的石颚碎背者掉落{quest:95214}。黑铁间谍在采石场以东的湖岸潜行；其中一个掉落{item:274268}。",
	["South down the road to {area:144}, finishing the ears, meat and ichor on the way."] = "沿路向南到{area:144}，顺路把耳朵、肉和脓液收齐。",
	["South through the Commons: {npc:1274} stands in the {object:171709} with King Magni."] = "向南穿过平民区：{npc:1274}在{object:171709}里，和麦格尼国王在一起。",
	["Stonesplinter Scout"] = "碎石侦察兵",
	["Stonesplinter Trogg"] = "碎石穴居人",
	["Stonesplinter troggs"] = "碎石穴居人",
	["The gryphons land in the {object:32372}: {npc:4256} works at its north end, and {npc:1573} keeps the gryphons where you landed."] = "狮鹫降落在{object:32372}：{npc:4256}在它的北端值守，{npc:1573}在你降落的地方照看狮鹫。",
	["The paladin, priest and mage trainers are in the {object:32386}, in the {object:32362}."] = "圣骑士、牧师和法师训练师在{object:32362}里的{object:32386}中。",
	["The pilots stand at the depot; {npc:1269} is on the road back west, north of {area:131}."] = "飞行员站在补给站；{npc:1269}在往西回去的路上，{area:131}以北。",
	["The tunnel post"] = "隧道岗哨",
	["The west hills and the {area:925}"] = "西边的丘陵和{area:925}",
	["West from the {object:32383} into the {object:32362}: {npc:5149}, {npc:6179} and {npc:6178} are in the {object:32386}, {npc:6179} and {npc:6178} on its upper floor: the stairs up start just north-east of {npc:5149}. {npc:6175}, a beggar, wanders the city. He asks for ten {item:2589}: the troggs and trolls of {area:1} drop it, and the Auction House sells it."] = "从{object:32383}向西进入{object:32362}：{npc:5149}、{npc:6179}和{npc:6178}在{object:32386}里，{npc:6179}和{npc:6178}在它的上层：上楼的楼梯就在{npc:5149}东北。乞丐{npc:6175}在城中游荡。他要十块{item:2589}：{area:1}的穴居人和巨魔会掉落，拍卖行也有卖。",
	["{item:2640}, from the crates"] = "{item:2640}，来自箱子",
	["{item:3110}: Tunnel Rat kobolds"] = "{item:3110}：隧道鼠狗头人",
	["{item:3172}: Mountain Boars"] = "{item:3172}：山地野猪",
	["{item:3173}: Elder Black Bears"] = "{item:3173}：老年黑熊",
	["{item:3174}: Forest Lurkers"] = "{item:3174}：森林潜伏者",
	["{npc:1252} stands by Eric's campfire in front of the {area:2102}; {npc:1241} is in the cellar west of it."] = "{npc:1252}站在{area:2102}前埃里克的篝火旁；{npc:1241}在它西边的地窖里。",
	["{npc:12997}, on the {zone:1455} platform"] = "{npc:12997}，在{zone:1455}站台",
	["{npc:13016}: use the {item:17117}"] = "{npc:13016}：使用{item:17117}",
	["{npc:13018}, on the {zone:1453} platform"] = "{npc:13018}，在{zone:1453}站台",
	["{npc:1572}: for {npc:4256} in {zone:1455}"] = "{npc:1572}：交给{zone:1455}的{npc:4256}",
}

G["forever/alliance/gnome/01-dun-morogh"] = {
	["Back to the tunnel post"] = "回到隧道岗哨",
	["Back to {npc:6122}. Use the {item:6928} at the summoning circle in the {object:2164}'s cellar and defeat the voidwalker it calls. {area:87} and east Elwynn are next, then {zone:1436}."] = "回到{npc:6122}。在{object:2164}地窖里的召唤法阵上使用{item:6928}，击败它召唤出的虚空行者。接下来去{area:87}和艾尔文森林东部，然后去{zone:1436}。",
	["Crag Boars and Young Black Bears roam the fields from Rumbleshot's camp north-east to {area:131} and the depot: kill them on the walk back."] = "峭壁野猪和小黑熊在从重枪的营地往东北直到{area:131}和补给站一带的田野里游荡：在往回走的路上把它们杀掉。",
	["Deeprun Rat"] = "矿道老鼠",
	["East along the hills to the mine at the north end of the loch: the Miners' League crates sit in its tunnels, among more Tunnel Rats."] = "沿山丘往东走到湖泊北端的矿洞：矿工联合会的箱子就放在矿洞的隧道里，周围还有更多坑道鼠狗头人。",
	["East back into {object:171524}: the {area:2257} leaves from its east end. Ride it to {zone:1453}."] = "往东回到{object:171524}里：{area:2257}从它的东端发车。乘它去{zone:1453}。",
	["East from the {object:32372} into {object:171524}: the {object:660964} lie by its mailbox. From here the guide goes once round the city: north to the {object:32383}, west to the {object:32362}, south through the Commons to the {object:171709}, east through the {object:32359} and back to {object:171524} for the tram."] = "从{object:32372}往东进入{object:171524}：{object:660964}就在它的邮箱旁。从这里指南绕城一圈：往北到{object:32383}，往西到{object:32362}，往南穿过平民区到{object:171709}，往东穿过{object:32359}，再回到{object:171524}坐地铁。",
	["East through the South Gate tunnel into {area:38}. {npc:1089} and {npc:1092} stand at the dwarven post just past it."] = "往东穿过南门隧道进入{area:38}。{npc:1089}和{npc:1092}站在刚过隧道的矮人岗哨处。",
	["East to the {object:32359}: the warrior trainers and {npc:11865} in the {object:32390}, the hunter trainers beside it."] = "往东到{object:32359}：战士训练师和{npc:11865}在{object:32390}里，猎人训练师就在旁边。",
	["From the {object:28027} south-west to {object:2098}: {npc:1646}'s compass is in his old house in {zone:1436}, on the way. The flight master and the {object:2096} are south of the square."] = "从{object:28027}往西南到{object:2098}：{npc:1646}的罗盘在{zone:1436}他的老房子里，顺路可取。飞行管理员和{object:2096}在广场南边。",
	["From {zone:1436}, walk to {zone:1453}; the tram from {zone:1455} arrives in the {object:28027}. {npc:5480} trains warriors in {object:2100}; {npc:6089} and {npc:6090} stand together by the {object:2152} there. {npc:6090} fights you for his mug. If {npc:5480} doesn't offer {quest:1638}, go straight to {npc:6089}: he gives {quest:1639} without it."] = "从{zone:1436}步行到{zone:1453}；从{zone:1455}开来的地铁到达{object:28027}。{npc:5480}在{object:2100}训练战士；{npc:6089}和{npc:6090}一起站在那里的{object:2152}旁。{npc:6090}会为了他的杯子和你打一架。如果{npc:5480}不给{quest:1638}，就直接去找{npc:6089}：不用它他也会给{quest:1639}。",
	["Leave {zone:1453} by the main gate and follow the road south to {area:87}: east Elwynn comes before {zone:1436}."] = "从正门离开{zone:1453}，沿道路往南到{area:87}：先到艾尔文森林东部，再进{zone:1436}。",
	["North of the post, west of the road: the Stonesplinter troggs and scouts camp in the hills. Both drop the Trogg Stone Teeth."] = "在岗哨以北、道路以西：碎石穴居人和斥候在山丘里扎营。两者都会掉落穴居人的石牙。",
	["North of the {object:32372}: {npc:258098}, the shaman trainer, stands at the south end of the {object:32383}, the rogue and warlock trainers and {npc:6120} just north of him."] = "在{object:32372}以北：萨满祭司训练师{npc:258098}站在{object:32383}的南端，盗贼和术士训练师以及{npc:6120}就在他北边。",
	["North through the hills west of the road to {npc:1343} at the {area:925}. The Tunnel Rat kobolds dig in the hills on the way; Elder Black Bears, Mountain Boars and Forest Lurkers roam the same ground."] = "往北穿过道路以西的山丘，到{area:925}的{npc:1343}那里。坑道鼠狗头人沿途在山丘里挖洞；老黑熊、山猪和森林潜伏者在同一片地方游荡。",
	["North up the road to {area:144}. {npc:1340} walks the road through town, {npc:1963} stands outside the {area:2101}, {npc:1681} on the east side of town; {npc:1572} keeps the gryphons."] = "沿道路往北到{area:144}。{npc:1340}在穿过镇子的路上走动，{npc:1963}站在{area:2101}外，{npc:1681}在镇子东边；{npc:1572}看管狮鹫。",
	["On the {zone:1455} platform of the {area:2257}, {npc:12997} asks for help with the rats: use his {item:17117} on the Deeprun Rats around the platform, hand them in, then take his letter to his brother {npc:13018} at the {zone:1453} end."] = "在{area:2257}的{zone:1455}站台上，{npc:12997}请你帮忙处理老鼠：用他的{item:17117}对付站台周围的矿道老鼠，把它们交上去，然后把他的信带给{zone:1453}那头的兄弟{npc:13018}。",
	["Ride the tram to {zone:1453}: {npc:13018} waits on the {zone:1453} platform. {npc:5413} stands in the {object:28027}, just outside the tram."] = "乘地铁到{zone:1453}：{npc:13018}在{zone:1453}站台上等着。{npc:5413}站在{object:28027}里，就在地铁外面。",
	["Rockjaw Ambushers by {area:212}, north of the quarry, and Rockjaw Backbreakers further east drop the {quest:95214}. Dark Iron Spies sneak around the lake shore east of the quarry; one of them drops the {item:274268}."] = "{area:212}旁、采石场以北的石颚伏击者，以及更东边的石颚碎背者掉落{quest:95214}。黑铁间谍在采石场以东的湖岸潜行；其中一个掉落{item:274268}。",
	["South down the road to {area:144}, finishing the ears, meat and ichor on the way."] = "沿道路往南到{area:144}，顺路把耳朵、肉和脓液都凑齐。",
	["South through the Commons: {npc:1274} stands in the {object:171709} with King Magni."] = "往南穿过平民区：{npc:1274}和麦格尼国王一起站在{object:171709}里。",
	["Stonesplinter Scout"] = "碎石斥候",
	["Stonesplinter Trogg"] = "碎石穴居人",
	["Stonesplinter troggs"] = "碎石穴居人",
	["The gryphons land in the {object:32372}: {npc:4256} works at its north end, and {npc:1573} keeps the gryphons where you landed."] = "狮鹫降落在{object:32372}：{npc:4256}在它的北端工作，{npc:1573}就在你降落的地方看管狮鹫。",
	["The paladin, priest and mage trainers are in the {object:32386}, in the {object:32362}."] = "圣骑士、牧师和法师训练师在{object:32362}内的{object:32386}里。",
	["The pilots stand at the depot; {npc:1269} is on the road back west, north of {area:131}."] = "驾驶员们站在补给站；{npc:1269}在往西回去的路上，{area:131}以北。",
	["The tunnel post"] = "隧道岗哨",
	["The west hills and the {area:925}"] = "西部丘陵和{area:925}",
	["West from the {object:32383} into the {object:32362}: {npc:5149}, {npc:6179} and {npc:6178} are in the {object:32386}, Tiza and Muiredon on its upper floor: the stairs up start just north-east of {npc:5149}. {npc:6175}, a beggar, wanders the city. He asks for ten {item:2589}: the troggs and trolls of {area:1} drop it, and the Auction House sells it."] = "从{object:32383}往西进入{object:32362}：{npc:5149}、{npc:6179}和{npc:6178}在{object:32386}里，提扎和缪瑞顿在它的上层：上楼的楼梯就在{npc:5149}东北。乞丐{npc:6175}在城中游荡。他要十块{item:2589}：{area:1}的穴居人和巨魔会掉落，拍卖行也有卖。",
	["{item:2640}, from the crates"] = "{item:2640}，来自箱子",
	["{item:3110}: Tunnel Rat kobolds"] = "{item:3110}：坑道鼠狗头人",
	["{item:3172}: Mountain Boars"] = "{item:3172}：山猪",
	["{item:3173}: Elder Black Bears"] = "{item:3173}：老黑熊",
	["{item:3174}: Forest Lurkers"] = "{item:3174}：森林潜伏者",
	["{npc:1252} stands by Eric's campfire in front of the {area:2102}; {npc:1241} is in the cellar west of it."] = "{npc:1252}站在{area:2102}前埃里克的篝火旁；{npc:1241}在它西边的地窖里。",
	["{npc:12997}, on the {zone:1455} platform"] = "{npc:12997}，在{zone:1455}站台上",
	["{npc:13016}: use the {item:17117}"] = "{npc:13016}：使用{item:17117}",
	["{npc:13018}, on the {zone:1453} platform"] = "{npc:13018}，在{zone:1453}站台上",
	["{npc:1572}: for {npc:4256} in {zone:1455}"] = "{npc:1572}：交给{zone:1455}的{npc:4256}",
}

G["forever/alliance/human/01-elwynn-forest"] = {
	["Follow the road south out of the valley to {area:87}. {npc:240} stands outside the smithy on the west side of the road, {npc:241} by the road south of it, and {npc:295} and {npc:253} in the Lion's Pride Inn across the road."] = "沿道路向南离开山谷到{area:87}。{npc:240}站在路西侧铁匠铺外，{npc:241}在铁匠铺南边的路旁，{npc:295}和{npc:253}在路对面的狮王之傲旅店里。",
	["Follow the road south to the {area:120}, on the way into {zone:1436}. {npc:963} stands outside the barracks; {npc:955} stands inside. He has {quest:91738} only while you carry the {item:247824}: talk to him and it goes straight to the hand-in."] = "沿道路向南到{area:120}，就在进入{zone:1436}的路上。{npc:963}站在兵营外；{npc:955}站在里面。只有你带着{item:247824}时他才会给{quest:91738}：和他交谈后就直接进入交付环节。",
	["Follow the road west back to {area:87}; {npc:6306} stands on the lake shore before town. {npc:377} (priests), {npc:328} (mages) and {npc:917} (rogues) stand upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart."] = "沿路向西回到{area:87}；{npc:6306}站在进城前的湖岸上。{npc:377}（牧师）、{npc:328}（法师）和{npc:917}（盗贼）站在旅店楼上：从里面上楼，箭头分不清楼层。",
	["Head east out of {area:87} along the lake shore. {npc:383} stands on the shore north-east of town."] = "沿湖岸往东离开{area:87}。{npc:383}站在镇子东北的岸上。",
	["{npc:514}, at the smithy: {npc:1416} in {zone:1453} takes it (02-westfall)"] = "{npc:514}，在铁匠铺：交给{zone:1453}的{npc:1416}（02-westfall）",
}

G["forever/alliance/nightelf/01-teldrassil"] = {
	["Fishers only: {npc:10216} stands on the pier. His {item:12238} is fished from the pier itself."] = "仅限钓鱼者：{npc:10216}站在码头上。他的{item:12238}就在码头上钓得到。",
	["Fly back to {area:702} from {npc:3841}, hand {item:16263} to {npc:10118} on the dock, then fly back to {area:442}."] = "从{npc:3841}处飞回{area:702}，把{item:16263}交给码头上的{npc:10118}，然后飞回{area:442}。",
	["Fly to {area:702} once more and take the portal up to {npc:4217}, then fly back to {area:442}."] = "再次飞往{area:702}，乘传送门上去找{npc:4217}，然后飞回{area:442}。",
	["Follow the road west into {zone:1457} and use the {item:279378} at the inn on the {area:1659} and at the tunnel mouth below {area:3425} for the last two owls. {npc:4241} stands on the {area:1659} just inside the city. {npc:3516} is in the {area:1658} at the north end of the city, {quest:922} just south of it; {npc:4092}, {npc:7999}, {npc:7313} and {npc:8396} are in the Temple of the Moon at the south end."] = "沿道路向西进入{zone:1457}，在{area:1659}上的旅店和{area:3425}下方的隧道口使用{item:279378}，找到最后两只猫头鹰。{npc:4241}站在一进城的{area:1659}上。{npc:3516}在城市北端的{area:1658}，{quest:922}就在其南边；{npc:4092}、{npc:7999}、{npc:7313}和{npc:8396}在南端的月神殿。",
	["Into the city through the gate. {quest:922} is just south of the {area:1658} at the north end, {npc:7316} in the west, {npc:7313} and {npc:8396} in the Temple of the Moon at the south end. On the way back out, use Dalia's {item:279378} at the bank and at the city gate; the other two owls wait for your last visit."] = "穿过大门进城。{quest:922}就在北端{area:1658}的南边，{npc:7316}在西部，{npc:7313}和{npc:8396}在南端的月神殿。往回走的时候，在银行和城门使用达莉娅的{item:279378}；另外两只猫头鹰留到你最后一次来时再找。",
	["Lead {quest:938} to the moonwell"] = "把{quest:938}引到月井",
	["Mangy Nightsabers and Thistle Boars roam north of {area:256}, on the way to the cave. {npc:1994} sits deep inside. {npc:8584} waits in the trees west of the cave mouth."] = "癞皮夜刃豹和蓟野猪在{area:256}以北游荡，就在去洞穴的路上。{npc:1994}坐在洞穴深处。{npc:8584}在洞口西边的树林里等候。",
	["North from the road the path to the glade crosses the {area:265}: the timberlings along it drop the Mossy Tumors."] = "从道路往北，通往林间空地的小径穿过{area:265}：沿路的树精会掉落青苔之瘤。",
	["South of the pools. The {object:6751} grows by the Hold; the furbolgs around it drop the rest of the fangs."] = "在水池南边。{object:6751}长在脊骨堡旁；周围的熊怪掉落剩下的尖牙。",
	["The Bloodfeather harpies nest on the slopes west and north of the glade. {quest:938}, an injured sabercat, lies by the glade's west wall among them: lead her back to Sentinel Arynia at the moonwell before her time runs out.\nCareful: The harpies stand packed together, so extra ones often join a fight. Casters are mixed in among them."] = "血羽鹰身人在林间空地以西和以北的山坡筑巢。{quest:938}是一只受伤的刃豹，躺在它们中间、林间空地的西墙旁：赶在时间耗尽前把她带回月井旁的哨兵艾瑞尼娅那里。\n注意：鹰身人站得很密集，所以常会有额外的加入战斗。施法者混在它们中间。",
	["The barrow is south of the road. {npc:275744} is held inside, {npc:7317} sleeps in its depths, and the four relic chests sit in the lower rooms. Its furbolgs drop Shayla's fangs."] = "兽穴在道路南边。{npc:275744}被关在里面，{npc:7317}在深处沉睡，四个圣物箱在下层房间里。里面的熊怪掉落莎伊拉的尖牙。",
	["The road west to the {area:264} runs through {area:186}: hand {npc:3567} the jewel on the way."] = "往西去{area:264}的路穿过{area:186}：顺路把宝石交给{npc:3567}。",
	["The {object:6752} grows at the glade's north end, on the way: then north of {npc:272046}, along the island's northern edge by {area:266}, {npc:7319}, a level 12 spider, lurks."] = "{object:6752}长在林间空地的北端，就在路上：再往北，在{npc:272046}以北、{area:266}旁岛屿北缘一带，潜伏着{npc:7319}，一只12级的蜘蛛。",
	["West along the road from {area:186}: Shayla still stands beside it, before the turn north to the glade."] = "从{area:186}沿道路往西：莎伊拉仍站在路旁，就在往北拐向林间空地之前。",
	["West along the road to the city gate: Shayla stands beside it. Every Gnarlpine furbolg drops fangs: the ambushers on this road, the barrow's and {area:261}'s all count."] = "沿道路往西到城门：莎伊拉站在城门旁。每只瘤背熊怪都掉落尖牙：这条路上的伏击者、兽穴里的和{area:261}的都算。",
	["the city gate"] = "城门",
	["the tunnel mouth below {area:3425}, on the way south"] = "{area:3425}下方的隧道口，在南下的路上",
	["{item:279378}: the bank, on the way out"] = "{item:279378}：银行，出去时顺路",
	["{item:279378}: the inn on the {area:1659}"] = "{item:279378}：{area:1659}上的旅店",
	["{item:5170}: timberlings"] = "{item:5170}：树精",
	["{item:5220}: any Gnarlpine furbolg"] = "{item:5220}：任意一只瘤背熊怪",
	["{npc:2150} sits by the road just east of {area:186}, between {area:186} and {area:260}."] = "{npc:2150}坐在{area:186}正东的路旁，就在{area:186}和{area:260}之间。",
	["{npc:4241}, on the {area:1659} just inside the city"] = "{npc:4241}，在刚进城处的{area:1659}上",
	["{npc:8396}, beside her"] = "{npc:8396}，在她旁边",
	["{quest:2520}, standing in the temple's central fountain"] = "{quest:2520}，站在月神殿中央的喷泉里",
	["{quest:938}, by the west wall"] = "{quest:938}，在西墙旁",
}

G["forever/alliance/nightelf/02-darkshore"] = {
	["Back north to {area:447}: the flame burns in the south of the ruins."] = "往北回到{area:447}：火焰在废墟南部燃烧。",
	["North along the hills to {npc:3650}, then west down to {area:442}."] = "沿山丘往北到{npc:3650}，再往西下去到{area:442}。",
	["Off the boat, {npc:268511} stands on the harbor: his shipment goes to {npc:483}' cheese shop in the {object:2096}, beside the flight master."] = "下船后，{npc:268511}站在港口：他的货物要送到{object:2096}里{npc:483}的奶酪店，就在飞行管理员旁边。",
	["Rabid Thistle Bears roam the hills south of {area:442}: use {item:7586} on one to capture it. Then walk up to the furbolg camp just east of them: nothing to kill yet."] = "狂暴蓟熊在{area:442}以南的丘陵里游荡：对其中一只使用{item:7586}把它捕获。然后走到它们正东的熊怪营地：现在还没有要杀的东西。",
	["Up the stairs in her shop: leave the shipment at the {object:460004}"] = "上她店里的楼梯：把货物留在{object:460004}处",
	["{npc:1646} stands in {object:2098}, west of the {object:2096}: his compass is in his old house in {zone:1436}, on the way."] = "{npc:1646}站在{object:2098}里，在{object:2096}以西：他的罗盘在{zone:1436}的老房子里，顺路可取。",
	["{npc:483}, in her cheese shop"] = "{npc:483}，在她的奶酪店里",
}

G["forever/alliance/skyborne/01-zephras-isle"] = {
	["On the road south-east to {area:16638}, {npc:273017} watches the {quest:98512} just north of him."] = "在往东南去{area:16638}的路上，{npc:273017}监视着他正北边的{quest:98512}。",
	["{npc:1646} stands in {object:2098}, on the way from the Keep to the main gate: his compass is in his old house in {area:40}, on the way."] = "{npc:1646}站在{object:2098}里，就在从要塞到正门的路上：他的罗盘在{area:40}的老房子里，顺路可取。",
	["{npc:252475} sends you on to {area:279}. Take the skycutter from the dock tower just south of {area:16638}: it lands by the Kirin Tor camp west of {area:279}, beside {npc:259084} and the Skyborne Portal."] = "{npc:252475}派你前往{area:279}。从{area:16638}正南的码头塔乘飞空艇：它会降落在{area:279}以西的肯瑞托营地旁，就在{npc:259084}和天裔传送门旁。",
	["{npc:255853} waits by the falls just north of the watchtower. {npc:258443} prowls the {area:16623} south-west of the dead cultist, where you go after {area:16638}."] = "{npc:255853}在哨塔正北的瀑布旁等候。{npc:258443}在死去的邪教徒西南的{area:16623}游荡，那是你去完{area:16638}之后要去的地方。",
}

G["forever/class/rogue/blade-of-cunning-alliance"] = {
	["{spell:921} the {npc:6846} for the {item:7675}"] = "对{npc:6846}使用{spell:921}，拿到{item:7675}",
}

G["forever/class/rogue/poisons-alliance"] = {
	["{spell:921} the {npc:7051} for the {item:7923}"] = "对{npc:7051}使用{spell:921}，拿到{item:7923}",
}

G["forever/class/warrior/fire-hardened-armor"] = {
	["The {quest:1708} grows on the sea floor just south of {area:150}, by the murloc huts and a wrecked boat: eight there and two south-east of the harbor, each back in 3 minutes, so you will wait for respawns to reach 20. The murlocs can net you underwater: watch your breath, and an Elixir of Water Breathing removes the risk."] = "{quest:1708}生长在{area:150}正南的海底，鱼人小屋和一条破船旁：那里有八株，港口东南有两株，各3分钟刷新，所以要等刷新凑够20个。鱼人在水下会用网困住你：留意呼吸条，一瓶水下呼吸药剂就能消除风险。",
}
